-- ===========================================================================
-- COUNTRY ON THE AGENCY PROFILE (2026-11-28)
-- ===========================================================================
-- WHY: the restructure's release 18 (docs/MAP.md §G). Malaysia's time zone
-- was typed into 205 functions, three column defaults and two scheduled
-- jobs, and the currency, locale and tax label into the pages: an install in
-- another country would have had to edit every one.
-- WHAT IT CHANGES
--   * `agency_profile` holds the country: `time_zone`, `country`,
--     `currency`, `currency_sign`, `locale`, `tax_label`, seeded with this
--     install's Malaysian values (a key already set keeps its value), so
--     nothing reads differently here. `agency_profile_read()` answers them
--     with the rest; js/config.js `ADspaceAgency` holds the same.
--   * A time zone the database does not know is refused on its write
--     (`agency_profile_check`).
--   * `agency_tz()`: the profile's time zone, the one read every function's
--     day and hour takes (`(now() at time zone public.agency_tz())::date` is
--     a function's today). Immutable, so the planner reads it once and a
--     query's plan is the one the typed zone gave; a changed zone reaches a
--     connection opened after the change. Refuses where the profile holds
--     none, never a silent UTC day.
--   * Every function whose last definition typed the zone is stated again,
--     word for word, reading `agency_tz()` (generated by tests/tzroute.js
--     from schema.sql; nothing else in them changes), and so are the three
--     column defaults and the two weekday reminder jobs.
-- ORDER: this file, then the pages (they read the same values from
-- js/config.js), then `meet-create`. An open tab meets the same answers
-- throughout: every function answers what it answered before.
-- ROLLBACK: run each function's earlier band again (schema.sql, the bands
-- before this one), the three defaults and the PUBLIC HOLIDAYS job block;
-- then `drop function public.agency_tz(); drop trigger agency_profile_check
-- on public.agency_profile; drop function public.agency_profile_check();
-- delete from public.agency_profile where key in ('time_zone', 'country',
-- 'currency', 'currency_sign', 'locale', 'tax_label');`. Safe to run twice.
-- ===========================================================================

-- COUNTRY ON THE AGENCY PROFILE ---------------------------------------------

insert into public.agency_profile (key, value) values
  ('time_zone', 'Asia/Kuala_Lumpur'),
  ('country', 'MY'),
  ('currency', 'MYR'),
  ('currency_sign', 'RM'),
  ('locale', 'en-MY'),
  ('tax_label', 'SST')
on conflict (key) do nothing;

create or replace function public.agency_profile_check()
returns trigger
language plpgsql set search_path = public as $$
begin
  if new.key = 'time_zone' and not exists (select 1 from pg_timezone_names z where z.name = new.value) then
    raise exception 'agency_profile: % is not a time zone', new.value using errcode = 'check_violation';
  end if;
  return new;
end $$;
revoke all on function public.agency_profile_check() from public, anon, authenticated;
drop trigger if exists agency_profile_check on public.agency_profile;
create trigger agency_profile_check before insert or update on public.agency_profile
  for each row execute function public.agency_profile_check();

create or replace function public.agency_tz()
returns text
language plpgsql immutable security definer set search_path = public as $$
declare
  v text;
begin
  select a.value into v from public.agency_profile a where a.key = 'time_zone';
  if coalesce(v, '') = '' then
    raise exception 'agency_profile: no time_zone' using errcode = 'no_data_found';
  end if;
  return v;
end $$;
revoke all on function public.agency_tz() from public, anon;
grant execute on function public.agency_tz() to authenticated, service_role;

alter table public.client_touches   alter column happened_at set default ((now() at time zone public.agency_tz())::date);
alter table public.client_documents alter column issued_at   set default ((now() at time zone public.agency_tz())::date);
alter table public.documents        alter column issued_at   set default ((now() at time zone public.agency_tz())::date);

/* The weekday reminders skip a public holiday of the agency's own day. */
do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'pg_cron is not enabled: the reminders keep their schedules until it is.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'tasks-reminder';
  perform cron.schedule('tasks-reminder', '0 4 * * 1-5',
    'select public.ops_tasks_remind() where public.public_holiday_on((now() at time zone public.agency_tz())::date) is null');
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'tasks-nudge';
  perform cron.schedule('tasks-nudge', '0 2-9 * * 1-5',
    'select public.ops_tasks_nudge() where public.public_holiday_on((now() at time zone public.agency_tz())::date) is null');
end $$;

-- Each function that typed the zone, stated again reading the profile's.

create or replace function public.ops_mark_live(
  p_task uuid, p_live_at timestamptz, p_reason text default null,
  p_version integer default null, p_assignee uuid default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m    public.team_members;
  t    public.ops_tasks;
  res  jsonb;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  if p_live_at is null then return jsonb_build_object('error', 'no-date'); end if;
  if (p_live_at at time zone public.agency_tz())::date
     > (now() at time zone public.agency_tz())::date then
    return jsonb_build_object('error', 'live-in-future');
  end if;
  if t.publish_at is not null
     and (p_live_at at time zone public.agency_tz())::date
         <> (t.publish_at at time zone public.agency_tz())::date
     and nullif(btrim(coalesce(p_reason, '')), '') is null then
    return jsonb_build_object('error', 'live-reason-required');
  end if;

  update public.ops_tasks set live_at = p_live_at where id = p_task;
  res := public.ops_transition_task(p_task, 'live', p_version, p_note, p_assignee, null);
  if res ? 'error' then
    update public.ops_tasks set live_at = t.live_at where id = p_task;
    return res;
  end if;
  perform public.ops_log(p_task, 'live_confirmed',
    jsonb_build_object('scheduled', t.publish_at),
    jsonb_build_object('live_at', p_live_at),
    case when nullif(btrim(coalesce(p_reason, '')), '') is null then '{}'::jsonb
         else jsonb_build_object('reason', btrim(p_reason)) end);
  return public.ops_task_json(p_task);
end $$;

create or replace function public.ops_recurring_periods()
returns text[]
language sql stable set search_path = public as $$
  select case
    when (now() at time zone public.agency_tz())::date
         > (date_trunc('month', now() at time zone public.agency_tz()) + interval '1 month' - interval '8 days')::date
    then array[to_char(now() at time zone public.agency_tz(), 'YYYY-MM'),
               to_char(date_trunc('month', now() at time zone public.agency_tz()) + interval '1 month', 'YYYY-MM')]
    else array[to_char(now() at time zone public.agency_tz(), 'YYYY-MM')]
  end
$$;

create or replace function public.team_access_ends(p_day date, p_time time)
returns timestamptz language sql stable as $$
  select case when p_day is null then null
              else ((p_day + coalesce(p_time, time '24:00')) at time zone public.agency_tz()) end
$$;

create or replace function public.ai_draft_day()
returns timestamptz
language sql stable set search_path = public as $$
  select (date_trunc('day', now() at time zone public.agency_tz())) at time zone public.agency_tz()
$$;

create or replace function public.ops_engagement_sync_reports(p_engagement uuid, p_moved boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  e public.ops_engagements;
  k text;
  v_ends date;
  v_due timestamptz;
  v_draft timestamptz;
  t public.ops_tasks;
  v_first text;
  res jsonb;
  made integer := 0;
  gone integer := 0;
begin
  select * into e from public.ops_engagements where id = p_engagement;
  if e.id is null or e.status in ('completed', 'cancelled') then
    return jsonb_build_object('made', 0, 'cancelled', 0);
  end if;
  select s.ends into v_ends from public.ops_month_span(e.period, e.start_day) s;
  v_due := ((v_ends + public.app_setting('report_due_days', v_ends)::integer)::timestamp + time '23:59') at time zone public.agency_tz();
  v_draft := v_due - interval '1 day';
  foreach k in array array['social', 'ads'] loop
    /* A report task nobody has started follows the month's manager. */
    if k = any (e.reports) and e.manager_id is not null then
      for t in select * from public.ops_tasks x
                where x.engagement_id = e.id and x.source_type = 'report_' || k
                  and x.cancelled_at is null and x.archived_at is null and x.completed_at is null
                  and x.stage_key = (select s.key from public.ops_workflow_stages s
                                      where s.workflow_id = x.workflow_id order by s.position limit 1)
                  and exists (select 1 from public.ops_task_assignees a
                               where a.task_id = x.id and a.responsibility = 'owner' and a.ended_at is null
                                 and a.team_member_id <> e.manager_id) loop
        update public.ops_task_assignees set ended_at = now()
         where task_id = t.id and responsibility = 'owner' and ended_at is null;
        insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
        values (t.id, e.manager_id, 'owner', e.manager_id);
        update public.ops_tasks set version = version + 1, updated_at = now() where id = t.id;
        perform public.ops_log(t.id, 'assignment_changed', null,
          jsonb_build_object('owner_id', e.manager_id),
          jsonb_build_object('note', 'The month''s manager changed.'));
      end loop;
    end if;
    if k = any (e.reports) then
      if not exists (select 1 from public.ops_tasks x
                      where x.engagement_id = e.id and x.source_type = 'report_' || k
                        and x.cancelled_at is null and x.archived_at is null) then
        res := public.ops_create_task(jsonb_build_object(
          'engagement_id', e.id, 'scope', 'client', 'client_id', e.client_id,
          'workflow_key', 'task', 'task_type', 'engagement', 'deliverable_type', 'report',
          'content_desc', case k when 'social' then 'Accounts report' else 'Advertising report' end,
          'code_period', e.period, 'first_draft_due_at', v_draft, 'final_due_at', v_due,
          'source_type', 'report_' || k,
          'owner_id', e.manager_id, 'manager_id', e.manager_id));
        if res ? 'error' then
          raise exception 'report-task: %', res ->> 'error' using errcode = 'P0001';
        end if;
        /* One date: the task is made with a draft date the day before (so
           neither the order check nor the Report template sets one), then
           it is taken off. */
        update public.ops_tasks set original_first_draft_due_at = null, current_first_draft_due_at = null
         where engagement_id = e.id and source_type = 'report_' || k
           and cancelled_at is null and archived_at is null and first_draft_submitted_at is null;
        made := made + 1;
      elsif p_moved then
        for t in select * from public.ops_tasks x
                  where x.engagement_id = e.id and x.source_type = 'report_' || k
                    and x.cancelled_at is null and x.archived_at is null and x.completed_at is null loop
          update public.ops_tasks set current_final_due_at = v_due,
                 updated_at = now(), version = version + 1
           where id = t.id;
          if t.current_final_due_at is distinct from v_due then
            perform public.ops_log(t.id, 'due_changed',
              jsonb_build_object('kind', 'final', 'value', t.current_final_due_at),
              jsonb_build_object('kind', 'final', 'value', v_due),
              jsonb_build_object('reason', 'scope_change', 'note', 'The month''s start day moved.'));
          end if;
        end loop;
      end if;
    else
      for t in select * from public.ops_tasks x
                where x.engagement_id = e.id and x.source_type = 'report_' || k
                  and x.cancelled_at is null and x.archived_at is null and x.completed_at is null loop
        select s.key into v_first from public.ops_workflow_stages s
         where s.workflow_id = t.workflow_id order by s.position limit 1;
        if t.stage_key = v_first then
          update public.ops_tasks set stage_key = 'cancelled', cancelled_at = now(), updated_at = now(),
                 version = version + 1
           where id = t.id;
          perform public.ops_log(t.id, 'stage_changed', jsonb_build_object('stage_key', t.stage_key),
            jsonb_build_object('stage_key', 'cancelled'),
            jsonb_build_object('note', 'The month no longer asks for this report.'));
          gone := gone + 1;
        end if;
      end loop;
    end if;
  end loop;
  return jsonb_build_object('made', made, 'cancelled', gone);
end $$;

create or replace function public.sm_report_sent(p_id uuid, p_on date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  v_today date := (now() at time zone public.agency_tz())::date;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.status <> 'published' then return jsonb_build_object('error', 'not-published'); end if;
  if p_on is not null and (p_on > v_today or p_on < r.period_start) then return jsonb_build_object('error', 'bad-date'); end if;
  if r.sent_on is not distinct from p_on then return jsonb_build_object('ok', true); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set sent_on = p_on, sent_by = case when p_on is null then null else me.name end where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.saved', 'Sent to client: ' ||
    coalesce(public.register_day(r.sent_on), 'not set') || ' → ' || coalesce(public.register_day(p_on), 'not set'));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.announcement_said(a public.announcements)
returns text
language sql stable set search_path = public as $$
  select case a.audience when 'team' then 'Team' else 'Clients' end || ' announcement: ' || a.body_en
      || case when a.tone = 'important' then ' · Important' else '' end
      || case when a.starts_at is not null
              then ' · from ' || to_char(a.starts_at at time zone public.agency_tz(), 'FMDD Mon YYYY HH24:MI') else '' end
      || case when a.ends_at is not null
              then ' · until ' || to_char(a.ends_at at time zone public.agency_tz(), 'FMDD Mon YYYY HH24:MI') else '' end
$$;

create or replace function public.health_today()
returns date language sql stable as $$
  select (now() at time zone public.agency_tz())::date
$$;

create or replace function public.meta_checks_on()
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.app_setting('meta_checks', (now() at time zone public.agency_tz())::date), 0) = 1
     and public.ops_granted('reports.meta', 'work')
$$;

create or replace function public.ops_priority_by(p_set timestamptz, p_level smallint)
returns timestamptz
language sql stable security definer set search_path = public as $$
  select p_set + make_interval(hours => coalesce(public.app_setting(
           'priority_' || case p_level when 1 then 'urgent' when 2 then 'high' else 'medium' end || '_hours',
           (p_set at time zone public.agency_tz())::date),
           case p_level when 1 then 24 when 2 then 48 else 72 end)::integer)
   where p_level in (1, 2, 4) and p_set is not null
$$;

create or replace function public.sm_report_running(p_id uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select r.period_end >= (now() at time zone public.agency_tz())::date
                     from public.sm_reports r where r.id = p_id), false)
$$;

create or replace function public.rate_card_publish(p_version text, p_valid_until date, p_note text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_ver  text := btrim(coalesce(p_version, ''));
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_snap jsonb := public.rate_card_draft();
  v_last jsonb;
  v_id   uuid;
begin
  if me.id is null or not public.allowed('services', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if v_ver !~ '^[0-9]{1,3}(\.[0-9]{1,3}){1,3}$' then return jsonb_build_object('error', 'bad-version'); end if;
  if exists (select 1 from public.rate_card_versions v where v.version = v_ver) then
    return jsonb_build_object('error', 'version-taken');
  end if;
  if p_valid_until is not null and p_valid_until < (now() at time zone public.agency_tz())::date then
    return jsonb_build_object('error', 'bad-date');
  end if;
  if v_note is not null and length(v_note) > 500 then return jsonb_build_object('error', 'too-long'); end if;
  select v.snapshot into v_last from public.rate_card_versions v order by v.published_at desc limit 1;
  if v_last is not null and v_last->'services' = v_snap->'services' and v_last->'text' = v_snap->'text'
     and v_last->'settings' = v_snap->'settings' then
    return jsonb_build_object('error', 'no-change');
  end if;
  insert into public.rate_card_versions (version, valid_until, note, snapshot, published_by)
  values (v_ver, p_valid_until, v_note, v_snap, me.name)
  returning id into v_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'service.published', 'Rate card',
          'v.' || v_ver || case when p_valid_until is not null then ' · valid until ' || public.register_day(p_valid_until) else '' end ||
          coalesce(' · ' || v_note, ''));
  return jsonb_build_object('ok', true, 'id', v_id, 'version', v_ver);
end $$;

create or replace function public.client_details_link(p_client uuid, p_reset boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  v_cl   public.clients;
  v_f    public.client_detail_forms;
  v_key  text;
  v_days int;
begin
  if me.id is null or not public.allowed('clients.billing', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v_cl from public.clients c where c.id = p_client;
  if v_cl.id is null or not public.client_seen(v_cl.id, 'work') then return jsonb_build_object('error', 'not-found'); end if;
  select * into v_f from public.client_detail_forms f
   where f.client_id = p_client and f.voided_at is null and f.submitted_at is null and f.expires_at > now()
   order by f.created_at desc limit 1;
  if v_f.id is not null and not coalesce(p_reset, false) then
    return jsonb_build_object('ok', true, 'id', v_f.id, 'key', v_f.access_key, 'expires_at', v_f.expires_at);
  end if;
  update public.client_detail_forms f set voided_at = now()
   where f.client_id = p_client and f.voided_at is null and f.submitted_at is null;
  loop
    v_key := public.new_link_key();
    exit when not exists (select 1 from public.client_detail_forms f where f.access_key = v_key);
  end loop;
  v_days := coalesce(public.app_setting('details_form_days', (now() at time zone public.agency_tz())::date), 14)::int;
  insert into public.client_detail_forms (client_id, access_key, created_by, expires_at)
  values (p_client, v_key, (select t.id from public.team_members t where t.id = me.id), now() + make_interval(days => v_days))
  returning * into v_f;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.edited', v_cl.name,
          case when coalesce(p_reset, false) then 'Details form link reset' else 'Details form link created' end);
  return jsonb_build_object('ok', true, 'id', v_f.id, 'key', v_f.access_key, 'expires_at', v_f.expires_at);
end $$;

create or replace function public.rate_card_draft()
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'services', coalesce((select jsonb_agg(jsonb_build_object(
        'slug', s.slug, 'category', s.category, 'name', s.name, 'rate', s.rate, 'unit', s.unit,
        'position', s.position, 'active', s.active, 'note', s.note, 'detail', s.detail,
        'min_months', s.min_months, 'spec', s.spec) order by s.position, s.slug)
      from public.services s), '[]'::jsonb),
    'text', coalesce((select jsonb_object_agg(t.key, t.value) from public.rate_card_text t), '{}'::jsonb),
    'settings', (select jsonb_object_agg(k, public.app_setting(k, (now() at time zone public.agency_tz())::date))
      from unnest(array['sst_pct', 'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24']) k))
$$;

create or replace function public.client_vic_set(p_client uuid, p_on boolean, p_note text default null,
                                                 p_since date default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  c public.clients;
  v_note text := case when coalesce(p_on, false) then nullif(btrim(coalesce(p_note, '')), '') end;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_was date;
  v_day date;
  v_at timestamptz;
  v_detail text;
  v_by text;
begin
  m := public.ops_me();
  if m.id is null or not public.ops_granted('clients.vic', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into c from public.clients where id = p_client;
  if c.id is null or not public.client_seen(p_client, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if char_length(coalesce(v_note, '')) > 300 then
    return jsonb_build_object('error', 'too-long');
  end if;
  if p_since is not null and (p_since > v_today or p_since < date '2023-08-14') then
    return jsonb_build_object('error', 'bad-date');
  end if;
  v_was := (c.vic_at at time zone public.agency_tz())::date;
  v_day := case when coalesce(p_on, false) then coalesce(p_since, v_was, v_today) end;
  v_at := case when v_day is null then null
               when v_day = v_was then c.vic_at
               when v_day = v_today then now()
               else (v_day::timestamp + time '12:00') at time zone public.agency_tz() end;
  if (c.vic_at is not null) = coalesce(p_on, false) and c.vic_note is not distinct from v_note
     and v_at is not distinct from c.vic_at then
    select t.name into v_by from public.team_members t where t.id = c.vic_by;
    return jsonb_build_object('ok', true, 'since', c.vic_at, 'by_name', v_by, 'note', c.vic_note);
  end if;
  v_detail := case
    when coalesce(p_on, false) and c.vic_at is null
      then 'VIC: off → on · since ' || public.vic_day(v_day) || coalesce(' · ' || v_note, '')
    when not coalesce(p_on, false) then 'VIC: on → off'
    else concat_ws(' · ',
      case when v_day is distinct from v_was then 'VIC since: ' || public.vic_day(v_was) || ' → ' || public.vic_day(v_day) end,
      case when c.vic_note is distinct from v_note
           then 'VIC note: ' || coalesce(c.vic_note, 'not set') || ' → ' || coalesce(v_note, 'not set') end) end;
  perform set_config('adspace.vic', 'on', true);
  update public.clients
     set vic_at = v_at,
         vic_by = case when coalesce(p_on, false) then case when c.vic_at is null then m.id else c.vic_by end end,
         vic_note = v_note
   where id = p_client
  returning * into c;
  perform set_config('adspace.vic', '', true);
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(nullif(m.name, ''), m.email), 'client.edited', c.name, v_detail);
  select t.name into v_by from public.team_members t where t.id = c.vic_by;
  return jsonb_build_object('ok', true, 'since', c.vic_at, 'by_name', v_by, 'note', c.vic_note);
end $$;

create or replace function public.perf_today()
returns date language sql stable as $$
  select (now() at time zone public.agency_tz())::date
$$;

create or replace function public.perf_overview(p_period date)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare me_row public.team_members; m date;
begin
  me_row := public.ops_me();
  if me_row.id is null or not public.ops_granted('team.performance', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  m := date_trunc('month', coalesce(p_period, (now() at time zone public.agency_tz())::date))::date;
  return jsonb_build_object('period', m, 'rows', coalesce((
    select jsonb_agg(jsonb_build_object('team_member_id', t.id, 'name', t.name,
             'status', coalesce(r.status, 'none')) order by t.name)
      from public.team_members t
      left join public.perf_reviews r on r.team_member_id = t.id and r.period = m
     where t.id is distinct from me_row.id
       and ((t.active and public.perf_reviewed(t.id)) or r.id is not null)), '[]'::jsonb));
end $$;

create or replace function public.portal_meetings(p_client uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
begin
  if auth.jwt() ->> 'email' is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  if p_client is null or p_client not in (select public.portal_clients()) then
    return jsonb_build_object('error', 'no-access');
  end if;
  /* The content meetings the team has put in the diary, from three months
     back. Nothing about the month's tasks, checks or status beyond this: a
     client reads when we meet, never how the work inside the month is going.
     The link is sent only while the meeting is still ahead. The three
     months are counted on Malaysia's calendar, then made a moment
     (2026-10-17: `at time zone` binds before `-`, so they were counted on
     the UTC calendar, and in March the window opened on 29 November). */
  /* Beside them, the meetings the team booked outside a month (Calls and
     visits, kind meeting, with a time; 2026-10-05): the time, the length
     and the link, never what was written about it. */
  return jsonb_build_object('meetings', coalesce((
    select jsonb_agg(x.j order by x.at desc) from (
      select e.meeting_at as at, jsonb_build_object(
               'kind', 'content', 'period', e.period, 'at', e.meeting_at, 'minutes', coalesce(e.meeting_minutes, 30),
               'channel', e.meeting_channel,
               'link', case when e.meeting_at + make_interval(mins => coalesce(e.meeting_minutes, 30)) > now()
                            then e.meeting_link end) as j
        from public.ops_engagements e
       where e.client_id = p_client
         and e.meeting_at is not null
         and not coalesce(e.meeting_na, false)
         and e.status <> 'cancelled'
         and e.meeting_at >= (date_trunc('month', now() at time zone public.agency_tz()) - interval '3 months') at time zone public.agency_tz()
      union all
      select t.meet_at, jsonb_build_object(
               'kind', 'meeting', 'period', null, 'at', t.meet_at, 'minutes', coalesce(t.meet_minutes, 30),
               'channel', case when t.meet_link ~* 'meet\.google\.com' then 'google_meet'
                               when t.meet_link ~* 'zoom\.us' then 'zoom'
                               when t.meet_link ~* 'teams\.' then 'teams' end,
               'link', case when t.meet_at + make_interval(mins => coalesce(t.meet_minutes, 30)) > now()
                            then t.meet_link end)
        from public.client_touches t
       where t.client_id = p_client
         and t.kind = 'meeting' and t.meet_at is not null and t.archived_at is null
         and t.meet_at >= (date_trunc('month', now() at time zone public.agency_tz()) - interval '3 months') at time zone public.agency_tz()) x), '[]'::jsonb));
end $$;

create or replace function public.perf_self_open(p_member uuid, p_period date)
returns text
language sql stable security definer set search_path = public as $$
  select case
    when p_period is null or extract(day from p_period) <> 1 or p_period < date '2026-06-01'
      or p_period >= date_trunc('month', public.perf_today())::date
      then 'bad-month'
    when exists (select 1 from public.perf_reviews r
                  where r.team_member_id = p_member and r.period = p_period and r.status <> 'draft')
      then 'shared'
    when not exists (select 1 from public.perf_reviews r
                      where r.team_member_id = p_member and r.period = p_period)
     and (not coalesce(public.perf_reviewed(p_member), false)
          or p_period < (select date_trunc('month', t.created_at at time zone public.agency_tz())::date
                           from public.team_members t where t.id = p_member))
      then 'not-reviewed'
  end
$$;

create or replace function public.perf_breach_log(p_token text, p_member uuid, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  err text; m public.team_members; on_ date; p date; cat text; sev integer; rep boolean;
  st text; nb public.perf_breaches; cl uuid;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  if p_member = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if not exists (select 1 from public.team_members where id = p_member and active) then
    return jsonb_build_object('error', 'not-found');
  end if;
  begin on_ := (p_payload ->> 'occurred_on')::date; exception when others then on_ := null; end;
  if on_ is null or on_ > (now() at time zone public.agency_tz())::date then return jsonb_build_object('error', 'bad-date'); end if;
  cat := p_payload ->> 'category';
  if cat is null or cat not in ('client', 'delivery', 'compliance', 'asset') then
    return jsonb_build_object('error', 'bad-category');
  end if;
  sev := case when (p_payload ->> 'severity') ~ '^[1-4]$' then (p_payload ->> 'severity')::integer end;
  if sev is null then return jsonb_build_object('error', 'bad-severity'); end if;
  if coalesce(btrim(p_payload ->> 'what'), '') = '' then return jsonb_build_object('error', 'what-needed'); end if;
  /* The client it concerns, optional (2026-10-15): a VIC client's issue
     counts double, stamped at logging. */
  if nullif(p_payload ->> 'client_id', '') is not null then
    begin cl := (p_payload ->> 'client_id')::uuid; exception when others then cl := null; end;
    if cl is null or not exists (select 1 from public.clients c where c.id = cl) then
      return jsonb_build_object('error', 'bad-client');
    end if;
  end if;
  p := date_trunc('month', on_)::date;
  select status into st from public.perf_reviews where team_member_id = p_member and period = p;
  if st is not null and st <> 'draft' then
    return jsonb_build_object('error', 'month-released', 'month', public.perf_month_word(p));
  end if;
  /* The same kind of breach earlier in the same quarter is a repeat, unless
     the reviewer says otherwise. */
  rep := case when p_payload ? 'repeated' and jsonb_typeof(p_payload -> 'repeated') = 'boolean'
              then (p_payload ->> 'repeated')::boolean
              else exists (select 1 from public.perf_breaches b
                            where b.team_member_id = p_member and b.category = cat
                              and b.voided_at is null
                              and date_trunc('quarter', b.occurred_on) = date_trunc('quarter', on_)
                              and b.occurred_on <= on_) end;
  insert into public.perf_breaches (team_member_id, occurred_on, period, category, severity,
                                    repeated, late, what, evidence, logged_by, client_id)
  values (p_member, on_, p, cat, sev, rep, coalesce((p_payload ->> 'late')::boolean, false),
          btrim(p_payload ->> 'what'), nullif(btrim(p_payload ->> 'evidence'), ''), m.id, cl)
  returning * into nb;
  perform public.perf_log((select id from public.perf_reviews where team_member_id = p_member and period = p),
    p_member, 'breach_logged', jsonb_build_object('breach', nb.id, 'category', cat, 'severity', sev,
      'repeated', rep, 'late', nb.late, 'vic', nb.vic,
      'deduction', round(public.perf_points_at(sev, rep, nb.late, nb.vic, p), 2)));
  return jsonb_build_object('ok', true, 'id', nb.id, 'repeated', rep, 'vic', nb.vic,
    'deduction', round(public.perf_points_at(sev, rep, nb.late, nb.vic, p), 2), 'period', p);
end $$;

create or replace function public.team_expiry_hand_back(p_member uuid)
returns int language plpgsql security definer set search_path = public as $$
declare
  v_who public.team_members;
  t public.ops_tasks;
  v_to uuid;
  v_title text;
  n int := 0;
begin
  select * into v_who from public.team_members where id = p_member;
  if v_who.id is null then return 0; end if;
  for t in select k.* from public.ops_tasks k
             join public.ops_task_assignees a on a.task_id = k.id
            where a.team_member_id = p_member and a.responsibility = 'owner' and a.ended_at is null
              and k.completed_at is null and k.cancelled_at is null and k.archived_at is null
            order by k.task_no loop
    v_to := case when t.created_by is not null and t.created_by <> p_member
                       and public.ops_takes_tasks(t.created_by) then t.created_by end;
    v_title := public.ops_serial(t.task_no) || ' · ' || public.ops_title(t);
    update public.ops_task_assignees set ended_at = now()
     where task_id = t.id and responsibility = 'owner' and ended_at is null;
    if v_to is not null then
      insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
      values (t.id, v_to, 'owner', null);
      update public.ops_tasks set version = version + 1, updated_at = now() where id = t.id;
      perform public.ops_notify(v_to, t.id, 'assigned', v_title,
        'Handed back to you: ' || v_who.name || '''s access ended.',
        'returned:' || t.id::text || ':' || v_to::text || ':' || to_char(now() at time zone public.agency_tz(), 'YYYYMMDDHH24MI'));
    else
      update public.ops_tasks set open_at = now(), open_by = null, version = version + 1, updated_at = now()
       where id = t.id;
      perform public.ops_notify(x.id, t.id, 'tasks.unassigned', v_title,
        v_who.name || '''s access ended. The task is open to take.',
        'unassigned:' || t.id::text || ':' || x.id::text || ':' || to_char(now() at time zone public.agency_tz(), 'YYYYMMDDHH24MI'))
        from public.team_members x
       where x.active and x.id <> p_member and not coalesce(x.system, false)
         and (coalesce(x.is_admin, false) or coalesce(x.role, '') = 'admin' or public.level_rank(x.access ->> 'ops') >= 3)
         and public.ops_takes_tasks(x.id);
    end if;
    insert into public.ops_task_events (task_id, event_type, actor_id, actor_email, from_value, to_value, detail)
    values (t.id, 'assignment_changed', null, null,
            jsonb_build_object('owner_id', p_member), jsonb_build_object('owner_id', v_to),
            jsonb_build_object('expired', true, 'note',
              case when v_to is not null then 'Access ended; handed back to whoever created it.'
                   else 'Access ended; open to take.' end));
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.ops_add_business_days(p_from timestamptz, p_days integer)
returns timestamptz
language plpgsql stable security definer set search_path = public as $$
declare
  d   timestamptz := p_from;
  n   integer := abs(coalesce(p_days, 0));
  dir integer := case when coalesce(p_days, 0) < 0 then -1 else 1 end;
begin
  if p_from is null then return null; end if;
  while n > 0 loop
    d := d + (dir || ' day')::interval;
    -- 0 is Sunday, 6 is Saturday in Postgres `dow`; a public holiday is no working day.
    if extract(dow from d at time zone public.agency_tz()) not in (0, 6)
       and not exists (select 1 from public.public_holidays h
                        where h.day = (d at time zone public.agency_tz())::date) then
      n := n - 1;
    end if;
  end loop;
  return d;
end $$;

create or replace function public.ops_tasks_revision_due()
returns trigger
language plpgsql security definer set search_path = public as $$
declare v_day date; v_due timestamptz;
begin
  if new.stage_key <> 'revision_client' or old.stage_key is not distinct from new.stage_key then return null; end if;
  v_day := (now() at time zone public.agency_tz())::date;
  v_due := ((public.ops_add_business_days(v_day::timestamp at time zone public.agency_tz(),
              coalesce(public.app_setting('revision_due_days', v_day), 1)::integer)
             at time zone public.agency_tz())::date::timestamp) at time zone 'UTC';
  if new.current_final_due_at is not null and new.current_final_due_at >= v_due then return null; end if;
  update public.ops_tasks set current_final_due_at = v_due, updated_at = now() where id = new.id;
  perform public.ops_log(new.id, 'due_changed',
    jsonb_build_object('kind', 'final', 'value', new.current_final_due_at),
    jsonb_build_object('kind', 'final', 'value', v_due),
    jsonb_build_object('reason', 'client_request', 'note', 'The client asked for changes.', 'auto', true));
  return null;
end $$;

create or replace function public.ops_log(
  p_task uuid, p_type text, p_from jsonb, p_to jsonb, p_detail jsonb default '{}'::jsonb)
returns void
language plpgsql security definer set search_path = public as $$
declare
  m      public.team_members;
  t      public.ops_tasks;
  owner  uuid;
  who    text;
  body   text;
  st     public.ops_workflow_stages;
begin
  m := public.ops_me();
  insert into public.ops_task_events (task_id, event_type, actor_id, actor_email,
                                      from_value, to_value, detail)
  values (p_task, p_type, m.id, m.email, p_from, p_to, coalesce(p_detail, '{}'::jsonb));

  select * into t from public.ops_tasks where id = p_task;
  if t.id is null then return; end if;
  who := coalesce(nullif(m.name, ''), m.email, 'Somebody');

  if p_type = 'assignment_changed' then
    owner := (p_to ->> 'owner_id')::uuid;
    if owner is not null and owner is distinct from m.id then
      perform public.ops_notify(owner, p_task, 'assigned',
        public.ops_serial(t.task_no) || ' · ' || public.ops_title(t),
        case when coalesce((p_detail ->> 'handover')::boolean, false)
             then 'Handed to you by ' || who || ' at ' ||
                  coalesce((public.ops_stage(t.workflow_id, p_detail ->> 'stage_key')).label, p_detail ->> 'stage_key') || '.'
             else 'Assigned to you by ' || who || '.' end,
        'assigned:' || p_task::text || ':' || owner::text || ':' || to_char(now(), 'YYYYMMDDHH24MI'));
    end if;
    return;
  end if;

  select team_member_id into owner from public.ops_task_assignees
   where task_id = p_task and responsibility = 'owner' and ended_at is null
   limit 1;
  if owner is null or owner = m.id then return; end if;

  if p_type = 'stage_changed' then
    /* One press, one notice (2026-10-18): a move that also handed the task
       on has already told its new owner, in the same transaction, with the
       stage it was handed at. */
    if exists (select 1 from public.ops_task_events e
                where e.task_id = p_task and e.event_type = 'assignment_changed'
                  and e.created_at = now()
                  and coalesce((e.detail ->> 'handover')::boolean, false)
                  and e.to_value ->> 'owner_id' = owner::text) then
      return;
    end if;
    st := public.ops_stage(t.workflow_id, p_to ->> 'stage_key');
    body := 'Moved to ' || coalesce(st.label, p_to ->> 'stage_key')
      || coalesce(', round ' || (p_detail ->> 'round'), '') || ' by ' || who || '.';
  elsif p_type = 'due_changed' then
    body := 'The ' || case when p_to ->> 'kind' = 'final' then 'final' else 'first draft' end
      || ' date moved to ' || public.register_day(((p_to ->> 'value')::timestamptz at time zone public.agency_tz())::date)
      || ' by ' || who || '.';
  elsif p_type = 'blocked' then
    body := 'Marked blocked by ' || who || ': '
      || coalesce(p_detail ->> 'category', 'reason not given') || '.';
  elsif p_type = 'unblocked' then
    body := 'Unblocked by ' || who || '.';
  elsif p_type = 'revision_requested' then
    body := 'A revision was requested by ' || who || '.';
  elsif p_type = 'approval_recorded' then
    body := 'A review decision was recorded by ' || who || '.';
  elsif p_type = 'reopened' then
    body := 'Reopened by ' || who || '.';
  elsif p_type = 'cancelled' then
    body := 'Cancelled by ' || who || '.';
  elsif p_type = 'commented' then
    body := who || ' commented: ' ||
      case when length(coalesce(p_detail ->> 'note', '')) > 140
           then left(p_detail ->> 'note', 139) || '…' else coalesce(p_detail ->> 'note', '') end;
  else
    return;
  end if;

  perform public.ops_notify(owner, p_task, p_type,
    public.ops_serial(t.task_no) || ' · ' || public.ops_title(t), body,
    p_type || ':' || p_task::text || ':' || owner::text || ':' ||
      /* Two comments in one minute are two things said; the same change
         twice in a minute is one. */
      case when p_type = 'commented' then md5(body) else to_char(now(), 'YYYYMMDDHH24MI') end);
end $$;

create or replace function public.supplier_link(p_id uuid, p_reset boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  s     public.suppliers;
  f     public.supplier_forms;
  v_key text;
  v_days int;
  v_purpose text;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  v_purpose := case when s.status = 'pending' then 'details' else 'update' end;
  select * into f from public.supplier_forms x
   where x.supplier_id = p_id and x.voided_at is null and x.submitted_at is null and x.expires_at > now()
   order by x.created_at desc limit 1;
  if f.id is not null and not coalesce(p_reset, false) then
    return jsonb_build_object('ok', true, 'id', f.id, 'key', f.access_key, 'expires_at', f.expires_at, 'purpose', f.purpose);
  end if;
  update public.supplier_forms x set voided_at = now()
   where x.supplier_id = p_id and x.voided_at is null and x.submitted_at is null;
  loop
    v_key := public.new_link_key();
    exit when not exists (select 1 from public.supplier_forms x where x.access_key = v_key);
  end loop;
  v_days := coalesce(public.app_setting('details_form_days', (now() at time zone public.agency_tz())::date), 14)::int;
  insert into public.supplier_forms (supplier_id, access_key, created_by, expires_at, purpose)
  values (p_id, v_key, me.id, now() + make_interval(days => v_days), v_purpose)
  returning * into f;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'supplier.edited', coalesce(s.name, s.code),
          s.code || ' · ' || case when v_purpose = 'update' then 'Update link' else 'Details form link' end ||
          case when coalesce(p_reset, false) then ' reset' else ' created' end);
  return jsonb_build_object('ok', true, 'id', f.id, 'key', f.access_key, 'expires_at', f.expires_at, 'purpose', f.purpose);
end $$;

create or replace function public.client_checklist(p_client uuid, p_kind text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.client_checklists;
  t jsonb;
  pre jsonb;
  hints jsonb := '{}'::jsonb;
  q record;
  m timestamptz;
begin
  if me.id is null or not public.allowed('clients.checklists', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_scope_ok('client', p_client, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  if p_kind not in ('onboarding', 'pre_ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select * into r from public.client_checklists where client_id = p_client and kind = p_kind;
  t := coalesce(r.template, public.checklist_template(p_kind));
  pre := public.checklist_prefill(p_client, p_kind);
  -- Once started, only what each reader's own access gives (the registered
  -- name, the quotation) is worked out on the read; it is never stored.
  if r.id is not null then
    pre := jsonb_strip_nulls(jsonb_build_object('details.entity', pre->'details.entity',
                                                'details.quotation', pre->'details.quotation'));
  end if;
  if p_kind = 'onboarding' and public.allowed('clients.quotes', 'view') then
    select x.ref, x.issued_at into q from public.quotations x
     where x.client_id = p_client and x.removed_at is null order by x.issued_at desc limit 1;
    if q.ref is not null then
      hints := hints || jsonb_build_object('pre.quotation', 'Quotation ' || q.ref || ' issued ' ||
        to_char(q.issued_at at time zone public.agency_tz(), 'FMDD Mon YYYY'));
    end if;
  end if;
  if p_kind = 'onboarding' then
    select min(e.meeting_at) into m from public.ops_engagements e where e.client_id = p_client and e.meeting_at is not null;
    if m is not null then
      hints := hints || jsonb_build_object('pre.first_meeting', 'Meeting set for ' ||
        to_char(m at time zone public.agency_tz(), 'FMDD Mon YYYY, FMHH12:MIam'));
    end if;
  end if;
  return jsonb_build_object(
    'kind', p_kind, 'title', t->>'title', 'version', t->>'version', 'lead', t->>'lead', 'sections', t->'sections',
    'started', r.id is not null, 'answers', coalesce(r.answers, '{}'::jsonb), 'prefill', coalesce(pre, '{}'::jsonb),
    'sections_na', to_jsonb(coalesce(r.sections_na, '{}'::text[])), 'status', coalesce(r.status, 'open'),
    'prepared', case when r.prepared_at is not null then jsonb_build_object('id', r.prepared_by, 'name', r.prepared_name, 'at', r.prepared_at) end,
    'reviewed', case when r.reviewed_at is not null then jsonb_build_object('id', r.reviewed_by, 'name', r.reviewed_name, 'at', r.reviewed_at) end,
    'history', jsonb_array_length(coalesce(r.history, '[]'::jsonb)),
    'hints', hints, 'me', me.id, 'filled_by_me', public.checklist_filled_by(r.answers, me.id, me.name),
    'can_work', public.allowed('clients.checklists', 'work') and public.client_scope_ok('client', p_client, 'work'),
    'can_manage', public.allowed('clients.checklists', 'manage') and public.client_scope_ok('client', p_client, 'manage'),
    'updated_at', r.updated_at);
end $$;

create or replace function public.client_checklists_due()
returns jsonb
language sql stable security definer set search_path = public as $$
  select case when (public.ops_me()).id is null or not public.allowed('clients.checklists', 'view') then '[]'::jsonb else
    coalesce((select jsonb_agg(jsonb_build_object('client_id', c.id, 'name', c.name, 'slug', c.slug, 'owner', c.owner,
              'kind', k.kind, 'status', coalesce(r.status, 'open'), 'started', r.id is not null,
              'since', coalesce(c.stage_since, c.created_at)) order by coalesce(c.stage_since, c.created_at))
       from public.clients c
       cross join (values ('onboarding'), ('pre_ads')) k(kind)
       left join public.client_checklists r on r.client_id = c.id and r.kind = k.kind
      where c.stage = 'active'
        and coalesce(r.status, 'open') <> 'signed'
        and (r.id is not null
             or (select min((e->>'at')::timestamptz) from jsonb_array_elements(coalesce(c.stage_log, '[]'::jsonb)) e
                  where e->>'stage' = 'active' and e->>'at' is not null)
                >= ('2026-10-15'::date)::timestamp at time zone public.agency_tz())
        and public.client_scope_ok('client', c.id, 'view')
        and not exists (select 1 from public.ops_engagement_checks x join public.ops_engagements e on e.id = x.engagement_id
                         where e.client_id = c.id and x.key = k.kind and x.state = 'na')), '[]'::jsonb) end
$$;

create or replace function public.quote_fx(p_client uuid)
returns numeric
language sql stable security definer set search_path = public as $$
  select case when exists (select 1 from public.clients c where c.id = p_client and c.market = 'SG' and c.bill_sgd)
              then coalesce(nullif(public.app_setting('fx_sgd', (now() at time zone public.agency_tz())::date), 0), 0) end
$$;

create or replace function public.app_setting(p_key text, p_at date)
returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select s.value from public.app_settings s where s.key = p_key and s.from_date <= coalesce(p_at, (now() at time zone public.agency_tz())::date)
      order by s.from_date desc limit 1),
    (select s.value from public.app_settings s where s.key = p_key and s.set_by is null order by s.from_date limit 1))
$$;

create or replace function public.team_place_ok(p_admin boolean, p_member uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(p_admin, false)
      or public.team_home_country(public.request_country())
      or exists (select 1 from public.team_abroad a
                  where a.team_member_id = p_member and a.status = 'approved'
                    and a.until >= (now() at time zone public.agency_tz())::date)
$$;

create or replace function public.abroad_state()
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  t public.team_members := public.abroad_who();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_admin boolean;
  a public.team_abroad;
begin
  if t.id is null then return jsonb_build_object('team', false); end if;
  v_admin := t.is_admin or t.role = 'admin';
  select * into a from public.team_abroad x where x.team_member_id = t.id order by x.asked_at desc limit 1;
  return jsonb_build_object(
    'team', true, 'admin', v_admin, 'country', public.request_country(),
    'held', not public.team_place_ok(v_admin, t.id),
    'today', v_today,
    'days', coalesce(public.app_setting('abroad_days', v_today), 14)::int,
    'request', case when a.id is null then null else jsonb_build_object(
      'id', a.id, 'status', case when a.status = 'approved' and a.until < v_today then 'expired' else a.status end,
      'until', a.until, 'country', a.country, 'reason', a.reason, 'note', a.note,
      'asked_at', a.asked_at, 'decided_at', a.decided_at) end);
end $$;

create or replace function public.abroad_list()
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare v_today date := (now() at time zone public.agency_tz())::date;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'today', v_today,
    'days', coalesce(public.app_setting('abroad_days', v_today), 14)::int,
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'id', a.id, 'member', a.team_member_id, 'name', m.name, 'code', m.staff_code,
        'country', a.country, 'reason', a.reason, 'until', a.until, 'note', a.note,
        'status', case when a.status = 'approved' and a.until < v_today then 'expired' else a.status end,
        'asked_at', a.asked_at, 'decided_at', a.decided_at,
        'decided_by', (select d.name from public.team_members d where d.id = a.decided_by))
        order by (a.status = 'waiting') desc, (a.status = 'approved' and a.until >= v_today) desc, a.asked_at desc)
      from public.team_abroad a join public.team_members m on m.id = a.team_member_id
     where a.status = 'waiting' or (a.status = 'approved' and a.until >= v_today)
        or a.asked_at > now() - interval '90 days'), '[]'::jsonb));
end $$;

create or replace function public.abroad_decide(p_id uuid, p_approve boolean, p_until date default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_days int := coalesce(public.app_setting('abroad_days', (now() at time zone public.agency_tz())::date), 14)::int;
  v_note text := nullif(btrim(regexp_replace(coalesce(p_note, ''), '\s+', ' ', 'g')), '');
  a public.team_abroad; v_name text;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  select * into a from public.team_abroad x where x.id = p_id for update;
  if a.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if a.status <> 'waiting' then return jsonb_build_object('error', 'not-waiting'); end if;
  if char_length(coalesce(v_note, '')) > 300 then return jsonb_build_object('error', 'too-long'); end if;
  if coalesce(p_approve, false) and (p_until is null or p_until < v_today or p_until > v_today + v_days) then
    return jsonb_build_object('error', 'bad-until', 'max', v_today + v_days);
  end if;
  update public.team_abroad
     set status = case when p_approve then 'approved' else 'declined' end,
         until = case when p_approve then p_until else until end,
         note = v_note, decided_by = v_me.id, decided_at = now()
   where id = a.id;
  select m.name into v_name from public.team_members m where m.id = a.team_member_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_me.name, 'admin'), 'team.changed', 'Overseas access',
    coalesce(v_name, 'A colleague') || ': ' ||
    case when p_approve then 'approved until ' || public.register_day(p_until) else 'declined' end ||
    case when a.country <> '' then ' · from ' || a.country else '' end ||
    case when v_note is not null then ' · ' || v_note else '' end);
  insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
  values (a.team_member_id, 'abroad.decided',
    case when p_approve then 'Overseas access approved until ' || public.register_day(p_until)
         else 'Overseas access declined' end,
    v_note, 'abroad.decided:' || a.id)
  on conflict (dedupe_key) do nothing;
  return public.abroad_list();
end $$;

create or replace function public.abroad_end(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  a public.team_abroad; v_name text;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  select * into a from public.team_abroad x where x.id = p_id for update;
  if a.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if a.status <> 'approved' or a.until < v_today then return jsonb_build_object('error', 'not-approved'); end if;
  update public.team_abroad set status = 'ended', decided_by = v_me.id, decided_at = now() where id = a.id;
  select m.name into v_name from public.team_members m where m.id = a.team_member_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_me.name, 'admin'), 'team.changed', 'Overseas access',
    coalesce(v_name, 'A colleague') || ': ended · was approved until ' || public.register_day(a.until));
  insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
  values (a.team_member_id, 'abroad.decided', 'Overseas access ended', null, 'abroad.ended:' || a.id)
  on conflict (dedupe_key) do nothing;
  return public.abroad_list();
end $$;

create or replace function public.abroad_request(p_reason text, p_until date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  t public.team_members := public.abroad_who();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_days int := coalesce(public.app_setting('abroad_days', (now() at time zone public.agency_tz())::date), 14)::int;
  v_reason text := btrim(regexp_replace(coalesce(p_reason, ''), '\s+', ' ', 'g'));
  v_country text := public.request_country();
  v_id uuid;
begin
  if t.id is null then return jsonb_build_object('error', 'denied'); end if;
  if t.is_admin or t.role = 'admin' then return jsonb_build_object('error', 'admin'); end if;
  if char_length(v_reason) < 3 or char_length(v_reason) > 300 then return jsonb_build_object('error', 'bad-reason'); end if;
  if p_until is null or p_until < v_today or p_until > v_today + v_days then
    return jsonb_build_object('error', 'bad-until', 'max', v_today + v_days);
  end if;
  select x.id into v_id from public.team_abroad x
   where x.team_member_id = t.id and x.status = 'waiting' order by x.asked_at desc limit 1 for update;
  if v_id is null then
    insert into public.team_abroad (team_member_id, country, reason, until)
    values (t.id, v_country, v_reason, p_until) returning id into v_id;
  else
    update public.team_abroad set country = v_country, reason = v_reason, until = p_until, asked_at = now(), reminded_at = null
     where id = v_id;
  end if;
  insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
  select m.id, 'abroad.request', 'Overseas access requested · ' || t.name,
         case when v_country <> '' then 'From ' || v_country || ' · ' else '' end ||
         'until ' || public.register_day(p_until) || ' · ' || v_reason,
         'abroad:' || v_id || ':' || m.id || ':' || to_char(now() at time zone public.agency_tz(), 'YYYYMMDDHH24MI')
    from public.team_members m
   where m.active and (m.is_admin or m.role = 'admin')
  on conflict (dedupe_key) do nothing;
  return public.abroad_state();
end $$;

create or replace function public.abroad_remind()
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_hours numeric := coalesce(public.app_setting('abroad_remind_hours', (now() at time zone public.agency_tz())::date), 2);
  v_today date := (now() at time zone public.agency_tz())::date;
  v_n int := 0;
  r record;
begin
  if v_hours <= 0 then return 0; end if;
  for r in
    select x.id, x.country, x.reason, x.until, t.name
      from public.team_abroad x join public.team_members t on t.id = x.team_member_id
     where x.status = 'waiting' and t.active and x.until >= v_today
       and greatest(x.asked_at, coalesce(x.reminded_at, x.asked_at)) <= now() - make_interval(mins => (v_hours * 60)::int)
     order by x.asked_at
     for update of x skip locked
  loop
    update public.team_abroad set reminded_at = now() where id = r.id;
    insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
    select m.id, 'abroad.request', 'Overseas access waiting · ' || r.name,
           case when r.country <> '' then 'From ' || r.country || ' · ' else '' end ||
           'until ' || public.register_day(r.until) || ' · ' || r.reason,
           'abroad:' || r.id || ':remind:' || m.id || ':' || to_char(now() at time zone public.agency_tz(), 'YYYYMMDDHH24MI')
      from public.team_members m
     where m.active and (m.is_admin or m.role = 'admin')
    on conflict (dedupe_key) do nothing;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

create or replace function public.quote_reply_by(p_at timestamptz)
returns timestamptz
language sql stable security definer set search_path = public as $$
  select public.ops_add_business_days(p_at,
    coalesce(public.app_setting('quote_reply_days', (p_at at time zone public.agency_tz())::date), 2)::int)
$$;

create or replace function public.quote_ref(p_brand text, p_at timestamptz)
returns text
language plpgsql volatile security definer set search_path = public as $$
declare
  v_z text := upper(left(regexp_replace(coalesce(p_brand, ''), '[^A-Za-z]', '', 'g'), 1));
  v_head text;
  v_n int;
begin
  if v_z = '' then v_z := 'X'; end if;
  v_head := 'ADP/QT' || to_char(p_at at time zone public.agency_tz(), 'YYMM') || '-' || v_z;
  perform pg_advisory_xact_lock(hashtext('quote_ref:' || v_head));
  -- A deleted quotation's reference is kept, so it is never issued again.
  select coalesce(max(substr(x.ref, length(v_head) + 1)::int), 0) + 1 into v_n
    from (select q.ref from public.quotations q
          union all
          select k.ref from public.quotation_refs_kept k) x
   where x.ref like v_head || '%' and substr(x.ref, length(v_head) + 1) ~ '^[0-9]+$';
  return v_head || lpad(v_n::text, 2, '0');
end $$;

create or replace function public.client_request_delete(p_id uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r  public.client_requests;
  v_name text;
begin
  if me.id is null or not public.allowed('clients.requests', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.client_requests where id = p_id for update;
  if r.id is null or not public.client_scope_ok('client', r.client_id, 'manage') then
    return jsonb_build_object('error', 'not-found');
  end if;
  select c.name into v_name from public.clients c where c.id = r.client_id;
  delete from public.client_requests where id = r.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'request.deleted', v_name,
          public.client_request_word(r.kind) || coalesce(' · ' || r.service_label, '') ||
          ' · ' || public.register_day((r.created_at at time zone public.agency_tz())::date));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.client_email_set(p_on boolean)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_was  numeric;
  v_to   numeric := case when coalesce(p_on, false) then 1 else 0 end;
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_was := public.app_setting('client_email_on', v_today);
  if v_was is not distinct from v_to then return jsonb_build_object('ok', true); end if;
  insert into public.app_settings (key, from_date, value, set_by, set_at)
  values ('client_email_on', v_today, v_to, me.id, now())
  on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Settings',
          'Send by email: ' || case when v_was = 1 then 'On' else 'Off' end || ' → ' ||
          case when v_to = 1 then 'On' else 'Off' end || ' · from ' || public.register_day(v_today));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.report_links_on()
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.app_setting('report_post_links', (now() at time zone public.agency_tz())::date), 0) = 1
$$;

create or replace function public.report_links_set(p_on boolean)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_was  numeric;
  v_to   numeric := case when coalesce(p_on, false) then 1 else 0 end;
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_was := public.app_setting('report_post_links', v_today);
  if v_was is not distinct from v_to then return jsonb_build_object('ok', true); end if;
  insert into public.app_settings (key, from_date, value, set_by, set_at)
  values ('report_post_links', v_today, v_to, me.id, now())
  on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Settings',
          'Posts linked to tasks: ' || case when v_was = 1 then 'On' else 'Off' end || ' → ' ||
          case when v_to = 1 then 'On' else 'Off' end || ' · from ' || public.register_day(v_today));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.ops_engagement_set_meeting(
  p_engagement uuid, p_at timestamptz, p_channel text default null,
  p_owner uuid default null, p_note text default null, p_na boolean default false,
  p_minutes integer default null, p_link text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; e public.ops_engagements; lk text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.ops_may_see_engagement(p_engagement) then return jsonb_build_object('error', 'denied'); end if;
  select * into e from public.ops_engagements where id = p_engagement for update;
  if e.id is null then return jsonb_build_object('error', 'not-found'); end if;

  if coalesce(p_na, false) then
    update public.ops_engagements set meeting_na = true, meeting_note = coalesce(p_note, meeting_note),
           meeting_link = null, updated_at = now(), version = version + 1 where id = p_engagement;
    perform public.ops_engagement_log(p_engagement, 'meeting_na', jsonb_build_object('note', p_note));
    return public.ops_engagement_json(p_engagement);
  end if;
  if p_at is null then return jsonb_build_object('error', 'no-date'); end if;
  if p_channel is not null and p_channel not in ('onsite', 'google_meet', 'zoom', 'other') then
    return jsonb_build_object('error', 'bad-channel');
  end if;
  if (p_at at time zone public.agency_tz())::date < date '2023-08-14' then
    return jsonb_build_object('error', 'meeting-before-floor');
  end if;
  if p_minutes is not null and (p_minutes < 15 or p_minutes > 240) then
    return jsonb_build_object('error', 'bad-minutes');
  end if;
  lk := nullif(btrim(coalesce(p_link, '')), '');
  if lk is not null and lk !~* '^https://([a-z0-9-]+\.)*(meet\.google\.com|zoom\.us|teams\.microsoft\.com|teams\.live\.com)/' then
    return jsonb_build_object('error', 'bad-meeting-link');
  end if;
  update public.ops_engagements set
    meeting_at = p_at, meeting_channel = coalesce(p_channel, meeting_channel),
    meeting_owner_id = coalesce(p_owner, meeting_owner_id, m.id),
    meeting_note = case when p_note is null then meeting_note else nullif(btrim(p_note), '') end,
    meeting_minutes = coalesce(p_minutes, meeting_minutes),
    meeting_link = case when p_link is null then meeting_link else lk end,
    outstation_told_at = case when e.meeting_at is distinct from p_at then null else outstation_told_at end,
    meeting_na = false, updated_at = now(), version = version + 1
  where id = p_engagement;
  perform public.ops_engagement_log(p_engagement, 'meeting_set',
    jsonb_build_object('at', p_at, 'channel', p_channel, 'owner_id', p_owner, 'was', e.meeting_at,
                       'minutes', p_minutes));
  return public.ops_engagement_json(p_engagement);
end $$;

create or replace function public.sm_report_task_sync(p_task uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  t public.ops_tasks;
  v_n integer;
  v_day date;
  v_views bigint;
  v_eng bigint;
  v_res boolean;
  v_set timestamptz;
  v_at timestamptz;
  v_prev jsonb;
  v_live timestamptz;
  v_lset boolean;
  v_rset boolean;
  v_rback boolean;
  v_now timestamptz := now();
begin
  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return; end if;
  select count(*), min(q.posted_on), sum(q.views), sum(coalesce(q.engagements, q.interactions)),
         coalesce(bool_or(q.views is not null or coalesce(q.engagements, q.interactions) is not null), false)
    into v_n, v_day, v_views, v_eng, v_res
    from public.sm_report_post_links k
    join public.sm_report_posts q on q.id = k.post_id and q.report_id = k.report_id
   where k.task_id = p_task and k.unlinked_at is null;
  if v_n = 0 or v_day is null then return; end if;
  select k.live_set, k.results_at into v_set, v_at
    from public.sm_report_post_links k
   where k.task_id = p_task and k.unlinked_at is null
   order by k.linked_at limit 1;
  select k.prev into v_prev
    from public.sm_report_post_links k
   where k.task_id = p_task and k.unlinked_at is null and k.prev ? 'stage_key'
   order by k.linked_at limit 1;
  v_lset := t.live_at is not distinct from v_set;
  v_rset := v_res and t.result_at is not distinct from v_at;
  /* The figures came from a post now unlinked and none left holds any:
     the task's own figures from before the first link come back. */
  v_rback := not v_res and v_at is not null and t.result_at is not distinct from v_at;
  v_live := case when (t.live_at at time zone public.agency_tz())::date = v_day then t.live_at
                 else (v_day + time '12:00') at time zone public.agency_tz() end;
  update public.ops_tasks set
    live_at = case when v_lset then v_live else live_at end,
    result_views = case when v_rset then least(v_views, 2147483647)::integer
                        when v_rback then (v_prev ->> 'result_views')::integer else result_views end,
    result_engagements = case when v_rset then least(v_eng, 2147483647)::integer
                              when v_rback then (v_prev ->> 'result_engagements')::integer else result_engagements end,
    result_by = case when v_rset then coalesce((public.ops_me()).id, result_by)
                     when v_rback then (v_prev ->> 'result_by')::uuid else result_by end,
    result_at = case when v_rset then v_now
                     when v_rback then (v_prev ->> 'result_at')::timestamptz else result_at end,
    version = version + 1, updated_at = v_now
   where id = t.id;
  update public.sm_report_post_links set
    live_set = case when v_lset then v_live else live_set end,
    results_at = case when v_rset then v_now when v_rback then null else results_at end
   where task_id = p_task and unlinked_at is null;
end $$;

create or replace function public.wa_messages(p_month date default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  v_from date := date_trunc('month', coalesce(p_month, (now() at time zone public.agency_tz())::date))::date;
  v_a    timestamptz;
  v_b    timestamptz;
  v_team boolean := public.allowed('team', 'view');
begin
  if me.id is null or not public.allowed('whatsapp', 'view') then return jsonb_build_object('error', 'denied'); end if;
  v_a := v_from::timestamp at time zone public.agency_tz();
  v_b := (v_from + interval '1 month')::timestamp at time zone public.agency_tz();
  return jsonb_build_object(
    'month', v_from,
    'items', coalesce((select jsonb_agg(x order by x.created_at desc) from (
        select o.id, o.purpose, o.template, o.category, o.to_kind, o.to_name,
               case when o.to_kind = 'colleague' and not v_team and o.to_number <> ''
                    then '••••' || right(o.to_number, 4) else o.to_number end as to_number, o.client_id,
               c.name as client, o.state, o.error, o.created_at, o.sent_at, o.created_by,
               o.delivered_at, o.read_at, o.failed_at, o.fail_code, o.fail_title, o.ref_kind, o.ref_id
          from public.wa_outbox o
          left join public.clients c on c.id = o.client_id
         where o.created_at >= v_a and o.created_at < v_b
           and (o.client_id is null or public.client_seen(o.client_id, 'view'))
         order by o.created_at desc
         limit 2000) x), '[]'::jsonb),
    'counts', (select jsonb_build_object(
        'utility',        count(*) filter (where o.category = 'utility'),
        'marketing',      count(*) filter (where o.category = 'marketing'),
        'authentication', count(*) filter (where o.category = 'authentication'))
      from public.wa_outbox o
     where o.state = 'sent' and o.failed_at is null and o.created_at >= v_a and o.created_at < v_b),
    'queue', (select jsonb_build_object(
        'queued',  count(*) filter (where o.state = 'queued'),
        'sending', count(*) filter (where o.state = 'sending'),
        'failed',  count(*) filter (where o.state = 'failed' and o.created_at > now() - interval '7 days'),
        -- Not confirmed: may have reached the person, so a colleague looks
        -- before sending again (2026-10-17).
        'unknown', count(*) filter (where o.state = 'unknown' and o.created_at > now() - interval '7 days'),
        'oldest',  min(o.created_at) filter (where o.state in ('queued', 'sending')))
      from public.wa_outbox o));
end $$;

create or replace function public.campaign_options_posted()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_day date; v_cur text; v_days int;
begin
  if new.state is distinct from 'posted' or old.state in ('posted', 'completed') then return new; end if;
  begin
    v_day := coalesce((select min(p.published_at) from public.option_posts p where p.option_id = new.id),
                      (now() at time zone public.agency_tz())::date);
    select r.currency into v_cur from public.creator_pay_requests r
     where r.creator_id = new.creator_id and r.status = 'approved' order by r.decided_at desc limit 1;
    v_days := coalesce(public.app_setting(case when coalesce(v_cur, 'MYR') = 'MYR' then 'creator_pay_days_myr' else 'creator_pay_days_other' end, v_day),
                       case when coalesce(v_cur, 'MYR') = 'MYR' then 10 else 21 end)::int;
    new.posted_on := coalesce(new.posted_on, v_day);
    new.pay_by := coalesce(new.pay_by,
      (public.ops_add_business_days((new.posted_on::timestamp at time zone public.agency_tz()), v_days) at time zone public.agency_tz())::date);
  exception when others then
    return new;
  end;
  return new;
end $$;

create or replace function public.creator_upload_claim(p_code text, p_option uuid, p_size bigint)
returns text
language plpgsql security definer set search_path = public as $$
declare
  v_day   date := (now() at time zone public.agency_tz())::date;
  v_row   public.creator_upload_counts;
begin
  if p_size is null or p_size < 1 or not public.creator_may_upload(p_code, p_option) then
    return 'not-allowed';
  end if;
  insert into public.creator_upload_counts (option_id, day) values (p_option, v_day)
    on conflict (option_id) do nothing;
  select * into v_row from public.creator_upload_counts where option_id = p_option for update;
  if v_row.day <> v_day then
    v_row.files := 0; v_row.bytes := 0;
  end if;
  if v_row.files >= 50 or v_row.bytes + p_size > 25::bigint * 1024 * 1024 * 1024 then
    return 'too-many';
  end if;
  update public.creator_upload_counts
     set day = v_day, files = v_row.files + 1, bytes = v_row.bytes + p_size
   where option_id = p_option;
  return 'ok';
end $$;

create or replace function public.creator_sheet_claim(p_n int default 5)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare v jsonb;
begin
  with c as (
    update public.creator_sheet_rows x set status = 'sending', claimed_at = now(), tries = x.tries + 1
     where x.id in (select y.id from public.creator_sheet_rows y
                     where y.status = 'queued' or (y.status = 'failed' and y.tries < 5)
                     order by y.created_at limit least(greatest(coalesce(p_n, 5), 1), 20) for update skip locked)
    returning x.*)
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'values', jsonb_build_object(
      'creator_id', k.creator_code, 'creator_name', k.name, 'reference', r.ref,
      'billing_as', case r.bill_kind when 'nric' then 'Individual (NRIC)' when 'passport' then 'Individual (Passport)' else 'Company' end,
      'id_no', r.id_no, 'legal_name', r.legal_name, 'tin', r.tin, 'address', r.address, 'currency', r.currency,
      'method', public.creator_pay_method(r.method, null), 'bank', r.bank, 'account', r.account, 'payee', r.payee,
      'email', r.email, 'whatsapp', r.whatsapp,
      'submitted', to_char(r.created_at at time zone public.agency_tz(), 'YYYY-MM-DD HH24:MI'),
      'approved', to_char(r.decided_at at time zone public.agency_tz(), 'YYYY-MM-DD HH24:MI'),
      'approved_by', m.name))), '[]'::jsonb)
    into v
    from c join public.creator_pay_requests r on r.id = c.request_id
    join public.creators k on k.id = r.creator_id
    left join public.team_members m on m.id = r.decided_by;
  return jsonb_build_object('rows', v,
    'sheet', (select jsonb_build_object('on', s.on_send, 'spreadsheet_id', s.spreadsheet_id, 'tab', s.tab)
                from public.creator_sheet_settings s where s.id = 1));
end $$;

create or replace function public.quote_wa_allowed(p_id uuid)
returns boolean
language plpgsql volatile security definer set search_path = public as $$
declare
  v_today date := (now() at time zone public.agency_tz())::date;
  v_cap numeric := coalesce(public.app_setting('quote_wa_day', v_today), 30);
  v_sent integer;
begin
  if v_cap <= 0 then return false; end if;
  perform pg_advisory_xact_lock(hashtextextended('quote-web-wa-day', 0));
  -- p_id is kept for the signature; every message counts, a resend included.
  select count(*) into v_sent from public.wa_outbox o
    join public.quotations q on q.id = o.ref_id and q.source = 'website'
   where o.purpose = 'quote_ready' and o.state <> 'failed'
     and o.created_at >= (v_today::timestamp at time zone public.agency_tz());
  return v_sent < v_cap;
end $$;

create or replace function public.auto_send_set(p_kind text, p_on boolean)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me      public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_key   text := case p_kind when 'email' then 'auto_email_on' when 'whatsapp' then 'auto_whatsapp_on' end;
  v_was   numeric;
  v_to    numeric := case when coalesce(p_on, false) then 1 else 0 end;
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if v_key is null then return jsonb_build_object('error', 'bad-kind'); end if;
  v_was := coalesce(public.app_setting(v_key, v_today), 1);
  if v_was is not distinct from v_to then return jsonb_build_object('ok', true); end if;
  insert into public.app_settings (key, from_date, value, set_by, set_at)
  values (v_key, v_today, v_to, me.id, now())
  on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Settings',
          case p_kind when 'email' then 'Automatic emails: ' else 'Automatic WhatsApp: ' end ||
          case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_to = 1 then 'On' else 'Off' end ||
          ' · from ' || public.register_day(v_today));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.ops_month_invoice_ask(p_engagement uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  e  public.ops_engagements;
  v_from date;
  v_to   date;
  v_c    bigint[];
begin
  if (public.ops_me()).id is null or not public.allowed('clients.billing', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into e from public.ops_engagements x where x.id = p_engagement;
  if e.id is null or not public.ops_may_see_engagement(e.id) or not public.client_seen(e.client_id, 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  if e.status = 'cancelled' then return jsonb_build_object('error', 'cancelled'); end if;
  select w.starts, w.ends into v_from, v_to from public.month_invoice_window(e.period) w;
  if v_from > (now() at time zone public.agency_tz())::date then
    return jsonb_build_object('error', 'not-started');
  end if;
  v_c := public.month_invoice_contacts(e.client_id);
  if cardinality(v_c) = 0 then return jsonb_build_object('error', 'not-linked'); end if;
  return jsonb_build_object('ok', true, 'engagement', e.id, 'client', e.client_id, 'from', v_from, 'to', v_to,
    'contacts', to_jsonb(v_c));
end $$;

create or replace function public.ops_month_invoices_due()
returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('engagement', e.id, 'from', w.starts, 'to', w.ends,
           'contacts', to_jsonb(public.month_invoice_contacts(e.client_id))) order by e.period desc), '[]'::jsonb)
    from public.ops_engagements e
    cross join lateral public.month_invoice_window(e.period) w
    left join public.ops_month_invoices m on m.engagement_id = e.id
   where e.status <> 'cancelled'
     and w.starts <= (now() at time zone public.agency_tz())::date
     and e.period >= to_char((now() at time zone public.agency_tz())::date - interval '4 months', 'YYYY-MM')
     and (m.engagement_id is null
          or (m.checked_at < now() - interval '20 hours'
              and (m.state = 'none' or exists (select 1 from jsonb_array_elements(m.invoices) v
                                                where coalesce((v->>'paid')::boolean, false) = false))))
     and cardinality(public.month_invoice_contacts(e.client_id)) > 0
$$;

create or replace function public.ops_months_not_invoiced()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if (public.ops_me()).id is null or not public.allowed('clients.billing', 'manage') then return '[]'::jsonb; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('engagement', e.id, 'client', c.id, 'name', c.name, 'slug', c.slug,
             'owner', c.owner, 'period', e.period, 'checked_at', m.checked_at, 'since', w.starts)
             order by e.period, c.name)
      from public.ops_month_invoices m
      join public.ops_engagements e on e.id = m.engagement_id
      join public.clients c on c.id = e.client_id
      cross join lateral public.month_invoice_window(e.period) w
     where m.state = 'none' and e.status <> 'cancelled'
       and (m.checked_at at time zone public.agency_tz())::date > w.starts
       and public.client_seen(c.id, 'view')), '[]'::jsonb);
end $$;

create or replace function public.wa_sent_recently(p_to_kind text, p_to uuid, p_purpose text, p_ref uuid, p_template text default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me      public.team_members := public.ops_me();
  v_prep  jsonb;
  v_hours numeric := coalesce(public.app_setting('wa_repeat_hours', (now() at time zone public.agency_tz())::date), 24);
  v_ref   uuid;
  v_tpl   text := coalesce(nullif(btrim(p_template), ''), '');
  w       public.wa_outbox;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  v_prep := public.wa_compose_prepare(p_to_kind, p_to, p_purpose, p_ref);
  if v_prep ? 'error' then return v_prep; end if;
  if v_hours <= 0 then return jsonb_build_object('ok', true, 'recent', false, 'hours', 0); end if;
  v_ref := case when p_purpose in ('feedback', 'representative') then (v_prep ->> 'client_id')::uuid
                when p_purpose = 'message' then null else p_ref end;
  select * into w from public.wa_outbox x
   where x.to_kind = p_to_kind and x.to_id = p_to
     and x.state in ('queued', 'sending', 'sent', 'unknown')
     and x.created_at > now() - make_interval(hours => v_hours::int)
     and ((x.purpose = p_purpose
           and x.ref_id is not distinct from v_ref
           and (p_purpose <> 'message' or x.template = v_tpl))
       -- a feedback request, a representative or a plain message: the same
       -- template to the same person, whatever purpose it was filed under
       or (p_purpose in ('feedback', 'representative', 'message') and v_tpl <> '' and x.template = v_tpl))
   order by x.created_at desc limit 1;
  if w.id is null then return jsonb_build_object('ok', true, 'recent', false, 'hours', v_hours); end if;
  return jsonb_build_object('ok', true, 'recent', true, 'hours', v_hours, 'at', w.created_at,
    'by', case when w.created_by = 'system' then null else w.created_by end, 'to', w.to_name, 'state', w.state);
end $$;

create or replace function public.creator_pay_form(p_code text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_id   uuid;
  v_lock integer;
  cr     public.creators;
  v_last public.creator_pay_requests;
  v_paid public.creator_pay_requests;
  v_day  date := (now() at time zone public.agency_tz())::date;
begin
  select t.o_creator, t.o_locked into v_id, v_lock from public.creator_code_try(p_code) t;
  if v_lock is not null then return jsonb_build_object('error', 'locked', 'minutes', v_lock); end if;
  select * into cr from public.creators x where x.id = v_id;
  if cr.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not cr.active then return jsonb_build_object('error', 'inactive'); end if;
  select * into v_last from public.creator_pay_requests x where x.creator_id = cr.id and x.status <> 'withdrawn'
   order by x.seq desc limit 1;
  select * into v_paid from public.creator_pay_requests x where x.creator_id = cr.id and x.status = 'approved'
   order by x.decided_at desc limit 1;
  return jsonb_build_object('ok', true, 'due', public.creator_pay_due(cr.id), 'whatsapp', public.creator_mask_phone(cr.whatsapp),
    'address_needed', v_paid.id is not null and v_paid.address is null,
    'last', public.creator_pay_masked(public.creator_pay_json(v_last, false)),
    'paid', public.creator_pay_masked(public.creator_pay_json(v_paid, false)),
    'days', jsonb_build_object('myr', public.app_setting('creator_pay_days_myr', v_day),
                               'other', public.app_setting('creator_pay_days_other', v_day)),
    'payments', coalesce((select jsonb_agg(jsonb_build_object(
        'job', public.creator_job_ref(o.id), 'campaign', m.title, 'state', o.state,
        'posted_on', o.posted_on, 'pay_by', o.pay_by,
        'bill', (select jsonb_build_object('status', b.status,
                   'paid_on', coalesce(b.paid_on, (b.paid_seen_at at time zone public.agency_tz())::date))
                   from public.creator_bills b where b.option_id = o.id and not b.gone
                  order by (b.status = 'processing') desc, b.bill_date desc nulls last limit 1))
        order by o.posted_on desc nulls first, m.created_at desc)
        from public.campaign_options o join public.campaigns m on m.id = o.campaign_id
       where o.creator_id = cr.id and o.state not in ('option', 'shortlisted', 'backup', 'withdrawn', 'replaced')), '[]'::jsonb));
end $$;

create or replace function public.ops_post_follow(p_post uuid, p_note text)
returns void
language plpgsql security definer set search_path = public as $$
declare
  k      public.ops_task_links;
  t      public.ops_tasks;
  v_to   text;
  v_from public.ops_workflow_stages;
  v_dest public.ops_workflow_stages;
  v_own  uuid;
  v_me   uuid := (public.ops_me()).id;
  v_back boolean := false;
begin
  select * into k from public.ops_task_links x
   where x.post_id = p_post and x.archived_at is null limit 1;
  if k.id is null then return; end if;
  v_to := public.ops_post_target(p_post);
  if v_to is null then return; end if;
  select * into t from public.ops_tasks x where x.id = k.task_id for update;
  if t.id is null or t.completed_at is not null or t.cancelled_at is not null or t.archived_at is not null
     or t.stage_key = v_to then
    return;
  end if;
  /* Approved is the content loop's own while Content Review moved it there:
     an approval taken back, or asked again, takes the task back with it
     (audit 2026-11-11). */
  v_back := t.stage_key = 'approved' and v_to in ('client_review', 'revision_client')
    and coalesce((select (e.detail ->> 'content_review')::boolean from public.ops_task_events e
                    where e.task_id = t.id and e.event_type = 'stage_changed'
                    order by e.created_at desc limit 1), false);
  if t.stage_key not in ('ready', 'in_production', 'internal_review', 'revision_internal',
                         'client_review', 'revision_client') and not v_back then
    return;
  end if;
  /* A move a person could not make is not made for them: the client sees
     the work only after AQC review, so a task that has not been through it
     goes to AQC review instead. */
  if v_to = 'client_review'
     and exists (select 1 from public.ops_workflow_stages s
                  where s.workflow_id = t.workflow_id and s.key = 'internal_review')
     and not exists (select 1 from public.ops_task_events e
                      where e.task_id = t.id and e.event_type = 'stage_changed'
                        and e.to_value ->> 'stage_key' = 'internal_review') then
    v_to := 'internal_review';
    if t.stage_key = v_to then return; end if;
  end if;
  /* Work not started waits on its month: the readiness ticks answered and
     the content meeting held or not needed, as ops_transition_task asks. */
  if t.stage_key = 'ready' and not public.ops_month_open_for_work(t.engagement_id) then return; end if;
  v_from := public.ops_stage(t.workflow_id, t.stage_key);
  v_dest := public.ops_stage(t.workflow_id, v_to);
  if v_from.key is null or v_dest.key is null or coalesce(v_dest.retired, false) then return; end if;
  if not (v_back or v_dest.position > v_from.position
          or (t.stage_key = 'revision_internal' and v_to = 'internal_review')
          or (t.stage_key = 'revision_client' and v_to = 'client_review')) then
    return;
  end if;
  update public.ops_tasks set stage_key = v_to, version = version + 1, updated_at = now(),
         blocked_at = null, blocked_category = null,
         first_draft_submitted_at = case when first_draft_submitted_at is null and coalesce(v_dest.is_review, false)
                                         then now() else first_draft_submitted_at end
   where id = t.id;
  insert into public.ops_task_events (task_id, event_type, actor_id, actor_email, from_value, to_value, detail)
  values (t.id, 'stage_changed', v_me, null,
          jsonb_build_object('stage_key', t.stage_key), jsonb_build_object('stage_key', v_to),
          jsonb_build_object('note', p_note, 'post_id', p_post, 'content_review', true));
  select a.team_member_id into v_own from public.ops_task_assignees a
   where a.task_id = t.id and a.responsibility = 'owner' and a.ended_at is null limit 1;
  if v_own is not null and v_own is distinct from v_me then
    perform public.ops_notify(v_own, t.id, 'stage_changed',
      public.ops_serial(t.task_no) || ' · ' || public.ops_title(t),
      'Moved to ' || v_dest.label || ': ' || p_note || '.',
      'stage_changed:' || t.id::text || ':' || v_own::text || ':' || to_char(now() at time zone public.agency_tz(), 'YYYYMMDDHH24MI'));
  end if;
exception when others then
  return;
end $$;

create or replace function public.ops_script_follow(p_script uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  k      public.ops_task_links;
  t      public.ops_tasks;
  s      public.video_scripts;
  v      public.ops_video_details;
  v_shot boolean;
  v_at   timestamptz;
  v_own  uuid;
  v_me   uuid := (public.ops_me()).id;
  v_dest public.ops_workflow_stages;
begin
  select * into k from public.ops_task_links x
   where x.script_id = p_script and x.archived_at is null limit 1;
  if k.id is null then return; end if;
  select * into s from public.video_scripts x where x.id = p_script;
  select * into t from public.ops_tasks x where x.id = k.task_id for update;
  if s.id is null or t.id is null or t.completed_at is not null or t.cancelled_at is not null
     or t.archived_at is not null then
    return;
  end if;
  select count(*) > 0 and count(*) filter (where c.shot_at is null) = 0 into v_shot
    from public.video_script_scenes c where c.script_id = s.id;
  v_at := case when s.shoot_on is null then null
               else (s.shoot_on + coalesce(s.shoot_time, time '09:00')) at time zone public.agency_tz() end;
  insert into public.ops_video_details (task_id) values (t.id) on conflict (task_id) do nothing;
  select * into v from public.ops_video_details x where x.task_id = t.id for update;
  if v.script_ready is distinct from (s.status = 'shared') or v.footage_ready is distinct from v_shot
     or v.shoot_at is distinct from v_at or v.shoot_required is distinct from (s.shoot_on is not null) then
    update public.ops_video_details set script_ready = (s.status = 'shared'), footage_ready = v_shot,
           shoot_at = v_at, shoot_required = (s.shoot_on is not null)
     where task_id = t.id;
    insert into public.ops_task_events (task_id, event_type, actor_id, actor_email, from_value, to_value, detail)
    values (t.id, 'video_changed', v_me, null,
            jsonb_build_object('script_ready', v.script_ready, 'footage_ready', v.footage_ready, 'shoot_at', v.shoot_at),
            jsonb_build_object('script_ready', s.status = 'shared', 'footage_ready', v_shot, 'shoot_at', v_at),
            jsonb_build_object('note', 'Updated from its script in Video Scripts', 'script_id', s.id));
    update public.ops_tasks set version = version + 1, updated_at = now() where id = t.id;
  end if;
  -- The footage in: a task not started moves into its work.
  if v_shot and v.footage_ready is distinct from true and t.stage_key = 'ready'
     and public.ops_month_open_for_work(t.engagement_id) then
    v_dest := public.ops_stage(t.workflow_id, 'in_production');
    if v_dest.key is not null and not coalesce(v_dest.retired, false) then
      update public.ops_tasks set stage_key = 'in_production', version = version + 1, updated_at = now()
       where id = t.id;
      insert into public.ops_task_events (task_id, event_type, actor_id, actor_email, from_value, to_value, detail)
      values (t.id, 'stage_changed', v_me, null,
              jsonb_build_object('stage_key', t.stage_key), jsonb_build_object('stage_key', 'in_production'),
              jsonb_build_object('note', 'Every scene shot in Video Scripts', 'script_id', s.id));
      select a.team_member_id into v_own from public.ops_task_assignees a
       where a.task_id = t.id and a.responsibility = 'owner' and a.ended_at is null limit 1;
      if v_own is not null and v_own is distinct from v_me then
        perform public.ops_notify(v_own, t.id, 'stage_changed',
          public.ops_serial(t.task_no) || ' · ' || public.ops_title(t),
          'Moved to ' || v_dest.label || ': every scene shot in Video Scripts.',
          'stage_changed:' || t.id::text || ':' || v_own::text || ':' ||
            to_char(now() at time zone public.agency_tz(), 'YYYYMMDDHH24MI'));
      end if;
    end if;
  end if;
exception when others then
  return;
end $$;

create or replace function public.doc_day_ok(p_day date)
returns boolean
language sql stable set search_path = public as $$
  -- A document's own date: from ADSPACE PLT's registration to today (MYT).
  select p_day is not null and p_day >= date '2023-08-14'
     and p_day <= (now() at time zone public.agency_tz())::date
$$;

