returns jsonb
language sql stable security definer set search_path = public as $$
  select public.quote_card((now() at time zone public.agency_tz())::date)
$$;

create or replace function public.quote_tax_snap(p_snap jsonb, p_client uuid)
returns jsonb
language sql stable set search_path = public as $$
  select public.quote_tax_snap(p_snap, p_client, (now() at time zone public.agency_tz())::date)
$$;

create or replace function public.ai_draft_usage()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_day timestamptz := public.ai_draft_day();
  v_month timestamptz := now() - interval '30 days';
  -- This calendar month in Malaysia, for what the calls cost.
  v_cal timestamptz := date_trunc('month', now() at time zone public.agency_tz()) at time zone public.agency_tz();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_uses constant text[] := array['drafts', 'checks', 'caption', 'script', 'picture', 'analysis', 'checklist', 'analytics', 'agent', 'next'];
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'limits', (select jsonb_object_agg(u, public.ai_cap(null, u)) from unnest(v_uses || array['per_report']) u),
    'cost', (select jsonb_build_object(
        'since', v_cal,
        'price_in', public.app_setting('ai_price_in', v_today),
        'price_out', public.app_setting('ai_price_out', v_today),
        'price_search', coalesce(public.app_setting('ai_price_search', v_today), 10),
        'price_image', coalesce(public.app_setting('ai_price_image', v_today), 0.07),
        'uses', count(*),
        'untracked', count(*) filter (where c.input_tokens is null),
        'input', coalesce(sum(c.input_tokens), 0),
        'output', coalesce(sum(c.output_tokens), 0),
        'searches', coalesce(sum(c.web_searches), 0),
        'usd', round(coalesce(sum(c.usd), 0), 2),
        'by', coalesce((select jsonb_object_agg(p.purpose, p.x) from (
            select c2.purpose, jsonb_build_object('uses', count(*), 'input', coalesce(sum(c2.input_tokens), 0),
                     'output', coalesce(sum(c2.output_tokens), 0), 'searches', coalesce(sum(c2.web_searches), 0),
                     'usd', round(coalesce(sum(c2.usd), 0), 2)) as x
              from (select d.purpose, d.input_tokens, d.output_tokens, d.web_searches,
                           (coalesce(d.input_tokens, 0) * public.app_setting('ai_price_in', (d.created_at at time zone public.agency_tz())::date)
                          + coalesce(d.output_tokens, 0) * public.app_setting('ai_price_out', (d.created_at at time zone public.agency_tz())::date)) / 1000000.0
                          + coalesce(d.web_searches, 0) * coalesce(public.app_setting('ai_price_search', (d.created_at at time zone public.agency_tz())::date), 10) / 1000.0
                          + case when d.purpose = 'picture' and coalesce(d.model, '') like 'gemini%' then coalesce(public.app_setting('ai_price_image', (d.created_at at time zone public.agency_tz())::date), 0.07) else 0 end as usd
                      from public.ai_drafts d where d.created_at >= v_cal and (d.outcome <> 'failed' or d.input_tokens is not null)) c2
             group by c2.purpose) p), '{}'::jsonb))
      from (select d.input_tokens, d.output_tokens, d.web_searches,
                   (coalesce(d.input_tokens, 0) * public.app_setting('ai_price_in', (d.created_at at time zone public.agency_tz())::date)
                  + coalesce(d.output_tokens, 0) * public.app_setting('ai_price_out', (d.created_at at time zone public.agency_tz())::date)) / 1000000.0
                  + coalesce(d.web_searches, 0) * coalesce(public.app_setting('ai_price_search', (d.created_at at time zone public.agency_tz())::date), 10) / 1000.0
                  + case when d.purpose = 'picture' and coalesce(d.model, '') like 'gemini%' then coalesce(public.app_setting('ai_price_image', (d.created_at at time zone public.agency_tz())::date), 0.07) else 0 end as usd
              from public.ai_drafts d where d.created_at >= v_cal and (d.outcome <> 'failed' or d.input_tokens is not null)) c),
    'resets_at', v_day + interval '1 day',
    'people', coalesce((select jsonb_agg(s.x order by s.x ->> 'name') from (
      select jsonb_build_object(
        'id', t.id, 'name', t.name, 'code', t.staff_code, 'group', g.name, 'group_slug', t.role,
        'admin', coalesce(t.is_admin, false) or t.role = 'admin',
        'used', jsonb_build_object('drafts', u.drafts, 'checks', u.checks, 'caption', u.caption, 'script', u.script, 'picture', u.picture,
                                   'analysis', u.analysis, 'checklist', u.checklist, 'analytics', u.analytics, 'agent', u.agent, 'next', u.nxt),
        'cap', (select jsonb_object_agg(k, public.ai_cap(t.id, k)) from unnest(v_uses) k),
        'own', coalesce((select jsonb_object_agg(split_part(l.scope, ':', 2), l.daily) from public.ai_draft_limits l
                          where l.scope like t.id::text || ':%' and l.daily is not null), '{}'::jsonb),
        'month', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month and d.outcome <> 'failed')) as x
        from public.team_members t
        left join public.team_roles g on g.slug = t.role
        cross join lateral (
          select count(*) filter (where d.purpose = 'draft') as drafts, count(*) filter (where d.purpose = 'check') as checks,
                 count(*) filter (where d.purpose = 'caption') as caption, count(*) filter (where d.purpose = 'script') as script,
                 count(*) filter (where d.purpose = 'picture') as picture,
                 count(*) filter (where d.purpose = 'analysis') as analysis, count(*) filter (where d.purpose = 'checklist') as checklist,
                 count(*) filter (where d.purpose = 'analytics') as analytics,
                 count(*) filter (where d.purpose = 'agent') as agent,
                 count(*) filter (where d.purpose = 'next') as nxt
            from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed') u
       -- Every active colleague may ask the assistant (the user, 2026-11-13:
       -- "all colleagues"), so every one is offered a limit.
       where t.active
    ) s), '[]'::jsonb));
end $$;

create or replace function public.agent_schedule_add(p_kind text, p_at timestamptz, p_title text, p_payload jsonb,
                                                     p_condition text default null, p_ref uuid default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_title text := btrim(coalesce(p_title, ''));
  v_err text;
  v_id uuid;
begin
  if me.id is null or not public.is_team() then return jsonb_build_object('error', 'denied'); end if;
  if p_kind is null or p_kind not in ('reminder', 'mark_sent', 'add_task', 'publish_set', 'unpublish_set', 'whatsapp') then
    return jsonb_build_object('error', 'bad-kind');
  end if;
  if p_at is null or p_at < now() + interval '1 minute' or p_at > now() + interval '92 days' then
    return jsonb_build_object('error', 'bad-time');
  end if;
  if length(v_title) not between 2 and 200 then return jsonb_build_object('error', 'bad-title'); end if;
  if (p_condition is null) <> (p_ref is null)
     or (p_condition is not null and p_condition not in ('set_undecided', 'report_not_sent', 'task_open')) then
    return jsonb_build_object('error', 'bad-condition');
  end if;
  v_err := public.agent_schedule_check(p_kind, coalesce(p_payload, '{}'::jsonb));
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  perform pg_advisory_xact_lock(hashtext('agent_schedule:' || me.id::text));
  if (select count(*) from public.agent_schedules s where s.team_member_id = me.id and s.state = 'waiting') >= 50 then
    return jsonb_build_object('error', 'too-many');
  end if;
  insert into public.agent_schedules (team_member_id, kind, run_at, title, payload, condition, condition_ref)
  values (me.id, p_kind, p_at, v_title, coalesce(p_payload, '{}'::jsonb), p_condition, p_ref)
  returning id into v_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'assistant.schedule', v_title,
          'Scheduled for ' || public.register_day((p_at at time zone public.agency_tz())::date) || ', ' ||
          lower(to_char(p_at at time zone public.agency_tz(), 'FMHH12:MIam')) || ' · confirmed through the Assistant');
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;

create or replace function public.quote_proceed_remind()
returns integer
language plpgsql volatile security definer set search_path = public as $$
declare
  r record;
  v_n int := 0;
begin
  for r in
    select q.id, q.ref, q.brand, q.client_id, q.proceed_due, q.proceed_start, q.proceed_decider
      from public.quotations q
      join public.clients c on c.id = q.client_id
     where q.source = 'website' and q.proceed_at is not null and q.proceed_reminded_at is null
       and q.removed_at is null and q.no_contact_at is null and q.status <> 'not_proceeding'
       and nullif(btrim(coalesce(c.owner, '')), '') is null and c.sales_by is null
       and now() >= q.proceed_due - interval '6 hours'
  loop
    update public.quotations set proceed_reminded_at = now() where id = r.id;
    insert into public.ops_notifications (team_member_id, kind, title, body, client_id, dedupe_key)
    select m.id, 'quote.proceed', 'Ready to proceed, waiting · ' || r.brand,
           r.ref || ' · ' || public.quote_proceed_words(r.proceed_start, r.proceed_decider) ||
             ' · nobody has taken the lead · contact by ' ||
             public.register_day((r.proceed_due at time zone public.agency_tz())::date) || ', ' ||
             lower(to_char(r.proceed_due at time zone public.agency_tz(), 'FMHH12:MIam')),
           r.client_id, 'quote.proceed:' || r.id || ':remind:' || m.id
      from public.team_members m
     where m.active
       and (m.is_admin or m.role = 'admin'
            or public.level_rank(coalesce(m.access ->> 'clients.leads', m.access ->> 'clients')) >= 3)
    on conflict (dedupe_key) do nothing;
    v_n := v_n + 1;
  end loop;
  -- A website quotation still waiting for the team six hours before its
  -- reply is owed (2026-10-29).
  for r in
    select q.id, q.ref, q.brand, q.client_id, q.reply_due
      from public.quotations q
     where q.source = 'website' and q.released_at is null and q.reply_due is not null
       and q.review_reminded_at is null and q.removed_at is null and q.status <> 'not_proceeding'
       and not exists (select 1 from public.quotations x where x.replaces = q.id and x.removed_at is null)
       and now() >= q.reply_due - interval '6 hours'
  loop
    update public.quotations set review_reminded_at = now() where id = r.id;
    insert into public.ops_notifications (team_member_id, kind, title, body, client_id, dedupe_key)
    select m.id, 'quote.website', 'Quotation to review, waiting · ' || r.brand,
           r.ref || ' · not sent to the prospect · send by ' ||
             public.register_day((r.reply_due at time zone public.agency_tz())::date) || ', ' ||
             lower(to_char(r.reply_due at time zone public.agency_tz(), 'FMHH12:MIam')),
           r.client_id, 'quote.review:' || r.id || ':remind:' || m.id
      from public.team_members m
     where m.active
       and (m.is_admin or m.role = 'admin'
            or public.level_rank(coalesce(m.access ->> 'clients.leads', m.access ->> 'clients')) >= 3)
    on conflict (dedupe_key) do nothing;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

create or replace function public.creator_post_save(
  p_code text, p_option uuid, p_platform text, p_url text, p_published date,
  p_impressions bigint, p_engagements bigint, p_views bigint)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id   uuid;
  v_lock integer;
  cr     creators%rowtype;
  o      campaign_options%rowtype;
  p      option_posts%rowtype;
  v_plat text;
  v_url  text := nullif(btrim(coalesce(p_url, '')), '');
  v_nums boolean := p_impressions is not null or p_engagements is not null or p_views is not null;
  v_live boolean := false;
begin
  -- The code through creator_code_try, so a wrong one is counted (audit 2026-11-15).
  select t.o_creator, t.o_locked into v_id, v_lock from public.creator_code_try(p_code) t;
  if v_lock is not null then return jsonb_build_object('error', 'locked', 'minutes', v_lock); end if;
  select * into cr from creators where id = v_id and active;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into o from campaign_options where id = p_option and creator_id = cr.id for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if o.state not in ('scheduled', 'posted') then return jsonb_build_object('error', 'closed'); end if;

  -- One of the placements this booking is for, by its printed name.
  select btrim(x) into v_plat
    from unnest(string_to_array(coalesce(o.platforms, ''), ',')) x
   where public.post_platform_key(x) = public.post_platform_key(p_platform)
   limit 1;
  if v_plat is null then return jsonb_build_object('error', 'platform'); end if;
  if v_url is not null and not public.post_link_ok(v_plat, v_url) then
    return jsonb_build_object('error', 'link');
  end if;
  if coalesce(p_impressions, 0) < 0 or coalesce(p_engagements, 0) < 0 or coalesce(p_views, 0) < 0 then
    return jsonb_build_object('error', 'number');
  end if;
  if p_published is not null and (p_published > (now() at time zone public.agency_tz())::date + 1 or p_published < date '2023-08-14') then
    return jsonb_build_object('error', 'date');
  end if;

  select * into p from option_posts
   where option_id = p_option and public.post_platform_key(platform) = public.post_platform_key(v_plat)
   limit 1;
  if p.id is null then
    insert into option_posts (option_id, platform, window_days)
    values (p_option, v_plat, 7) returning * into p;
  end if;
  -- The numbers are counted over the period the team set, and wait for it.
  if v_nums and (p.measure_from is null or p.measure_to is null) then
    return jsonb_build_object('error', 'period');
  end if;

  update option_posts
     set post_url = coalesce(v_url, post_url),
         published_at = coalesce(p_published, published_at, case when v_url is not null then (now() at time zone public.agency_tz())::date end),
         impressions = case when v_nums then p_impressions else impressions end,
         engagements = case when v_nums then p_engagements else engagements end,
         views = case when v_nums then p_views else views end,
         measured_at = case when v_nums then (now() at time zone public.agency_tz())::date else measured_at end,
         entered_by = 'creator', entered_at = now()
   where id = p.id;

  -- The post is out: the booking says so, on the creator's word.
  if o.state = 'scheduled' and v_url is not null then
    update campaign_options set state = 'posted' where id = p_option;
    v_live := true;
  end if;

  insert into public.activity_log (actor, action, subject, detail)
  select cr.name, 'campaign.results', c.title,
         cr.name || ' · ' || v_plat ||
         case when v_url is not null and v_url is distinct from p.post_url then ' · link' else '' end ||
         case when v_nums then ' · ' || coalesce(p_views::text, '—') || ' views, ' ||
              coalesce(p_engagements::text, '—') || ' engagements, ' ||
              coalesce(p_impressions::text, '—') || ' impressions' else '' end ||
         case when v_live then ' · Posted' else '' end
    from campaigns c where c.id = o.campaign_id;

  return jsonb_build_object('ok', true, 'posted', v_live);
end $$;

create or replace function public.perf_flex_calc(p_period date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_p date := date_trunc('month', p_period)::date;
  v_total integer; v_finals integer; v_at integer; v_rows jsonb;
  v_share numeric := public.perf_setting('flex_team_share', date_trunc('month', p_period)::date);
  v_fmin numeric := public.perf_setting('flex_member_min', date_trunc('month', p_period)::date);
begin
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode,
           case when r.id is not null then coalesce(r.result, public.perf_calc(r)) end as res
      from public.team_members t
      left join public.perf_reviews r on r.team_member_id = t.id and r.period = v_p and r.status = 'final'
     /* Who was on the list in that month: a colleague added later never
        unsettles a month decided, nor one who left with a final review
        (audit 2026-11-15). */
     where (t.active and public.perf_reviewed(t.id)
            and date_trunc('month', t.created_at at time zone public.agency_tz())::date <= v_p)
        or r.id is not null
  )
  select count(*)::int, count(m.res)::int,
         (count(*) filter (where (m.res ->> 'final')::numeric >= v_fmin))::int,
         coalesce(jsonb_agg(jsonb_build_object('team_member_id', m.mid, 'name', m.mname, 'staff_code', m.mcode,
           'final', m.res -> 'final', 'grade', m.res ->> 'grade',
           'breach', coalesce((m.res ->> 'l3')::boolean or (m.res ->> 'l4')::boolean, false),
           'eligible', coalesce((m.res ->> 'final')::numeric >= v_fmin
                                and not (m.res ->> 'l3')::boolean and not (m.res ->> 'l4')::boolean, false))
           order by m.mname), '[]'::jsonb)
    into v_total, v_finals, v_at, v_rows
    from m;
  return jsonb_build_object('period', v_p, 'month', public.perf_month_word(v_p),
    'next', (v_p + interval '1 month')::date,
    'next_month', public.perf_month_word((v_p + interval '1 month')::date),
    'members', v_total, 'finals', v_finals, 'at_70', v_at,
    'decided', v_total > 0 and v_finals = v_total,
    'unlocked', v_total > 0 and v_finals = v_total and v_at * 100 >= v_total * v_share,
    'people', v_rows, 'rules', jsonb_build_object('share', v_share, 'min', v_fmin));
end $$;

create or replace function public.perf_quarter_calc(p_quarter date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_q date := date_trunc('quarter', p_quarter)::date;
  v_qe date := (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_people jsonb; v_wins integer; v_each numeric; v_ind jsonb;
  v_depts jsonb; v_dwins integer; v_both boolean; v_why text; v_dp jsonb;
  v_open integer; v_missing integer; v_ended boolean := public.perf_today() >= (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_ip numeric := public.perf_setting('prize_individual', date_trunc('quarter', p_quarter)::date);
  v_dpool numeric := public.perf_setting('prize_department', date_trunc('quarter', p_quarter)::date);
  v_dmin numeric := public.perf_setting('prize_department_min_total', date_trunc('quarter', p_quarter)::date);
begin
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.department as mdept, t.active as mactive,
           public.perf_reviewed(t.id) as monlist, f.nmonths, f.nfinal, f.mean, f.emonth,
           (select count(*)::int from public.perf_reviews o
             where o.team_member_id = t.id and o.status <> 'final'
               and o.period >= v_q and o.period < v_qe) as nopen,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_q and b.period < v_qe) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths, (count(*) filter (where x.st = 'final'))::int as nfinal,
               round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res, r.status as st
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status <> 'draft'
                   and r.period >= v_q and r.period < v_qe) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-month' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end,
             case when not m.monlist then 'not-reviewed' end], null) as why
      from m
  ), w as (
    select e.*, cardinality(e.why) = 0 as ok,
           coalesce(cardinality(e.why) = 0
                    and e.mean = max(e.mean) filter (where cardinality(e.why) = 0) over (), false) as won
      from e
  ), p as (
    select w.*, count(*) filter (where w.won) over () as nwon,
           case when w.nmonths > 0 then rank() over (order by w.mean desc nulls last) end as mrank
      from w
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', p.mid, 'name', p.mname, 'staff_code', p.mcode, 'department', p.mdept,
           'active', p.mactive, 'reviewed', p.monlist, 'months', p.nmonths, 'finals', p.nfinal, 'open', p.nopen,
           'rank', p.mrank, 'average', p.mean,
           'grade', case when p.nmonths > 0 then public.perf_grade_at(p.mean, v_q) end,
           'e_month', p.emonth, 'l4', p.ml4, 'eligible', p.ok, 'reasons', to_jsonb(p.why),
           'prize', case when p.won then floor(v_ip * 100 / p.nwon) / 100 else 0 end)
         order by p.mean desc nulls last, p.mname), '[]'::jsonb),
         coalesce(max(p.nwon), 0)
    into v_people, v_wins
    from p;
  v_each := case when v_wins > 0 then floor(v_ip * 100 / v_wins) / 100 end;
  v_ind := jsonb_build_object('pool', v_ip, 'winners', v_wins, 'each', v_each,
    'paid', coalesce(v_each * v_wins, 0), 'remainder', v_ip - coalesce(v_each * v_wins, 0),
    'reason', case when v_wins = 0 then 'nobody-eligible' end);

  with d as (
    select k.key as dep, k.name as dname, k.criteria as dnames, s.c1, s.c2, s.c3, s.c4, s.c5, coalesce(s.critical, false) as crit,
           s.c1 + s.c2 + s.c3 + s.c4 + s.c5 as total, s.quarter is not null as entered,
           row_number() over (order by k.position, lower(k.name)) as ord
      from public.departments k
      left join public.perf_dept_scores s on s.quarter = v_q and s.department = k.key
     where k.active and k.in_prize
  ), x as (
    select d.*, bool_and(d.entered) over () as bothin,
           coalesce(d.total = max(d.total) over (), false) as istop
      from d
  ), y as (
    select x.*, (x.bothin and x.istop and x.total >= v_dmin and not x.crit) as won,
           coalesce((select array_agg(t.id order by t.name) from public.team_members t
                      where t.active and t.department = x.dep and public.perf_reviewed(t.id)), '{}'::uuid[]) as mems
      from x
  ), z as (
    select y.*, count(*) filter (where y.won) over () as nwon,
           case when y.won then floor((v_dpool * 100) / count(*) filter (where y.won) over ()) end as sharec
      from y
  )
  select jsonb_agg(jsonb_build_object(
           'department', z.dep, 'name', z.dname, 'names', coalesce(z.dnames, '[]'::jsonb), 'entered', z.entered,
           'criteria', case when z.entered then jsonb_build_array(z.c1, z.c2, z.c3, z.c4, z.c5) end,
           'total', z.total, 'grade', case when z.entered then public.perf_grade_at(z.total, v_q) end,
           'critical', z.crit, 'top', z.bothin and z.istop,
           'qualifies', z.entered and z.total >= v_dmin and not z.crit, 'won', z.won,
           'share', coalesce(z.sharec / 100, 0), 'members', to_jsonb(z.mems))
         order by z.ord),
         coalesce(max(z.nwon), 0), bool_and(z.bothin),
         case when bool_and(z.bothin) and max(z.nwon) = 0 then
           case when bool_or(z.istop and z.total >= v_dmin and z.crit) then 'critical-issue' else 'below-b' end end
    into v_depts, v_dwins, v_both, v_why
    from z;
  v_dp := jsonb_build_object('pool', v_dpool, 'winners', v_dwins,
    'paid', case when v_dwins > 0 then floor((v_dpool * 100) / v_dwins) * v_dwins / 100 else 0 end,
    'remainder', case when v_dwins > 0 then v_dpool - floor((v_dpool * 100) / v_dwins) * v_dwins / 100 else v_dpool end,
    'reason', case when v_depts is null then 'no-departments' when not v_both then 'scores-needed' else v_why end);

  -- a leaver's draft, which can never be released, holds nothing (audit 2026-11-15)
  select count(*)::int into v_open
    from public.perf_reviews r join public.team_members t on t.id = r.team_member_id
   where r.status <> 'final' and r.period >= v_q and r.period < v_qe
     and not (r.status = 'draft' and not t.active);
  select count(*)::int into v_missing
    from public.team_members t
    cross join generate_series(v_q, (v_qe - interval '1 month')::date, interval '1 month') g(mo)
   where t.active and public.perf_reviewed(t.id)
     and (g.mo + interval '1 month')::date <= public.perf_today()
     and date_trunc('month', t.created_at at time zone public.agency_tz())::date <= g.mo::date
     and not exists (select 1 from public.perf_reviews r where r.team_member_id = t.id and r.period = g.mo::date);

  return jsonb_build_object('quarter', v_q, 'word', public.perf_quarter_word(v_q),
    'ended', v_ended, 'provisional', not v_ended or v_open > 0 or v_missing > 0,
    'people', v_people, 'individual', v_ind,
    'departments', coalesce(v_depts, '[]'::jsonb), 'department_prize', v_dp,
    'open_months', v_open, 'missing_months', v_missing,
    'rules', jsonb_build_object('individual', v_ip, 'department', v_dpool, 'min_total', v_dmin,
      'grades', jsonb_build_object('A', public.perf_setting('grade_a', v_q), 'B', public.perf_setting('grade_b', v_q),
                                   'C', public.perf_setting('grade_c', v_q), 'D', public.perf_setting('grade_d', v_q))));
end $$;

create or replace function public.quote_fx(p_client uuid, p_at date)
returns numeric
language sql stable security definer set search_path = public as $$
  select case when exists (select 1 from public.clients c where c.id = p_client and c.market = 'SG' and c.bill_sgd)
              then coalesce(nullif(public.app_setting('fx_sgd', coalesce(p_at, (now() at time zone public.agency_tz())::date)), 0), 0) end
$$;

create or replace function public.quote_card(p_at date, p_version text)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', v.id, 'version', v.version,
           'snapshot', v.snapshot || jsonb_build_object('settings',
             coalesce(v.snapshot->'settings', '{}'::jsonb) ||
             coalesce((select jsonb_object_agg(k, public.app_setting(k, p_at))
                         from unnest(array['sst_pct', 'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24']) k
                        where public.app_setting(k, p_at) is not null), '{}'::jsonb)))
    from public.rate_card_versions v
   where (nullif(p_version, '') is not null and v.version = p_version)
      or (nullif(p_version, '') is null and v.id = coalesce(
            (select x.id from public.rate_card_versions x
              where x.published_at < ((p_at + 1)::timestamp at time zone public.agency_tz())
              order by x.published_at desc limit 1),
            (select x.id from public.rate_card_versions x order by x.published_at limit 1)))
   limit 1
$$;

create or replace function public.ops_create_task(p_payload jsonb, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  tpl   public.ops_task_templates;
  fam   public.ops_template_variants;
  byfmt boolean := false;
  wf    uuid;
  tid   uuid;
  owner uuid;
  publish timestamptz;
  fd    timestamptz;
  fin   timestamptz;
  item  jsonb;
  i     integer := 0;
  scope text;
  ttype text;
  cid   uuid;
  bad   text;
  descr text;
  period text;
  cper  text;
  week  integer;
  seq   integer;
  code  text;
  title text;
  first_stage text;
  wkey  text;
  base  timestamptz;
  eng   public.ops_engagements;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  -- The same press twice is one task, two presses at once included: the
  -- key's lock is taken before it is looked up (audit 2026-11-15).
  if p_idem is not null then
    perform pg_advisory_xact_lock(hashtext('ops_create_task:' || p_idem));
    select id into tid from public.ops_tasks where idem_key = p_idem;
    if tid is not null then return public.ops_task_json(tid); end if;
  end if;

  scope := coalesce(p_payload ->> 'scope', 'client');
  cid := (p_payload ->> 'client_id')::uuid;
  /* A task linked to a month's engagement takes the client from it: the
     person names the month once and the client comes with it. */
  if (p_payload ->> 'engagement_id') is not null then
    select * into eng from public.ops_engagements where id = (p_payload ->> 'engagement_id')::uuid;
    if eng.id is null then return jsonb_build_object('error', 'not-found'); end if;
    if cid is null then cid := eng.client_id; scope := 'client'; end if;
  end if;
  bad := public.ops_scope_error(scope, cid);
  if bad is not null then return jsonb_build_object('error', bad); end if;

  ttype := coalesce(p_payload ->> 'task_type', 'adhoc');
  if ttype not in ('engagement', 'adhoc', 'goodwill', 'special') then
    return jsonb_build_object('error', 'bad-task-type');
  end if;

  /* The description is the team's to edit and may start blank on a task that
     carries a code; a task with no code is named by its description alone, so
     there it is required. `title` is accepted from older callers as the
     description. */
  descr := nullif(btrim(coalesce(p_payload ->> 'content_desc', p_payload ->> 'title', '')), '');

  if (p_payload ->> 'template_id') is not null then
    select * into tpl from public.ops_task_templates
     where id = (p_payload ->> 'template_id')::uuid;
    descr := coalesce(descr, nullif(btrim(coalesce(tpl.default_title, tpl.name, '')), ''));
  end if;
  /* No template named: the family that owns the chosen format fills the task
     (its checklist, complexity, draft and final offsets, owner) and the
     format's own variant its hours (TEMPLATE FAMILIES, 2026-09-28). */
  if tpl.id is null and nullif(p_payload ->> 'deliverable_type', '') is not null then
    select v.* into fam from public.ops_template_variants v
      join public.ops_task_templates t on t.id = v.template_id and t.active
     where v.format = p_payload ->> 'deliverable_type';
    if fam.id is not null then
      select * into tpl from public.ops_task_templates where id = fam.template_id;
      byfmt := true;
    end if;
  end if;
  /* New work goes on the content workflow. A caller may still name another
     (a template's own, or one somebody adds), and a task already on a retired
     workflow is never moved. */
  wf := coalesce((p_payload ->> 'workflow_id')::uuid,
                 (select id from public.ops_workflows where key = p_payload ->> 'workflow_key' and active),
                 case when byfmt then null else tpl.workflow_id end,
                 (select id from public.ops_workflows where key = 'content' and active),
                 (select id from public.ops_workflows where active order by created_at limit 1));
  if wf is null then return jsonb_build_object('error', 'workflow-required'); end if;
  select key into first_stage from public.ops_workflow_stages
   where workflow_id = wf order by position limit 1;
  select key into wkey from public.ops_workflows where id = wf;

  publish := (p_payload ->> 'publish_at')::timestamptz;
  fd := coalesce((p_payload ->> 'first_draft_due_at')::timestamptz,
        case when publish is not null and tpl.first_draft_offset_business_days is not null
             then public.ops_add_business_days(publish, -tpl.first_draft_offset_business_days)
             when tpl.first_draft_offset_business_days is not null
             then public.ops_add_business_days(now(), tpl.first_draft_offset_business_days)
        end);
  /* A template's due date is a number of calendar days from the day the
     work is made for (the base date the caller names, else today). */
  base := coalesce((p_payload ->> 'base_date')::timestamptz, now());
  fin := coalesce((p_payload ->> 'final_due_at')::timestamptz,
        case when tpl.due_offset_days is not null and not byfmt
             then ((base at time zone public.agency_tz())::date + tpl.due_offset_days)::timestamp at time zone 'UTC'
             when publish is not null and tpl.final_offset_business_days is not null
             then public.ops_add_business_days(publish, -tpl.final_offset_business_days)
             when tpl.final_offset_business_days is not null
             then public.ops_add_business_days(now(), tpl.final_offset_business_days)
        end);
  /* Dates a person typed stand as typed, and a date left blank stays blank:
     nothing is worked out from a template's offsets (the user, 2026-10-05). */
  if coalesce((p_payload ->> 'dates_as_given')::boolean, false) then
    fd := (p_payload ->> 'first_draft_due_at')::timestamptz;
    fin := (p_payload ->> 'final_due_at')::timestamptz;
  end if;
  if fd is not null and fin is not null and not public.ops_due_order_ok(fd, fin) then
    return jsonb_build_object('error', 'draft-not-before-final');
  end if;

  /* The name. The month is the content month (the scheduled publish date's,
     else the one the caller names, else this one); the week is the planned
     publishing week, chosen by the caller and prefilled by the page from the
     date; the running number is the client's for the month. Generated once,
     under the lock, and never rewritten: a publish date that moves later
     leaves the name as it was, because the name is a label and not a fact
     about the date. */
  if wkey = 'task' then
    /* An everyday task is named by what it is. It carries no content code,
       because the code numbers a client's deliverables for the month and a
       task is not one; the content month is kept where it is known, so the
       task can be grouped with the month it belongs to. */
    if descr is null then return jsonb_build_object('error', 'title-required'); end if;
    title := descr;
    period := coalesce(nullif(p_payload ->> 'code_period', ''), eng.period);
  elsif scope <> 'internal' then
    period := coalesce(nullif(p_payload ->> 'code_period', ''),
                       case when publish is not null then to_char(publish, 'YYYY-MM') end,
                       to_char((now() at time zone public.agency_tz())::date, 'YYYY-MM'));
    if period !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
    /* A client's deliverable belongs to a month the team has planned: one
       that exists, is still open, and has its content meeting set or marked
       not applicable. The same three refusals Bulk add gives. */
    if scope = 'client' then
      cper := period;
      if eng.id is null or eng.period <> cper then
        select * into eng from public.ops_engagements x where x.client_id = cid and x.period = cper;
      end if;
      if eng.id is null then return jsonb_build_object('error', 'no-month'); end if;
      if eng.status in ('completed', 'cancelled') then return jsonb_build_object('error', 'month-closed'); end if;
      if eng.meeting_at is null and not eng.meeting_na then
        return jsonb_build_object('error', 'month-not-confirmed');
      end if;
    end if;
    week := coalesce((p_payload ->> 'code_week')::integer,
                     case when publish is not null
                          then least(5, ((extract(day from publish)::integer - 1) / 7) + 1) end,
                     1);
    if week < 1 or week > 5 then return jsonb_build_object('error', 'bad-week'); end if;
    seq := public.ops_next_seq(cid, period);
    code := public.ops_code_of(period, week, seq);
    title := btrim(code || ' ' || coalesce(descr, ''));
  else
    if descr is null then return jsonb_build_object('error', 'title-required'); end if;
    title := descr;
  end if;

  insert into public.ops_tasks (
    scope, client_id, campaign_id, batch_id, source_type, source_id, template_id,
    workflow_id, stage_key, title, description, remarks, deliverable_type,
    language_codes, priority_level, complexity, estimate_minutes, publish_at,
    original_first_draft_due_at, current_first_draft_due_at,
    original_final_due_at, current_final_due_at, created_by, idem_key,
    legacy_source, legacy_key, data_quality,
    task_type, code, code_period, code_week, code_seq, content_desc,
    engagement_id, manager_id, parent_task_id)
  values (
    scope, cid,
    (p_payload ->> 'campaign_id')::uuid,
    (p_payload ->> 'batch_id')::uuid,
    p_payload ->> 'source_type',
    (p_payload ->> 'source_id')::uuid,
    tpl.id, wf, coalesce(first_stage, 'intake'),
    title, p_payload ->> 'description', p_payload ->> 'remarks',
    coalesce(p_payload ->> 'deliverable_type', tpl.deliverable_type, 'other'),
    coalesce((select array_agg(x) from jsonb_array_elements_text(
               coalesce(p_payload -> 'language_codes', '[]'::jsonb)) x), '{}'),
    coalesce((p_payload ->> 'priority_level')::smallint, 3),
    coalesce(p_payload ->> 'complexity', tpl.default_complexity),
    coalesce((p_payload ->> 'estimate_minutes')::integer, fam.estimate_minutes, tpl.default_estimate_minutes),
    publish, fd, fd, fin, fin, m.id, p_idem,
    p_payload ->> 'legacy_source', p_payload ->> 'legacy_key',
    coalesce(p_payload ->> 'data_quality', 'complete'),
    ttype, code, period, week, seq, descr,
    coalesce(eng.id, (p_payload ->> 'engagement_id')::uuid),
    coalesce((p_payload ->> 'manager_id')::uuid, m.id),
    (p_payload ->> 'parent_task_id')::uuid)
  returning id into tid;

  /* Every task has an owner from the moment it exists: the one named, the
     template's, or else whoever made it. */
  owner := coalesce((p_payload ->> 'owner_id')::uuid, tpl.default_owner_id, m.id);
  if owner is not null then
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (tid, owner, 'owner', m.id);
    perform public.ops_log(tid, 'assignment_changed', null,
      jsonb_build_object('owner_id', owner), '{}'::jsonb);
  end if;
  if (p_payload ->> 'reviewer_id') is not null then
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (tid, (p_payload ->> 'reviewer_id')::uuid, 'reviewer', m.id);
  end if;

  -- The template's checklist, or the one the caller hands over (a duplicate
  -- carries its source's labels, unticked), in the order stated.
  for item in select * from jsonb_array_elements(
      coalesce(p_payload -> 'checklist', tpl.checklist, '[]'::jsonb)) loop
    i := i + 1;
    insert into public.ops_task_checklist_items (task_id, label, position)
    values (tid, item #>> '{}', i);
  end loop;

  if (p_payload -> 'video') is not null then
    insert into public.ops_video_details (
      task_id, output_duration_seconds, footage_duration_seconds,
      subtitle_required, motion_graphics_required, aspect_ratios,
      script_ready, footage_ready, shoot_required, shoot_at, variant_count)
    values (tid,
      ((p_payload -> 'video') ->> 'output_duration_seconds')::integer,
      ((p_payload -> 'video') ->> 'footage_duration_seconds')::integer,
      coalesce(((p_payload -> 'video') ->> 'subtitle_required')::boolean, false),
      coalesce(((p_payload -> 'video') ->> 'motion_graphics_required')::boolean, false),
      coalesce((select array_agg(x) from jsonb_array_elements_text(
                 coalesce((p_payload -> 'video') -> 'aspect_ratios', '[]'::jsonb)) x), '{}'),
      ((p_payload -> 'video') ->> 'script_ready')::boolean,
      ((p_payload -> 'video') ->> 'footage_ready')::boolean,
      coalesce(((p_payload -> 'video') ->> 'shoot_required')::boolean, false),
      ((p_payload -> 'video') ->> 'shoot_at')::timestamptz,
      coalesce(((p_payload -> 'video') ->> 'variant_count')::integer, 1));
  end if;

  perform public.ops_log(tid, 'task_created', null,
    jsonb_build_object('title', title, 'code', code,
                       'first_draft_due_at', fd, 'final_due_at', fin),
    case when (p_payload ->> 'duplicated_from') is null then '{}'::jsonb
         else jsonb_build_object('duplicated_from', p_payload ->> 'duplicated_from') end);
  return public.ops_task_json(tid);
end $$;

create or replace function public.creator_bill_prep(p_option uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  o  public.campaign_options;
  m  public.campaigns;
  c  public.creators;
  cl public.clients;
  f  public.creator_fees;
  l  public.bukku_links;
  b  public.bukku_settings;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_fx numeric := 1;
begin
  if me.id is null or not public.ops_granted('campaigns.pay', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into o from public.campaign_options x where x.id = p_option for update;
  if o.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if o.state not in ('posted', 'completed') then return jsonb_build_object('error', 'not-posted'); end if;
  select * into f from public.creator_fees x where x.option_id = o.id;
  if f.option_id is null or f.amount <= 0 then return jsonb_build_object('error', 'no-fee'); end if;
  -- A fee is billed in the currency the creator is paid in now (audit 2026-11-15).
  if f.currency is distinct from public.creator_pay_currency(o.creator_id) then
    return jsonb_build_object('error', 'currency-changed', 'currency', public.creator_pay_currency(o.creator_id));
  end if;
  select * into l from public.bukku_links x where x.kind = 'creator' and x.record_id = o.creator_id;
  if l.contact_id is null then return jsonb_build_object('error', 'not-linked'); end if;
  if exists (select 1 from public.creator_bills x where x.option_id = o.id and not x.gone) then return jsonb_build_object('error', 'billed'); end if;
  select * into b from public.bukku_settings where id = 1;
  -- The bill's item, classification and account are Business settings (2026-11-15).
  if b.bill_account_code is null then return jsonb_build_object('error', 'no-account'); end if;
  if b.bill_item_sku is null or b.bill_class_code is null then return jsonb_build_object('error', 'no-item'); end if;
  if f.currency = 'SGD' then
    v_fx := nullif(public.app_setting('fx_sgd', v_today), 0);
    if v_fx is null then return jsonb_build_object('error', 'no-fx'); end if;
  end if;
  if exists (select 1 from public.creator_bill_claims k where k.option_id = o.id and k.claimed_at > now() - interval '10 minutes') then
    return jsonb_build_object('error', 'creating');
  end if;
  insert into public.creator_bill_claims (option_id, claimed_by, claimed_at) values (o.id, me.id, now())
  on conflict (option_id) do update set claimed_by = excluded.claimed_by, claimed_at = now();
  select * into m from public.campaigns x where x.id = o.campaign_id;
  select * into c from public.creators x where x.id = o.creator_id;
  select * into cl from public.clients x where x.id = m.client_id;
  return jsonb_build_object('ok', true, 'creator', o.creator_id, 'contact_id', l.contact_id, 'amount', f.amount, 'currency', f.currency,
    'fx', v_fx, 'ref', public.creator_job_ref(o.id), 'date', v_today,
    'due', case when o.pay_by >= v_today then o.pay_by end, 'account', b.bill_account,
    'sku', b.bill_item_sku, 'class_code', b.bill_class_code, 'account_code', b.bill_account_code,
    'client_name', coalesce(cl.name, ''), 'campaign', coalesce(nullif(btrim(m.title), ''), 'Creator campaign'), 'creator_name', coalesce(c.name, ''),
    'description', left(coalesce(nullif(btrim(m.title), ''), 'Creator campaign') || ' · ' || coalesce(c.name, ''), 200));
end $$;

create or replace function public.perf_save(p_token text, p_member uuid, p_period date,
                                            p_payload jsonb, p_rev integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  err text; m public.team_members; r public.perf_reviews; p date := date_trunc('month', p_period)::date;
  sc jsonb := coalesce(p_payload -> 'scores', '{}'::jsonb);
  rt jsonb := coalesce(p_payload -> 'rates', '{}'::jsonb);
  k text; v jsonb; mx numeric; rb date; ev date; was public.perf_reviews; changed jsonb; held jsonb;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  if p_member = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if not exists (select 1 from public.team_members where id = p_member and active) then
    return jsonb_build_object('error', 'not-found');
  end if;
  /* Reviews run from June 2026 to the month in hand, never ahead of it. */
  if p < date '2026-06-01' or p > date_trunc('month', public.perf_today())::date then
    return jsonb_build_object('error', 'bad-month', 'from', date '2026-06-01');
  end if;
  if jsonb_typeof(sc) <> 'object' or jsonb_typeof(rt) <> 'object'
     or (p_payload ? 'notes' and jsonb_typeof(p_payload -> 'notes') <> 'object') then
    return jsonb_build_object('error', 'bad-payload');
  end if;
  for k, v in select key, value from jsonb_each(sc) loop
    mx := case k when 'output' then 25 when 'accuracy' then 15 when 'delivery' then 15
                 when 'client' then 20 when 'comms' then 15 when 'initiative' then 10 end;
    if mx is null then return jsonb_build_object('error', 'bad-score', 'key', k); end if;
    if jsonb_typeof(v) <> 'null' then
      if jsonb_typeof(v) <> 'number' then return jsonb_build_object('error', 'bad-score', 'key', k, 'max', mx); end if;
      if (v #>> '{}')::numeric not between 0 and mx or round((v #>> '{}')::numeric, 1) <> (v #>> '{}')::numeric then
        return jsonb_build_object('error', 'bad-score', 'key', k, 'max', mx);
      end if;
    end if;
  end loop;
  for k, v in select key, value from jsonb_each(rt) loop
    mx := case k when 'pacing' then 1000 when 'posting' then 100 when 'timeline' then 100
                 when 'satisfaction' then 100 when 'sla' then 100 end;
    if mx is null then return jsonb_build_object('error', 'bad-rate', 'key', k); end if;
    if jsonb_typeof(v) <> 'null' then
      if jsonb_typeof(v) <> 'number' then return jsonb_build_object('error', 'bad-rate', 'key', k); end if;
      if (v #>> '{}')::numeric not between 0 and mx then return jsonb_build_object('error', 'bad-rate', 'key', k); end if;
    end if;
  end loop;
  if coalesce(p_payload ->> 'review_by', '') <> '' then
    begin
      rb := (p_payload ->> 'review_by')::date;
    exception when others then
      return jsonb_build_object('error', 'bad-date');
    end;
  end if;

  /* The day the month was evaluated: on or after its first day, never
     after today in Malaysia. */
  if coalesce(p_payload ->> 'evaluated_on', '') <> '' then
    begin
      ev := (p_payload ->> 'evaluated_on')::date;
    exception when others then
      return jsonb_build_object('error', 'bad-eval-date');
    end;
    if ev < p or ev > (now() at time zone public.agency_tz())::date then
      return jsonb_build_object('error', 'bad-eval-date');
    end if;
  end if;

  /* A month inside a confirmed quarter or half is paid on that snapshot:
     nothing in it is begun or scored until the period is reopened. */
  held := public.perf_period_held(p);
  if held is not null then return held; end if;

  select * into r from public.perf_reviews where team_member_id = p_member and period = p for update;
  if r.id is null then
    insert into public.perf_reviews (team_member_id, period) values (p_member, p)
    on conflict (team_member_id, period) do nothing;
    select * into r from public.perf_reviews where team_member_id = p_member and period = p for update;
    perform public.perf_log(r.id, p_member, 'started', '{}'::jsonb);
  elsif p_rev is not null and r.rev <> p_rev then
    return jsonb_build_object('error', 'stale', 'record', public.perf_json(r, true));
  end if;
  /* The scores are the draft's. What the month asks of the person next (the
     improvement, the date it is reviewed by, the step or reward) is written
     at the 1-1 and may be filled in until the record is final. */
  if r.status = 'final' or (r.status <> 'draft'
       and (p_payload - 'improvement' - 'review_by' - 'reward_step' - 'evaluated_on') <> '{}'::jsonb) then
    return jsonb_build_object('error', 'not-draft');
  end if;

  was := r;
  update public.perf_reviews set
    s_output     = case when sc ? 'output'     then (sc ->> 'output')::numeric     else s_output end,
    s_accuracy   = case when sc ? 'accuracy'   then (sc ->> 'accuracy')::numeric   else s_accuracy end,
    s_delivery   = case when sc ? 'delivery'   then (sc ->> 'delivery')::numeric   else s_delivery end,
    s_client     = case when sc ? 'client'     then (sc ->> 'client')::numeric     else s_client end,
    s_comms      = case when sc ? 'comms'      then (sc ->> 'comms')::numeric      else s_comms end,
    s_initiative = case when sc ? 'initiative' then (sc ->> 'initiative')::numeric else s_initiative end,
    r_posting      = case when rt ? 'posting'      then (rt ->> 'posting')::numeric      else r_posting end,
    r_timeline     = case when rt ? 'timeline'     then (rt ->> 'timeline')::numeric     else r_timeline end,
    r_satisfaction = case when rt ? 'satisfaction' then (rt ->> 'satisfaction')::numeric else r_satisfaction end,
    r_pacing       = case when rt ? 'pacing'       then (rt ->> 'pacing')::numeric       else r_pacing end,
    r_sla          = case when rt ? 'sla'          then (rt ->> 'sla')::numeric          else r_sla end,
    notes       = case when p_payload ? 'notes' then coalesce(p_payload -> 'notes', '{}'::jsonb) else notes end,
    improvement = case when p_payload ? 'improvement' then nullif(btrim(p_payload ->> 'improvement'), '') else improvement end,
    review_by   = case when p_payload ? 'review_by' then rb else review_by end,
    reward_step = case when p_payload ? 'reward_step' then nullif(btrim(p_payload ->> 'reward_step'), '') else reward_step end,
    evaluated_on = case when p_payload ? 'evaluated_on' then ev else evaluated_on end,
    updated_at = now(), rev = rev + 1
  where id = r.id
  returning * into r;
  /* What the save changed, named: each scorecard and rate whose value moved,
     from and to, then whether the notes or the plan moved. A save that moved
     nothing is not filed. */
  select coalesce(jsonb_agg(jsonb_build_object('key', c.key, 'from', c.a, 'to', c.b) order by c.n), '[]'::jsonb)
    into changed
    from (values (1, 'output', was.s_output, r.s_output), (2, 'accuracy', was.s_accuracy, r.s_accuracy),
                 (3, 'delivery', was.s_delivery, r.s_delivery), (4, 'client', was.s_client, r.s_client),
                 (5, 'comms', was.s_comms, r.s_comms), (6, 'initiative', was.s_initiative, r.s_initiative),
                 (7, 'posting', was.r_posting, r.r_posting), (8, 'timeline', was.r_timeline, r.r_timeline),
                 (9, 'satisfaction', was.r_satisfaction, r.r_satisfaction), (10, 'pacing', was.r_pacing, r.r_pacing),
                 (11, 'sla', was.r_sla, r.r_sla)) as c(n, key, a, b)
   where c.a is distinct from c.b;
  if coalesce(was.notes, '{}'::jsonb) is distinct from coalesce(r.notes, '{}'::jsonb) then
    changed := changed || jsonb_build_array(jsonb_build_object('key', 'notes'));
  end if;
  if was.improvement is distinct from r.improvement or was.review_by is distinct from r.review_by
     or was.reward_step is distinct from r.reward_step then
    changed := changed || jsonb_build_array(jsonb_build_object('key', 'plan'));
  end if;
  if was.evaluated_on is distinct from r.evaluated_on then
    changed := changed || jsonb_build_array(jsonb_build_object('key', 'evaluated_on', 'from', was.evaluated_on, 'to', r.evaluated_on));
  end if;
  if jsonb_array_length(changed) > 0 then
    perform public.perf_log(r.id, p_member, 'scored', jsonb_build_object('changed', changed));
  end if;
  return public.perf_json(r, true);
end $$;

create or replace function public.perf_release(p_token text, p_review uuid, p_rev integer, p_notify boolean default true)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare err text; m public.team_members; r public.perf_reviews; tm public.team_members; held jsonb;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  select * into r from public.perf_reviews where id = p_review for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.team_member_id = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if p_rev is not null and r.rev <> p_rev then
    return jsonb_build_object('error', 'stale', 'record', public.perf_json(r, true));
  end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft'); end if;
  held := public.perf_period_held(r.period);
  if held is not null then return held; end if;
  if not (public.perf_calc(r) ->> 'complete')::boolean then
    return jsonb_build_object('error', 'incomplete');
  end if;
  select * into tm from public.team_members where id = r.team_member_id;
  if r.serial is null and coalesce(btrim(tm.staff_code), '') = '' then
    return jsonb_build_object('error', 'no-staff-code');
  end if;
  update public.perf_reviews set status = 'released', released_at = now(),
         dispute_until = now() + make_interval(days => public.perf_setting('dispute_days', r.period)::integer), reviewer_id = m.id,
         evaluated_on = coalesce(evaluated_on, (now() at time zone public.agency_tz())::date),
         serial = coalesce(serial, 'ADHR/' || upper(btrim(tm.staff_code)) || '/PR' || to_char(period, 'YYMM')),
         rev = rev + 1, updated_at = now()
   where id = r.id returning * into r;
  perform public.perf_log(r.id, r.team_member_id, 'released',
    jsonb_build_object('version', r.version, 'notified', coalesce(p_notify, true)));
  if coalesce(p_notify, true) then
    perform public.perf_notify(r.team_member_id, 'perf.released',
      'Your ' || public.perf_month_word(r.period) || ' performance review is ready.',
      -- released again after a correction is told again (audit 2026-11-15)
      'perf.released.' || r.id || '.' || r.version || '.' || r.rev);
  end if;
  return public.perf_json(r, true);
end $$;

create or replace function public.hiring_get(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  c public.hiring_candidates;
  v_role text := public.hiring_role(p_id);
  v_days int := coalesce(public.app_setting('hiring_link_days', (now() at time zone public.agency_tz())::date)::int, 30);
begin
  if v_role is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.hiring_candidates where id = p_id;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  return jsonb_build_object('ok', true, 'role', v_role,
    'candidate', public.hiring_row(c, v_role) || jsonb_strip_nulls(jsonb_build_object(
      'email', c.email, 'phone', c.phone, 'cv_url', c.cv_url, 'cv_path', c.cv_path, 'cv_name', c.cv_name,
      'note', c.note, 'updated_at', c.updated_at,
      'link_key', case when v_role in ('admin', 'owner') then c.link_key end,
      'link_ends', c.last_step_at + make_interval(days => v_days))),
    'people', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'role', p.role,
                          'designation', t.designation) order by (p.role <> 'owner'), t.name)
                          from public.hiring_people p join public.team_members t on t.id = p.team_member_id
                         where p.candidate_id = c.id), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(jsonb_build_object('actor', e.actor, 'action', e.action, 'detail', e.detail,
                          'created_at', e.created_at) order by e.created_at desc)
                          from (select * from public.hiring_events e where e.candidate_id = c.id
                                 order by e.created_at desc limit 100) e), '[]'::jsonb));
end $$;

create or replace function public.quotation_withdraw(p_id uuid, p_on date, p_reason text, p_lines boolean)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  q  public.quotations;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_today date := (now() at time zone public.agency_tz())::date;
  v_lines jsonb := '[]'::jsonb;
  v_n integer := 0;
begin
  if me.id is null or not public.allowed('clients.quotes', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into q from public.quotations x where x.id = p_id for update;
  if q.id is null or not public.client_scope_ok('client', q.client_id, 'manage') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if q.signed_at is null then return jsonb_build_object('error', 'not-signed'); end if;
  if q.withdrawn_at is not null then return jsonb_build_object('error', 'withdrawn'); end if;
  if p_on is null or p_on < (q.signed_at at time zone public.agency_tz())::date or p_on > v_today then
    return jsonb_build_object('error', 'bad-date');
  end if;
  if char_length(v_reason) < 3 or char_length(v_reason) > 300 then return jsonb_build_object('error', 'bad-reason'); end if;
  if coalesce(p_lines, false) then
    select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'state', s.state)), '[]'::jsonb), count(*)
      into v_lines, v_n
      from public.client_services s
     where s.quotation_id = q.id and s.archived_at is null and s.state = 'confirmed';
    update public.client_services set state = 'to_quote'
     where quotation_id = q.id and archived_at is null and state = 'confirmed';
  end if;
  update public.quotations
     set withdrawn_at = now(), withdrawn_on = p_on, withdrawn_reason = v_reason, withdrawn_by = me.name, withdrawn_lines = v_lines
   where id = q.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', q.brand,
          q.ref || ' withdrawn from ' || public.register_day(p_on) || ' · ' || v_reason ||
          case when v_n > 0 then ' · ' || v_n || case when v_n = 1 then ' service line' else ' service lines' end || ' returned to To quote' else '' end);
  return jsonb_build_object('ok', true, 'lines', v_n);
end $$;

create or replace function public.personnel_today()
returns date
language sql stable set search_path = public as $$
  select (now() at time zone public.agency_tz())::date
$$;

create or replace function public.careers_pool(p_key text, p_yes boolean)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c public.hiring_candidates;
  v_days int := coalesce(public.app_setting('hiring_link_days', (now() at time zone public.agency_tz())::date)::int, 30);
  v_months int := coalesce(public.app_setting('hiring_pool_months', (now() at time zone public.agency_tz())::date)::int, 12);
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' or p_yes is null then return jsonb_build_object('error', 'not_found'); end if;
  select * into c from public.hiring_candidates where link_key = p_key and removed_at is null for update;
  if c.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if c.last_step_at + make_interval(days => v_days) <= now() then return jsonb_build_object('error', 'expired'); end if;
  if c.stage <> 'pool' or c.pool_consent is distinct from 'asked' then return jsonb_build_object('error', 'not-open'); end if;
  if p_yes then
    update public.hiring_candidates set pool_consent = 'yes', pool_until = now() + make_interval(months => v_months),
      last_step_at = now(), updated_at = now() where id = c.id;
  else
    update public.hiring_candidates set pool_consent = 'no', stage = 'closed', last_step_at = now(), updated_at = now() where id = c.id;
  end if;
  insert into public.hiring_events (candidate_id, actor, action, detail)
  values (c.id, 'Candidate page', 'candidate.decided', case when p_yes then 'Agreed to the talent pool' else 'Declined the talent pool' end);
  perform public.hiring_tell(c.id, 'hiring.pool', case when p_yes then 'A candidate agreed to the talent pool' else 'A candidate declined the talent pool' end,
    c.position || '.');
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.sm_report_gate(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  e public.ops_engagements;
  task public.ops_tasks;
  v_starts date;
  v_ends date;
  v_due timestamptz;
  v_made integer := 0;
  v_posted integer := 0;
  v_delayed integer := 0;
  v_lacking jsonb := '[]'::jsonb;
  v_missing text[] := '{}';
  v_links boolean := public.report_links_on();
  v_wl boolean;
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen_by(c.stage, c.owner, c.owner_id, c.sales_by, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.period_start < date '2026-10-01' or r.on_request then
    return jsonb_build_object('applies', false, 'ok', true, 'missing', '[]'::jsonb, 'on_request', r.on_request);
  end if;
  /* A white-label report's accounts are not ADspace's: no post is held
     to it (2026-11-06). */
  v_wl := r.brand_id is not null or coalesce(c.white_label, false);
  select x.* into e from public.ops_engagements x
   cross join lateral public.ops_month_span(x.period, x.start_day) s
   where x.client_id = r.client_id and x.status <> 'cancelled'
     and r.period_end between s.starts and s.ends
   order by x.period desc limit 1;
  if e.id is null then
    v_missing := v_missing || 'no-month'::text;
    v_due := ((r.period_end + public.app_setting('report_due_days', r.period_end)::integer)::timestamp + time '23:59') at time zone public.agency_tz();
  else
    select s.starts, s.ends into v_starts, v_ends from public.ops_month_span(e.period, e.start_day) s;
    v_due := ((v_ends + public.app_setting('report_due_days', v_ends)::integer)::timestamp + time '23:59') at time zone public.agency_tz();
    if not (r.kind = any (e.reports)) then
      v_missing := v_missing || 'not-ticked'::text;
    else
      select * into task from public.ops_tasks x
       where x.engagement_id = e.id and x.source_type = 'report_' || r.kind
         and x.cancelled_at is null and x.archived_at is null
       order by x.created_at desc limit 1;
      if task.id is null then
        v_missing := v_missing || 'no-task'::text;
      else
        v_due := coalesce(task.current_final_due_at, v_due);
      end if;
    end if;
    select count(*) into v_made from public.ops_tasks x
     where x.engagement_id = e.id and x.cancelled_at is null and x.archived_at is null
       and coalesce(x.source_type, '') not in ('report_social', 'report_ads');
    /* Planned content holds an Accounts Report alone (2026-11-02). A post
       counts once it is linked to its post in a report and holds its dates
       (2026-11-06), or, with links off, once it has gone live and holds
       every date (2026-11-05). A post marked delayed counts too. */
    if r.kind = 'social' then
      if v_made < e.planned_count then v_missing := v_missing || 'content'::text; end if;
      if not v_wl then
        select count(*) filter (where k.counted), count(*) filter (where not k.counted and k.delayed)
          into v_posted, v_delayed
          from (select x.delayed_at is not null as delayed,
                       x.current_first_draft_due_at is not null and x.current_final_due_at is not null and x.publish_at is not null
                       and case when v_links then public.sm_report_task_linked(x.id)
                                else x.stage_key in ('live', 'performance_review', 'completed') and x.live_at is not null end as counted
                  from public.ops_tasks x
                 where x.engagement_id = e.id and x.cancelled_at is null and x.archived_at is null
                   and coalesce(x.source_type, '') not in ('report_social', 'report_ads')) k;
        if v_posted + v_delayed < e.planned_count then v_missing := v_missing || 'posted'::text; end if;
        if v_posted < e.planned_count then
          select coalesce(jsonb_agg(l.j order by l.n), '[]'::jsonb) into v_lacking from (
            select x.task_no as n, jsonb_build_object('id', x.id, 'task_no', x.task_no, 'code', x.code,
                     'stage_key', x.stage_key,
                     'delayed', x.delayed_at is not null, 'delayed_reason', x.delayed_reason, 'delayed_note', x.delayed_note,
                     'needs', to_jsonb(array_remove(array[
                       case when v_links and not public.sm_report_task_linked(x.id) then 'link' end,
                       case when not v_links and x.stage_key not in ('live', 'performance_review', 'completed') then 'stage' end,
                       case when x.current_first_draft_due_at is null then 'draft' end,
                       case when x.current_final_due_at is null then 'due' end,
                       case when x.publish_at is null then 'post' end,
                       case when not v_links and x.live_at is null then 'live' end], null))) as j
              from public.ops_tasks x
             where x.engagement_id = e.id and x.cancelled_at is null and x.archived_at is null
               and coalesce(x.source_type, '') not in ('report_social', 'report_ads')
               and not (x.current_first_draft_due_at is not null and x.current_final_due_at is not null and x.publish_at is not null
                        and case when v_links then public.sm_report_task_linked(x.id)
                                 else x.stage_key in ('live', 'performance_review', 'completed') and x.live_at is not null end)
             order by x.task_no limit 20) l;
        end if;
      end if;
    end if;
  end if;
  return jsonb_build_object(
    'applies', true, 'ok', cardinality(v_missing) = 0, 'missing', to_jsonb(v_missing),
    'month', case when e.id is null then null else jsonb_build_object(
               'id', e.id, 'period', e.period, 'start_day', e.start_day, 'starts', v_starts, 'ends', v_ends,
               'reports', to_jsonb(e.reports)) end,
    'planned', coalesce(e.planned_count, 0), 'made', v_made, 'posted', v_posted, 'delayed', v_delayed, 'lacking', v_lacking,
    'links', v_links and not v_wl, 'white_label', v_wl,
    'task', case when task.id is null then null else jsonb_build_object(
              'id', task.id, 'task_no', task.task_no, 'stage_key', task.stage_key) end,
    'due', v_due, 'late', now() > v_due,
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage'));
end $$;

create or replace function public.sm_report_post_delay(p_report uuid, p_task uuid, p_reason text, p_note text default null, p_on boolean default true)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  e public.ops_engagements;
  t public.ops_tasks;
  v_owner uuid;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_word text;
  v_counted boolean;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen_by(c.stage, c.owner, c.owner_id, c.sales_by, 'work') then return jsonb_build_object('error', 'denied'); end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft'); end if;
  select x.* into e from public.ops_engagements x
   cross join lateral public.ops_month_span(x.period, x.start_day) s
   where x.client_id = r.client_id and x.status <> 'cancelled'
     and r.period_end between s.starts and s.ends
   order by x.period desc limit 1;
  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null or e.id is null or r.kind <> 'social' or t.engagement_id is distinct from e.id
     or t.cancelled_at is not null or t.archived_at is not null
     or coalesce(t.source_type, '') in ('report_social', 'report_ads') then
    return jsonb_build_object('error', 'not-in-month');
  end if;
  if not coalesce(p_on, true) then
    if t.delayed_at is null then return jsonb_build_object('ok', true, 'id', t.id); end if;
    update public.ops_tasks set delayed_at = null, delayed_by = null, delayed_reason = null, delayed_note = null,
           delayed_report = null, version = version + 1, updated_at = now()
     where id = t.id;
    perform public.ops_log(t.id, 'delay_cleared', jsonb_build_object('reason', t.delayed_reason), '{}'::jsonb,
      jsonb_build_object('report_id', r.id));
    perform public.sm_report_log(r.id, 'report.saved', coalesce(t.code, public.ops_serial(t.task_no)) || ' no longer marked delayed');
    return jsonb_build_object('ok', true, 'id', t.id);
  end if;
  v_counted := t.current_first_draft_due_at is not null and t.current_final_due_at is not null and t.publish_at is not null
     and case when public.report_links_on() then public.sm_report_task_linked(t.id)
              else t.stage_key in ('live', 'performance_review', 'completed') and t.live_at is not null end;
  if v_counted then
    return jsonb_build_object('error', 'posted');
  end if;
  v_word := case p_reason when 'client_request' then 'Client request' when 'scope_change' then 'Scope change'
    when 'capacity' then 'Internal capacity' when 'pending_assets' then 'Pending assets'
    when 'pending_confirmation' then 'Pending confirmation' end;
  if v_word is null then return jsonb_build_object('error', 'bad-reason'); end if;
  if char_length(coalesce(v_note, '')) > 300 then return jsonb_build_object('error', 'too-long'); end if;
  update public.ops_tasks set delayed_at = now(), delayed_by = me.id, delayed_reason = p_reason, delayed_note = v_note,
         delayed_report = r.id, version = version + 1, updated_at = now()
   where id = t.id;
  perform public.ops_log(t.id, 'delayed', '{}'::jsonb,
    jsonb_build_object('reason', p_reason, 'note', v_note), jsonb_build_object('report_id', r.id));
  perform public.sm_report_log(r.id, 'report.saved',
    coalesce(t.code, public.ops_serial(t.task_no)) || ' marked delayed: ' || v_word || coalesce(' · ' || v_note, ''));
  select a.team_member_id into v_owner from public.ops_task_assignees a
   where a.task_id = t.id and a.responsibility = 'owner' and a.ended_at is null limit 1;
  if v_owner is not null and v_owner <> me.id then
    perform public.ops_notify(v_owner, t.id, 'delayed', public.ops_serial(t.task_no) || ' · ' || public.ops_title(t),
      'Marked delayed in the Accounts Report by ' || coalesce(nullif(me.name, ''), me.email) || ': ' || v_word || '.',
      'delayed:' || t.id::text || ':' || v_owner::text || ':' || to_char(now() at time zone public.agency_tz(), 'YYYYMMDDHH24MI'));
  end if;
  return jsonb_build_object('ok', true, 'id', t.id);
end $$;

create or replace function public.sm_report_post_link(p_post uuid, p_task uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  p public.sm_report_posts;
  r public.sm_reports;
  c public.clients;
  e public.ops_engagements;
  t public.ops_tasks;
  l public.sm_report_post_links;
  o public.sm_reports;
  a public.sm_report_platforms;
  f public.sm_report_post_links;
  v_code text;
  v_live timestamptz;
  v_moved boolean;
  v_views integer;
  v_eng integer;
  v_res boolean;
  v_name text;
  v_was_day date;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into p from public.sm_report_posts where id = p_post;
  if p.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into r from public.sm_reports where id = p.report_id for update;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen_by(c.stage, c.owner, c.owner_id, c.sales_by, 'work') then return jsonb_build_object('error', 'denied'); end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft'); end if;

  /* Taking a link off works with the switch off too, so Off can be
     walked back post by post. */
  select * into l from public.sm_report_post_links where post_id = p.id and unlinked_at is null;
  if p_task is null then
    if l.id is not null then
      perform public.sm_report_post_revert(l.id);
      select coalesce(x.code, public.ops_serial(x.task_no)) into v_code from public.ops_tasks x where x.id = l.task_id;
      perform public.sm_report_log(r.id, 'report.saved', coalesce(v_code, 'A task') || ' no longer linked to its post');
    end if;
    return jsonb_build_object('ok', true);
  end if;
  if not public.report_links_on() then return jsonb_build_object('error', 'links-off'); end if;
  if r.kind <> 'social' or r.on_request or r.brand_id is not null or coalesce(c.white_label, false) then
    return jsonb_build_object('error', 'not-linkable');
  end if;
  if l.task_id = p_task then return jsonb_build_object('ok', true, 'id', p_task); end if;

  if p.posted_on is null then return jsonb_build_object('error', 'no-date'); end if;
  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null or t.client_id is distinct from r.client_id or t.cancelled_at is not null or t.archived_at is not null
     or coalesce(t.source_type, '') in ('report_social', 'report_ads') then
    return jsonb_build_object('error', 'not-in-month');
  end if;
  select x.* into e from public.ops_engagements x
   cross join lateral public.ops_month_span(x.period, x.start_day) s
   where x.client_id = r.client_id and x.status <> 'cancelled'
     and r.period_end between s.starts and s.ends
   order by x.period desc limit 1;
  /* The month's own posts, a post marked delayed from an earlier month;
     an admin or Reports Full Access any of the client's posts. */
  if not ((e.id is not null and t.engagement_id = e.id) or t.delayed_at is not null
          or coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage')) then
    return jsonb_build_object('error', 'not-in-month');
  end if;
  /* A task's links are one report's: a link in another report is taken
     off there first. */
  select o2.* into o from public.sm_report_post_links k
    join public.sm_report_posts q on q.id = k.post_id and q.report_id = k.report_id
    join public.sm_reports o2 on o2.id = k.report_id
   where k.task_id = t.id and k.unlinked_at is null and k.report_id <> r.id
   limit 1;
  if o.id is not null then
    return jsonb_build_object('error', 'linked', 'period', public.sm_period_word(o.period_start, o.period_end));
  end if;
  /* One post an account: another post of this account already holds it. */
  select a2.* into a from public.sm_report_post_links k
    join public.sm_report_posts q on q.id = k.post_id and q.report_id = k.report_id
    join public.sm_report_platforms a2 on a2.id = q.platform_id
   where k.task_id = t.id and k.unlinked_at is null and k.report_id = r.id
     and q.platform_id = p.platform_id and q.id <> p.id
   limit 1;
  if a.id is not null then
    return jsonb_build_object('error', 'same-account', 'account', coalesce(nullif(a.account_name, ''), nullif(a.handle, ''), a.platform));
  end if;
  /* What this post held, and a link the task held on a post since
     removed, let go first. */
  if l.id is not null then perform public.sm_report_post_revert(l.id); end if;
  perform public.sm_report_post_revert(k.id) from public.sm_report_post_links k
   where k.task_id = t.id and k.unlinked_at is null
     and not exists (select 1 from public.sm_report_posts q where q.id = k.post_id and q.report_id = k.report_id);
  select * into t from public.ops_tasks where id = p_task;
  v_name := nullif(btrim(coalesce(t.content_desc, '')), '');
  v_code := coalesce(t.code, public.ops_serial(t.task_no));

  /* A task already linked to another account's post: this post joins it,
     and the task's date and figures are worked out over all of them. */
  select k.* into f from public.sm_report_post_links k
    join public.sm_report_posts q on q.id = k.post_id and q.report_id = k.report_id
   where k.task_id = t.id and k.unlinked_at is null
   order by k.linked_at limit 1;
  if f.id is not null then
    insert into public.sm_report_post_links (post_id, report_id, task_id, prev, moved, live_set, results_at, linked_by)
    values (p.id, r.id, t.id, jsonb_build_object('post_title', p.title), false, f.live_set, f.results_at, me.id);
    if v_name is not null then
      update public.sm_report_posts set title = v_name where id = p.id;
    end if;
    perform public.sm_report_task_sync(t.id);
    perform public.ops_log(t.id, 'report_linked', jsonb_build_object('live_at', t.live_at),
      jsonb_build_object('live_at', (select x.live_at from public.ops_tasks x where x.id = t.id), 'posted_on', p.posted_on),
      jsonb_build_object('report_id', r.id, 'post_id', p.id));
    perform public.sm_report_log(r.id, 'report.saved',
      v_code || ' linked to its post of ' || public.register_day(p.posted_on) || ' on another account');
    return jsonb_build_object('ok', true, 'id', t.id, 'moved', false, 'extra', true, 'title', v_name, 'live', p.posted_on);
  end if;

  v_was_day := (t.live_at at time zone public.agency_tz())::date;
  v_live := case when v_was_day = p.posted_on then t.live_at
                 else (p.posted_on + time '12:00') at time zone public.agency_tz() end;
  /* A task held (On hold, Blocked, Taken down) stays where it is: only
     the line short of the review moves. */
  v_moved := t.stage_key not in ('performance_review', 'completed', 'on_hold', 'blocked', 'taken_down', 'cancelled')
             and exists (select 1 from public.ops_workflow_stages s
                          where s.workflow_id = t.workflow_id and s.key = 'performance_review');
  v_views := case when p.views is null then null else least(p.views, 2147483647)::integer end;
  v_eng := case when coalesce(p.engagements, p.interactions) is null then null
                else least(coalesce(p.engagements, p.interactions), 2147483647)::integer end;
  v_res := v_views is not null or v_eng is not null;

  insert into public.sm_report_post_links (post_id, report_id, task_id, prev, moved, live_set, results_at, linked_by)
  values (p.id, r.id, t.id, jsonb_build_object(
            'stage_key', t.stage_key, 'completed_at', t.completed_at, 'live_at', t.live_at,
            'delayed_at', t.delayed_at, 'delayed_by', t.delayed_by, 'delayed_reason', t.delayed_reason,
            'delayed_note', t.delayed_note, 'delayed_report', t.delayed_report,
            'result_views', t.result_views, 'result_engagements', t.result_engagements,
            'result_at', t.result_at, 'result_by', t.result_by,
            'blocked_at', t.blocked_at, 'blocked_category', t.blocked_category, 'post_title', p.title),
          v_moved, v_live, case when v_res then now() end, me.id);
  update public.ops_tasks set
    live_at = v_live,
    stage_key = case when v_moved then 'performance_review' else stage_key end,
    completed_at = case when v_moved then null else completed_at end,
    blocked_at = case when v_moved then null else blocked_at end,
    blocked_category = case when v_moved then null else blocked_category end,
    delayed_at = null, delayed_by = null, delayed_reason = null, delayed_note = null, delayed_report = null,
    result_views = case when v_res then v_views else result_views end,
    result_engagements = case when v_res then v_eng else result_engagements end,
    result_at = case when v_res then now() else result_at end,
    result_by = case when v_res then me.id else result_by end,
    version = version + 1, updated_at = now()
   where id = t.id;
  if v_name is not null then
    update public.sm_report_posts set title = v_name where id = p.id;
  end if;

  if v_moved then
    perform public.ops_log(t.id, 'stage_changed', jsonb_build_object('stage_key', t.stage_key),
      jsonb_build_object('stage_key', 'performance_review'),
      jsonb_build_object('note', 'Linked to its Accounts Report post', 'report_id', r.id));
  end if;
  perform public.ops_log(t.id, 'report_linked', jsonb_build_object('live_at', t.live_at),
    jsonb_build_object('live_at', v_live, 'posted_on', p.posted_on), jsonb_build_object('report_id', r.id, 'post_id', p.id));
  perform public.sm_report_log(r.id, 'report.saved',
    v_code || ' linked to its post of ' || public.register_day(p.posted_on)
    || case when v_was_day is not null and v_was_day <> p.posted_on
            then ' · date it went live ' || public.register_day(v_was_day) || ' → ' || public.register_day(p.posted_on) else '' end);
  return jsonb_build_object('ok', true, 'id', t.id, 'moved', v_moved, 'title', v_name,
    'was_live', v_was_day, 'live', p.posted_on);
end $$;

create or replace function public.sm_reports_owed(p_period text default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_period   text := coalesce(nullif(btrim(p_period), ''),
                       to_char(date_trunc('month', now() at time zone public.agency_tz()) - interval '1 month', 'YYYY-MM'));
  v_items    jsonb := '[]'::jsonb;
  v_seen     uuid[] := '{}';
  v_task     uuid;
  v_tdue     timestamptz;
  v_assignee text;
  v_due      timestamptz;
  v_found    boolean;
  e          record;
  k          text;
  r          record;
begin
  if not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if v_period !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then return jsonb_build_object('error', 'bad-period'); end if;

  -- Every report a month of the period asks for, found or not started.
  for e in
    select x.id, x.client_id, x.reports, s.starts, s.ends, c.name as client_name, c.slug as client_slug
      from public.ops_engagements x
      join public.clients c on c.id = x.client_id
     cross join lateral public.ops_month_span(x.period, x.start_day) s
     where x.period = v_period and x.status <> 'cancelled' and cardinality(x.reports) > 0
       and public.client_row_seen_by(c.stage, c.owner, c.owner_id, c.sales_by, 'view')
     order by c.name
  loop
    foreach k in array e.reports loop
      v_task := null; v_tdue := null; v_assignee := null;
      select x.id, x.current_final_due_at, m.name into v_task, v_tdue, v_assignee
        from public.ops_tasks x
        left join public.ops_task_assignees a
          on a.task_id = x.id and a.responsibility = 'owner' and a.ended_at is null
        left join public.team_members m on m.id = a.team_member_id
       where x.engagement_id = e.id and x.source_type = 'report_' || k
         and x.cancelled_at is null and x.archived_at is null
       order by x.created_at desc limit 1;
      v_due := coalesce(v_tdue,
        ((e.ends + public.app_setting('report_due_days', e.ends)::integer)::timestamp + time '23:59') at time zone public.agency_tz());
      v_found := false;
      for r in
        select y.id, y.status, y.sent_on, b.name as brand_name
          from public.sm_reports y
          left join public.client_brands b on b.id = y.brand_id
         where y.client_id = e.client_id and y.kind = k and not y.on_request
           and y.period_end between e.starts and e.ends
         order by b.name nulls first, y.period_start
      loop
        v_found := true;
        v_seen := v_seen || r.id;
        v_items := v_items || jsonb_build_object(
          'client_id', e.client_id, 'client', e.client_name, 'slug', e.client_slug, 'kind', k,
          'brand', r.brand_name, 'report_id', r.id, 'status', r.status, 'sent_on', r.sent_on,
          'asked', true, 'task_id', v_task, 'assignee', v_assignee, 'due', v_due,
          'late', r.status <> 'published' and now() > v_due);
      end loop;
      if not v_found then
        v_items := v_items || jsonb_build_object(
          'client_id', e.client_id, 'client', e.client_name, 'slug', e.client_slug, 'kind', k,
          'brand', null, 'report_id', null, 'status', 'none', 'sent_on', null,
          'asked', true, 'task_id', v_task, 'assignee', v_assignee, 'due', v_due, 'late', now() > v_due);
      end if;
    end loop;
  end loop;

  -- Every report made for the period that no month's tick asked for: it
  -- belongs to the month whose span holds its last day, else to the
  -- calendar month of that day.
  for r in
    select y.id, y.client_id, y.kind, y.status, y.sent_on, y.period_end,
           c.name as client_name, c.slug as client_slug, b.name as brand_name
      from public.sm_reports y
      join public.clients c on c.id = y.client_id
      left join public.client_brands b on b.id = y.brand_id
     where not (y.id = any (v_seen)) and not y.on_request
       and coalesce((select x.period from public.ops_engagements x
                      cross join lateral public.ops_month_span(x.period, x.start_day) s
                      where x.client_id = y.client_id and x.status <> 'cancelled'
                        and y.period_end between s.starts and s.ends
                      order by x.period desc limit 1),
                    to_char(y.period_end, 'YYYY-MM')) = v_period
       and public.client_row_seen_by(c.stage, c.owner, c.owner_id, c.sales_by, 'view')
     order by c.name, y.kind, b.name nulls first
  loop
    v_due := ((r.period_end + public.app_setting('report_due_days', r.period_end)::integer)::timestamp + time '23:59') at time zone public.agency_tz();
    v_items := v_items || jsonb_build_object(
      'client_id', r.client_id, 'client', r.client_name, 'slug', r.client_slug, 'kind', r.kind,
      'brand', r.brand_name, 'report_id', r.id, 'status', r.status, 'sent_on', r.sent_on,
      'asked', false, 'task_id', null, 'assignee', null, 'due', v_due,
      'late', r.status <> 'published' and now() > v_due);
  end loop;

  return jsonb_build_object('period', v_period, 'items', v_items);
end $$;

create or replace function public.hiring_doc_mark(p_doc uuid, p_route text, p_on date, p_path text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  d public.hiring_docs; v_role text;
  v_today date := (now() at time zone public.agency_tz())::date;
begin
  select * into d from public.hiring_docs where id = p_doc for update;
  if d.id is null then return jsonb_build_object('error', 'gone'); end if;
  v_role := public.hiring_role(d.candidate_id);
  if v_role is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_role not in ('admin', 'owner') then return jsonb_build_object('error', 'denied'); end if;
  if d.state not in ('sent', 'withdrawn') then return jsonb_build_object('error', 'not-sent'); end if;
  if coalesce(p_route, '') not in ('scan', 'paper') then return jsonb_build_object('error', 'bad-request'); end if;
  if p_on is null or p_on > v_today or p_on < (d.sent_at at time zone public.agency_tz())::date then return jsonb_build_object('error', 'bad-date'); end if;
  if coalesce(p_path, '') !~ ('^' || d.candidate_id::text || '/[0-9]{10,16}-[A-Za-z0-9._ -]{1,120}\.pdf$') then
    return jsonb_build_object('error', 'bad-file');
  end if;
  update public.hiring_docs set state = 'signed', signed_at = now(), answered_at = now(),
    signed = jsonb_build_object('via', p_route, 'on', p_on, 'path', p_path, 'record', jsonb_build_object('by', me.name, 'at', now())),
    updated_at = now()
   where id = d.id;
  update public.hiring_candidates set last_step_at = now(), updated_at = now() where id = d.candidate_id;
  perform public.hiring_log(d.candidate_id, 'candidate.document', d.serial || case p_route when 'scan' then ' signed by scan' else ' signed on paper' end ||
    ' on ' || public.register_day(p_on));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.careers_doc_of(p_key text, p_doc uuid)
returns public.hiring_docs language plpgsql stable security definer set search_path = public as $$
declare c public.hiring_candidates; d public.hiring_docs;
  v_days int := coalesce(public.app_setting('hiring_link_days', (now() at time zone public.agency_tz())::date)::int, 30);
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' or p_doc is null then return null; end if;
  select * into c from public.hiring_candidates where link_key = p_key and removed_at is null;
  if c.id is null or c.last_step_at + make_interval(days => v_days) <= now() then return null; end if;
  select * into d from public.hiring_docs where id = p_doc and candidate_id = c.id and state in ('sent', 'signed', 'confirmed', 'declined');
  return d;
end $$;

create or replace function public.portal_on(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.app_setting(p_key, (now() at time zone public.agency_tz())::date), 1) = 1
$$;

create or replace function public.portal_switch_set(p_key text, p_on boolean)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me      public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_was   numeric;
  v_to    numeric := case when coalesce(p_on, false) then 1 else 0 end;
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_key is null or p_key not in ('ai_on', 'email_on', 'whatsapp_on') then return jsonb_build_object('error', 'bad-key'); end if;
  v_was := coalesce(public.app_setting(p_key, v_today), 1);
  if v_was is not distinct from v_to then return jsonb_build_object('ok', true); end if;
  insert into public.app_settings (key, from_date, value, set_by, set_at)
  values (p_key, v_today, v_to, me.id, now())
  on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Portal switches',
          case p_key when 'ai_on' then 'AI: ' when 'email_on' then 'Email: ' else 'WhatsApp: ' end ||
          case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_to = 1 then 'On' else 'Off' end ||
          ' · from ' || public.register_day(v_today));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.auto_send_on(p_kind text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.portal_on(case p_kind when 'email' then 'email_on' else 'whatsapp_on' end)
     and coalesce(public.app_setting(case p_kind when 'email' then 'auto_email_on' else 'auto_whatsapp_on' end,
                                     (now() at time zone public.agency_tz())::date), 1) = 1
$$;

create or replace function public.ops_request_due_change(
  p_task uuid, p_kind text, p_value timestamptz, p_reason text,
  p_note text default null, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  t     public.ops_tasks;
  who   uuid;
  was   timestamptz;
  v_id  uuid;
  nm    text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_reason, '') = '' then return jsonb_build_object('error', 'reason-required'); end if;
  if p_kind not in ('first_draft', 'final') then return jsonb_build_object('error', 'bad-kind'); end if;
  if p_value is null then return jsonb_build_object('error', 'no-date'); end if;

  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;

  /* Refused before an ask is raised as well as before a move is made: an ask
     nobody could approve without breaking the plan is one to turn away at the
     door, with the word the move itself would have used. */
  if not public.ops_due_order_ok(
       case when p_kind = 'first_draft' then p_value else t.current_first_draft_due_at end,
       case when p_kind = 'final'       then p_value else t.current_final_due_at end) then
    return jsonb_build_object('error', 'draft-not-before-final');
  end if;

  who := public.ops_due_decider(p_task, p_kind);
  /* Nobody to ask — the team's own first draft milestone, or a task whose
     creator is the person asking — so the move is theirs to make and the
     round would be a form with one name on both ends. */
  /* An admin moves any date directly: the round protects the person who set
     the date from somebody else, and an admin is the one who may overwrite
     anybody's. The move still files its event and keeps the original. */
  if who is null or who = m.id or public.ops_granted('ops.override', 'work') then
    return public.ops_change_due_date(p_task, p_kind, p_value, p_reason, p_note, p_version);
  end if;

  was := case when p_kind = 'final' then t.current_final_due_at
              else t.current_first_draft_due_at end;

  insert into public.ops_due_requests
    (task_id, kind, was_at, wants_at, reason, note, asked_by, decider_id)
  values (p_task, p_kind, was, p_value, p_reason, nullif(btrim(p_note), ''), m.id, who)
  on conflict (task_id, kind) where state = 'asked' do nothing
  returning id into v_id;

  /* The same press twice is the same ask. The open one is handed back so the
     page can say it is already with somebody. */
  if v_id is null then
    select id into v_id from public.ops_due_requests
      where task_id = p_task and kind = p_kind and state = 'asked';
    return jsonb_build_object('ok', true, 'repeat', true, 'request', v_id,
                              'task', public.ops_task_json(p_task));
  end if;

  select name into nm from public.team_members where id = m.id;
  perform public.ops_notify(who, p_task, 'due_requested',
    'Extension requested',
    coalesce(nm, 'A colleague') || ' asked to move ' ||
      case when p_kind = 'final' then 'the due date' else 'the first draft date' end ||
      ' to ' || public.register_day((timezone(public.agency_tz(), p_value))::date),
    'due_req:' || v_id::text);

  perform public.ops_log(p_task, 'due_requested',
    jsonb_build_object('kind', p_kind, 'value', was),
    jsonb_build_object('kind', p_kind, 'value', p_value),
    jsonb_build_object('reason', p_reason, 'note', p_note, 'request', v_id));

  return jsonb_build_object('ok', true, 'request', v_id, 'asked', true,
                            'task', public.ops_task_json(p_task));
end $$;

create or replace function public.build_word(p_commit text, p_built timestamptz)
returns text
language sql immutable set search_path = public as $$
  select case when p_commit is null or p_built is null then 'not set'
    else 'v' || to_char(p_built at time zone public.agency_tz(), 'YY.MM.DD') || ' · ' || left(p_commit, 7) end
$$;

create or replace function public.hiring_doc_serial(p_kind text)
returns text language plpgsql volatile security definer set search_path = public as $$
declare
  v_pre text := 'ADHR/' || case p_kind when 'offer' then 'OFR' else 'EMP' end || to_char(now() at time zone public.agency_tz(), 'YYMM');
  v_n int;
begin
  perform pg_advisory_xact_lock(hashtext('hiring_doc_serial:' || p_kind));
  select coalesce(max(right(d.serial, 3)::int), 0) + 1 into v_n
    from (select d.serial from public.hiring_docs d where d.serial like v_pre || '___'
          union all select k.serial from public.hiring_serials_kept k where k.serial like v_pre || '___') d;
  if v_n > 999 then raise exception 'no-serial'; end if;
  return v_pre || lpad(v_n::text, 3, '0');
end $$;

create or replace function public.usage_month_of(p_from date, p_to date)
returns jsonb
language sql stable security definer set search_path = public as $$
  /* One month's use, Malaysia's days [p_from, p_to). */
  with a as (
    select count(*) as runs, coalesce(sum(d.input_tokens), 0) as tin, coalesce(sum(d.output_tokens), 0) as tout,
           coalesce(sum((coalesce(d.input_tokens, 0) * coalesce(public.app_setting('ai_price_in', (d.created_at at time zone public.agency_tz())::date), 0)
                       + coalesce(d.output_tokens, 0) * coalesce(public.app_setting('ai_price_out', (d.created_at at time zone public.agency_tz())::date), 0)) / 1000000.0
                       + coalesce(d.web_searches, 0) * coalesce(public.app_setting('ai_price_search', (d.created_at at time zone public.agency_tz())::date), 10) / 1000.0
                       + case when d.purpose = 'picture' and coalesce(d.model, '') like 'gemini%'
                              then coalesce(public.app_setting('ai_price_image', (d.created_at at time zone public.agency_tz())::date), 0.07) else 0 end), 0) as usd
      from public.ai_drafts d
     where d.created_at >= p_from::timestamp at time zone public.agency_tz()
       and d.created_at < p_to::timestamp at time zone public.agency_tz()
  ), m as (
    select (select count(*) from public.client_emails e where e.created_at >= p_from::timestamp at time zone public.agency_tz() and e.created_at < p_to::timestamp at time zone public.agency_tz())
         + (select count(*) from public.creator_emails e where e.created_at >= p_from::timestamp at time zone public.agency_tz() and e.created_at < p_to::timestamp at time zone public.agency_tz())
         + (select count(*) from public.supplier_emails e where e.created_at >= p_from::timestamp at time zone public.agency_tz() and e.created_at < p_to::timestamp at time zone public.agency_tz())
         + (select count(*) from public.system_emails e where e.created_at >= p_from::timestamp at time zone public.agency_tz() and e.created_at < p_to::timestamp at time zone public.agency_tz()) as emails,
           (select count(*) from public.wa_outbox w where w.created_at >= p_from::timestamp at time zone public.agency_tz() and w.created_at < p_to::timestamp at time zone public.agency_tz()) as whatsapp
  )
  select jsonb_build_object('ai_runs', a.runs, 'ai_tokens_in', a.tin, 'ai_tokens_out', a.tout, 'ai_usd', round(a.usd::numeric, 2),
                            'emails', m.emails, 'whatsapp', m.whatsapp)
    from a, m
$$;

create or replace function public.usage_report(p_month date default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_today date := (now() at time zone public.agency_tz())::date;
  v_m date;
  v_size bigint := pg_database_size(current_database());
  v_limit numeric;
begin
  if not public.ops_granted('team.settings', 'view') then return jsonb_build_object('error', 'denied'); end if;
  v_m := date_trunc('month', least(coalesce(p_month, v_today), v_today))::date;
  v_limit := coalesce(public.app_setting('plan_db_mb', v_today), 500);
  return jsonb_build_object(
    'month', v_m,
    'this', public.usage_month_of(v_m, least((v_m + interval '1 month')::date, v_today + 1)),
    'last', public.usage_month_of((v_m - interval '1 month')::date, v_m),
    'db', jsonb_build_object('bytes', v_size, 'limit_mb', v_limit,
            'alert_pct', coalesce(public.app_setting('plan_db_alert_pct', v_today), 80),
            'pct', round(v_size / (v_limit * 1048576.0) * 100, 1),
            'tables', coalesce((select jsonb_agg(jsonb_build_object('name', t.relname, 'bytes', t.b) order by t.b desc)
                                  from (select c.relname, pg_total_relation_size(c.oid) as b
                                          from pg_class c join pg_namespace n on n.oid = c.relnamespace
                                         where n.nspname = 'public' and c.relkind = 'r'
                                         order by 2 desc limit 5) t), '[]'::jsonb)),
    's3', (select jsonb_build_object('ran_at', s.ran_at, 'files', s.listed, 'bytes', s.listed_bytes)
             from public.s3_sweeps s where coalesce(s.failed, 0) = 0 and s.listed is not null
            order by s.ran_at desc limit 1));
end $$;

create or replace function public.usage_watch(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_today date := (p_now at time zone public.agency_tz())::date;
  v_m date := date_trunc('month', v_today)::date;
  v_last jsonb;
  v_size bigint := pg_database_size(current_database());
  v_limit numeric := coalesce(public.app_setting('plan_db_mb', v_today), 500);
  v_alert numeric := coalesce(public.app_setting('plan_db_alert_pct', v_today), 80);
  v_pct numeric;
  v_told int := 0;
  v_n int;
  v_words text;
begin
  v_pct := round(v_size / (v_limit * 1048576.0) * 100, 1);
  if extract(day from v_today) = 1 then
    v_last := public.usage_month_of((v_m - interval '1 month')::date, v_m);
    v_words := concat_ws(' · ',
      'Database ' || round(v_size / 1048576.0) || ' MB of ' || v_limit || ' MB',
      'AI ' || (v_last ->> 'ai_runs') || case when (v_last ->> 'ai_runs')::int = 1 then ' run' else ' runs' end
            || ', about US$ ' || to_char((v_last ->> 'ai_usd')::numeric, 'FM999,990.00'),
      (v_last ->> 'emails') || case when (v_last ->> 'emails')::int = 1 then ' email' else ' emails' end,
      (v_last ->> 'whatsapp') || case when (v_last ->> 'whatsapp')::int = 1 then ' WhatsApp message' else ' WhatsApp messages' end) || '.';
    insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
    select t.id, 'usage.month', 'Usage for ' || (array['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sept','Oct','Nov','Dec'])[extract(month from (v_m - interval '1 month'))::int] || ' ' || extract(year from (v_m - interval '1 month'))::int, v_words,
           'usage.month.' || to_char(v_m, 'YYYY-MM') || '.' || t.id
      from public.team_members t
     where t.active and t.is_admin
    on conflict (dedupe_key) do nothing;
    get diagnostics v_n = row_count; v_told := v_told + v_n;
  end if;
  if v_pct >= v_alert then
    insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
    select t.id, 'usage.limit', 'Database nearly full',
           'The database holds ' || round(v_size / 1048576.0) || ' MB of the database plan''s ' || v_limit || ' MB (' || v_pct || '%). Upgrade the plan or remove data that is no longer needed.',
           'usage.limit.' || to_char(v_m, 'YYYY-MM') || '.' || t.id
      from public.team_members t
     where t.active and t.is_admin
    on conflict (dedupe_key) do nothing;
    get diagnostics v_n = row_count; v_told := v_told + v_n;
  end if;
  return jsonb_build_object('db_pct', v_pct, 'told', v_told);
end $$;

create or replace function public.ops_timeliness(p_from timestamptz, p_to timestamptz)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  out jsonb;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_from date;
  v_to date;
  v_live boolean;
  v_all boolean := public.ops_granted('ops.all', 'view');
begin
  if not public.ops_granted('ops.reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '800 days' then
    return jsonb_build_object('error', 'bad-range');
  end if;
  v_from := (p_from at time zone public.agency_tz())::date;
  v_to := ((p_to - interval '1 microsecond') at time zone public.agency_tz())::date;
  v_live := p_to >= now() - interval '10 minutes';

  with
  base as (
    select t.id, t.task_no, t.title, t.client_id, t.created_at, t.completed_at, t.engagement_id,
           (t.current_final_due_at at time zone public.agency_tz())::date as due_d,
           case t.source_type when 'report_ads' then 'ads' when 'report_social' then 'social'
                else case when w.key = 'task' then 'task' else 'content' end end as kind,
           (select a.team_member_id from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc limit 1) as owner_id,
           (select min(e.created_at) from public.ops_task_events e
              join public.ops_workflow_stages s on s.workflow_id = t.workflow_id and s.key = e.to_value ->> 'stage_key'
             where e.task_id = t.id and e.event_type = 'stage_changed' and s.stage_group = 'client_review') as review_at
      from public.ops_tasks t
      join public.ops_workflows w on w.id = t.workflow_id
     where t.cancelled_at is null and t.archived_at is null
       and t.created_at < p_to
       and (t.completed_at is null or t.completed_at >= p_from - interval '120 days')
       and public.ops_task_in_scope(t.id)
  ),
  /* A month's report is delivered the day it was marked sent: the first
     version sent of the month's own report (never one on request). */
  rep as (
    select b.id, min(r.sent_on) as sent_on, max(s.ends) as span_end
      from base b
      join public.ops_engagements e on e.id = b.engagement_id
      cross join lateral public.ops_month_span(e.period, e.start_day) s
      left join public.sm_reports r
        on r.client_id = b.client_id and r.kind = b.kind and r.brand_id is null and not r.on_request
       and r.period_end between s.starts and s.ends and r.sent_on is not null
     where b.kind in ('ads', 'social')
     group by b.id
  ),
  items as (
    select b.*,
           case when b.kind in ('ads', 'social') then coalesce(rp.sent_on, (b.completed_at at time zone public.agency_tz())::date)
                else (coalesce(b.review_at, b.completed_at) at time zone public.agency_tz())::date end as done_d,
           case when b.kind in ('ads', 'social') then rp.span_end
                else (b.created_at at time zone public.agency_tz())::date end as start_d
      from base b
      left join rep rp on rp.id = b.id
  ),
  meas as (
    select x.*,
           case when x.due_d is null then null when x.diff < 0 then 'early' when x.diff = 0 then 'day' else 'late' end as said,
           to_char(coalesce(x.done_d, x.due_d), 'YYYY-MM') as mon,
           case when not x.open and x.start_d is not null then greatest(x.done_d - x.start_d, 0) end as turn
      from (
        select i.*, i.done_d - i.due_d as diff, false as open
          from items i
         where i.done_d between v_from and v_to
        union all
        /* Not delivered and past its due date: late by the days so far. */
        select i.*, v_today - i.due_d as diff, true as open
          from items i
         where i.done_d is null and i.due_d is not null and i.due_d < v_today
           and (i.due_d between v_from and v_to or v_live)
      ) x
  ),
  agg as (
    select grouping(m.owner_id) as g_o, grouping(m.kind) as g_k, grouping(m.mon) as g_m,
           m.owner_id, m.kind, m.mon,
           jsonb_build_object(
             'n', count(m.said),
             'early', count(*) filter (where m.said = 'early'),
             'on_day', count(*) filter (where m.said = 'day'),
             'late', count(*) filter (where m.said = 'late'),
             'late_open', count(*) filter (where m.said = 'late' and m.open),
             'delivered', count(*) filter (where not m.open),
             'late_days', round(avg(m.diff) filter (where m.said = 'late'), 1),
             'lateness', round(avg(greatest(m.diff, 0)) filter (where m.said is not null), 1),
             'lead_days', round(avg(-m.diff) filter (where m.said = 'early'), 1),
             'turn_days', round((percentile_cont(0.5) within group (order by m.turn))::numeric, 1),
             'turn_p90', round((percentile_cont(0.9) within group (order by m.turn))::numeric, 1)) as f
      from meas m
     group by grouping sets ((), (m.owner_id), (m.kind), (m.mon))
  )
  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'target', jsonb_build_object('pct', coalesce(public.app_setting('timely_pct', v_today), 85),
                                        'late_days', coalesce(public.app_setting('timely_late_days', v_today), 1)),
           'team', coalesce((select a.f from agg a where a.g_o = 1 and a.g_k = 1 and a.g_m = 1), '{}'::jsonb),
           'kinds', coalesce((select jsonb_agg(a.f || jsonb_build_object('kind', a.kind) order by a.kind)
                                from agg a where a.g_k = 0), '[]'::jsonb),
           'months', coalesce((select jsonb_agg(a.f || jsonb_build_object('month', a.mon) order by a.mon)
                                 from agg a where a.g_m = 0), '[]'::jsonb),
           'people', case when v_all then coalesce((
               select jsonb_agg(a.f || jsonb_build_object('team_member_id', a.owner_id, 'name', coalesce(tm.name, 'Unassigned'))
                                order by coalesce(tm.name, 'Unassigned'))
                 from agg a left join public.team_members tm on tm.id = a.owner_id
                where a.g_o = 0), '[]'::jsonb) end,
           'worst', case when v_all then coalesce((
               select jsonb_agg(q.x order by q.d desc, q.due) from (
                 select jsonb_build_object('task_id', m.id, 'task_no', m.task_no, 'title', m.title,
                          'client', c.name, 'owner', tm.name, 'owner_id', m.owner_id, 'kind', m.kind,
                          'due', m.due_d, 'delivered', m.done_d, 'open', m.open, 'days', m.diff) as x,
                        m.diff as d, m.due_d as due
                   from meas m
                   left join public.clients c on c.id = m.client_id
                   left join public.team_members tm on tm.id = m.owner_id
                  where m.said = 'late'
                  order by m.diff desc, m.due_d
                  limit 8) q), '[]'::jsonb) end)
    into out;
  return out;
end $$;

create or replace function public.ops_move_day(p_task uuid, p_on date, p_after timestamptz, p_window boolean)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_today date := (now() at time zone public.agency_tz())::date;
  v_back integer := coalesce(public.app_setting('stage_back_days', v_today), 7)::integer;
  v_floor timestamptz;
  v_at timestamptz;
begin
  if p_on > v_today then return jsonb_build_object('error', 'future-day'); end if;
  if p_window and p_on < v_today - v_back then
    return jsonb_build_object('error', 'too-early', 'days', v_back);
  end if;
  select greatest(t.created_at, coalesce(p_after, t.created_at)) into v_floor
    from public.ops_tasks t where t.id = p_task;
  if v_floor is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_on < (v_floor at time zone public.agency_tz())::date then
    return jsonb_build_object('error', 'before-last',
      'day', public.register_day((v_floor at time zone public.agency_tz())::date));
  end if;
  v_at := (p_on + time '18:00') at time zone public.agency_tz();
  if v_at <= v_floor then v_at := v_floor + interval '1 second'; end if;
  return jsonb_build_object('at', v_at);
end $$;

create or replace function public.ops_transition_task_on(
  p_task uuid, p_next text, p_on date, p_version integer default null, p_note text default null,
  p_assignee uuid default null, p_skip_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_today date := (now() at time zone public.agency_tz())::date;
  v_last timestamptz;
  v_day jsonb;
  v_at timestamptz;
  v_out jsonb;
begin
  if p_on is null or p_on = v_today then
    return public.ops_transition_task(p_task, p_next, p_version, p_note, p_assignee, p_skip_reason);
  end if;
  if (public.ops_me()).id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  select max(e.created_at) into v_last from public.ops_task_events e
   where e.task_id = p_task and e.event_type = 'stage_changed';
  v_day := public.ops_move_day(p_task, p_on, v_last, true);
  if v_day ? 'error' then return v_day; end if;
  v_at := (v_day ->> 'at')::timestamptz;
  v_out := public.ops_transition_task(p_task, p_next, p_version, p_note, p_assignee, p_skip_reason);
  if v_out ? 'error' then return v_out; end if;
  /* The rows this move wrote, in this transaction, take its day. */
  update public.ops_task_events e
     set created_at = v_at,
         detail = case when e.event_type = 'stage_changed'
                       then e.detail || jsonb_build_object('dated', p_on) else e.detail end
   where e.task_id = p_task and e.recorded_at = now()
     and e.event_type in ('stage_changed', 'stage_skipped', 'delivered', 'completed');
  update public.ops_tasks t set
    first_draft_submitted_at = case when t.first_draft_submitted_at = now() then v_at else t.first_draft_submitted_at end,
    delivered_at = case when t.delivered_at = now() then v_at else t.delivered_at end,
    completed_at = case when t.completed_at = now() then v_at else t.completed_at end,
    cancelled_at = case when t.cancelled_at = now() then v_at else t.cancelled_at end
   where t.id = p_task;
  return public.ops_task_json(p_task);
end $$;

create or replace function public.ops_task_move_redate(p_event uuid, p_on date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m      public.team_members;
  ev     public.ops_task_events;
  v_admin boolean;
  v_prev timestamptz;
  v_next timestamptz;
  v_day  jsonb;
  v_at   timestamptz;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_back integer := coalesce(public.app_setting('stage_back_days', v_today), 7)::integer;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  select * into ev from public.ops_task_events e where e.id = p_event and e.event_type = 'stage_changed';
  if ev.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.ops_may_see_task(ev.task_id) or not public.allowed('ops', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  v_admin := public.ops_granted('ops.override', 'work');
  /* A colleague dates again a move of their own made inside the window; an
     admin any move. */
  if not v_admin and (ev.actor_id is distinct from m.id
       or (ev.recorded_at at time zone public.agency_tz())::date < v_today - v_back) then
    return jsonb_build_object('error', 'not-yours');
  end if;
  perform 1 from public.ops_tasks t where t.id = ev.task_id for update;
  select max(e.created_at) into v_prev from public.ops_task_events e
   where e.task_id = ev.task_id and e.event_type = 'stage_changed' and e.created_at < ev.created_at;
  select min(e.created_at) into v_next from public.ops_task_events e
   where e.task_id = ev.task_id and e.event_type = 'stage_changed' and e.created_at > ev.created_at;
  v_day := public.ops_move_day(ev.task_id, p_on, v_prev, not v_admin);
  if v_day ? 'error' then return v_day; end if;
  v_at := (v_day ->> 'at')::timestamptz;
  if v_next is not null and v_at >= v_next then
    if p_on > (v_next at time zone public.agency_tz())::date then
      return jsonb_build_object('error', 'after-next',
        'day', public.register_day((v_next at time zone public.agency_tz())::date));
    end if;
    v_at := v_next - interval '1 second';
  end if;
  if v_at = ev.created_at then return public.ops_task_json(ev.task_id); end if;
  /* The rows of the same move (one press, one recorded moment) and the
     task's stamps it set follow it. */
  update public.ops_tasks t set
    first_draft_submitted_at = case when t.first_draft_submitted_at = ev.created_at then v_at else t.first_draft_submitted_at end,
    delivered_at = case when t.delivered_at = ev.created_at then v_at else t.delivered_at end,
    completed_at = case when t.completed_at = ev.created_at then v_at else t.completed_at end,
    cancelled_at = case when t.cancelled_at = ev.created_at then v_at else t.cancelled_at end
   where t.id = ev.task_id;
  update public.ops_task_events e
     set created_at = v_at,
         detail = case when e.id = ev.id then e.detail || jsonb_build_object('dated', p_on) else e.detail end
   where e.task_id = ev.task_id and e.recorded_at = ev.recorded_at and e.created_at = ev.created_at
     and e.event_type in ('stage_changed', 'stage_skipped', 'delivered', 'completed');
  perform public.ops_log(ev.task_id, 'move_dated',
    jsonb_build_object('at', ev.created_at, 'event', ev.id),
    jsonb_build_object('at', v_at, 'stage_key', ev.to_value ->> 'stage_key'), '{}'::jsonb);
  return public.ops_task_json(ev.task_id);
end $$;

create or replace function public.payment_analysis(p_currency text default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_from date;
  v_y1 date;
  v_y2 date;
  v_wk0 date;
  v_scope jsonb;
  v_cur text;
  v_curs jsonb;
  v_lag numeric;
  v_sum jsonb;
  v_payers jsonb;
  v_weeks jsonb;
  v_later jsonb;
  v_marks jsonb;
begin
  if me.id is null or not public.allowed('clients.billing', 'manage') then
    return jsonb_build_object('error', 'denied');
  end if;
  v_scope := public.invoice_scope();
  if v_scope ? 'error' then return jsonb_build_object('error', v_scope ->> 'error'); end if;
  v_from := (v_today - interval '24 months')::date;
  v_y1 := (v_today - interval '12 months')::date;
  v_y2 := v_from;
  v_wk0 := v_today - (extract(isodow from v_today)::integer - 1);

  select coalesce(jsonb_agg(c.currency order by c.currency <> 'MYR', c.n desc, c.currency), '[]'::jsonb) into v_curs
    from (select x.currency, count(*) as n from public.payment_docs(v_scope, v_from) x group by x.currency) c;
  v_cur := case when p_currency is not null and v_curs ? p_currency then p_currency
                when v_curs ? 'MYR' or jsonb_array_length(v_curs) = 0 then 'MYR'
                else v_curs ->> 0 end;

  /* Everyone's average days from due to paid, for a payer with none. */
  select avg(x.paid_on - x.due) into v_lag
    from public.payment_docs(v_scope, v_from) x
   where x.currency = v_cur and x.balance <= 0 and x.paid_on is not null and x.paid_on > v_y1;

  select jsonb_build_object(
      'open', coalesce(sum(x.balance) filter (where x.balance > 0), 0),
      'overdue', coalesce(sum(x.balance) filter (where x.balance > 0 and x.due < v_today), 0),
      'open_count', count(*) filter (where x.balance > 0),
      'aging', jsonb_build_object(
        'current', coalesce(sum(x.balance) filter (where x.balance > 0 and x.due >= v_today), 0),
        'd30', coalesce(sum(x.balance) filter (where x.balance > 0 and v_today - x.due between 1 and 30), 0),
        'd60', coalesce(sum(x.balance) filter (where x.balance > 0 and v_today - x.due between 31 and 60), 0),
        'd90', coalesce(sum(x.balance) filter (where x.balance > 0 and v_today - x.due between 61 and 90), 0),
        'over90', coalesce(sum(x.balance) filter (where x.balance > 0 and v_today - x.due > 90), 0)),
      'invoiced_90', coalesce(sum(x.amount) filter (where x.doc_date > v_today - 90), 0),
      'dso', case when coalesce(sum(x.amount) filter (where x.doc_date > v_today - 90), 0) > 0
                  then round(coalesce(sum(x.balance) filter (where x.balance > 0), 0)
                             / sum(x.amount) filter (where x.doc_date > v_today - 90) * 90) end,
      'paid', count(*) filter (where x.balance <= 0 and x.paid_on > v_y1),
      'days_to_pay', round(avg(x.paid_on - x.doc_date) filter (where x.balance <= 0 and x.paid_on > v_y1), 1),
      'days_late', round(avg(greatest(0, x.paid_on - x.due)) filter (where x.balance <= 0 and x.paid_on > v_y1), 1),
      'on_time', round(100.0 * count(*) filter (where x.balance <= 0 and x.paid_on > v_y1 and x.paid_on <= x.due)
                       / nullif(count(*) filter (where x.balance <= 0 and x.paid_on > v_y1), 0)),
      'paid_before', count(*) filter (where x.balance <= 0 and x.paid_on > v_y2 and x.paid_on <= v_y1),
      'days_to_pay_before', round(avg(x.paid_on - x.doc_date) filter (where x.balance <= 0 and x.paid_on > v_y2 and x.paid_on <= v_y1), 1),
      'days_late_before', round(avg(greatest(0, x.paid_on - x.due)) filter (where x.balance <= 0 and x.paid_on > v_y2 and x.paid_on <= v_y1), 1),
      'on_time_before', round(100.0 * count(*) filter (where x.balance <= 0 and x.paid_on > v_y2 and x.paid_on <= v_y1 and x.paid_on <= x.due)
                       / nullif(count(*) filter (where x.balance <= 0 and x.paid_on > v_y2 and x.paid_on <= v_y1), 0)),
      'invoices', count(*))
    into v_sum
    from public.payment_docs(v_scope, v_from) x
   where x.currency = v_cur;

  select coalesce(jsonb_agg(to_jsonb(p) - 'lag' order by p.open desc, p.name), '[]'::jsonb) into v_payers
    from (
      select x.contact_id as contact, min(x.payer) as name, x.client_id as client, x.client_name, x.slug, x.code,
             count(*) as invoices,
             count(*) filter (where x.balance <= 0) as paid,
             round(avg(x.paid_on - x.doc_date) filter (where x.balance <= 0 and x.paid_on > v_y1), 1) as days_to_pay,
             round(avg(greatest(0, x.paid_on - x.due)) filter (where x.balance <= 0 and x.paid_on > v_y1), 1) as days_late,
             round(100.0 * count(*) filter (where x.balance <= 0 and x.paid_on > v_y1 and x.paid_on <= x.due)
                   / nullif(count(*) filter (where x.balance <= 0 and x.paid_on > v_y1), 0)) as on_time,
             round(avg(greatest(0, x.paid_on - x.due)) filter (where x.balance <= 0 and x.paid_on > v_y2 and x.paid_on <= v_y1), 1) as late_before,
             coalesce(sum(x.balance) filter (where x.balance > 0), 0) as open,
             coalesce(sum(x.balance) filter (where x.balance > 0 and x.due < v_today), 0) as overdue,
             max(x.paid_on) as last_paid,
             avg(x.paid_on - x.due) filter (where x.balance <= 0 and x.paid_on > v_y1) as lag
        from public.payment_docs(v_scope, v_from) x
       where x.currency = v_cur
       group by x.contact_id, x.client_id, x.client_name, x.slug, x.code
    ) p;

  /* Thirteen weeks from this Monday: in, each open invoice at its due date
     moved by its payer's lag; out, the unpaid bills by their due date; never
     before today; what falls after the thirteenth week is `later`. */
  with lags as (
    select x.contact_id, avg(x.paid_on - x.due) as lag
      from public.payment_docs(v_scope, v_from) x
     where x.currency = v_cur and x.balance <= 0 and x.paid_on is not null and x.paid_on > v_y1
     group by x.contact_id
  ), ins as (
    select greatest(v_today, x.due + round(coalesce(l.lag, v_lag, 0))::integer) as at, x.balance as amt
      from public.payment_docs(v_scope, v_from) x left join lags l on l.contact_id = x.contact_id
     where x.currency = v_cur and x.balance > 0
  ), outs as (
    select greatest(v_today, b.due) as at, b.amount as amt, b.source
      from public.payment_bills(v_scope) b where b.currency = v_cur
  ), wk as (
    select g as n, v_wk0 + g * 7 as start from generate_series(0, 12) g
  )
  select jsonb_agg(jsonb_build_object('start', wk.start,
           'in', coalesce((select sum(i.amt) from ins i where i.at >= wk.start and i.at < wk.start + 7), 0),
           'out', coalesce((select sum(o.amt) from outs o where o.at >= wk.start and o.at < wk.start + 7), 0),
           'creators', coalesce((select sum(o.amt) from outs o where o.source = 'creator' and o.at >= wk.start and o.at < wk.start + 7), 0),
           'suppliers', coalesce((select sum(o.amt) from outs o where o.source = 'supplier' and o.at >= wk.start and o.at < wk.start + 7), 0))
           order by wk.n),
         jsonb_build_object(
           'in', coalesce((select sum(i.amt) from ins i where i.at >= v_wk0 + 91), 0),
           'out', coalesce((select sum(o.amt) from outs o where o.at >= v_wk0 + 91), 0))
    into v_weeks, v_later
    from wk;

  select jsonb_build_object('back_to', min(m.back_to) filter (where m.kind = 'invoice'), 'read_at', max(m.read_at))
    into v_marks from public.bukku_doc_marks m;

  return jsonb_build_object('ok', true, 'today', v_today, 'from', v_from, 'currency', v_cur, 'currencies', v_curs,
    'all', coalesce((v_scope ->> 'all')::boolean, false), 'lag', round(v_lag, 1),
    'summary', v_sum, 'payers', v_payers, 'weeks', v_weeks, 'later', v_later,
    'back_to', v_marks ->> 'back_to', 'read_at', v_marks ->> 'read_at');
end $$;

create or replace function public.hiring_decide_by_at(p_at timestamptz, p_n int)
returns timestamptz language sql stable security definer set search_path = public as $$
  select (public.hiring_workday_add((p_at at time zone public.agency_tz())::date,
           coalesce(p_n, public.app_setting('hiring_decision_days', (p_at at time zone public.agency_tz())::date)::int, 7))
          + time '18:00') at time zone public.agency_tz();
$$;

create or replace function public.hiring_decide_by_suggest()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare me public.team_members := public.ops_me();
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object('ok', true, 'at', public.hiring_decide_by_at(now(), null), 'latest', public.hiring_decide_by_at(now(), 30),
    'days', coalesce(public.app_setting('hiring_decision_days', (now() at time zone public.agency_tz())::date)::int, 7));
end $$;

create or replace function public.hiring_when(p_at timestamptz)
returns text language sql stable set search_path = public as $$
  select case when p_at is null then null else
    public.register_day((p_at at time zone public.agency_tz())::date) || ' ('
    || to_char(p_at at time zone public.agency_tz(), 'FMDay') || '), '
    || ltrim(lower(to_char(p_at at time zone public.agency_tz(), 'HH12:MIam')), '0') end;
$$;

create or replace function public.hiring_decide_by_change(p_interview uuid, p_decide_by timestamptz, p_note text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  i public.hiring_interviews;
  c public.hiring_candidates;
  v_role text;
begin
  select * into i from public.hiring_interviews where id = p_interview for update;
  if i.id is null then return jsonb_build_object('error', 'not-found'); end if;
  v_role := public.hiring_role(i.candidate_id);
  if v_role is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_role not in ('admin', 'owner') then return jsonb_build_object('error', 'denied'); end if;
  select * into c from public.hiring_candidates where id = i.candidate_id for update;
  if i.held_at is null or c.decide_by is null then return jsonb_build_object('error', 'not-held'); end if;
  if c.outcome is not null then return jsonb_build_object('error', 'decided'); end if;
  if p_decide_by is null or p_decide_by <= now() then return jsonb_build_object('error', 'past'); end if;
  if p_decide_by > public.hiring_decide_by_at(now(), 30) then return jsonb_build_object('error', 'too-far'); end if;
  if not public.is_working_day((p_decide_by at time zone public.agency_tz())::date) then return jsonb_build_object('error', 'not-workday'); end if;
  if char_length(coalesce(p_note, '')) > 500 then return jsonb_build_object('error', 'too-long'); end if;
  if p_decide_by = c.decide_by and nullif(btrim(coalesce(p_note, '')), '') is not distinct from c.decide_note then
    return jsonb_build_object('ok', true, 'same', true, 'decide_by', c.decide_by);
  end if;
  update public.hiring_candidates set decide_by = p_decide_by, decide_note = nullif(btrim(coalesce(p_note, '')), ''),
    decide_soon_at = null, decide_due_at = null, decide_moved_at = now(), last_step_at = now(), updated_at = now() where id = c.id;
  update public.hiring_interviews set held_mail = null, held_mail_at = null, updated_at = now() where id = i.id;
  perform public.hiring_log(c.id, 'candidate.interview', 'Decision date changed from ' || public.hiring_when(c.decide_by) ||
    ' to ' || public.hiring_when(p_decide_by));
  return jsonb_build_object('ok', true, 'was', c.decide_by, 'decide_by', p_decide_by);
end $$;

create or replace function public.hiring_decide_remind(p_today date default null)
returns int language plpgsql security definer set search_path = public as $$
declare
  r record;
  n int := 0;
  v_today date := coalesce(p_today, (now() at time zone public.agency_tz())::date);
  v_day date;
  v_left int;
  v_when text;
begin
  for r in
    select c.id, c.position, c.decide_by, c.decide_soon_at, c.decide_due_at, c.decide_over_on from public.hiring_candidates c
     where c.decide_by is not null and c.outcome is null and c.removed_at is null and c.stage = 'interview'
     for update
  loop
    v_day := (r.decide_by at time zone public.agency_tz())::date;
    if v_today = v_day and r.decide_due_at is null then
      update public.hiring_candidates set decide_due_at = now() where id = r.id;
      perform public.hiring_tell(r.id, 'hiring.decide_due', 'A hiring decision is due today',
        'Decide on the ' || r.position || ' candidate by ' || public.hiring_when(r.decide_by) || ' on the Scores tab.');
      n := n + 1;
    elsif v_today < v_day and v_today >= public.hiring_workday_add(v_day, -2) and r.decide_soon_at is null then
      select count(*) into v_left from generate_series(v_today + 1, v_day, interval '1 day') g(d)
       where public.is_working_day(g.d::date);
      v_when := case when v_day = v_today + 1 then 'tomorrow' when v_left <= 1 then 'on the next working day'
        else 'in ' || v_left || ' working days' end;
      update public.hiring_candidates set decide_soon_at = now() where id = r.id;
      perform public.hiring_tell(r.id, 'hiring.decide_soon', 'A hiring decision is due ' || v_when,
        'Decide on the ' || r.position || ' candidate by ' || public.hiring_when(r.decide_by) || ' on the Scores tab.');
      n := n + 1;
    elsif v_today > v_day and public.is_working_day(v_today) and r.decide_over_on is distinct from v_today then
      update public.hiring_candidates set decide_over_on = v_today where id = r.id;
      perform public.hiring_tell(r.id, 'hiring.decide_over', 'A hiring decision is overdue',
        'The decision on the ' || r.position || ' candidate was due ' || public.hiring_when(r.decide_by) || '. Decide on the Scores tab, or change the decision date.');
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;

create or replace function public.hiring_day_end(p_at timestamptz, p_days int)
returns timestamptz language sql stable security definer set search_path = public as $$
  select (((p_at at time zone public.agency_tz())::date + coalesce(p_days, 0)) + time '18:00') at time zone public.agency_tz();
$$;

create or replace function public.hiring_reply_by(p_invited timestamptz, p_slots timestamptz[])
returns timestamptz language sql stable security definer set search_path = public as $$
  select least(public.hiring_day_end(p_invited, coalesce(public.app_setting('hiring_reply_days',
           (p_invited at time zone public.agency_tz())::date)::int, 3)),
         (select max(s) from unnest(p_slots) s));
$$;

create or replace function public.sm_report_task_move(
  p_task uuid, p_to text, p_sent date, p_note text, p_report uuid, p_quiet boolean default false)
returns void
language plpgsql security definer set search_path = public as $$
declare
  t public.ops_tasks;
  ws public.ops_work_sessions;
  v_done boolean := p_to = 'complete';
  v_at timestamptz;
  v_mins integer;
  v_from jsonb;
  v_to jsonb;
  v_detail jsonb := jsonb_build_object('note', p_note, 'report_id', p_report);
begin
  select * into t from public.ops_tasks x where x.id = p_task for update;
  if t.id is null or p_to is null or t.stage_key is not distinct from p_to then return; end if;
  if v_done then
    v_at := least(now(), ((coalesce(p_sent, (now() at time zone public.agency_tz())::date) + 1)::timestamp
                          at time zone public.agency_tz()) - interval '1 second');
  end if;
  update public.ops_tasks set stage_key = p_to, version = version + 1, updated_at = now(),
         completed_at = v_at, blocked_at = null, blocked_category = null
   where id = t.id;
  v_from := jsonb_build_object('stage_key', t.stage_key);
  v_to := jsonb_build_object('stage_key', p_to);
  if p_quiet then
    insert into public.ops_task_events (task_id, event_type, from_value, to_value, detail)
    values (t.id, 'stage_changed', v_from, v_to, v_detail);
  else
    perform public.ops_log(t.id, 'stage_changed', v_from, v_to, v_detail);
  end if;
  if v_done then
    for ws in select * from public.ops_work_sessions x
               where x.task_id = t.id and x.ended_at is null loop
      v_mins := greatest(0, (extract(epoch from (now() - ws.started_at)) / 60)::integer);
      update public.ops_work_sessions set ended_at = now(), minutes = v_mins where id = ws.id;
      insert into public.ops_task_events (task_id, event_type, to_value, detail)
      values (t.id, 'work_stopped', jsonb_build_object('session_id', ws.id, 'minutes', v_mins),
              jsonb_build_object('note', 'Stopped when the task finished'));
    end loop;
    if p_quiet then
      insert into public.ops_task_events (task_id, event_type, detail)
      values (t.id, 'completed', jsonb_build_object('report_id', p_report));
    else
      perform public.ops_log(t.id, 'completed', null, null, jsonb_build_object('report_id', p_report));
    end if;
  end if;
end $$;

create or replace function public.verify_check_note(f jsonb)
returns void
language plpgsql volatile set search_path = public as $$
declare
  v_ip   text := public.request_ip();
  v_day  date := (now() at time zone public.agency_tz())::date;
  v_salt text;
  v_id   uuid;
  v_new  integer := 0;
begin
  if f is null or coalesce(f ->> 'src', '') = '' or coalesce(f ->> 'id', '') = '' or v_ip = '' or public.is_team() then return; end if;
  begin
    v_id := (f ->> 'id')::uuid;
  exception when others then return;
  end;
  select s.value into v_salt from public.app_secrets s where s.key = 'verify_check_salt';
  if v_salt is null then
    insert into public.app_secrets (key, value)
    values ('verify_check_salt', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
    on conflict (key) do nothing;
    select s.value into v_salt from public.app_secrets s where s.key = 'verify_check_salt';
  end if;
  insert into public.verify_checks (kind, doc_id, day, addr_hash)
  values (f ->> 'src', v_id, v_day, encode(sha256(convert_to(v_salt || '|' || v_day::text || '|' || v_ip, 'UTF8')), 'hex'))
  on conflict do nothing;
  get diagnostics v_new = row_count;
  if v_new > 0 then
    insert into public.verify_check_totals as t (kind, doc_id, n) values (f ->> 'src', v_id, 1)
    on conflict (kind, doc_id) do update set n = t.n + 1;
  end if;
end $$;

create or replace function public.manual_send_on(p_channel text)
returns boolean language sql stable security definer set search_path = public as $$
  select p_channel in ('email', 'whatsapp') and public.portal_on(p_channel || '_on')
     and coalesce(public.app_setting(case p_channel when 'email' then 'client_email_on' else 'client_wa_on' end,
                                     (now() at time zone public.agency_tz())::date), 1) = 1
$$;

create or replace function public.manual_send_set(p_channel text, p_on boolean)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me      public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_key   text := case p_channel when 'email' then 'client_email_on' when 'whatsapp' then 'client_wa_on' end;
  v_was   numeric;
  v_to    numeric := case when coalesce(p_on, false) then 1 else 0 end;
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if v_key is null then return jsonb_build_object('error', 'bad-kind'); end if;
  v_was := coalesce(public.app_setting(v_key, v_today), 1);
  if v_was is not distinct from v_to then return jsonb_build_object('ok', true); end if;
  insert into public.app_settings (key, from_date, value, set_by, set_at)
  values (v_key, v_today, v_to, me.id, now())
  on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Settings',
          case p_channel when 'email' then 'Send by email: ' else 'Send on WhatsApp: ' end ||
          case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_to = 1 then 'On' else 'Off' end ||
          ' · from ' || public.register_day(v_today));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.health_load(p_member uuid, p_day date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_m     public.team_members;
  v_ws    date := public.health_week(p_day);
  v_cap   integer;
  v_near  numeric := coalesce(public.app_setting('health_near_pct', p_day), 90);
  v_each  integer := round(coalesce(public.app_setting('health_task_hours', p_day), 2) * 60)::integer;
  v_load  integer := 0; v_late integer := 0; v_n integer := 0; v_nl integer := 0; v_ne integer := 0;
begin
  select * into v_m from public.team_members t where t.id = p_member;
  if v_m.id is null then return null; end if;
  v_cap := coalesce(v_m.capacity_minutes_week,
                    round(coalesce(public.app_setting('health_cap_default', p_day), 45) * 60)::integer);
  select coalesce(sum(x.mins), 0), coalesce(sum(x.mins) filter (where x.day < p_day), 0),
         count(*), count(*) filter (where x.day < p_day), count(*) filter (where x.est is null)
    into v_load, v_late, v_n, v_nl, v_ne
    from (select t.estimate_minutes as est, coalesce(t.estimate_minutes, v_each) as mins,
                 (case when t.first_draft_submitted_at is null and t.current_first_draft_due_at is not null
                       then t.current_first_draft_due_at else t.current_final_due_at end
                  at time zone public.agency_tz())::date as day
            from public.ops_tasks t
           where t.completed_at is null and t.cancelled_at is null and t.archived_at is null
             and exists (select 1 from public.ops_task_assignees a
                          where a.task_id = t.id and a.team_member_id = p_member
                            and a.responsibility = 'owner' and a.ended_at is null)) x
   where x.day is not null and x.day <= v_ws + 6;
  return jsonb_build_object('week', v_ws, 'week_end', v_ws + 6,
    'measured', not (coalesce(v_m.is_admin, false) or v_m.role = 'admin' or coalesce(v_m.system, false) or v_cap <= 0),
    'cap', v_cap, 'load', v_load, 'late', v_late, 'tasks', v_n, 'late_tasks', v_nl, 'no_estimate', v_ne,
    'pct', case when v_cap > 0 then round(v_load * 100.0 / v_cap) end,
    'near', v_near,
    'heavy', not (coalesce(v_m.is_admin, false) or v_m.role = 'admin' or coalesce(v_m.system, false) or v_cap <= 0)
             and v_load * 100.0 >= v_cap * v_near);
end $$;

create or replace function public.health_period(p_member uuid, p_day date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_l jsonb; v_kind text; v_s date; v_e date; v_c public.health_moods;
begin
  v_l := public.health_load(p_member, p_day);
  if coalesce((v_l ->> 'heavy')::boolean, false) then
    v_kind := 'week'; v_s := public.health_week(p_day); v_e := v_s + 6;
  else
    v_kind := 'month'; v_s := date_trunc('month', p_day)::date; v_e := (v_s + interval '1 month' - interval '1 day')::date;
  end if;
  select * into v_c from public.health_moods k
   where k.team_member_id = p_member
     and greatest(k.period_start, (k.created_at at time zone public.agency_tz())::date) between v_s and v_e
   order by (k.period = v_kind and k.period_start = v_s) desc, k.created_at desc limit 1;
  return jsonb_build_object('kind', v_kind, 'start', v_s, 'end', v_e, 'load', v_l,
    'due', v_c.id is null, 'current', case when v_c.id is null then null else public.health_mood_json(v_c) end);
end $$;

create or replace function public.health_team(p_token text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; h date; e text; d date := public.health_today(); w0 date;
begin
  m := public.ops_me();
  e := public.health_check(p_token);
  if e is not null then return jsonb_build_object('error', e); end if;
  h := public.health_half(d);
  w0 := public.health_week(d) - 77;
  return jsonb_build_object('half', h, 'half_end', public.health_half_end(h), 'today', d,
    'people', coalesce((select jsonb_agg(jsonb_build_object(
        'id', t.id, 'name', t.name, 'staff_code', t.staff_code, 'designation', t.designation,
        'department', t.department, 'role', t.role,
        'consent', case when c.team_member_id is null then null else jsonb_build_object(
          'agreed_at', c.agreed_at, 'withdrawn_at', c.withdrawn_at,
          'current', c.wording >= public.health_wording_now()) end,
        'period', public.health_period(t.id, d) - 'current'
                  || jsonb_build_object('current', case when public.health_agreed(t.id)
                       then public.health_period(t.id, d) -> 'current' end),
        'moods', case when public.health_agreed(t.id) then coalesce((
            select jsonb_agg(public.health_mood_json(x) order by x.created_at desc)
              from (select * from public.health_moods k
                     where k.team_member_id = t.id and k.updated_at >= c.agreed_at
                     order by k.created_at desc limit 26) x), '[]'::jsonb) else '[]'::jsonb end,
        'checkins', case when public.health_agreed(t.id) then coalesce((
            select jsonb_agg(public.health_checkin_json(x) order by x.half desc)
              from (select * from public.health_checkins k
                     where k.team_member_id = t.id and k.updated_at >= c.agreed_at
                     order by k.half desc limit 12) x), '[]'::jsonb) else '[]'::jsonb end)
        order by t.staff_code nulls last, t.name)
        from public.team_members t
        left join public.health_consents c on c.team_member_id = t.id
       where t.active), '[]'::jsonb),
    /* What the team reads together never names a colleague: a week, or a
       band, of fewer than 3 check-ins is sent without its average. */
    'trend', (select jsonb_agg(jsonb_build_object('week', wk.w, 'n', coalesce(s.n, 0),
                'avg', case when coalesce(s.n, 0) >= 3 then s.avg end) order by wk.w)
                from generate_series(w0, public.health_week(d), interval '7 days') wk0(x)
                cross join lateral (select wk0.x::date as w) wk
                left join (select public.health_week(greatest(k.period_start, (k.created_at at time zone public.agency_tz())::date)) as w,
                                  count(*)::integer as n, round(avg(k.mood), 1) as avg
                             from public.health_moods k
                             join public.health_consents c2 on c2.team_member_id = k.team_member_id
                             join public.team_members t2 on t2.id = k.team_member_id and t2.active
                            where public.health_agreed(k.team_member_id) and k.updated_at >= c2.agreed_at
                              and greatest(k.period_start, (k.created_at at time zone public.agency_tz())::date) >= w0
                            group by 1) s on s.w = wk.w),
    'bands', (select jsonb_agg(jsonb_build_object('band', b.band, 'n', coalesce(s.n, 0),
                'avg', case when coalesce(s.n, 0) >= 3 then s.avg end) order by b.band)
                from (values (1), (2), (3)) b(band)
                left join (select case when k.load_minutes * 100.0 < k.cap_minutes * 50 then 1
                                       when k.load_minutes * 100.0 < k.cap_minutes * coalesce(public.app_setting('health_near_pct', d), 90) then 2
                                       else 3 end as band,
                                  count(*)::integer as n, round(avg(k.mood), 1) as avg
                             from public.health_moods k
                             join public.health_consents c2 on c2.team_member_id = k.team_member_id
                             join public.team_members t2 on t2.id = k.team_member_id and t2.active
                            where public.health_agreed(k.team_member_id) and k.updated_at >= c2.agreed_at
                              and k.cap_minutes > 0 and k.load_minutes is not null
                              and greatest(k.period_start, (k.created_at at time zone public.agency_tz())::date) >= w0
                            group by 1) s on s.band = b.band),
    'talks', coalesce((select jsonb_agg(jsonb_build_object(
        'id', k.id, 'from', f.name, 'from_id', k.team_member_id, 'with', w.name, 'with_id', k.with_id,
        'status', k.status, 'at', k.created_at, 'closed_at', k.closed_at)
        order by (k.status = 'open') desc, k.created_at desc)
        from public.health_talks k
        join public.team_members f on f.id = k.team_member_id
        join public.team_members w on w.id = k.with_id
       where k.status <> 'withdrawn' and k.created_at > now() - interval '90 days'
         and public.health_agreed(k.team_member_id)), '[]'::jsonb));
end $$;

create or replace function public.campaign_creator_bills(p_campaign uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_client uuid;
begin
  if (public.ops_me()).id is null or not public.allowed('campaigns', 'view')
     or not public.ops_granted('campaigns.pay', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select m.client_id into v_client from public.campaigns m where m.id = p_campaign;
  if v_client is null or not public.client_seen(v_client, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  return jsonb_build_object('ok', true,
    'bookings', coalesce((select jsonb_agg(jsonb_build_object(
        'option', o.id, 'creator', o.creator_id, 'state', o.state, 'posted_on', o.posted_on,
        'linked', exists (select 1 from public.bukku_links l
                           where l.kind = 'creator' and l.record_id = o.creator_id and l.contact_id is not null),
        'bill', case when b.bill_id is not null then jsonb_build_object(
                  'number', b.number, 'status', b.status, 'date', b.bill_date,
                  'paid_on', case when b.status = 'paid' then coalesce(b.paid_on, (b.paid_seen_at at time zone public.agency_tz())::date) end,
                  'amount', b.amount, 'currency', b.currency) end)
        order by o.position)
        from public.campaign_options o
        left join lateral (select y.* from public.creator_bills y where y.option_id = o.id and not y.gone
                            order by (y.status = 'processing') desc, (y.status = 'draft') desc, y.bill_date desc nulls last
                            limit 1) b on true
       where o.campaign_id = p_campaign
         and o.state not in ('option', 'shortlisted', 'backup', 'withdrawn', 'replaced')), '[]'::jsonb));
end $$;

create or replace function public.supplier_bills(p_supplier uuid default null, p_paid_from date default null, p_doc bigint default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_rows jsonb;
  v_read timestamptz;
begin
  if me.id is null or not public.allowed('suppliers', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  if p_supplier is not null and not exists (select 1 from public.suppliers s where s.id = p_supplier) then
    return jsonb_build_object('error', 'not-found');
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', d.doc_id, 'supplier', s.id, 'code', s.code, 'name', coalesce(s.name, s.code),
           'number', d.number, 'ref_no', d.ref_no, 'date', d.doc_date, 'due', coalesce(d.due_date, d.doc_date),
           'amount', d.amount, 'balance', d.balance, 'currency', d.currency, 'paid_on', d.paid_on,
           'client', case when c.id is not null and public.client_seen(c.id, 'view') then c.name end,
           'client_code', case when c.id is not null and public.client_seen(c.id, 'view') then c.client_code end)
         order by coalesce(d.due_date, d.doc_date), d.doc_id), '[]'::jsonb)
    into v_rows
    from public.bukku_docs d
    join public.bukku_links bl on bl.kind = 'supplier' and bl.contact_id = d.contact_id
    join public.suppliers s on s.id = bl.record_id
    left join public.clients c on c.id = s.client_id
   where d.kind = 'bill' and not d.gone
     and (p_supplier is null or s.id = p_supplier)
     and (p_doc is null or d.doc_id = p_doc)
     and (p_paid_from is null or d.balance > 0 or coalesce(d.paid_on, d.doc_date) >= p_paid_from);
  select m.read_at into v_read from public.bukku_doc_marks m where m.kind = 'bill';
  return jsonb_build_object('ok', true, 'today', v_today, 'work', public.allowed('suppliers', 'work'),
    'read_at', v_read, 'bills', v_rows);
end $$;

create or replace function public.creator_bills_list(p_creator uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_pay boolean := public.ops_granted('campaigns.pay', 'view'); l public.bukku_links;
begin
  if (public.ops_me()).id is null or not public.allowed('campaigns.creators', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if not exists (select 1 from public.creators c where c.id = p_creator) then return jsonb_build_object('error', 'not-found'); end if;
  select * into l from public.bukku_links x where x.kind = 'creator' and x.record_id = p_creator;
  return jsonb_build_object('ok', true, 'pay', v_pay, 'linked', l.contact_id is not null,
    'read_at', (select max(b.read_at) from public.creator_bills b where b.creator_id = p_creator),
    -- The creator fees (2026-11-13): the standard fee, and whether the
    -- account a bill is posted to is set, at Creator payments View alone.
    'standard_fee', case when v_pay then (select jsonb_build_object('amount', s.amount, 'currency', s.currency)
        from public.creator_standard_fees s where s.creator_id = p_creator) end,
    'bill_account', case when v_pay then exists (select 1 from public.bukku_settings s where s.id = 1 and s.bill_account is not null) end,
    'jobs', coalesce((select jsonb_agg(jsonb_build_object(
        'option', o.id, 'job', public.creator_job_ref(o.id), 'earlier_job', o.earlier_job, 'state', o.state,
        'campaign', m.title, 'campaign_id', m.id, 'posted_on', o.posted_on, 'pay_by', o.pay_by,
        'fee', case when v_pay then (select jsonb_build_object('amount', f.amount, 'currency', f.currency, 'source', f.source)
                 from public.creator_fees f where f.option_id = o.id) end,
        'bill', (select jsonb_build_object('number', b.number, 'ref_no', b.ref_no, 'status', b.status, 'date', b.bill_date,
                   'amount', case when v_pay then b.amount end, 'currency', b.currency, 'paid_on', case when b.status = 'paid' then coalesce(b.paid_on, (b.paid_seen_at at time zone public.agency_tz())::date) end)
                   from public.creator_bills b where b.option_id = o.id and not b.gone
                  order by (b.status = 'processing') desc, b.bill_date desc nulls last limit 1))
        order by o.posted_on desc nulls first, m.created_at desc)
        from public.campaign_options o join public.campaigns m on m.id = o.campaign_id
       where o.creator_id = p_creator and o.state not in ('option', 'shortlisted', 'backup', 'withdrawn', 'replaced')), '[]'::jsonb),
    -- a creator's past job IDs from before the portal, each with the bill
    -- whose reference or number holds it
    'past', coalesce((select jsonb_agg(jsonb_build_object('id', e.id, 'ref', e.ref,
        'bill', (select jsonb_build_object('number', b.number, 'ref_no', b.ref_no, 'status', b.status, 'date', b.bill_date,
                   'amount', case when v_pay then b.amount end, 'currency', b.currency, 'paid_on', case when b.status = 'paid' then coalesce(b.paid_on, (b.paid_seen_at at time zone public.agency_tz())::date) end)
                   from public.creator_bills b
                  where b.creator_id = p_creator and b.option_id is null and not b.gone
                    and length(public.creator_ref_key(e.ref)) >= 4
                    and (position(public.creator_ref_key(e.ref) in public.creator_ref_key(b.ref)) > 0
                      or position(public.creator_ref_key(e.ref) in public.creator_ref_key(b.number)) > 0)
                  order by (b.status = 'processing') desc, b.bill_date desc nulls last limit 1))
        order by e.ref desc)
        from public.creator_earlier_jobs e where e.creator_id = p_creator and e.removed_at is null), '[]'::jsonb),
    'earlier', coalesce((select jsonb_agg(jsonb_build_object('number', b.number, 'ref', b.ref, 'ref_no', b.ref_no, 'status', b.status, 'date', b.bill_date,
        'amount', case when v_pay then b.amount end, 'currency', b.currency, 'paid_on', case when b.status = 'paid' then coalesce(b.paid_on, (b.paid_seen_at at time zone public.agency_tz())::date) end) order by b.bill_date desc nulls last)
        from public.creator_bills b where b.creator_id = p_creator and b.option_id is null and not b.gone
         and not exists (select 1 from public.creator_earlier_jobs e
                          where e.creator_id = p_creator and e.removed_at is null and length(public.creator_ref_key(e.ref)) >= 4
                            and (position(public.creator_ref_key(e.ref) in public.creator_ref_key(b.ref)) > 0
                              or position(public.creator_ref_key(e.ref) in public.creator_ref_key(b.number)) > 0))), '[]'::jsonb));
end $$;

create or replace function public.creator_payments_queue(p_paid_from date default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_pay  boolean := public.ops_granted('campaigns.pay', 'view');
  v_from date := coalesce(p_paid_from,
    (date_trunc('month', now() at time zone public.agency_tz()) - interval '1 month')::date);
begin
  if (public.ops_me()).id is null or not public.allowed('campaigns.creators', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('ok', true, 'pay', v_pay, 'work', public.ops_granted('campaigns.pay', 'work'),
    'paid_from', v_from,
    'bill_account', case when v_pay then exists (select 1 from public.bukku_settings s where s.id = 1 and s.bill_account is not null) end,
    'read_at', (select max(b.read_at) from public.creator_bills b),
    -- Payment details waiting for review, oldest first.
    'review', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id, 'creator', cr.id, 'name', cr.name, 'code', cr.creator_code, 'ref', r.ref,
        'currency', r.currency, 'method_word', public.creator_pay_method(r.method, r.bank),
        'account_end', right(r.account, 4), 'created_at', r.created_at,
        'replaces', exists (select 1 from public.creator_pay_requests y where y.creator_id = r.creator_id and y.status = 'approved'))
        order by r.created_at)
        from public.creator_pay_requests r join public.creators cr on cr.id = r.creator_id
       where r.status = 'pending'), '[]'::jsonb),
    -- Every booking posted in the portal, or holding a live bill.
    'jobs', coalesce((select jsonb_agg(x.j order by x.k) from (
      select jsonb_build_object(
          'option', o.id, 'creator', cr.id, 'name', cr.name, 'code', cr.creator_code,
          'linked', exists (select 1 from public.bukku_links l where l.kind = 'creator' and l.record_id = cr.id and l.contact_id is not null),
          'job', public.creator_job_ref(o.id), 'state', o.state, 'campaign', case when public.client_seen(c.id, 'view') then m.title end, 'campaign_id', m.id,
          'client', case when public.client_seen(c.id, 'view') then c.name end,
          'client_code', case when public.client_seen(c.id, 'view') then c.client_code end,
          'posted_on', o.posted_on, 'pay_by', o.pay_by,
          'currency', coalesce(f.currency, (select p.currency from public.creator_pay_requests p
                                             where p.creator_id = cr.id and p.status = 'approved' order by p.seq desc limit 1), 'MYR'),
          'fee', case when v_pay and f.option_id is not null then jsonb_build_object('amount', f.amount, 'currency', f.currency) end,
          'bill', case when b.bill_id is not null then jsonb_build_object('number', b.number, 'ref_no', b.ref_no, 'status', b.status, 'date', b.bill_date,
                    'paid_on', coalesce(b.paid_on, (b.paid_seen_at at time zone public.agency_tz())::date),
                    'amount', case when v_pay then b.amount end, 'currency', b.currency) end) as j,
          coalesce(o.pay_by, o.posted_on) as k
        from public.campaign_options o
        join public.creators cr on cr.id = o.creator_id
        join public.campaigns m on m.id = o.campaign_id
        join public.clients c on c.id = m.client_id
        left join public.creator_fees f on f.option_id = o.id
        left join lateral (select y.* from public.creator_bills y where y.option_id = o.id and not y.gone
                            order by (y.status = 'processing') desc, (y.status = 'draft') desc, y.bill_date desc nulls last limit 1) b on true
       where o.state not in ('option', 'shortlisted', 'backup', 'withdrawn', 'replaced')
         and ((b.bill_id is null and o.posted_on is not null and o.state in ('posted', 'completed'))
           or b.status in ('draft', 'processing')
           or (b.status = 'paid' and coalesce(b.paid_on, (b.paid_seen_at at time zone public.agency_tz())::date, b.bill_date) >= v_from))
      ) x), '[]'::jsonb));
end $$;

create or replace function public.outstation_reading_error(p_lat numeric, p_lng numeric, p_accuracy numeric, p_read_at timestamptz)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_limit numeric := coalesce(public.app_setting('outstation_accuracy_m', (now() at time zone public.agency_tz())::date), 50);
begin
  if p_lat is null or p_lng is null or p_accuracy is null or p_read_at is null
     or p_lat not between -90 and 90 or p_lng not between -180 and 180 or p_accuracy < 0
     or p_read_at > now() + interval '2 minutes' or p_read_at < now() - interval '10 minutes' then
    return jsonb_build_object('error', 'bad-location');
  end if;
  if p_accuracy > v_limit then return jsonb_build_object('error', 'vague', 'limit', v_limit, 'accuracy', round(p_accuracy)); end if;
  return null;
end $$;

create or replace function public.outstation_trips(p_from date, p_to date, p_all boolean default false)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_me public.team_members;
begin
  v_me := public.ops_me();
  if v_me.id is null or not public.allowed('ops', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_all, false) and not public.ops_granted('ops.outstation', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 400 then return jsonb_build_object('error', 'bad-period'); end if;
  return jsonb_build_object('ok', true, 'me', v_me.id, 'trips', coalesce((
    select jsonb_agg(public.outstation_trip_json(t.id) order by t.started_at desc)
      from public.outstation_trips t
     where ((t.started_at at time zone public.agency_tz())::date between p_from and p_to
            or (t.state = 'open' and t.driver_id = v_me.id))
       and (coalesce(p_all, false) or t.driver_id = v_me.id or v_me.id = any(t.companions))), '[]'::jsonb));
end $$;

create or replace function public.outstation_prune()
returns integer
language plpgsql security definer set search_path = public as $$
declare v_months integer := coalesce(public.app_setting('outstation_keep_months', (now() at time zone public.agency_tz())::date), 24)::integer;
  v_n integer;
begin
  delete from public.outstation_trips t
   where t.state = 'closed' and t.ended_at < now() - make_interval(months => v_months);
  get diagnostics v_n = row_count;
  return v_n;
end $$;

create or replace function public.careers_pick(p_key text, p_slot int)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c public.hiring_candidates;
  i public.hiring_interviews;
  v_days int := coalesce(public.app_setting('hiring_link_days', (now() at time zone public.agency_tz())::date)::int, 30);
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into c from public.hiring_candidates where link_key = p_key and removed_at is null for update;
  if c.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if c.last_step_at + make_interval(days => v_days) <= now() then return jsonb_build_object('error', 'expired'); end if;
  -- A decision taken closes the choice (review 2026-11-24).
  if c.stage not in ('new', 'invited', 'interview') then return jsonb_build_object('error', 'not-open'); end if;
  select * into i from public.hiring_interviews where candidate_id = c.id and state = 'invited'
   order by invited_at desc limit 1 for update;
  if i.id is null then return jsonb_build_object('error', 'not-open'); end if;
  if i.reply_by <= now() then return jsonb_build_object('error', 'reply-passed'); end if;
  if p_slot is null or p_slot < 1 or p_slot > cardinality(i.slots) then return jsonb_build_object('error', 'bad-slot'); end if;
  if i.slots[p_slot] < now() then return jsonb_build_object('error', 'slot-past'); end if;
  update public.hiring_interviews set state = 'picked', picked = p_slot, picked_at = now(), updated_at = now() where id = i.id;
  update public.hiring_candidates set last_step_at = now(), updated_at = now() where id = c.id;
  insert into public.hiring_events (candidate_id, actor, action, detail)
  values (c.id, 'Candidate page', 'candidate.interview', 'Time chosen: ' || public.hiring_when(i.slots[p_slot]));
  perform public.hiring_tell(c.id, 'hiring.picked', 'A candidate chose an interview time',
    c.position || ' · ' || public.hiring_when(i.slots[p_slot]) || '. Approve it to send the confirmation.');
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.creator_pay_submit(p_code text, p_values jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_id   uuid;
  v_lock integer;
  cr     public.creators;
  v_held public.creator_pay_requests;
  v_in   jsonb := coalesce(p_values, '{}'::jsonb);
  v_chk  jsonb;
  v      jsonb;
  v_seq  int;
  v_new  public.creator_pay_requests;
  v_was  public.creator_pay_requests;
  v_chg  text[];
begin
  select t.o_creator, t.o_locked into v_id, v_lock from public.creator_code_try(p_code) t;
  if v_lock is not null then return jsonb_build_object('error', 'locked', 'minutes', v_lock); end if;
  select * into cr from public.creators x where x.id = v_id for update;
  if cr.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not cr.active then return jsonb_build_object('error', 'inactive'); end if;
  if not public.creator_pay_due(cr.id) then return jsonb_build_object('error', 'not-due'); end if;
  if (select count(*) from public.creator_pay_requests x where x.creator_id = cr.id
       and x.created_at > now() - interval '1 day') >= 5 then
    return jsonb_build_object('error', 'too-many');
  end if;
  -- A number left blank keeps the one held, where nothing it belongs to moved;
  -- a detail the page shows masked, left blank, keeps the one held.
  select * into v_held from public.creator_pay_requests x where x.creator_id = cr.id and x.status in ('approved', 'pending')
   order by x.seq desc limit 1;
  if v_held.id is not null then
    if btrim(coalesce(v_in->>'id_no', '')) = '' and v_in->>'bill_kind' = v_held.bill_kind then
      v_in := v_in || jsonb_build_object('id_no', v_held.id_no);
    end if;
    if btrim(coalesce(v_in->>'account', '')) = '' and v_in->>'method' = v_held.method
       and upper(coalesce(v_in->>'currency', '')) = v_held.currency and coalesce(v_in->>'bank', '') = coalesce(v_held.bank, '') then
      v_in := v_in || jsonb_build_object('account', v_held.account);
    end if;
    if btrim(coalesce(v_in->>'legal_name', '')) = '' then v_in := v_in || jsonb_build_object('legal_name', v_held.legal_name); end if;
    if btrim(coalesce(v_in->>'tin', '')) = '' and v_held.tin is not null then v_in := v_in || jsonb_build_object('tin', v_held.tin); end if;
    if btrim(coalesce(v_in->>'address', '')) = '' then v_in := v_in || jsonb_build_object('address', v_held.address); end if;
    if btrim(coalesce(v_in->>'payee', '')) = '' then v_in := v_in || jsonb_build_object('payee', v_held.payee); end if;
    if btrim(coalesce(v_in->>'email', '')) = '' then v_in := v_in || jsonb_build_object('email', v_held.email); end if;
    if btrim(coalesce(v_in->>'whatsapp', '')) = '' then v_in := v_in || jsonb_build_object('whatsapp', v_held.whatsapp); end if;
  end if;
  -- What is on file: the details approved last, the ones the bills go to.
  select * into v_was from public.creator_pay_requests x where x.creator_id = cr.id and x.status = 'approved'
   order by x.seq desc limit 1;
  v_chk := public.creator_pay_check(v_in);
  if v_chk ? 'field' then return jsonb_build_object('error', 'bad', 'field', v_chk->>'field'); end if;
  v := v_chk->'values';
  update public.creator_pay_requests x set status = 'withdrawn' where x.creator_id = cr.id and x.status = 'pending';
  select coalesce(max(x.seq), 0) + 1 into v_seq from public.creator_pay_requests x where x.creator_id = cr.id;
  insert into public.creator_pay_requests (creator_id, seq, ref, bill_kind, id_no, legal_name, tin, address, currency,
    method, bank, account, payee, email, whatsapp)
  values (cr.id, v_seq, public.creator_pay_ref(cr.creator_code, v_seq), v->>'bill_kind', v->>'id_no', v->>'legal_name',
    v->>'tin', v->>'address', v->>'currency', v->>'method', v->>'bank', v->>'account', v->>'payee', v->>'email', v->>'whatsapp')
  returning * into v_new;
  v_chg := public.creator_pay_changes(v_was, v_new);
  update public.creator_pay_requests x set changes = v_chg, prior_id = v_was.id where x.id = v_new.id
  returning * into v_new;
  insert into public.activity_log (actor, action, subject, detail)
  values ('Creator page', 'creator.updated', cr.name,
          coalesce(cr.creator_code || ' · ', '') || 'Payment details submitted · ' || v_new.ref || ' · ' ||
          public.creator_pay_method(v_new.method, v_new.bank) || ' ending ' || right(v_new.account, 4) ||
          coalesce(' · ' || nullif(array_to_string(v_chg, ' · '), ''), ''));
  perform public.creator_mail_queue('received', v_new.id);
  perform public.creator_mail_queue('review', v_new.id);
  -- Details on file changed: the email and WhatsApp on file are told too,
  -- so a change the creator did not make is seen (review 2026-11-24).
  if v_was.id is not null and cardinality(v_chg) > 0 then
    perform public.creator_mail_queue('changed', v_new.id);
    perform public.wa_enqueue('creator_changed', public.wa_number(coalesce(nullif(v_was.whatsapp, ''), cr.whatsapp), 'MY'), cr.name,
      jsonb_build_array(cr.name, public.register_day((v_new.created_at at time zone public.agency_tz())::date)),
      'creator', cr.id, null, null);
  end if;
  return jsonb_build_object('ok', true, 'ref', v_new.ref);
end $$;

create or replace function public.hiring_doc_wrong_today(p_doc uuid)
returns integer language sql stable security definer set search_path = public as $$
  select coalesce((select w.n from public.hiring_doc_wrong_days w
                    where w.doc_id = p_doc and w.day = (now() at time zone public.agency_tz())::date), 0)
$$;

create or replace function public.careers_doc_open(p_key text, p_doc uuid, p_code text, p_device text)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  d public.hiring_docs := public.careers_doc_of(p_key, p_doc);
  s public.hiring_doc_codes;
  v_tok text;
begin
  if d.id is null then return jsonb_build_object('error', 'not_found'); end if;
  perform 1 from public.hiring_docs where id = d.id for update;
  -- Ten wrong codes a document a Malaysian day, whatever code they were
  -- typed against (review 2026-11-24: a new code every hour gave five more).
  if public.hiring_doc_wrong_today(d.id) >= 10 then return jsonb_build_object('error', 'locked-today'); end if;
  select * into s from public.hiring_doc_codes x where x.doc_id = d.id and x.used_at is null
   order by x.created_at desc limit 1 for update;
  if s.id is null then return jsonb_build_object('error', 'no-code'); end if;
  if s.expires_at <= now() then return jsonb_build_object('error', 'code-expired'); end if;
  if s.tries >= 5 then return jsonb_build_object('error', 'locked'); end if;
  if regexp_replace(coalesce(p_code, ''), '\s+', '', 'g') !~ '^[0-9]{6}$'
     or crypt(regexp_replace(p_code, '\s+', '', 'g'), s.code_hash) <> s.code_hash then
    update public.hiring_doc_codes set tries = tries + 1 where id = s.id;
    -- counted on the Malaysian day it was typed, whenever its code was made
    insert into public.hiring_doc_wrong_days as w (doc_id, day, n)
    values (d.id, (now() at time zone public.agency_tz())::date, 1)
    on conflict (doc_id, day) do update set n = w.n + 1;
    return jsonb_build_object('error', 'wrong', 'left', greatest(0, 4 - s.tries));
  end if;
  v_tok := encode(gen_random_bytes(24), 'hex');
  update public.hiring_doc_codes set used_at = now(), view_hash = encode(digest(v_tok, 'sha256'), 'hex'),
    view_until = now() + interval '30 minutes' where id = s.id;
  insert into public.signing_steps (doc_kind, doc_id, step, email, ip, country, device)
  values ('hiring_doc', d.id, 'opened', s.email, nullif(public.request_ip(), ''), nullif(public.request_country(), ''), public.seal_device(p_device));
  return public.careers_doc_json(d) || jsonb_build_object('view', v_tok);
end $$;

create or replace function public.feedback_throttle(p_bad boolean default false)
returns boolean
language plpgsql volatile security definer set search_path = public as $$
declare
  v_ip   text := coalesce(nullif(public.request_ip(), ''), 'none');
  v_hour timestamp := date_trunc('hour', now() at time zone public.agency_tz());
  v_row  public.feedback_hits;
begin
  insert into public.feedback_hits as h (ip, hour, n, bad)
  values (v_ip, v_hour, 1, case when p_bad then 1 else 0 end)
  on conflict (ip) do update
     set n    = case when h.hour < v_hour then 1 else h.n + 1 end,
         bad  = case when h.hour < v_hour then (case when p_bad then 1 else 0 end)
                     else h.bad + (case when p_bad then 1 else 0 end) end,
         hour = v_hour
  returning * into v_row;
  return v_row.n <= 120 and v_row.bad <= 20;
end $$;

create or replace function public.feedback_figures(p_from date, p_to date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me      public.team_members := public.ops_me();
  v_from  timestamptz;
  v_to    timestamptz;
  v_prev  timestamptz;
  v_quiet int;
begin
  if me.id is null or not public.allowed('clients', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 800 then return jsonb_build_object('error', 'bad-period'); end if;
  v_from := p_from::timestamp at time zone public.agency_tz();
  v_to   := (p_to + 1)::timestamp at time zone public.agency_tz();
  v_prev := (p_from - (p_to - p_from + 1))::timestamp at time zone public.agency_tz();
  v_quiet := coalesce(public.app_setting('feedback_quiet_months', (now() at time zone public.agency_tz())::date), 6)::int;
  return jsonb_build_object('ok', true,
    'rating', (select round(avg(s.score)::numeric, 1) from public.feedback_responses s
                where s.kind = 'quick' and s.submitted_at >= v_from and s.submitted_at < v_to and public.client_seen(s.client_id, 'view')),
    'rating_n', (select count(*) from public.feedback_responses s
                  where s.kind = 'quick' and s.submitted_at >= v_from and s.submitted_at < v_to and public.client_seen(s.client_id, 'view')),
    'nps', (select round(100.0 * (count(*) filter (where s.band = 'high') - count(*) filter (where s.band = 'low')) / nullif(count(*), 0))
              from public.feedback_responses s
             where s.kind = 'review' and s.submitted_at >= v_from and s.submitted_at < v_to and public.client_seen(s.client_id, 'view')),
    'nps_n', (select count(*) from public.feedback_responses s
               where s.kind = 'review' and s.submitted_at >= v_from and s.submitted_at < v_to and public.client_seen(s.client_id, 'view')),
    'low_open', (select count(*) from public.feedback_responses s
                  left join public.ops_tasks t on t.id = s.followup_task_id
                  where s.band = 'low' and t.completed_at is null and public.client_seen(s.client_id, 'view')),
    'low_oldest', (select min(s.submitted_at) from public.feedback_responses s
                    left join public.ops_tasks t on t.id = s.followup_task_id
                    where s.band = 'low' and t.completed_at is null and public.client_seen(s.client_id, 'view')),
    'quiet_months', v_quiet,
    'quiet', (select count(*) from public.clients c
               where c.stage = 'active' and public.client_seen(c.id, 'view')
                 and not exists (select 1 from public.feedback_requests r where r.client_id = c.id
                                  and r.created_at >= (now() - make_interval(months => v_quiet)))),
    'people', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.manager_id, 'name', p.manager_name,
               'requested', p.requested, 'answered', p.answered, 'rating', p.rating, 'nps', p.nps,
               'manager_score', case when public.feedback_sees_manager(p.manager_id) then p.mgr end,
               'manager_max', case when public.feedback_sees_manager(p.manager_id) then
                 (select x.scale_max from public.feedback_questions x where x.kind = 'quick' and x.key = 'manager') end,
               'manager_before', case when public.feedback_sees_manager(p.manager_id) then p.mgr_before end)
             order by p.manager_name)
        from (
          select r.manager_id, max(r.manager_name) as manager_name,
                 count(*) filter (where r.created_at >= v_from and r.created_at < v_to) as requested,
                 count(s.id) filter (where s.submitted_at >= v_from and s.submitted_at < v_to) as answered,
                 round(avg(s.score) filter (where s.kind = 'quick' and s.submitted_at >= v_from and s.submitted_at < v_to)::numeric, 1) as rating,
                 round(100.0 * (count(*) filter (where s.kind = 'review' and s.band = 'high' and s.submitted_at >= v_from and s.submitted_at < v_to)
                              - count(*) filter (where s.kind = 'review' and s.band = 'low' and s.submitted_at >= v_from and s.submitted_at < v_to))
                       / nullif(count(*) filter (where s.kind = 'review' and s.submitted_at >= v_from and s.submitted_at < v_to), 0)) as nps,
                 round(avg(s.manager_score) filter (where s.kind = 'quick' and s.submitted_at >= v_from and s.submitted_at < v_to)::numeric, 1) as mgr,
                 round(avg(s.manager_score) filter (where s.kind = 'quick' and s.submitted_at >= v_prev and s.submitted_at < v_from)::numeric, 1) as mgr_before
            from public.feedback_requests r
            left join public.feedback_responses s on s.request_id = r.id
           where r.manager_id is not null and public.client_seen(r.client_id, 'view')
             and r.created_at >= v_prev and r.created_at < v_to
           group by r.manager_id
        ) p
       where p.requested > 0 or p.answered > 0), '[]'::jsonb));
end $$;

create or replace function public.careers_none(p_key text, p_note text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c public.hiring_candidates;
  i public.hiring_interviews;
  v_days int := coalesce(public.app_setting('hiring_link_days', (now() at time zone public.agency_tz())::date)::int, 30);
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  if char_length(coalesce(p_note, '')) > 300 then return jsonb_build_object('error', 'too-long'); end if;
  select * into c from public.hiring_candidates where link_key = p_key and removed_at is null for update;
  if c.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if c.last_step_at + make_interval(days => v_days) <= now() then return jsonb_build_object('error', 'expired'); end if;
  -- A decision taken closes the choice (review 2026-11-24).
  if c.stage not in ('new', 'invited', 'interview') then return jsonb_build_object('error', 'not-open'); end if;
  select * into i from public.hiring_interviews where candidate_id = c.id and state = 'invited'
   order by invited_at desc limit 1 for update;
  if i.id is null then return jsonb_build_object('error', 'not-open'); end if;
  if i.reply_by <= now() then return jsonb_build_object('error', 'reply-passed'); end if;
  update public.hiring_interviews set state = 'none', candidate_note = nullif(btrim(coalesce(p_note, '')), ''), updated_at = now() where id = i.id;
  update public.hiring_candidates set last_step_at = now(), updated_at = now() where id = c.id;
  insert into public.hiring_events (candidate_id, actor, action, detail)
  values (c.id, 'Candidate page', 'candidate.interview', 'New times requested');
  perform public.hiring_tell(c.id, 'hiring.none', 'A candidate requested new interview times',
    c.position || '. Send new times from the candidate''s Interview tab.');
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.outstation_trip_delete(p_trip uuid, p_confirm text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me public.team_members; v_t public.outstation_trips; v_driver text; v_stops integer;
begin
  v_me := public.ops_me();
  if v_me.id is null or not public.allowed('ops', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into v_t from public.outstation_trips t where t.id = p_trip for update;
  if v_t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_t.driver_id <> v_me.id and not (v_me.is_admin or v_me.role = 'admin') then
    return jsonb_build_object('error', 'denied');
  end if;
  if upper(regexp_replace(coalesce(p_confirm, ''), '[^A-Za-z0-9]', '', 'g'))
     <> upper(regexp_replace(v_t.ref, '[^A-Za-z0-9]', '', 'g')) then
    return jsonb_build_object('error', 'confirm-required');
  end if;
  select m.name into v_driver from public.team_members m where m.id = v_t.driver_id;
  select count(*) into v_stops from public.outstation_stops s where s.trip_id = v_t.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_me.name, v_me.email), 'ops.deleted', v_t.ref,
          'Outstation trip · ' || public.register_day((v_t.started_at at time zone public.agency_tz())::date)
          || ' · ' || coalesce(v_driver, 'Former colleague') || ' · ' || v_stops || case when v_stops = 1 then ' stop' else ' stops' end);
  /* The visits it filed go with it: a trip deleted did not happen (the
     user, 2026-11-24). */
  delete from public.client_touches
   where id in (select s.touch_id from public.outstation_stops s where s.trip_id = v_t.id and s.touch_id is not null);
  delete from public.outstation_trips where id = v_t.id;
  return jsonb_build_object('ok', true, 'deleted', true, 'ref', v_t.ref);
end $$;

create or replace function public.verify_by_day(f jsonb)
returns boolean language plpgsql stable set search_path = public as $$
declare
  v_from numeric := public.app_setting('verify_code_from', (now() at time zone public.agency_tz())::date);
begin
  if f is null or f ->> 'issued' is null then return false; end if;
  if coalesce((f ->> 'by_code')::boolean, false) then return false; end if;
  if f ->> 'code' is null then return true; end if;
  if v_from is null then return false; end if;
  return (f ->> 'issued')::date < to_date(v_from::bigint::text, 'YYYYMMDD');
end $$;

create or replace function public.creator_pay_add(p_creator uuid, p_values jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  cr     public.creators;
  v_held public.creator_pay_requests;
  v_in   jsonb := coalesce(p_values, '{}'::jsonb) || jsonb_build_object('confirm', 'true');
  v_chk  jsonb;
  v      jsonb;
  v_seq  int;
  v_new  public.creator_pay_requests;
  v_was  public.creator_pay_requests;
  v_chg  text[];
begin
  if me.id is null or not public.ops_granted('campaigns.pay', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into cr from public.creators x where x.id = p_creator for update;
  if cr.id is null then return jsonb_build_object('error', 'not-found'); end if;
  -- A number or detail left blank keeps the one held, as the creator's page does.
  select * into v_held from public.creator_pay_requests x where x.creator_id = cr.id and x.status in ('approved', 'pending')
   order by x.seq desc limit 1;
  if v_held.id is not null then
    if btrim(coalesce(v_in->>'id_no', '')) = '' and v_in->>'bill_kind' = v_held.bill_kind then
      v_in := v_in || jsonb_build_object('id_no', v_held.id_no);
    end if;
    if btrim(coalesce(v_in->>'account', '')) = '' and v_in->>'method' = v_held.method
       and upper(coalesce(v_in->>'currency', '')) = v_held.currency and coalesce(v_in->>'bank', '') = coalesce(v_held.bank, '') then
      v_in := v_in || jsonb_build_object('account', v_held.account);
    end if;
    if btrim(coalesce(v_in->>'address', '')) = '' and v_held.address is not null then v_in := v_in || jsonb_build_object('address', v_held.address); end if;
  end if;
  -- What is on file: the details approved last, the ones the bills go to.
  select * into v_was from public.creator_pay_requests x where x.creator_id = cr.id and x.status = 'approved'
   order by x.seq desc limit 1;
  v_chk := public.creator_pay_check(v_in);
  if v_chk ? 'field' then return jsonb_build_object('error', 'bad', 'field', v_chk->>'field'); end if;
  v := v_chk->'values';
  update public.creator_pay_requests x set status = 'withdrawn' where x.creator_id = cr.id and x.status = 'pending';
  select coalesce(max(x.seq), 0) + 1 into v_seq from public.creator_pay_requests x where x.creator_id = cr.id;
  insert into public.creator_pay_requests (creator_id, seq, ref, bill_kind, id_no, legal_name, tin, address, currency,
    method, bank, account, payee, email, whatsapp, entered_by)
  values (cr.id, v_seq, public.creator_pay_ref(cr.creator_code, v_seq), v->>'bill_kind', v->>'id_no', v->>'legal_name',
    v->>'tin', v->>'address', v->>'currency', v->>'method', v->>'bank', v->>'account', v->>'payee', v->>'email', v->>'whatsapp', me.id)
  returning * into v_new;
  v_chg := public.creator_pay_changes(v_was, v_new);
  update public.creator_pay_requests x set changes = v_chg, prior_id = v_was.id where x.id = v_new.id
  returning * into v_new;
  update public.creator_pay_requests x set status = 'replaced' where x.creator_id = cr.id and x.status = 'approved';
  update public.creator_pay_requests x set status = 'approved', decided_at = now(), decided_by = me.id where x.id = v_new.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'creator.updated', cr.name,
          coalesce(cr.creator_code || ' · ', '') || 'Payment details added by the team and approved · ' || v_new.ref || ' · ' ||
          public.creator_pay_method(v_new.method, v_new.bank) || ' ending ' || right(v_new.account, 4) ||
          coalesce(' · ' || nullif(array_to_string(v_chg, ' · '), ''), ''));
  -- Details on file changed by the team: the email and WhatsApp on file are
  -- told, as a change on the creator page tells them (review 2026-11-24).
  if v_was.id is not null and cardinality(v_chg) > 0 then
    perform public.creator_mail_queue('changed', v_new.id);
    perform public.wa_enqueue('creator_changed', public.wa_number(coalesce(nullif(v_was.whatsapp, ''), cr.whatsapp), 'MY'), cr.name,
      jsonb_build_array(cr.name, public.register_day((v_new.created_at at time zone public.agency_tz())::date)),
      'creator', cr.id, null, null);
  end if;
  return jsonb_build_object('ok', true, 'ref', v_new.ref);
end $$;

create or replace function public.outstation_ref_take(p_at timestamptz)
returns text
language plpgsql volatile security definer set search_path = public as $$
declare v_m text := to_char(coalesce(p_at, now()) at time zone public.agency_tz(), 'YYYYMM'); v_n integer;
  v_p text; v_w int;
begin
  insert into public.outstation_ref_months (month, last) values (v_m, 1)
  on conflict (month) do update set last = public.outstation_ref_months.last + 1
  returning last into v_n;
  -- The prefix and digits are Settings' (Outstation trip numbers).
  select f.prefix, f.width into v_p, v_w from public.id_formats f where f.kind = 'trip';
  v_p := coalesce(v_p, 'OS'); v_w := coalesce(v_w, 2);
  return '#' || v_p || substr(v_m, 3) || lpad(v_n::text, greatest(v_w, length(v_n::text)), '0');
end $$;

create or replace function public.outstation_file_visit(p_stop uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare v_s public.outstation_stops; v_t public.outstation_trips; v_driver text; v_with text; v_touch uuid; v_line text;
begin
  select * into v_s from public.outstation_stops where id = p_stop;
  if v_s.id is null or v_s.client_id is null then return; end if;
  select * into v_t from public.outstation_trips where id = v_s.trip_id;
  select m.name into v_driver from public.team_members m where m.id = v_t.driver_id;
  select string_agg(m.name, ', ' order by m.name) into v_with from public.team_members m where m.id = any(v_t.companions);
  /* Filed when the stop begins, in progress, and completed with its end
     time once left (the user, 2026-11-24: "as long as its for that
     specific client, then it should be recorded under"). */
  v_line := 'Outstation visit: ' || initcap(v_t.purpose)
    || coalesce(', at ' || nullif(btrim(v_s.venue), ''), '') || ', '
    || case when v_s.left_at is null
            then 'from ' || lower(to_char(v_s.arrived_at at time zone public.agency_tz(), 'FMHH12:MIam')) || ' (in progress)'
            else lower(to_char(v_s.arrived_at at time zone public.agency_tz(), 'FMHH12:MIam')) || ' to '
                 || lower(to_char(v_s.left_at at time zone public.agency_tz(), 'FMHH12:MIam')) end
    || coalesce(', with ' || v_with, '') || '.'
    || coalesce(' ' || nullif(btrim(v_t.note), ''), '');
  begin
    if v_s.touch_id is not null and exists (select 1 from public.client_touches c where c.id = v_s.touch_id) then
      update public.client_touches set summary = v_line where id = v_s.touch_id;
    else
      insert into public.client_touches (client_id, kind, happened_at, by_whom, summary)
      values (v_s.client_id, 'visit', (v_s.arrived_at at time zone public.agency_tz())::date, v_driver, v_line)
      returning id into v_touch;
      update public.outstation_stops set touch_id = v_touch where id = p_stop;
    end if;
  exception when others then
    return;
  end;
end $$;

create or replace function public.clients_stage_next()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.stage_next is not null then raise exception 'stage-next-day' using errcode = 'P0001'; end if;
    return new;
  end if;
  /* A real move, by hand or by clients_stage_due, ends the change set ahead. */
  if new.stage is distinct from old.stage then
    new.stage_next := null;
    new.stage_next_on := null;
    new.stage_next_reason := null;
    new.stage_next_note := null;
    return new;
  end if;
  if new.stage_next is null then
    new.stage_next_on := null;
    new.stage_next_reason := null;
    new.stage_next_note := null;
    return new;
  end if;
  if (new.stage_next, new.stage_next_on, new.stage_next_reason) is not distinct from
     (old.stage_next, old.stage_next_on, old.stage_next_reason) then
    return new;
  end if;
  if new.stage_next_on <= (now() at time zone public.agency_tz())::date then
    raise exception 'stage-next-day' using errcode = 'P0001';
  end if;
  if new.stage_next = new.stage then
    raise exception 'stage-next-same' using errcode = 'P0001';
  end if;
  if new.stage_next_reason = 'completed' and new.stage <> 'active'
     and not exists (select 1 from jsonb_array_elements(coalesce(new.stage_log, '[]'::jsonb)) e
                      where e ->> 'stage' = 'active') then
    raise exception 'stage-next-reason' using errcode = 'P0001';
  end if;
  new.stage_next_note := nullif(btrim(coalesce(new.stage_next_note, '')), '');
  return new;
end $$;

create or replace function public.clients_stage_due()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  c record;
  n integer := 0;
  v_day date := (now() at time zone public.agency_tz())::date;
begin
  for c in select x.id, x.name, x.stage_next, x.stage_next_on, x.stage_next_reason, x.stage_next_note
             from public.clients x
            where x.stage_next is not null and x.stage_next_on <= v_day
            order by x.stage_next_on, x.name loop
    begin
      update public.clients
         set stage = c.stage_next, stage_reason = c.stage_next_reason, stage_note = c.stage_next_note
       where id = c.id and stage_next = c.stage_next and stage_next_on = c.stage_next_on;
      if found then
        insert into public.activity_log (actor, action, subject, detail)
        values ('system', 'client.stage', c.name,
                case c.stage_next when 'paused' then 'Paused' else 'Past' end || ' from ' ||
                public.register_day(c.stage_next_on) || ', as scheduled · ' ||
                case c.stage_next_reason when 'budget' then 'Budget' when 'results' then 'Results'
                  when 'in_house' then 'Moved in-house' when 'closed' then 'Business closed'
                  when 'no_reply' then 'No reply' when 'completed' then 'Completed' else 'Other' end ||
                coalesce(': ' || c.stage_next_note, ''));
        n := n + 1;
      end if;
    exception when others then
      raise notice 'clients-stage-ahead: % was not moved (%).', c.id, sqlerrm;
    end;
  end loop;
  return n;
end $$;

create or replace function public.quote_change_open(p_key text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  w public.quotations;
  q public.quotations;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not-found'); end if;
  select * into w from public.quotations x where x.access_key = p_key and x.removed_at is null;
  if w.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into q from public.quotations x where x.id = public.quote_shown(w.id);
  if w.status = 'not_proceeding' or q.status = 'not_proceeding' then return jsonb_build_object('error', 'closed'); end if;
  if q.source = 'website' and q.released_at is null then return jsonb_build_object('error', 'unsent'); end if;
  if q.signed_at is not null then return jsonb_build_object('error', 'signed'); end if;
  if q.valid_until < (now() at time zone public.agency_tz())::date then return jsonb_build_object('error', 'expired'); end if;
  return jsonb_build_object('id', q.id);
end $$;

create or replace function public.quote_change_snap(q public.quotations)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_on date := (q.issued_at at time zone public.agency_tz())::date;
  v_card jsonb := coalesce(public.quote_card(v_on, q.version), public.quote_card());
  v_fx numeric := public.quote_fx(q.client_id, v_on);
begin
  if v_card is null then return null; end if;
  return jsonb_build_object('fx', v_fx, 'version', v_card->>'version',
    'snap', public.quote_fx_snap(public.quote_tax_snap(v_card->'snapshot', q.client_id, v_on), v_fx));
end $$;

create or replace function public.quote_catalogue()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_card jsonb := public.quote_card();
  v_svc jsonb;
  v_text jsonb;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_names constant jsonb := '{"meta":"Meta","tiktok":"TikTok","rednote":"rednote","linkedin":"LinkedIn"}';
begin
  if v_card is null then return jsonb_build_object('error', 'no-card'); end if;
  v_svc := coalesce(v_card->'snapshot'->'services', '[]'::jsonb);
  v_text := coalesce(v_card->'snapshot'->'text', '{}'::jsonb);
  return jsonb_build_object(
    'version', v_card->>'version',
    'valid_days', coalesce(public.app_setting('quote_valid_days', v_today), 30)::int,
    'terms', to_jsonb(public.quote_web_terms()),
    'plans', coalesce((select jsonb_agg(jsonb_build_object(
        'slug', s->>'slug', 'plan', s->'spec'->>'plan', 'ads', coalesce((s->'spec'->>'ads')::boolean, false),
        'platforms', (s->'spec'->>'platforms')::int, 'contents', (s->'spec'->>'contents')::int,
        'mix', s->'spec'->'mix', 'ad_budget', (s->'spec'->>'ad_budget')::numeric, 'best_for', s->'spec'->>'best_for',
        'included', coalesce((select jsonb_agg(btrim(d)) from unnest(string_to_array(coalesce(v_text->>
            case when coalesce((s->'spec'->>'ad_budget')::numeric, 0) > 0 then 'plans_ads_included' else 'plans_included' end, ''), E'\n')) d
           where btrim(d) <> ''), '[]'::jsonb))
        order by s->'spec'->>'plan')
      from jsonb_array_elements(v_svc) s
     where s->'spec'->>'role' = 'plan' and s->>'rate' is not null and coalesce((s->>'active')::boolean, true)), '[]'::jsonb),
    'platforms', coalesce((select jsonb_agg(s->'spec'->>'platform'
        order by array_position(array['meta', 'tiktok', 'rednote', 'linkedin'], s->'spec'->>'platform'))
      from jsonb_array_elements(v_svc) s
     where s->'spec'->>'role' = 'platform' and s->>'rate' is not null and coalesce((s->>'active')::boolean, true)), '[]'::jsonb),
    'contents', coalesce((select jsonb_agg(jsonb_build_object('slug', s->>'slug', 'name', s->>'name', 'kind', s->'spec'->>'kind',
        'piece', public.quote_piece_class(s->'spec'->>'kind'))
        order by (s->>'rate')::numeric)
      from jsonb_array_elements(v_svc) s
     where s->'spec'->>'role' = 'content' and s->>'rate' is not null and coalesce((s->>'active')::boolean, true)), '[]'::jsonb),
    'budgets', coalesce((select jsonb_agg(b order by b) from (
        select distinct (s->'spec'->>'budget')::numeric b from jsonb_array_elements(v_svc) s
         where s->'spec'->>'role' in ('ads', 'booster') and s->>'rate' is not null
           and coalesce((s->>'active')::boolean, true)) z), '[]'::jsonb),
    'verify', coalesce((select jsonb_agg(jsonb_build_object('slug', s->>'slug', 'name', s->>'name',
        -- the platform it verifies: its own, else the platform its name names
        'platform', coalesce(s->'spec'->>'platform', (select k from jsonb_each_text(v_names) n(k, w)
                                                        where s->>'name' ~* ('\m' || w || '\M') limit 1))))
      from jsonb_array_elements(v_svc) s
     where s->'spec'->>'role' = 'verify' and s->>'rate' is not null and coalesce((s->>'active')::boolean, true)), '[]'::jsonb),
    'koc', coalesce((select jsonb_agg(jsonb_build_object('slug', s->>'slug', 'name', s->>'name',
        'creators', (s->'spec'->>'creators')::int) order by (s->'spec'->>'creators')::int nulls last)
      from jsonb_array_elements(v_svc) s
     where s->'spec'->>'role' = 'koc' and coalesce((s->>'active')::boolean, true)), '[]'::jsonb),
    'kol', (select s->>'slug' from jsonb_array_elements(v_svc) s
     where s->'spec'->>'role' = 'kol' and coalesce((s->>'active')::boolean, true) limit 1),
    'files', coalesce((select jsonb_agg(jsonb_build_object('slug', s->>'slug', 'name', s->>'name',
        'covers', public.quote_file_covers(s)) order by (s->>'rate')::numeric)
      from jsonb_array_elements(v_svc) s
     where s->'spec'->>'role' = 'addon' and public.quote_web_once_ok(s) and s->>'rate' is not null
       and coalesce((s->>'active')::boolean, true)), '[]'::jsonb),
    -- Whether the card prices a translation, never its rate.
    'translation', exists (select 1 from jsonb_array_elements(v_svc) s
     where s->'spec'->>'role' = 'language' and s->>'rate' is not null and coalesce((s->>'active')::boolean, true)));
end $$;

create or replace function public.quote_preview(p_sel jsonb)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_on date := public.doc_day_of(p_sel->>'date');
  v_card jsonb;
  v_cl uuid;
  v_fx numeric;
  v_over jsonb := '[]'::jsonb;
  v_b jsonb;
  v_i int;
  v_s jsonb;
  v_cap jsonb;
  v_o jsonb;
  v_x jsonb;
  v_c text;
  v_lim int;
begin
  -- Priced on the quotation's own date (2026-11-12), today where none.
  if v_on is not null and not public.doc_day_ok(v_on) then return jsonb_build_object('error', 'bad-date'); end if;
  v_on := coalesce(v_on, (now() at time zone public.agency_tz())::date);
  v_card := public.quote_card(v_on, nullif(btrim(coalesce(p_sel->>'card', '')), ''));
  if not public.is_team() or not public.allowed('clients.quotes', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  if v_card is null then return jsonb_build_object('error', case when nullif(btrim(coalesce(p_sel->>'card', '')), '') is not null then 'bad-card' else 'no-card' end); end if;
  if coalesce(p_sel->>'client', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     and public.client_scope_ok('client', (p_sel->>'client')::uuid, 'view') then
    v_cl := (p_sel->>'client')::uuid;
  end if;
  v_fx := public.quote_fx(v_cl, v_on);
  if v_fx = 0 then return jsonb_build_object('error', 'no-fx'); end if;
  -- The files asked beyond the pieces they cover, each brand on its own.
  for v_b, v_i in
    select case when jsonb_typeof(p_sel->'brands') = 'array' then (p_sel - 'brands') || b else p_sel end,
           case when jsonb_typeof(p_sel->'brands') = 'array' then (n - 1)::int end
      from jsonb_array_elements(case when jsonb_typeof(p_sel->'brands') = 'array' then p_sel->'brands' else '[null]'::jsonb end)
           with ordinality x(b, n)
     where jsonb_typeof(p_sel->'brands') is distinct from 'array' or jsonb_typeof(b) = 'object'
  loop
    if jsonb_typeof(v_b->'once') = 'array' then
      v_cap := public.quote_files_cap(v_b, v_card->'snapshot');
      for v_o in select * from jsonb_array_elements(v_b->'once') loop
        v_s := public.quote_svc(v_card->'snapshot', v_o->>'slug');
        if v_s->'spec'->>'role' = 'addon' and public.quote_web_once_ok(v_s) and coalesce(v_o->>'qty', '') ~ '^[0-9]{1,3}$' then
          v_c := public.quote_file_covers(v_s);
          v_lim := case when v_c is null then (v_cap->>'graphic')::int + (v_cap->>'reel')::int else (v_cap->>v_c)::int end;
          if (v_o->>'qty')::int > v_lim then
            v_x := jsonb_build_object('slug', v_s->>'slug', 'name', v_s->>'name', 'qty', (v_o->>'qty')::int, 'cap', v_lim, 'covers', v_c, 'brand', v_i);
            v_over := v_over || jsonb_build_array(v_x);
          end if;
        end if;
      end loop;
    end if;
  end loop;
  -- Custom lines and starts (2026-11-12) priced with the rest, before S$.
  return public.quote_fx_out(public.quote_compose(public.quote_fx_snap(public.quote_tax_snap(v_card->'snapshot', v_cl, v_on), v_fx),
           p_sel - 'client' - 'date', true), v_fx)
         || jsonb_build_object('version', v_card->>'version', 'versions', public.quote_card_versions(), 'files_over', v_over);
end $$;

create or replace function public.quote_throttle()
returns boolean
language plpgsql volatile security definer set search_path = public as $$
declare
  v_ip   text := coalesce(nullif(public.request_ip(), ''), 'none');
  v_hour timestamp := date_trunc('hour', now() at time zone public.agency_tz());
  v_n    int;
begin
  insert into public.quote_hits as h (ip, hour, n) values (v_ip, v_hour, 1)
  on conflict (ip) do update
     set n = case when h.hour < v_hour then 1 else h.n + 1 end, hour = v_hour
  returning n into v_n;
  return v_n <= 240;
end $$;

create or replace function public.quote_proceed(p_key text, p_start text, p_decider text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  w  public.quotations;
  q  public.quotations;
  v_due timestamptz;
  v_words text;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not-found'); end if;
  select * into w from public.quotations x
   where x.access_key = p_key and x.source = 'website' and x.removed_at is null for update;
  if w.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if w.proceed_at is not null then
    return jsonb_build_object('ok', true, 'again', true, 'at', w.proceed_at, 'due', w.proceed_due);
  end if;
  -- What the prospect sees is the latest revision: its validity and its
  -- state decide (2026-10-26, audit).
  select * into q from public.quotations x where x.id = public.quote_shown(w.id);
  if w.status = 'not_proceeding' or q.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  if q.source = 'website' and q.released_at is null then return jsonb_build_object('error', 'not-sent'); end if;
  if coalesce(p_start, '') not in ('month', 'quarter') or coalesce(p_decider, '') not in ('yes', 'others') then
    return jsonb_build_object('error', 'bad-answer');
  end if;
  if q.valid_until < (now() at time zone public.agency_tz())::date then return jsonb_build_object('error', 'expired'); end if;
  v_due := public.quote_reply_by(now());
  v_words := public.quote_proceed_words(p_start, p_decider);
  update public.quotations
     set proceed_at = now(), proceed_due = v_due, proceed_start = p_start, proceed_decider = p_decider
   where id = w.id;
  insert into public.activity_log (actor, action, subject, detail)
  values ('Quotation portal', 'client.quotation', w.brand,
          w.ref || ' · Ready to proceed on the website' ||
          coalesce(' by ' || nullif(btrim(w.contact->>'name'), ''), '') || ' · ' || v_words);
  perform public.quote_tell(w.client_id, 'quote.proceed', 'Ready to proceed · ' || w.brand,
    w.ref || coalesce(' · ' || nullif(btrim(w.contact->>'name'), ''), '') || ' · ' || v_words || ' · contact by ' ||
      public.register_day((v_due at time zone public.agency_tz())::date) || ', ' ||
      lower(to_char(v_due at time zone public.agency_tz(), 'FMHH12:MIam')),
    w.id::text);
  return jsonb_build_object('ok', true, 'at', now(), 'due', v_due);
end $$;

create or replace function public.outstation_check_out_office(
  p_trip uuid, p_lat numeric, p_lng numeric, p_accuracy numeric, p_read_at timestamptz, p_note text, p_rating integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_t public.outstation_trips; v_last public.outstation_stops; v_err jsonb; v_day date := (now() at time zone public.agency_tz())::date;
  v_lat numeric := public.app_setting('outstation_office_lat', v_day); v_lng numeric := public.app_setting('outstation_office_lng', v_day);
  v_radius numeric := coalesce(public.app_setting('outstation_office_radius_m', v_day), 100);
begin
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_t := public.outstation_own_trip(p_trip);
  if v_t.id is null then return jsonb_build_object('error', 'no-trip'); end if;
  if v_t.state <> 'open' then return jsonb_build_object('error', 'closed'); end if;
  if length(coalesce(p_note, '')) > 2000 then return jsonb_build_object('error', 'too-long'); end if;
  if p_rating is not null and p_rating not between 1 and 5 then return jsonb_build_object('error', 'bad-rating'); end if;
  v_err := public.outstation_reading_error(p_lat, p_lng, p_accuracy, p_read_at);
  if v_err is not null then return v_err; end if;
  if v_lat is null or v_lng is null or public.outstation_metres(p_lat, p_lng, v_lat, v_lng) > v_radius then
    return jsonb_build_object('error', 'not-office', 'radius', v_radius);
  end if;
  select * into v_last from public.outstation_stops s where s.trip_id = v_t.id order by s.seq desc limit 1 for update;
  if not exists (select 1 from public.outstation_photos p where p.stop_id = v_last.id and p.removed_at is null) then
    return jsonb_build_object('error', 'no-photo');
  end if;
  update public.outstation_stops set left_at = now(), left_how = 'office' where id = v_last.id;
  perform public.outstation_file_visit(v_last.id);
  update public.outstation_trips
     set state = 'closed', ended_at = now(), end_lat = p_lat, end_lng = p_lng, end_accuracy_m = p_accuracy,
         end_note = nullif(btrim(coalesce(p_note, '')), ''), rating = p_rating, updated_at = now()
   where id = v_t.id;
  return jsonb_build_object('ok', true, 'trip', public.outstation_trip_json(v_t.id));
end $$;

create or replace function public.outstation_close_open()
returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0; v_today date := (now() at time zone public.agency_tz())::date; v_at timestamptz;
begin
  for r in
    select t.id, t.ref, t.driver_id,
           (select s.id from public.outstation_stops s where s.trip_id = t.id order by s.seq desc limit 1) as last_stop
      from public.outstation_trips t
     where t.state = 'open' and (t.started_at at time zone public.agency_tz())::date < v_today
     for update of t skip locked
  loop
    v_at := coalesce(public.outstation_last_activity(r.last_stop), now());
    if r.last_stop is not null then
      update public.outstation_stops set left_at = v_at, left_how = 'auto' where id = r.last_stop;
      perform public.outstation_file_visit(r.last_stop);
    end if;
    update public.outstation_trips set state = 'closed', ended_at = v_at, updated_at = now() where id = r.id;
    insert into public.activity_log (actor, action, subject, detail)
    values ('Portal', 'ops.trip_closed', r.ref,
            'Outstation trip · ' || coalesce((select m.name from public.team_members m where m.id = r.driver_id), 'Former colleague') ||
            ' · ended at midnight, at its last activity');
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.request_visit()
returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  h json := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::json;
  v_agent text := left(regexp_replace(coalesce(public.request_relayed('agent'), h ->> 'user-agent', ''), '[[:cntrl:]]', '', 'g'), 300);
  v_country text := upper(coalesce(public.request_relayed('country'), public.request_country(), ''));
  v_city text := left(public.seal_device(left(coalesce(public.request_relayed('city'), h ->> 'cf-ipcity'), 60)), 60);
  v_ip text := coalesce(public.request_ip(), '');
  v_salt text := (select s.value from public.app_secrets s where s.key = 'activity_session_salt');
begin
  if v_country !~ '^[A-Z]{2}$' or v_country in ('XX', 'T1') then v_country := null; end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'device', public.ua_device(v_agent),
    'city', v_city,
    'country', v_country,
    'session', case when v_salt is not null and (v_ip <> '' or v_agent <> '') then
      upper(left(encode(digest(v_salt || '|' || v_ip || '|' || coalesce(public.ua_device(v_agent), '') || '|' ||
        ((now() at time zone public.agency_tz())::date)::text, 'sha256'), 'hex'), 6)) end));
end $$;

create or replace function public.hiring_retention()
returns integer language plpgsql volatile security definer set search_path = public as $$
declare
  v_today date := (now() at time zone public.agency_tz())::date;
  v_days int := coalesce(public.app_setting('hiring_link_days', v_today)::int, 30);
  v_keep int := coalesce(public.app_setting('hiring_keep_months', v_today)::int, 12);
  v_n int;
  v_ids uuid[];
begin
  select coalesce(array_agg(c.id), '{}') into v_ids from public.hiring_candidates c
   where c.stage <> 'hired' and (
         (c.stage = 'pool' and c.pool_consent = 'yes' and c.pool_until < now())
      or (c.stage = 'pool' and c.pool_consent = 'asked' and c.outcome_at + make_interval(days => v_days) < now())
      or (c.stage = 'closed' and coalesce(c.outcome_at, c.updated_at) + make_interval(months => v_keep) < now())
      or (c.removed_at is not null and c.removed_at + make_interval(months => v_keep) < now()));
  -- Their offer's and contract's signing steps go with them (RETENTION AND
  -- JOBS HELD): the steps name the document, never the candidate, so the
  -- cascade never reached them.
  delete from public.signing_steps g
   where g.doc_kind = 'hiring_doc'
     and g.doc_id in (select d.id from public.hiring_docs d where d.candidate_id = any(v_ids));
  with gone as (
    delete from public.hiring_candidates c
     where c.id = any(v_ids)
    returning c.cv_path)
  insert into public.hiring_files_gone (path) select g.cv_path from gone g where g.cv_path is not null
  on conflict (path) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

create or replace function public.hiring_expire_mail_claim()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v jsonb;
begin
  -- As the decision emails: a send going out for 10 minutes is not confirmed.
  update public.hiring_docs d set expire_mail = 'unknown', expire_mail_at = now()
   where d.expire_mail = 'sending' and coalesce(d.expire_mail_at, d.expired_told_at) < now() - interval '10 minutes';
  /* Only the rows this call takes: a second wake meanwhile claims none of them. */
  with due as (
    select d.id from public.hiring_docs d join public.hiring_candidates c on c.id = d.candidate_id
     where d.expire_mail = 'queued' and c.removed_at is null and c.link_key is not null
     order by d.expired_told_at limit 20 for update of d skip locked),
  took as (
    update public.hiring_docs d set expire_mail = 'sending', expire_mail_at = now() from due where d.id = due.id
    returning d.id, d.kind, d.serial, d.terms, d.sent_at, d.reply_by, d.candidate_id)
  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'kind', 'expired', 'doc', t.kind, 'ref', t.serial, 'to', c.email,
      'name', c.name, 'position', t.terms->>'position', 'key', c.link_key,
      'sent', public.register_day((t.sent_at at time zone public.agency_tz())::date), 'reply_by', public.hiring_when(t.reply_by),
      'contact', public.mail_sender('careers')->>'reply_to', 'system', true)), '[]'::jsonb) into v
    from took t join public.hiring_candidates c on c.id = t.candidate_id;
  return v;
end $$;

create or replace function public.jobs_watch(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_jobs jsonb := '[]'::jsonb;
  v_runs integer := 0;
  v_self integer := 0;
  v_sweeps integer := 0;
  v_quiet boolean := false;
  v_words text;
  v_day text := to_char(p_now at time zone public.agency_tz(), 'YYYY-MM-DD');
  v_told integer := 0;
  v_rules integer := 0;
  v_wa integer := 0;
  v_agent integer := 0;
  v_mail integer := 0;
  v_hire integer := 0;
  v_bukku text;
  v_names text;
  v_task uuid;
  v_since timestamptz := p_now - interval '24 hours';
  v_last timestamptz;
begin
  if to_regclass('cron.job_run_details') is not null then
    /* Back to this check's own last successful run, so a morning whose
       check failed is reported by the next: at least 24 hours, at most
       seven days. */
    select max(d.start_time) into v_last
      from cron.job_run_details d join cron.job j on j.jobid = d.jobid
     where j.jobname = 'jobs-watch' and d.status = 'succeeded' and d.start_time < p_now - interval '1 minute';
    v_since := greatest(p_now - interval '7 days', least(p_now - interval '24 hours', coalesce(v_last, p_now - interval '24 hours')));
    select coalesce(jsonb_agg(jsonb_build_object('job', x.name, 'failed', x.n) order by x.n desc, x.name), '[]'::jsonb),
           coalesce(sum(x.n), 0)::int
      into v_jobs, v_runs
      from (select coalesce(j.jobname, 'job ' || d.jobid) as name, count(*)::int as n
              from cron.job_run_details d
              left join cron.job j on j.jobid = d.jobid
             where d.status = 'failed' and d.start_time >= v_since and d.start_time < p_now
             group by 1) x;
    select coalesce(sum((e ->> 'failed')::int), 0)::int into v_self
      from jsonb_array_elements(v_jobs) e where e ->> 'job' = 'jobs-watch';
    /* The S3 report's job posts to its edge function and succeeds either
       way: a report that never arrived is a failure too. */
    v_quiet := exists (select 1 from cron.job j where j.jobname = 's3-sweep-daily' and j.active)
           and not exists (select 1 from public.s3_sweeps s where s.ran_at >= p_now - interval '26 hours' and s.ran_at < p_now);
  end if;
  select count(*)::int into v_sweeps from public.s3_sweeps s
   where s.mode = 'failed' and s.ran_at >= v_since and s.ran_at < p_now;
  /* The WhatsApp messages the portal sends by itself (a reminder, a
     booking): one Meta refused, or that could not be sent at all. An
     expired token fails every one, and nobody sees it otherwise. */
  select count(*)::int into v_wa
    from (select coalesce(o.failed_at, case when o.state = 'failed' then coalesce(o.sent_at, o.claimed_at, o.created_at) end) as at
            from public.wa_outbox o where o.created_by = 'system') w
   where w.at >= v_since and w.at < p_now;
  /* What colleagues scheduled through the Assistant that could not be done
     (each colleague is told of their own at the run). */
  select count(*)::int into v_agent from public.agent_schedules s
   where s.state = 'failed' and s.ran_at >= v_since and s.ran_at < p_now;

  /* Each repeat rule that could not make its task, named: its client (else
     Internal), the rule or its task, and the task number. */
  select count(*)::int,
         string_agg(w.label, '; ' order by w.at) filter (where w.n <= 5),
         (array_agg(w.task order by w.at) filter (where w.task is not null))[1]
    into v_rules, v_names, v_task
    from (select coalesce(c.name, 'Internal') || ': ' || coalesce(nullif(btrim(x.name), ''), public.ops_title(t), 'Repeating task')
                 || coalesce(' (' || public.ops_serial(t.task_no) || ')', '') as label,
                 x.last_error_at as at, t.id as task,
                 row_number() over (order by x.last_error_at) as n
            from public.ops_recurring_rules x
            left join public.ops_tasks t on t.id = x.source_task_id
            left join public.clients c on c.id = coalesce(case when t.id is not null then case when t.scope = 'client' then t.client_id end
                                                              else x.client_id end, x.client_id)
           where x.active and x.last_error_at >= v_since and x.last_error_at < p_now) w;

  /* The creator emails the portal sends by itself that failed or were not
     confirmed, and the nightly Bukku read: its job only wakes an edge
     function and succeeds either way, so the run writes a beat when it ends
     (`job_beats`), and none in 26 hours, or one that failed, is told
     (audit 2026-11-15). */
  select count(*)::int into v_mail from public.creator_emails e
   where e.status in ('failed', 'unknown', 'bounced') and e.created_at >= v_since and e.created_at < p_now;
  -- And the candidate emails the portal sends by itself (RETENTION AND JOBS HELD).
  select (select count(*) from public.hiring_candidates c
           where c.outcome_mail in ('failed', 'unknown') and c.outcome_mail_at >= v_since and c.outcome_mail_at < p_now)
       + (select count(*) from public.hiring_docs d
           where d.expire_mail in ('failed', 'unknown') and d.expire_mail_at >= v_since and d.expire_mail_at < p_now)
    into v_hire;
  if to_regclass('cron.job') is not null then
    if exists (select 1 from cron.job j where j.jobname = 'bukku-read-nightly' and j.active) then
    select case when b.job is null or b.ran_at < p_now - interval '26 hours' then 'the nightly read from Bukku did not run'
                when not b.ok then 'the nightly read from Bukku failed: ' || coalesce(b.detail, 'no reason given') end
      into v_bukku
      from (select 1) one left join public.job_beats b on b.job = 'bukku-nightly';
    end if;
  end if;
  if v_runs = 0 and v_sweeps = 0 and not v_quiet and v_rules = 0 and v_wa = 0 and v_agent = 0 and v_mail = 0 and v_hire = 0 and v_bukku is null then
    return jsonb_build_object('failed', 0, 'told', 0);
  end if;
  v_words := concat_ws('; ',
    case when v_self > 0 then 'the morning check of scheduled jobs failed ' || v_self ||
                              case when v_self = 1 then ' time' else ' times' end end,
    nullif((select string_agg((e ->> 'job') || ' failed ' || (e ->> 'failed') ||
                              case when (e ->> 'failed')::int = 1 then ' time' else ' times' end, '; ')
              from jsonb_array_elements(v_jobs) e where e ->> 'job' <> 'jobs-watch'), ''),
    case when v_sweeps > 0 then 'the S3 report was filed as failed' end,
    case when v_quiet then 'the S3 report did not arrive' end,
    case when v_wa > 0 then v_wa || case when v_wa = 1 then ' automatic WhatsApp message' else ' automatic WhatsApp messages' end
                            || ' failed to send' end,
    v_bukku,
    case when v_mail > 0 then v_mail || case when v_mail = 1 then ' creator email was not sent or not confirmed'
                                            else ' creator emails were not sent or not confirmed' end end,
    case when v_hire > 0 then v_hire || case when v_hire = 1 then ' candidate email was not sent or not confirmed'
                                            else ' candidate emails were not sent or not confirmed' end end,
    case when v_agent > 0 then v_agent || case when v_agent = 1 then ' scheduled Assistant action' else ' scheduled Assistant actions' end
                               || ' could not be done' end,
    case when v_rules > 0 then v_rules || case when v_rules = 1 then ' repeating task could' else ' repeating tasks could' end
                               || ' not be made: ' || v_names
                               || case when v_rules > 5 then ' and ' || (v_rules - 5) || ' more' else '' end end) || '.';
  insert into public.ops_notifications (team_member_id, task_id, kind, title, body, dedupe_key)
  select t.id, v_task, 'jobs.failed',
         case when v_since < p_now - interval '25 hours' then 'Scheduled jobs failed since the last check'
              else 'Scheduled jobs failed in the last 24 hours' end,
         v_words, 'jobs.failed.' || v_day || '.' || t.id
    from public.team_members t
   where t.active
     and (t.is_admin
          or (not exists (select 1 from public.team_members o where o.active and o.is_admin)
              and public.level_rank(t.access ->> 'team') >= 3))
  on conflict (dedupe_key) do nothing;
  get diagnostics v_told = row_count;
  return jsonb_build_object('failed', v_runs + v_sweeps + case when v_quiet then 1 else 0 end + v_rules + v_wa + v_agent + v_mail + v_hire
      + case when v_bukku is null then 0 else 1 end, 'whatsapp', v_wa, 'creator_mail', v_mail, 'candidate_mail', v_hire, 'bukku', v_bukku,
    'assistant', v_agent, 'jobs', v_jobs, 'self', v_self, 'since', v_since, 'sweeps', v_sweeps, 'sweep_missing', v_quiet,
    'repeats', v_rules, 'told', v_told);
end $$;

create or replace function public.ops_tasks_remind(p_today date default null)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_today date := coalesce(p_today, (now() at time zone public.agency_tz())::date);
  m record;
  v_open boolean;
  v_made boolean;
  n integer := 0;
begin
  if extract(isodow from v_today) > 5 or public.public_holiday_on(v_today) is not null then return 0; end if;
  for m in select t.id from public.team_members t
            where t.active and not coalesce(t.is_admin, false) and coalesce(t.role, '') <> 'admin'
              and public.ops_takes_tasks(t.id)
            order by t.id loop
    v_open := exists (select 1 from public.ops_task_assignees a
                        join public.ops_tasks k on k.id = a.task_id
                       where a.team_member_id = m.id and a.responsibility = 'owner' and a.ended_at is null
                         and k.completed_at is null and k.cancelled_at is null and k.archived_at is null);
    v_made := exists (select 1 from public.ops_tasks k where k.created_by = m.id);
    if v_open and v_made then continue; end if;
    insert into public.ops_notifications (team_member_id, task_id, kind, title, body, dedupe_key)
    values (m.id, null, 'tasks.empty',
            case when not v_open then 'No open tasks are assigned to you. Add the work you are on in My Work.'
                 else 'Add the tasks you are working on in My Work.' end,
            null, 'tasks.remind.' || m.id || '.' || v_today)
    on conflict (dedupe_key) do nothing;
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.ops_generate_recurring(
  p_period text, p_rules uuid[] default null, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  r     public.ops_recurring_rules;
  src   public.ops_tasks;
  made  integer := 0;
  skip  integer := 0;
  key   text;
  first_day date;
  last_day date;
  anchor date;
  d     date;
  stepd integer;
  one   jsonb;
  wk    integer;
  held  integer := 0;
  ccl   uuid;
  mon   public.ops_engagements;
  errs  jsonb := '[]'::jsonb;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_period !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
  first_day := (p_period || '-01')::date;
  last_day := (first_day + interval '1 month' - interval '1 day')::date;

  for r in select * from public.ops_recurring_rules
            where active and (p_rules is null or id = any (p_rules))
              and (source_task_id is null or public.ops_may_see_task(source_task_id)) loop
    if r.source_task_id is not null then
      select * into src from public.ops_tasks where id = r.source_task_id;
    else
      src := null;
    end if;

    /* A client's repeats wait for the client's month: one that exists, is
       open and has its content meeting set or marked not applicable. Until
       then the rule is held and counted, and a later run makes them. */
    ccl := case when src.id is not null then case when src.scope = 'client' then src.client_id end
                else r.client_id end;
    mon := null;
    if ccl is not null then
      select * into mon from public.ops_engagements x where x.client_id = ccl and x.period = p_period;
      if mon.id is null or mon.status in ('completed', 'cancelled')
         or (mon.meeting_at is null and not mon.meeting_na) then
        held := held + 1;
        continue;
      end if;
    end if;

    /* The dates this rule falls on inside the month. */
    if r.frequency = 'monthly' then
      d := first_day + (least(coalesce(r.day_of_month,
              case when src.publish_at is not null then extract(day from src.publish_at)::integer else 1 end),
              extract(day from last_day)::integer) - 1);
      stepd := null;
    else
      stepd := case when r.frequency = 'weekly' then 7 else greatest(1, coalesce(r.interval_days, 7)) end;
      anchor := coalesce(src.publish_at::date, (r.created_at at time zone public.agency_tz())::date, first_day);
      if anchor > first_day then d := anchor;
      else d := anchor + ((((first_day - anchor) + stepd - 1) / stepd) * stepd); end if;
    end if;

    while d is not null and d <= last_day loop
      if d >= first_day
         /* The task a rule copies is its first occurrence: nothing on or
            before its day is made again. */
         and (src.id is null or d > coalesce(src.publish_at::date, (r.created_at at time zone public.agency_tz())::date))
         and (r.ends_on is null or d <= r.ends_on)
         and (r.max_count is null or r.generated_count < r.max_count) then
        key := 'recur:' || r.id::text || ':' || to_char(d, 'YYYY-MM-DD');
        -- One maker of a rule's dates at a time (RETENTION AND JOBS HELD):
        -- two presses at once read the same dates as free.
        perform pg_advisory_xact_lock(hashtext('recur:' || r.id::text));
        /* Made once is made: a copy since deleted stays deleted, and a rule
           set again on the same task makes none of its dates twice. */
        if exists (select 1 from public.ops_tasks where idem_key = key)
           or exists (select 1 from public.ops_recurring_made x
                       where x.on_date = d
                         and (x.rule_id = r.id
                              or (r.source_task_id is not null and x.source_task_id = r.source_task_id))) then
          skip := skip + 1;
        else
          wk := coalesce(r.code_week, least(5, ((extract(day from d)::integer - 1) / 7) + 1));
          /* One rule that cannot make its task never stops the others: the
             attempt is undone, its error kept on the rule and answered, and
             the run goes on to the next rule. */
          one := null;
          begin
            if src.id is not null then
              one := public.ops_duplicate_task(src.id, jsonb_build_object(
                'keep_desc', true, 'copy_dates', false, 'copy_assignees', true,
                'publish_at', d::timestamptz, 'code_period', p_period, 'code_week', wk,
                'engagement_id', mon.id), key);
            else
              one := public.ops_create_task(jsonb_build_object(
                'scope', case when r.client_id is null then 'internal' else 'client' end,
                'client_id', r.client_id, 'template_id', r.template_id,
                'title', r.name || ' — ' || p_period, 'content_desc', r.name,
                'owner_id', r.owner_id, 'publish_at', d::timestamptz,
                'code_period', p_period, 'code_week', wk, 'engagement_id', mon.id), key);
            end if;
            if one ? 'error' then raise exception using message = 'repeat-refused'; end if;
          exception when others then
            if one is null or not (one ? 'error') then one := jsonb_build_object('error', sqlerrm); end if;
          end;
          if one ? 'error' then
            errs := errs || jsonb_build_array(jsonb_build_object('rule', r.id, 'on', d, 'error', one ->> 'error'));
            update public.ops_recurring_rules
               set last_error = left(one ->> 'error', 500), last_error_at = now()
             where id = r.id;
            exit;
          end if;
          made := made + 1;
          insert into public.ops_recurring_made (rule_id, source_task_id, on_date)
          values (r.id, r.source_task_id, d) on conflict do nothing;
          update public.ops_recurring_rules
             set generated_count = generated_count + 1, last_generated_period = p_period, updated_at = now(),
                 last_error = null, last_error_at = null
           where id = r.id;
          r.generated_count := r.generated_count + 1;
        end if;
      end if;
      exit when stepd is null;
      d := d + stepd;
    end loop;
  end loop;
  return jsonb_build_object('created', made, 'skipped', skip, 'held', held, 'period', p_period,
    'failed', jsonb_array_length(errs), 'errors', errs);
end $$;

create or replace function public.verify_find(p_serial text)
returns jsonb
language plpgsql stable set search_path = public as $$
declare
  s text := upper(btrim(coalesce(p_serial, '')));
  sd text;
  d public.documents%rowtype;
  l public.client_documents%rowtype;
  q public.quotations%rowtype;
  h public.hiring_docs%rowtype;
  rv public.perf_reviews%rowtype;
  dl public.perf_deleted%rowtype;
  rp public.sm_report_versions%rowtype;
  vs public.video_scripts%rowtype;
  v_code text;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_state text;
  v_rep date;
  v_ref text;
begin
  if length(s) < 3 or length(s) > 40 then return null; end if;
  sd := replace(s, '/', '-');
  select * into d from public.documents x
   where upper(replace(x.serial, '/', '-')) = sd
   order by (upper(x.serial) = s) desc, (x.voided_at is null) desc, x.created_at desc limit 1;
  if d.id is not null then
    return jsonb_build_object('src', 'document', 'id', d.id, 'serial', d.serial,
      'kind', case when d.family = 'hr' then 'HR Letter' else d.kind end,
      'issued', d.issued_at, 'code', d.doc_code, 'sealed', false,
      'names', public.verify_names(array[d.recipient ->> 'name',
        (select c.legal_name from public.clients c where c.id = d.client_id),
        (select m.name from public.team_members m where m.id = d.member_id),
        (select coalesce(nullif(to_jsonb(u) ->> 'legal_name', ''), to_jsonb(u) ->> 'name') from public.suppliers u where u.id = d.supplier_id)]),
      'state', case when d.voided_at is null then 'valid' else 'voided' end,
      'steps', public.verify_steps(jsonb_build_array(
        jsonb_build_object('step', 'issued', 'day', d.issued_at),
        jsonb_build_object('step', 'voided', 'day', (d.voided_at at time zone public.agency_tz())::date))));
  end if;
  select * into l from public.client_documents x
   where upper(replace(x.number, '/', '-')) = sd
   order by (upper(x.number) = s) desc limit 1;
  if l.id is not null then
    select x.issued_at into v_rep
      from public.client_documents x where x.id = l.superseded_by;
    return jsonb_build_object('src', 'letter', 'id', l.id, 'serial', l.number, 'kind', 'Letter of Offer',
      'issued', l.issued_at, 'code', l.doc_code, 'sealed', false,
      'names', public.verify_names(array[coalesce(nullif(l.bill_to ->> 'legal_name', ''), l.bill_to ->> 'name'), l.bill_to ->> 'contact',
        (select c.legal_name from public.clients c where c.id = l.client_id)]),
      'state', case when l.voided_at is not null then 'voided'
                    when l.superseded_by is not null then 'replaced'
                    else 'valid' end,
      'steps', public.verify_steps(jsonb_build_array(
        jsonb_build_object('step', 'issued', 'day', l.issued_at),
        jsonb_build_object('step', 'signed', 'day', (l.signed_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'confirmed', 'day', (l.verified_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'replaced', 'day', v_rep),
        jsonb_build_object('step', 'voided', 'day', (l.voided_at at time zone public.agency_tz())::date))));
  end if;
  select * into q from public.quotations x
   where (upper(replace(x.ref, '/', '-')) = sd)
     and public.quotation_issued(x)
   order by (upper(x.ref) = s) desc, x.issued_at desc limit 1;
  if q.id is not null then
    select (min(r.issued_at) at time zone public.agency_tz())::date into v_rep
      from public.quotations r where r.replaces = q.id and r.removed_at is null;
    v_state := case when q.withdrawn_at is not null then 'withdrawn'
                    when q.status = 'not_proceeding' or q.removed_at is not null then 'voided'
                    when v_rep is not null then 'replaced'
                    when q.signed_at is null and q.valid_until is not null and q.valid_until < v_today then 'expired'
                    else 'valid' end;
    return jsonb_build_object('src', 'quotation', 'id', q.id, 'serial', q.ref, 'kind', 'Quotation',
      'issued', (q.issued_at at time zone public.agency_tz())::date, 'code', q.doc_code, 'sealed', q.seal_key is not null,
      'names', public.verify_names(array[q.contact ->> 'name', to_jsonb(q) #>> '{bill_to,legal_name}',
        (select c.legal_name from public.clients c where c.id = q.client_id)]),
      'state', v_state,
      'steps', public.verify_steps(jsonb_build_array(
        jsonb_build_object('step', 'issued', 'day', (q.issued_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'sent', 'day', (q.sent_out_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'signed', 'day', (q.signed_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'confirmed', 'day', (q.reviewed_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'sealed', 'day', (q.sealed_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'declined', 'day', (q.declined_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'withdrawn', 'day', q.withdrawn_on),
        jsonb_build_object('step', 'voided', 'day', (q.removed_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'replaced', 'day', v_rep),
        jsonb_build_object('step', 'expired', 'day', case when v_state = 'expired' then q.valid_until + 1 end))));
  end if;
  /* An offer or a contract once sent: the version standing first (a
     replacement keeps the reference, the one it replaced void). */
  select * into h from public.hiring_docs x
   where (upper(replace(x.serial, '/', '-')) = sd)
     and x.sent_at is not null and x.state <> 'draft'
   order by (upper(x.serial) = s) desc, (x.state <> 'void') desc, x.sent_at desc limit 1;
  if h.id is not null then
    v_state := case when h.state = 'void' then 'voided'
                    when h.state = 'withdrawn' then 'withdrawn'
                    when h.state = 'declined' then 'declined'
                    when h.state = 'sent' and h.reply_by is not null and h.reply_by < now() then 'expired'
                    else 'valid' end;
    return jsonb_build_object('src', 'hiring', 'id', h.id, 'serial', h.serial, 'kind', 'HR Letter',
      'issued', (h.sent_at at time zone public.agency_tz())::date, 'code', h.doc_code, 'sealed', h.seal_sha is not null,
      'names', public.verify_names(array[(select k.name from public.hiring_candidates k where k.id = h.candidate_id)]),
      'state', v_state,
      'steps', public.verify_steps(jsonb_build_array(
        jsonb_build_object('step', 'issued', 'day', (h.sent_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'signed', 'day', (h.signed_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'confirmed', 'day', (h.confirmed_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'sealed', 'day', (h.sealed_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'declined', 'day', case when h.state = 'declined' then (coalesce(h.answered_at, h.updated_at) at time zone public.agency_tz())::date end),
        jsonb_build_object('step', 'withdrawn', 'day', case when h.state = 'withdrawn' then (h.updated_at at time zone public.agency_tz())::date end),
        jsonb_build_object('step', 'voided', 'day', (h.voided_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'expired', 'day', case when v_state = 'expired' then (h.reply_by at time zone public.agency_tz())::date end))));
  end if;
  select * into rv from public.perf_reviews pr
   where (upper(replace(pr.serial, '/', '-')) = sd)
     and exists (select 1 from public.perf_events pe where pe.review_id = pr.id and pe.kind = 'printed')
   limit 1;
  if rv.id is not null then
    return jsonb_build_object('src', 'perf', 'id', rv.id, 'serial', rv.serial, 'kind', 'HR Letter',
      'issued', (rv.released_at at time zone public.agency_tz())::date, 'code', rv.doc_code, 'sealed', false,
      'names', public.verify_names(array[(select m.name from public.team_members m where m.id = rv.team_member_id)]),
      'state', case when rv.status = 'draft' then 'replaced' else 'valid' end,
      'steps', public.verify_steps(jsonb_build_array(
        jsonb_build_object('step', 'issued', 'day', (rv.released_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'acknowledged', 'day', (rv.acknowledged_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'finalised', 'day', (rv.finalised_at at time zone public.agency_tz())::date))));
  end if;
  select * into dl from public.perf_deleted pd
   where pd.printed and (upper(replace(pd.serial, '/', '-')) = sd)
   order by pd.deleted_at desc limit 1;
  if dl.id is not null then
    return jsonb_build_object('src', 'perf_deleted', 'id', dl.id, 'serial', dl.serial, 'kind', 'HR Letter',
      'issued', (dl.released_at at time zone public.agency_tz())::date, 'code', null, 'sealed', false, 'state', 'voided',
      'names', public.verify_names(array[(select m.name from public.team_members m where m.id = dl.team_member_id)]),
      'steps', public.verify_steps(jsonb_build_array(
        jsonb_build_object('step', 'issued', 'day', (dl.released_at at time zone public.agency_tz())::date),
        jsonb_build_object('step', 'voided', 'day', (dl.deleted_at at time zone public.agency_tz())::date))));
  end if;
  /* A report as published and a video script as shared hold no reference
     of their own: the Document ID their foot prints is what /verify/ is
     asked (DOCUMENT ID ON EVERY FOOT, 2026-11-24). */
  v_code := regexp_replace(s, '[^0-9A-Z]', '', 'g');
  if v_code ~ '^[2-9A-Z]{8}$' then
    select * into rp from public.sm_report_versions x where x.doc_code = v_code limit 1;
    if rp.id is not null then
      select (min(n.published_at) at time zone public.agency_tz())::date into v_rep
        from public.sm_report_versions n where n.report_id = rp.report_id and n.version_no > rp.version_no;
      return jsonb_build_object('src', 'report', 'id', rp.id, 'serial', substr(v_code, 1, 4) || '-' || substr(v_code, 5, 4), 'by_code', true,
        'kind', case when coalesce(rp.snapshot #>> '{report,kind}', (select r.kind from public.sm_reports r where r.id = rp.report_id)) = 'ads'
                     then 'Social Media Advertising Report' else 'Social Media Accounts Report' end,
        'issued', (rp.published_at at time zone public.agency_tz())::date, 'code', rp.doc_code, 'sealed', false,
        'state', case when rp.withdrawn_at is not null then 'withdrawn' when v_rep is not null then 'replaced' else 'valid' end,
        'steps', public.verify_steps(jsonb_build_array(
          jsonb_build_object('step', 'issued', 'day', (rp.published_at at time zone public.agency_tz())::date),
          jsonb_build_object('step', 'replaced', 'day', v_rep),
          jsonb_build_object('step', 'withdrawn', 'day', (rp.withdrawn_at at time zone public.agency_tz())::date))));
    end if;
    /* A quotation by the Document ID its foot prints (QUOTATIONS ISSUED
       WHEN CREATED, 2026-11-26): its reference is what is typed, the code
       found here stands for it, as a report's does. */
    select x.ref into v_ref from public.quotations x where x.doc_code = v_code and public.quotation_issued(x) limit 1;
    if v_ref is not null then
      return public.verify_find(v_ref) || jsonb_build_object('serial', substr(v_code, 1, 4) || '-' || substr(v_code, 5, 4), 'by_code', true);
    end if;
    select * into vs from public.video_scripts x where x.doc_code = v_code and x.shared_at is not null limit 1;
    if vs.id is not null then
      return jsonb_build_object('src', 'script', 'id', vs.id, 'serial', substr(v_code, 1, 4) || '-' || substr(v_code, 5, 4), 'by_code', true,
        'kind', 'Video Script',
        'issued', (vs.shared_at at time zone public.agency_tz())::date, 'code', vs.doc_code, 'sealed', false,
        'state', case when vs.status = 'shared' then 'valid' else 'withdrawn' end,
        'steps', public.verify_steps(jsonb_build_array(
          jsonb_build_object('step', 'issued', 'day', (vs.shared_at at time zone public.agency_tz())::date),
          jsonb_build_object('step', 'withdrawn', 'day', case when vs.status <> 'shared' then (vs.updated_at at time zone public.agency_tz())::date end))));
    end if;
  end if;
  return null;
end $$;

create or replace function public.campaign_invoice_prep(p_campaign uuid, p_mode text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  m public.campaigns;
  cl public.clients;
  b public.bukku_settings;
  v_contact bigint; v_cur text; v_fx numeric := 1; v_lines jsonb;
begin
  if me.id is null or not public.allowed('campaigns.finance', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_mode is null or p_mode not in ('create', 'link') then return jsonb_build_object('error', 'bad-request'); end if;
  select * into m from public.campaigns x where x.id = p_campaign for update;
  if m.id is null or not public.client_scope_ok('campaign', m.id, 'work') then return jsonb_build_object('error', 'not-found'); end if;
  -- An invoice typed or uploaded before stays as it was (read only).
  if m.bukku_invoice_id is not null or m.invoice_no is not null or m.invoice_url is not null then
    return jsonb_build_object('error', 'invoiced', 'number', m.invoice_no);
  end if;
  select * into cl from public.clients x where x.id = m.client_id;
  select l.contact_id into v_contact from public.bukku_links l where l.kind = 'client' and l.record_id = m.client_id;
  if v_contact is null then v_contact := (public.bukku_shared('client', m.client_id)->>'contact_id')::bigint; end if;
  if v_contact is null then return jsonb_build_object('error', 'not-linked'); end if;
  v_cur := case when upper(coalesce(cl.market, '')) = 'SG' and cl.bill_sgd then 'SGD' else 'MYR' end;
  if p_mode = 'link' then
    return jsonb_build_object('ok', true, 'contact_id', v_contact, 'currency', v_cur);
  end if;
  select * into b from public.bukku_settings where id = 1;
  if nullif(btrim(coalesce(b.campaign_invoice_model, '')), '') is null then return jsonb_build_object('error', 'no-model'); end if;
  if v_cur = 'SGD' then
    v_fx := nullif(public.app_setting('fx_sgd', (now() at time zone public.agency_tz())::date), 0);
    if v_fx is null then return jsonb_build_object('error', 'no-fx'); end if;
  end if;
  -- One line a booked creator at the client rate, in the order they were booked.
  select coalesce(jsonb_agg(jsonb_build_object('label', left(coalesce(c.name, 'Creator') || ' · ' || m.title, 255),
           'amount', o.rate) order by o.position, o.added_at), '[]'::jsonb)
    into v_lines
    from public.campaign_options o left join public.creators c on c.id = o.creator_id
   where o.campaign_id = m.id and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted',
         'reviewing', 'changes', 'scheduled', 'posted', 'completed')
     and not coalesce(o.goodwill, false) and coalesce(o.rate, 0) > 0;
  if jsonb_array_length(v_lines) = 0 then return jsonb_build_object('error', 'nothing'); end if;
  if m.invoice_claimed_at is not null and m.invoice_claimed_at > now() - interval '10 minutes' then
    return jsonb_build_object('error', 'creating');
  end if;
  update public.campaigns x set invoice_claimed_at = now(), invoice_claimed_by = me.id where x.id = m.id;
  return jsonb_build_object('ok', true, 'contact_id', v_contact, 'currency', v_cur, 'fx', v_fx, 'sst', cl.sst_applies,
    'model', btrim(b.campaign_invoice_model), 'lines', v_lines,
    'ref', left(coalesce(nullif(m.campaign_code, '') || ' · ', '') || m.title, 50),
    'date', (now() at time zone public.agency_tz())::date, 'description', left(m.title, 200));
end $$;

create or replace function public.hiring_invite(p_id uuid, p_slots timestamptz[], p_minutes int, p_mode text, p_note text, p_idem text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_role text := public.hiring_role(p_id);
  c public.hiring_candidates;
  i public.hiring_interviews;
  v_days int := coalesce(public.app_setting('hiring_invite_days', (now() at time zone public.agency_tz())::date)::int, 3);
  v_slots timestamptz[];
  v_round int;
begin
  if v_role is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_role not in ('admin', 'owner') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_idem, '') !~ '^[A-Za-z0-9-]{8,64}$' then return jsonb_build_object('error', 'bad-request'); end if;
  perform pg_advisory_xact_lock(hashtext('hiring_invite:' || p_idem));
  select * into i from public.hiring_interviews where idem = p_idem;
  if i.id is not null then return jsonb_build_object('ok', true, 'id', i.id, 'again', true); end if;
  select * into c from public.hiring_candidates where id = p_id for update;
  if c.id is null or c.removed_at is not null then return jsonb_build_object('error', 'not-found'); end if;
  if c.stage in ('hired', 'closed') then return jsonb_build_object('error', 'closed'); end if;
  select array_agg(distinct s order by s) into v_slots from unnest(coalesce(p_slots, '{}')) s where s is not null;
  if v_slots is null or cardinality(v_slots) < 1 or cardinality(v_slots) > 3 then return jsonb_build_object('error', 'bad-slots'); end if;
  if v_slots[1] < now() + interval '1 hour' then return jsonb_build_object('error', 'slot-past'); end if;
  if v_slots[cardinality(v_slots)] > now() + interval '60 days' then return jsonb_build_object('error', 'slot-far'); end if;
  if (v_slots[cardinality(v_slots)] at time zone public.agency_tz())::date - (v_slots[1] at time zone public.agency_tz())::date >= v_days then
    return jsonb_build_object('error', 'slot-window', 'days', v_days);
  end if;
  if coalesce(p_minutes, 0) not in (30, 45, 60, 90) then return jsonb_build_object('error', 'bad-minutes'); end if;
  if coalesce(p_mode, '') not in ('online', 'office') then return jsonb_build_object('error', 'bad-mode'); end if;
  if char_length(coalesce(p_note, '')) > 500 then return jsonb_build_object('error', 'too-long'); end if;
  update public.hiring_interviews set state = 'replaced', updated_at = now()
   where candidate_id = c.id and state in ('invited', 'picked', 'none');
  /* New times cancel a confirmed interview not yet held (the page takes its
     Meet off and tells the candidate first; 2026-11-20). */
  update public.hiring_interviews set state = 'cancelled', updated_at = now()
   where candidate_id = c.id and state = 'confirmed' and held_at is null;
  select coalesce(max(round), 0) + 1 into v_round from public.hiring_interviews where candidate_id = c.id and state <> 'replaced';
  insert into public.hiring_interviews (candidate_id, round, slots, minutes, mode, note, idem, invited_by)
  values (c.id, least(v_round, 20), v_slots, p_minutes, p_mode, nullif(btrim(coalesce(p_note, '')), ''), p_idem, me.id)
  returning * into i;
  -- Where its interviews now leave it: Invited, or Interview while one
  -- confirmed stands (a held round); a confirmed one just cancelled no
  -- longer holds it at Interview (2026-11-26).
  update public.hiring_candidates set stage = case when stage in ('new', 'pool', 'invited', 'interview') then public.hiring_interview_stage(id, 'invited') else stage end,
    last_step_at = now(), updated_at = now() where id = c.id;
  perform public.hiring_log(c.id, 'candidate.invited', cardinality(v_slots) || case when cardinality(v_slots) = 1 then ' time' else ' times' end
    || ' · ' || case p_mode when 'online' then 'Google Meet' else 'At the office' end || ' · ' || p_minutes || ' minutes');
  return jsonb_build_object('ok', true, 'id', i.id);
end $$;

create or replace function public.quote_draft_ref(p_at timestamptz)
returns text language plpgsql volatile set search_path = public, extensions as $$
declare
  alphabet constant text := 'BCDFGHJKLMNPQRSTVWXZ';
  v_out text; v_bytes bytea; v_i int; v_b int;
begin
  loop
    v_out := '';
    v_bytes := gen_random_bytes(16);
    for v_i in 0..15 loop
      v_b := get_byte(v_bytes, v_i);
      if v_b < 240 and length(v_out) < 4 then v_out := v_out || substr(alphabet, 1 + (v_b % 20), 1); end if;
    end loop;
    continue when length(v_out) < 4;
    v_out := 'ADP/QT' || to_char(p_at at time zone public.agency_tz(), 'YYMM') || '-DRAFT-' || v_out;
    exit when not exists (select 1 from public.quotations q where q.ref = v_out);
  end loop;
  return v_out;
end $$;

create or replace function public.quotation_make(p_client uuid, p_sel jsonb, p_idem text, p_source text,
                                                 p_by text, p_contact jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_c public.clients;
  v_on date := case when p_source = 'console' and jsonb_typeof(p_sel) = 'object' then public.doc_day_of(p_sel->>'date') end;
  v_card jsonb;
  v_p jsonb;
  v_q public.quotations;
  v_now timestamptz := now();
  v_days int;
  v_fx numeric;
  v_x jsonb;
  v_b jsonb;
  v_sel jsonb := case when jsonb_typeof(p_sel) is distinct from 'object' then p_sel
                      when p_source = 'console' then p_sel - 'client' - 'date'
                      else p_sel - 'edits' - 'client' - 'date' end;
begin
  if p_idem is not null then
    select * into v_q from public.quotations q where q.idem = p_idem and q.client_id = p_client;
    if v_q.id is not null then return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'again', true); end if;
  end if;
  /* The quotation's own date (2026-11-12, the user: a document may be
     backdated): its reference's month, its validity, and the SST and terms
     in force; a team's alone, today where none is chosen. */
  if v_on is not null and not public.doc_day_ok(v_on) then return jsonb_build_object('error', 'bad-date'); end if;
  if v_on is not null and v_on <> (v_now at time zone public.agency_tz())::date then
    v_now := (v_on::timestamp + (v_now at time zone public.agency_tz())::time) at time zone public.agency_tz();
  end if;
  v_on := (v_now at time zone public.agency_tz())::date;
  -- the Rate Card chosen in Build quote, else the one live on the date (2026-11-15)
  v_card := public.quote_card(v_on, case when p_source = 'console' then nullif(btrim(coalesce(p_sel->>'card', '')), '') end);
  select * into v_c from public.clients where id = p_client;
  if v_c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_card is null then return jsonb_build_object('error', 'no-card'); end if;
  v_fx := public.quote_fx(v_c.id, v_on);
  if v_fx = 0 then return jsonb_build_object('error', 'no-fx'); end if;
  v_p := public.quote_fx_out(public.quote_compose(public.quote_fx_snap(public.quote_tax_snap(v_card->'snapshot', v_c.id, v_on), v_fx),
           v_sel, p_source = 'console'), v_fx);
  if v_p ? 'error' then return v_p; end if;
  /* The advertising budget and the payment terms (2026-11-12): a team's
     own; a website quotation takes none and NET 7. */
  v_x := public.quote_extras(case when p_source = 'console' then v_sel else '{}'::jsonb end);
  if v_x ? 'error' then return v_x; end if;
  if p_source = 'console' then
    v_b := public.quote_client_extras(v_c.id, v_p->'lines', v_sel);
    if v_b ? 'error' then return v_b; end if;
    v_x := v_x || v_b;
  end if;
  /* A quotation holds at least one priced line (2026-10-29): a selection of
     items quoted on request alone (a KOL campaign, a custom creator list)
     made a quotation with no line and no figure. */
  if jsonb_typeof(v_p->'lines') is distinct from 'array' or jsonb_array_length(v_p->'lines') = 0 then
    return jsonb_build_object('error', 'nothing-priced');
  end if;
  v_days := coalesce((v_x->>'valid_days')::int, public.app_setting('quote_valid_days', (v_now at time zone public.agency_tz())::date), 30)::int;
  begin
  insert into public.quotations (ref, client_id, brand, version, version_id, selection, lines, totals, source,
                                 issued_at, valid_until, made_by, contact, idem, access_key, request_ref)
  values (case when p_source = 'website' then public.quote_request_ref(v_now) else public.quote_draft_ref(v_now) end, v_c.id, v_c.name, v_card->>'version', (v_card->>'id')::uuid, v_sel,
          v_p->'lines', v_p->'totals' || jsonb_build_object('on_request', v_p->'on_request') || v_x, p_source,
          v_now, (v_now at time zone public.agency_tz())::date + v_days, p_by, p_contact, p_idem,
          case when p_source = 'website' then public.new_link_key() end, null)
  returning * into v_q;
  -- A website request keeps the number its sender was given, after its
  -- reference is issued at Send quotation (QUOTATIONS CONFIRMED, 2026-11-26).
  if p_source = 'website' then update public.quotations set request_ref = ref where id = v_q.id returning * into v_q; end if;
  -- Two presses at once with one key: the second answers the first's.
  exception when unique_violation then
    select * into v_q from public.quotations q where q.idem = p_idem and q.client_id = p_client;
    if p_idem is null or v_q.id is null then raise; end if;
    return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'again', true);
  end;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(p_by, 'Website'), 'client.quotation', v_c.name,
          v_q.ref || case when p_source = 'website' then ' requested · ' else ' drafted · ' end || coalesce('Monthly incl. SST ' || case when v_fx is null then 'RM ' else 'S$ ' end ||
            to_char((v_q.totals->'month'->>'incl')::numeric, 'FM999,999,990.00'), 'one-time') ||
          ' · Rate Card v.' || v_q.version ||
          case coalesce((v_p->>'adjusted')::int, 0) when 0 then '' when 1 then ' · 1 line changed'
               else ' · ' || (v_p->>'adjusted') || ' lines changed' end);
  return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'key', v_q.access_key);
end $$;

create or replace function public.quotation_resend(p_id uuid, p_again boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  q  public.quotations;
  t  public.wa_templates;
  o  public.wa_outbox;
  k  public.client_contacts;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_hours numeric;
  v_wa text;
  v_name text;
  v_greet text;
  v_team boolean;
begin
  if me.id is null or not public.allowed('clients.quotes', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.send_ok('whatsapp') then return jsonb_build_object('error', 'send-off'); end if;
  select * into q from public.quotations x where x.id = p_id for update;
  if q.id is null or q.removed_at is not null or not public.client_scope_ok('client', q.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- A draft goes nowhere until it is confirmed (QUOTATIONS CONFIRMED, 2026-11-26).
  if q.confirmed_at is null then return jsonb_build_object('error', 'not-confirmed'); end if;
  v_team := q.source <> 'website';
  if not v_team and q.access_key is null then return jsonb_build_object('error', 'bad-quotation'); end if;
  if not v_team and q.released_at is null then return jsonb_build_object('error', 'not-sent'); end if;
  if q.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  if exists (select 1 from public.quotations x where x.replaces = q.id and x.removed_at is null) then
    return jsonb_build_object('error', 'revised');
  end if;
  if q.valid_until is not null and q.valid_until < v_today then return jsonb_build_object('error', 'expired'); end if;
  if q.no_contact_at is not null then return jsonb_build_object('error', 'no-contact'); end if;
  if v_team and q.signed_at is not null then return jsonb_build_object('error', 'signed'); end if;
  select * into t from public.wa_templates x where x.purpose = 'quote_ready' and x.active and x.name <> '';
  if t.purpose is null then return jsonb_build_object('error', 'wa-off'); end if;
  if v_team then
    select * into k from public.client_contacts x
     where x.client_id = q.client_id and x.archived_at is null and x.is_primary
     order by x.created_at limit 1;
    v_wa := public.wa_number(case when btrim(coalesce(k.whatsapp, '')) <> '' and btrim(k.whatsapp) !~ '^@' then k.whatsapp else k.phone end);
    v_name := coalesce(nullif(btrim(coalesce(k.name, '')), ''), q.brand);
    v_greet := public.contact_greeting(k.salutation, v_name);
  else
    v_wa := public.quote_website_number(q.contact->>'whatsapp');
    v_name := coalesce(nullif(btrim(q.contact->>'name'), ''), q.brand);
    v_greet := public.contact_greeting(q.contact->>'salutation', v_name);
  end if;
  if v_wa is null or v_wa !~ '^(60|65)[0-9]{8,10}$' then return jsonb_build_object('error', 'no-number'); end if;
  v_hours := coalesce(public.app_setting('wa_repeat_hours', v_today), 24);
  if v_hours > 0 and not coalesce(p_again, false) then
    select * into o from public.wa_outbox x
     where x.purpose = 'quote_ready' and x.ref_id = q.id and x.state <> 'failed'
       and x.created_at > now() - make_interval(secs => v_hours * 3600)
     order by x.created_at desc limit 1;
    if o.id is not null then
      return jsonb_build_object('error', 'recent', 'recent', jsonb_build_object('at', o.created_at,
        'by', case when coalesce(o.created_by, 'system') = 'system' then null else o.created_by end));
    end if;
  end if;
  if not v_team and not public.quote_wa_allowed(q.id) then
    return jsonb_build_object('error', 'wa-limit', 'cap', coalesce(public.app_setting('quote_wa_day', v_today), 30));
  end if;
  -- A team's quotation takes its link the first time it is sent.
  if q.access_key is null then
    update public.quotations set access_key = public.new_link_key() where id = q.id returning * into q;
  end if;
  perform public.wa_enqueue('quote_ready', v_wa, v_name,
    jsonb_build_array(v_greet, coalesce(q.contact->>'brand', q.brand), q.ref),
    'quotation', q.id, q.client_id, q.access_key);
  update public.wa_outbox x set created_by = me.name
   where x.purpose = 'quote_ready' and x.ref_id = q.id and x.created_at = now() and x.created_by = 'system';
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', q.brand,
          q.ref || case when v_team then ' link sent on WhatsApp to ' || v_name else ' sent again to the prospect on WhatsApp' end);
  return jsonb_build_object('ok', true, 'key', q.access_key);
end $$;

create or replace function public.quotation_paper(p_id uuid, p_payload jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  q  public.quotations;
  pl jsonb := coalesce(p_payload, '{}'::jsonb);
  c1 jsonb; c2 jsonb;
  v_name text := btrim(regexp_replace(coalesce(pl->'signer'->>'name', ''), '\s+', ' ', 'g'));
  v_role text := btrim(regexp_replace(coalesce(pl->'signer'->>'designation', ''), '\s+', ' ', 'g'));
  v_day  text := btrim(coalesce(pl->>'day', ''));
  v_scan text := nullif(btrim(coalesce(pl->>'scan', '')), '');
  v_at timestamptz;
  v_d  date;
begin
  if me.id is null or not public.allowed('clients.quotes', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into q from public.quotations x where x.id = p_id for update;
  if q.id is null or q.removed_at is not null or not public.client_scope_ok('client', q.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- A draft goes nowhere until it is confirmed (QUOTATIONS CONFIRMED, 2026-11-26).
  if q.confirmed_at is null then return jsonb_build_object('error', 'not-confirmed'); end if;
  if q.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  if q.signed_at is not null then return jsonb_build_object('error', 'signed'); end if;
  c1 := public.quote_sign_company(pl->'company'); if c1 ? 'error' then return c1; end if;
  c2 := public.quote_sign_contact(pl->'contact'); if c2 ? 'error' then return c2; end if;
  if length(v_name) < 2 or length(v_name) > 80 then return jsonb_build_object('error', 'bad-signer_name'); end if;
  if length(v_role) < 2 or length(v_role) > 80 then return jsonb_build_object('error', 'bad-signer_designation'); end if;
  -- A day that is no date (30 February) is bad-day, never the database's
  -- own refusal (audit 2026-11-04).
  if v_day !~ '^\d{4}-\d{2}-\d{2}$' then return jsonb_build_object('error', 'bad-day'); end if;
  begin
    v_d := v_day::date;
  exception when others then
    return jsonb_build_object('error', 'bad-day');
  end;
  if v_d > (now() at time zone public.agency_tz())::date or v_d < (q.issued_at at time zone public.agency_tz())::date then
    return jsonb_build_object('error', 'bad-day');
  end if;
  if v_scan is not null and v_scan !~ '^https://[^\s"''<>`\\]+$' then return jsonb_build_object('error', 'bad-scan'); end if;
  -- Noon in Malaysia on the day it was signed.
  v_at := (v_d + time '12:00') at time zone public.agency_tz();
  update public.quotations
     set signed_at = v_at,
         signed = jsonb_build_object('via', 'paper', 'company', c1->'company', 'contact', c2->'contact',
           'signer', jsonb_build_object('name', v_name, 'designation', v_role), 'signature', null, 'scan', v_scan,
           'record', jsonb_build_object('at', v_at, 'by', me.name, 'entered_at', now())),
         returned_at = null, return_note = null, returned_by = null
   where id = q.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', q.brand,
          q.ref || ' signed on paper by ' || v_name || ' for ' || (c1->'company'->>'legal_name') || ' on ' ||
          public.register_day(v_d) || ' · keyed in by ' || me.name);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.quotation_offer(p_id uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_q public.quotations;
  v_l jsonb;
  v_ids uuid[] := '{}';
  v_id uuid;
begin
  if me.id is null or not (public.allowed('clients.quotes', 'work') and public.allowed('clients.services', 'work')
                           and public.allowed('clients.documents', 'work')) then return jsonb_build_object('error', 'denied'); end if;
  select * into v_q from public.quotations where id = p_id for update;
  if v_q.id is null or v_q.removed_at is not null or not public.client_scope_ok('client', v_q.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- A draft goes nowhere until it is confirmed (QUOTATIONS CONFIRMED, 2026-11-26).
  if v_q.confirmed_at is null then return jsonb_build_object('error', 'not-confirmed'); end if;
  if v_q.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  select coalesce(array_agg(s.id order by s.created_at), '{}') into v_ids
    from public.client_services s where s.quotation_id = v_q.id and s.archived_at is null;
  if array_length(v_ids, 1) is not null then return jsonb_build_object('ok', true, 'ids', to_jsonb(v_ids), 'again', true); end if;
  if v_q.valid_until < (now() at time zone public.agency_tz())::date then return jsonb_build_object('error', 'expired'); end if;
  for v_l in select * from jsonb_array_elements(v_q.lines) loop
    insert into public.client_services (client_id, service_slug, label, qty, rate, unit, state, note,
                                        tenure, term_adjust, term_pct, detail, quotation_id, tax_code)
    values (v_q.client_id,
            case when exists (select 1 from public.services s where s.slug = v_l->>'slug') then v_l->>'slug' end,
            public.quote_line_label(v_q.totals, v_l), (v_l->>'qty')::numeric, (v_l->>'rate')::numeric,
            case when v_l->>'basis' = 'month' then 'Per month' else 'One-time' end, 'quoted',
            'Quotation ' || v_q.ref,
            case when v_l->>'basis' = 'month' then coalesce((v_l->>'months')::int, (v_q.totals->>'term')::int) else 1 end,
            v_l->>'basis' = 'month', case when v_l->>'basis' = 'month' then (v_q.totals->>'term_pct')::numeric else 0 end,
            nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(v_l->'detail', '[]'::jsonb))), E'\n'), ''),
            v_q.id, nullif(v_l->>'tax_code', ''))
    returning id into v_id;
    v_ids := v_ids || v_id;
  end loop;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', v_q.brand, v_q.ref || ' · ' || array_length(v_ids, 1) || ' lines To quote for the Letter of Offer');
  return jsonb_build_object('ok', true, 'ids', to_jsonb(v_ids));
end $$;

create or replace function public.id_formats_list()
returns jsonb language sql stable security definer set search_path = public as $$
  select case when public.is_team() then coalesce(jsonb_agg(jsonb_build_object(
           'kind', f.kind, 'prefix', f.prefix, 'width', f.width,
           'next', case when f.kind = 'trip'
                        then coalesce((select m.last from public.outstation_ref_months m
                                        where m.month = to_char(now() at time zone public.agency_tz(), 'YYYYMM')), 0) + 1
                        else f.next_no end,
           'pattern', f.pattern)
           order by array_position(array['creator', 'campaign', 'job', 'trip', 'request', 'revision'], f.kind)), '[]'::jsonb)
         else '[]'::jsonb end
    from public.id_formats f
$$;

create or replace function public.hiring_interview_held(p_interview uuid, p_decide_by timestamptz)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  i public.hiring_interviews;
  c public.hiring_candidates;
  v_role text;
  v_at timestamptz;
begin
  select * into i from public.hiring_interviews where id = p_interview for update;
  if i.id is null then return jsonb_build_object('error', 'not-found'); end if;
  v_role := public.hiring_role(i.candidate_id);
  if v_role is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_role not in ('admin', 'owner') then return jsonb_build_object('error', 'denied'); end if;
  select * into c from public.hiring_candidates where id = i.candidate_id for update;
  if i.held_at is not null then return jsonb_build_object('ok', true, 'same', true, 'decide_by', c.decide_by); end if;
  -- A missed interview is never later completed (INTERVIEW MISSED, 2026-11-26).
  if i.state = 'missed' then return jsonb_build_object('error', 'missed'); end if;
  if i.state <> 'confirmed' or i.picked is null then return jsonb_build_object('error', 'not-confirmed'); end if;
  if c.outcome is not null or c.stage <> 'interview' then return jsonb_build_object('error', 'decided'); end if;
  if i.slots[i.picked] > now() then return jsonb_build_object('error', 'not-yet'); end if;
  v_at := coalesce(p_decide_by, public.hiring_decide_by_at(now(), null));
  if v_at <= now() then return jsonb_build_object('error', 'past'); end if;
  if v_at > public.hiring_decide_by_at(now(), 30) then return jsonb_build_object('error', 'too-far'); end if;
  if not public.is_working_day((v_at at time zone public.agency_tz())::date) then return jsonb_build_object('error', 'not-workday'); end if;
  update public.hiring_interviews set held_at = now(), held_by = me.id, held_mail = null, held_mail_at = null, updated_at = now() where id = i.id;
  update public.hiring_candidates set decide_by = v_at, decide_note = null, decide_soon_at = null, decide_due_at = null, decide_moved_at = null,
    last_step_at = now(), updated_at = now() where id = c.id;
  perform public.hiring_log(c.id, 'candidate.interview', 'Interview completed. The decision is due by ' || public.hiring_when(v_at) || '.');
  return jsonb_build_object('ok', true, 'decide_by', v_at);
end $$;

create or replace function public.hiring_outcome_mail_prepare(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_role text := public.hiring_role(p_id);
  c public.hiring_candidates;
  v_missed uuid;
begin
  if v_role is null or v_role not in ('admin', 'owner') then return jsonb_build_object('error', 'denied'); end if;
  select * into c from public.hiring_candidates where id = p_id;
  if c.removed_at is not null or c.link_key is null then return jsonb_build_object('error', 'not-found'); end if;
  if c.outcome not in ('pool', 'not') then return jsonb_build_object('error', 'no-email'); end if;
  -- Closed at Did not attend: the missed interview's own email (2026-11-26).
  v_missed := public.hiring_closed_missed(c.id);
  return jsonb_build_object('id', c.id, 'kind', case when v_missed is not null then 'missed' else c.outcome end,
    'to', c.email, 'name', c.name, 'position', c.position, 'key', c.link_key,
    'months', coalesce(public.app_setting('hiring_pool_months', (now() at time zone public.agency_tz())::date)::int, 12),
    'when', (select public.hiring_when(m.slots[m.picked]) from public.hiring_interviews m where m.id = v_missed),
    'contact', case when v_missed is not null then public.mail_sender('careers')->>'reply_to' end,
    'sender', me.name, 'system', coalesce(me.system, false));
end $$;

create or replace function public.hiring_outcome_mail_claim()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v jsonb; v_stuck uuid[];
begin
  -- A send still marked going out after 10 minutes never answered: it is
  -- marked not confirmed, filed, and told by the morning check
  -- (RETENTION AND JOBS HELD).
  with stuck as (
    update public.hiring_candidates c set outcome_mail = 'unknown', outcome_mail_at = now()
     where c.outcome_mail = 'sending' and coalesce(c.outcome_mail_at, c.updated_at) < now() - interval '10 minutes'
    returning c.id)
  select coalesce(array_agg(x.id), '{}') into v_stuck from stuck x;
  perform public.hiring_log(x, 'candidate.email', 'Decision sent to the candidate, but its delivery could not be verified.')
    from unnest(v_stuck) x;
  with due as (
    select c.id from public.hiring_candidates c
     where c.outcome_mail = 'queued' and c.outcome_mail_due <= now() and c.outcome in ('pool', 'not')
       and c.removed_at is null and c.link_key is not null
     order by c.outcome_mail_due limit 20 for update skip locked),
  took as (
    update public.hiring_candidates c set outcome_mail = 'sending', outcome_mail_due = null, outcome_mail_at = now() from due where c.id = due.id
    returning c.id, c.outcome, c.email, c.name, c.position, c.link_key)
  -- Closed at Did not attend: the missed interview's own email (2026-11-26).
  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'kind', case when x.mid is not null then 'missed' else t.outcome end,
      'to', t.email, 'name', t.name, 'position', t.position, 'key', t.link_key,
      'months', coalesce(public.app_setting('hiring_pool_months', (now() at time zone public.agency_tz())::date)::int, 12),
      'when', (select public.hiring_when(m.slots[m.picked]) from public.hiring_interviews m where m.id = x.mid),
      'contact', case when x.mid is not null then public.mail_sender('careers')->>'reply_to' end,
      'system', true)), '[]'::jsonb) into v
    from took t cross join lateral (select public.hiring_closed_missed(t.id) as mid) x;
  return v;
end $$;

create or replace function public.careers_read(p_key text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_contact text := public.mail_sender('careers')->>'reply_to';
  c public.hiring_candidates;
  i public.hiring_interviews;
  m public.hiring_interviews;
  v_state text;
  v_missed jsonb;
  v_days int := coalesce(public.app_setting('hiring_link_days', (now() at time zone public.agency_tz())::date)::int, 30);
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found', 'contact', v_contact); end if;
  select * into c from public.hiring_candidates where link_key = p_key and removed_at is null;
  if c.id is null then return jsonb_build_object('error', 'not_found', 'contact', v_contact); end if;
  if c.last_step_at + make_interval(days => v_days) <= now() and not (c.stage = 'pool' and c.pool_consent = 'yes') then
    return jsonb_build_object('error', 'expired', 'contact', v_contact);
  end if;
  select * into i from public.hiring_interviews where candidate_id = c.id and state <> 'replaced'
   order by invited_at desc limit 1;
  v_state := case when i.id is null then null else public.hiring_interview_state(i) end;
  /* Interview missed (2026-11-26): its time, while no later interview has
     been confirmed and the candidate is still in the running, or where it
     closed the application. */
  select * into m from public.hiring_interviews where candidate_id = c.id and state = 'missed'
   order by invited_at desc limit 1;
  v_missed := case when m.id is not null
      and not exists (select 1 from public.hiring_interviews j where j.candidate_id = c.id and j.invited_at > m.invited_at and j.state = 'confirmed')
      and ((c.stage in ('new', 'invited', 'interview') and c.outcome is null) or public.hiring_closed_missed(c.id) = m.id)
    then jsonb_strip_nulls(jsonb_build_object('at', m.slots[m.picked], 'closed', case when c.outcome = 'not' then true end)) end;
  return jsonb_strip_nulls(jsonb_build_object('missed', v_missed)) || jsonb_build_object('ok', true, 'contact', v_contact, 'name', c.name, 'position', c.position, 'stage',
    case when c.stage = 'new' or (c.stage = 'pool' and c.outcome is null) then 'received' else c.stage end, 'received_at', c.created_at,
    'request_ref', c.request_ref,
    'pool_declined', case when c.outcome = 'pool' and c.pool_consent = 'no' then true end,
    'pool', case when c.stage = 'pool' and c.outcome = 'pool' then jsonb_strip_nulls(jsonb_build_object('consent', c.pool_consent,
      'until', c.pool_until, 'months', coalesce(public.app_setting('hiring_pool_months', (now() at time zone public.agency_tz())::date)::int, 12))) end,
    'interview', case when i.id is null or c.stage in ('pool', 'closed') or i.state = 'missed' then null
      /* Cancelled: the state alone, never its time or link (2026-11-20). */
      when i.state = 'cancelled' then case when c.stage in ('new', 'invited', 'interview') and c.outcome is null
        then jsonb_build_object('state', 'cancelled') end
      /* A time chosen, not yet confirmed: the time, its length and online or
         at the office alone, never the note or a link (2026-11-22). */
      when v_state = 'picked' then jsonb_strip_nulls(jsonb_build_object('state', v_state, 'minutes', i.minutes, 'mode', i.mode,
        'at', i.slots[i.picked]))
      else jsonb_strip_nulls(jsonb_build_object(
      'state', v_state, 'slots', case when v_state = 'invited' then to_jsonb(i.slots) end, 'minutes', i.minutes,
      'mode', i.mode, 'note', i.note, 'at', case when i.picked is not null then i.slots[i.picked] end,
      'reply_by', case when v_state = 'invited' then i.reply_by end,
      'link', case when i.state = 'confirmed' and i.held_at is null then i.meeting_link end,
      /* Moved by the team (2026-11-22): the time it held before, while the
         interview is confirmed and not yet held. */
      'was', case when i.state = 'confirmed' and i.held_at is null then i.moved_from end,
      'held', case when i.held_at is not null then true end,
      'decide_by', case when i.held_at is not null and c.outcome is null then c.decide_by end,
      /* Past it with no decision: the careers mailbox to contact (2026-11-20). */
      'contact', case when i.held_at is not null and c.outcome is null and c.decide_by <= now() then v_contact end)) end,
    'docs', case when c.stage in ('offer', 'hired') then coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id', d.id, 'kind', d.kind,
        'serial', d.serial, 'state', case when d.state = 'sent' and d.reply_by <= now() then 'expired' else d.state end,
        'sent_at', d.sent_at, 'reply_by', d.reply_by, 'signed_at', d.signed_at)) order by d.sent_at)
      from public.hiring_docs d where d.candidate_id = c.id and d.state in ('sent', 'signed', 'confirmed', 'declined')), '[]'::jsonb) end);
end $$;

create or replace function public.quote_details_state(p public.quotations)
returns text
language sql stable security definer set search_path = public as $$
  select case
    when p.details_asked_at is null then 'none'
    when p.details_at is not null then 'received'
    when now() > p.details_due + make_interval(days => coalesce(public.app_setting('quote_details_close_days',
           (p.details_due at time zone public.agency_tz())::date), 7)::int) then 'closed'
    when now() > p.details_due then 'late'
    else 'asked' end
$$;

create or replace function public.quote_details_submit(p_key text, p_answers jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  w   public.quotations;
  q   public.quotations;
  v_f text[];
  v   jsonb;
  v_ds text;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not-found'); end if;
  if public.page_covered('quote') then return jsonb_build_object('error', 'unavailable'); end if;
  select * into w from public.quotations x where x.access_key = p_key and x.removed_at is null;
  if w.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into q from public.quotations x where x.id = public.quote_shown(w.id) for update;
  if q.released_at is not null then return jsonb_build_object('error', 'sent'); end if;
  v_ds := public.quote_details_state(q);
  if v_ds = 'received' then return jsonb_build_object('error', 'received'); end if;
  if q.status = 'not_proceeding' or v_ds not in ('asked', 'late') then return jsonb_build_object('error', 'closed'); end if;
  v_f := array(select jsonb_array_elements_text(q.details_ask->'fields'));
  v := public.quote_intake_check(coalesce(p_answers, '{}'::jsonb), v_f);
  if v ? 'error' then return v; end if;
  update public.quotations x
     set details = v, details_at = now(), contact = x.contact || v, reply_due = public.quote_reply_by(now())
   where x.id = q.id
  returning * into q;
  perform public.quote_details_apply(q.id, v);
  insert into public.activity_log (actor, action, subject, detail)
  values ('Quotation portal', 'client.quotation', q.brand, q.ref || ' · Details received from ' ||
          coalesce(public.contact_named(q.contact->>'salutation', q.contact->>'name'), 'the prospect'));
  perform public.quote_tell(q.client_id, 'quote.details', 'Details received · ' || coalesce(q.contact->>'brand', q.brand),
    q.ref || ' · ' || coalesce(q.contact->>'name', '') || ' · Send by ' ||
      public.quote_day_word((q.reply_due at time zone public.agency_tz())::date, false),
    q.id::text || ':' || extract(epoch from q.details_at)::bigint::text);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.quote_website_create(p_sel jsonb, p_contact jsonb, p_idem text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_name  text := btrim(regexp_replace(coalesce(p_contact->>'name', ''), '\s+', ' ', 'g'));
  v_email text := lower(btrim(coalesce(p_contact->>'email', '')));
  v_wa    text := public.quote_website_number(p_contact->>'whatsapp');
  v_brand text := btrim(regexp_replace(coalesce(p_contact->>'brand', ''), '\s+', ' ', 'g'));
  v_ind   text;
  v_lang  text := case when p_contact->>'lang' = 'zh' then 'zh' else 'en' end;
  v_sal   text := nullif(btrim(coalesce(p_contact->>'salutation', '')), '');
  v_start text;
  v_on    date;
  v_reg   jsonb;
  v_cm    text := nullif(btrim(replace(coalesce(p_contact->>'comments', ''), E'\r', '')), '');
  v_key   text;
  v_match jsonb;
  v_hold  boolean := false;
  v_col   text;
  v_lead  public.clients;
  v_idem  text := nullif(btrim(coalesce(p_idem, '')), '');
  v_sel   jsonb;
  v_q     public.quotations;
  v_c     public.clients;
  v_base  text;
  v_slug  text;
  v_n     int := 1;
  v_r     jsonb;
  v_new   boolean := false;
  v_known boolean := false;
  v_hits  int;
  v_pic   uuid;
  v_chk   jsonb;
begin
  if v_idem is null or length(v_idem) > 80 then return jsonb_build_object('error', 'bad-request'); end if;
  -- The quotation portal covered (Page availability) makes nothing.
  if public.page_covered('quote') then return jsonb_build_object('error', 'unavailable'); end if;
  select * into v_q from public.quotations q
   where q.idem = v_idem and q.source = 'website' and lower(q.contact->>'email') = v_email;
  if v_q.id is not null then
    return jsonb_build_object('ok', true, 'ref', v_q.ref, 'key', v_q.access_key, 'again', true);
  end if;
  if length(v_name) < 2 or length(v_name) > 80 then return jsonb_build_object('error', 'bad-name'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 160 then return jsonb_build_object('error', 'bad-email'); end if;
  if v_wa !~ '^(60(1[0-9]{8,9}|7[0-9]{7,8})|65[0-9]{8})$' then return jsonb_build_object('error', 'bad-whatsapp'); end if;
  if length(v_brand) < 2 or length(v_brand) > 120 then return jsonb_build_object('error', 'bad-brand'); end if;
  -- A name or brand is never a web address: both go into the WhatsApp the
  -- prospect is sent from ADspace's number (2026-10-26, audit).
  if v_name ~* public.quote_link_like() then return jsonb_build_object('error', 'bad-name'); end if;
  if v_brand ~* public.quote_link_like() then return jsonb_build_object('error', 'bad-brand'); end if;
  if v_sal is not null and v_sal not in ('Mr', 'Ms', 'Mrs', 'Mdm', 'Dr', 'Prof', 'Dato''', 'Datin', 'Datuk',
      'Dato'' Sri', 'Datin Sri', 'Tan Sri', 'Puan Sri', 'Tun', 'Tuan', 'Puan', 'Encik', 'Cik') then
    return jsonb_build_object('error', 'bad-salutation');
  end if;
  -- The intake (QUOTE INTAKE, 2026-11-27): Registering as, the Business
  -- Registration No. and registered name, the industry, a website or a
  -- social media account and Planned commencement, each required, checked
  -- as details sent later are (`quote_intake_check`).
  v_reg := public.quote_intake_check(p_contact, array['registration', 'industry', 'online', 'commence']);
  if v_reg ? 'error' then return v_reg; end if;
  v_ind := v_reg->>'industry';
  v_start := v_reg->>'commence';
  v_on := (v_reg->>'commence_on')::date;
  if v_cm is not null and length(v_cm) > 1000 then return jsonb_build_object('error', 'bad-comments'); end if;
  if coalesce((p_contact->>'consent')::boolean, false) is not true then return jsonb_build_object('error', 'consent'); end if;
  -- What changed since the page read the card, as the preflight asks it
  -- (QUOTATION PREFLIGHT, 2026-11-25): nothing is written while any stands.
  v_chk := public.quote_web_check(p_sel, case when jsonb_typeof(p_sel) = 'object' then p_sel->>'seen' end);
  if v_chk->'changes' @> '[{"kind": "off"}]'::jsonb then return jsonb_build_object('error', 'no-card'); end if;
  if jsonb_array_length(v_chk->'changes') > 0 then
    return jsonb_build_object('error', 'changed', 'changes', v_chk->'changes');
  end if;
  -- What the price reads, and nothing else (QUOTE WEBSITE CHOICES, 2026-11-24).
  v_sel := public.quote_website_sel(p_sel, coalesce(public.quote_card()->'snapshot', '{}'::jsonb));
  if v_sel ? 'error' then return v_sel; end if;

  -- Two posts at once are counted one after the other.
  perform pg_advisory_xact_lock(hashtextextended('quote-web:' || least(v_email, v_wa), 0));
  perform pg_advisory_xact_lock(hashtextextended('quote-web:' || greatest(v_email, v_wa), 0));
  if (select count(*) from public.quotations q
       where q.source = 'website' and q.issued_at > now() - interval '1 day'
         and (lower(q.contact->>'email') = v_email or q.contact->>'whatsapp' = '+' || v_wa)) >= 5 then
    return jsonb_build_object('error', 'limit');
  end if;

  -- Who this is (QUOTE INTAKE, 2026-11-27; never said on the page): the
  -- Business Registration No. first, then a contact holding both the email
  -- and the number. The same brand is that record (a lead while Lead,
  -- Contacted or Proposal sent, else the client served); another brand is
  -- a new lead the team sees as Matches existing client. The registration
  -- typed for a record kept is held for Use details, never written over
  -- Billing. Never the company or brand name alone, and never a guess.
  v_key := public.quote_brand_key(v_brand);
  select c.* into v_c from public.clients c
    join public.client_entities ce on ce.client_id = c.id
    join public.billing_entities e on e.id = ce.entity_id
   where regexp_replace(coalesce(e.company_no, ''), '\D', '', 'g') = v_reg->>'brn'
     and public.quote_brand_key(c.name) = v_key
   order by (c.stage in ('lead', 'contacted', 'proposal')) desc, c.created_at desc limit 1;
  if v_c.id is null then
    select jsonb_build_object('client', c.id, 'name', c.name, 'entity', e.id, 'by', 'brn') into v_match
      from public.clients c
      join public.client_entities ce on ce.client_id = c.id
      join public.billing_entities e on e.id = ce.entity_id
     where regexp_replace(coalesce(e.company_no, ''), '\D', '', 'g') = v_reg->>'brn'
     order by (c.stage = 'active') desc, ce.is_main desc, c.created_at desc limit 1;
  end if;
  -- A number some entity holds is never written to a new lead's Billing.
  v_hold := v_c.id is not null or v_match is not null
    or exists (select 1 from public.billing_entities e where regexp_replace(coalesce(e.company_no, ''), '\D', '', 'g') = v_reg->>'brn');
  if v_c.id is null and v_match is null then
    -- A lead this person already is (the same contact holds both).
    select c.* into v_lead from public.clients c
      join public.client_contacts k on k.client_id = c.id
     where c.stage in ('lead', 'contacted', 'proposal')
       and k.archived_at is null
       and lower(k.email) = v_email
       and public.quote_website_number(k.whatsapp) = v_wa
     order by c.created_at desc limit 1;
    if v_lead.id is not null then
      if public.quote_brand_key(v_lead.name) = v_key then v_c := v_lead;
      else v_match := jsonb_build_object('client', v_lead.id, 'name', v_lead.name, 'by', 'contact');
      end if;
    end if;
  end if;
  -- Else a client the team already serves, at any other stage (Active,
  -- Paused, Past; WEBSITE QUOTATION FINDS ITS CLIENT, 2026-11-25): one of
  -- its contacts holds both; two such clients pick neither.
  if v_c.id is null and v_match is null then
    select count(distinct c.id) into v_hits from public.clients c
      join public.client_contacts k on k.client_id = c.id
     where c.stage not in ('lead', 'contacted', 'proposal')
       and k.archived_at is null
       and lower(k.email) = v_email
       and public.quote_website_number(k.whatsapp) = v_wa;
    if v_hits = 1 then
      select c.* into v_lead from public.clients c
        join public.client_contacts k on k.client_id = c.id
       where c.stage not in ('lead', 'contacted', 'proposal')
         and k.archived_at is null
         and lower(k.email) = v_email
         and public.quote_website_number(k.whatsapp) = v_wa
       limit 1;
      if public.quote_brand_key(v_lead.name) = v_key then v_c := v_lead;
      else v_match := jsonb_build_object('client', v_lead.id, 'name', v_lead.name, 'by', 'contact');
      end if;
    end if;
  end if;
  v_known := v_c.id is not null and v_c.stage not in ('lead', 'contacted', 'proposal');
  if v_c.id is null then
    v_base := btrim(regexp_replace(lower(v_brand), '[^a-z0-9]+', '-', 'g'), '-');
    if v_base = '' then v_base := 'client'; end if;
    v_slug := v_base;
    while exists (select 1 from public.clients c where lower(c.slug) = v_slug) loop
      v_n := v_n + 1; v_slug := v_base || '-' || v_n;
    end loop;
    v_col := case v_reg->>'platform' when 'instagram' then 'ig' when 'facebook' then 'fb'
               when 'tiktok' then 'tiktok' when 'xhs' then 'xhs' end;
    insert into public.clients (name, access_token, stage, industry, source, market, slug, deal_note, commence,
                                website, handle_ig, handle_fb, handle_tiktok, handle_xhs)
    values (v_brand, public.new_link_key(), 'lead', v_ind, 'website',
            case when v_wa like '65%' then 'SG' else 'MY' end, v_slug,
            coalesce(v_cm, 'Quotation requested on the website.'), v_start, v_reg->>'website',
            case when v_col = 'ig' then v_reg->>'handle' end, case when v_col = 'fb' then v_reg->>'handle' end,
            case when v_col = 'tiktok' then v_reg->>'handle' end, case when v_col = 'xhs' then v_reg->>'handle' end)
    returning * into v_c;
    -- A new lead's Billing takes the registration typed, unless some
    -- entity already holds the number (then held for Use details below).
    if not v_hold then
      update public.clients x set legal_name = v_reg->>'legal', company_no = v_reg->>'brn' where x.id = v_c.id;
    end if;
    insert into public.client_contacts (client_id, salutation, name, email, whatsapp, lang, is_primary)
    values (v_c.id, v_sal, v_name, v_email, '+' || v_wa, v_lang, true);
    insert into public.activity_log (actor, action, subject, detail)
    values ('Quotation portal', 'client.added', v_c.name, 'Website · ' || coalesce(v_sal || ' ', '') || v_name);
    v_new := true;
  end if;

  v_r := public.quotation_make(v_c.id, v_sel, v_idem, 'website', null,
    jsonb_strip_nulls(jsonb_build_object('salutation', v_sal, 'name', v_name, 'email', v_email,
      'whatsapp', '+' || v_wa, 'lang', v_lang, 'brand', v_brand) || v_reg ||
      jsonb_strip_nulls(jsonb_build_object('comments', v_cm))));
  if v_r ? 'error' then
    if v_new then raise exception using message = 'quote:' || (v_r->>'error'); end if;
    return v_r;
  end if;
  select * into v_q from public.quotations where id = (v_r->>'id')::uuid;
  -- The version checked is the version priced: a card published between
  -- the two undoes the whole request.
  if v_q.version is distinct from v_chk->>'version' then raise exception using message = 'quote:changed'; end if;
  -- A lead asking again says when it plans to start now, once its
  -- quotation is made (a refused one changes nothing). A client already
  -- served keeps its record as the team keeps it.
  if not v_new and not v_known and v_start is not null and v_c.commence is distinct from v_start then
    update public.clients set commence = v_start where id = v_c.id;
    insert into public.activity_log (actor, action, subject, detail)
    values ('Quotation portal', 'client.edited', v_c.name, 'Planned commencement: ' ||
      coalesce(public.quote_commence_word(v_c.commence), 'not set') || ' → ' || public.quote_commence_word(v_start));
  end if;
  -- The price waits for the team (the user, 2026-10-29: "the price
  -- shouldnt send out straight"): the quotation is owed a reply by working
  -- days, the team is told to review it, and the prospect is sent nothing
  -- until a colleague sends it (`quotation_send`).
  update public.quotations set reply_due = public.quote_reply_by(now()), commence_on = v_on, match = v_match where id = v_q.id
   returning * into v_q;
  if v_hold then perform public.quote_reg_hold(v_c.id, v_q.id, v_reg); end if;
  if v_known then
    -- A client already served: its person in charge is told, else the
    -- managers who hold leads at Full Access (as `quote_proceed_remind`).
    select m.id into v_pic from public.team_members m
     where m.id = v_c.owner_id and m.active and not coalesce(m.system, false) and m.removed_at is null;
    insert into public.ops_notifications (team_member_id, kind, title, body, client_id, dedupe_key)
    select m.id, 'quote.website', 'Quotation to review · ' || v_c.name,
    v_q.ref || ' · ' || coalesce('RM ' ||
      to_char((v_q.totals->'month'->>'incl')::numeric, 'FM999,999,990.00') || ' per month incl. SST', 'one-time') || ' · ' || v_name
      || coalesce(' · Preferred start date ' || public.register_day(v_on),
                  ' · Starts ' || lower(public.quote_commence_word(v_start)), '')
      || coalesce(' · Matches existing client ' || (v_match->>'name'), '')
      || ' · Send by ' || public.register_day((v_q.reply_due at time zone public.agency_tz())::date)
      || ' (' || trim(to_char(v_q.reply_due at time zone public.agency_tz(), 'FMDay')) || '), ' ||
      lower(to_char(v_q.reply_due at time zone public.agency_tz(), 'FMHH12:MIam')),
           v_c.id, 'quote.website:' || v_q.id || ':' || m.id
      from public.team_members m
     where m.active and not coalesce(m.system, false)
       and (m.id = v_pic
            or (v_pic is null and (m.is_admin or m.role = 'admin'
                or public.level_rank(coalesce(m.access ->> 'clients.leads', m.access ->> 'clients')) >= 3)))
    on conflict (dedupe_key) do nothing;
  else
    perform public.quote_tell(v_c.id, 'quote.website', 'Quotation to review · ' || v_c.name,
      v_q.ref || ' · ' || coalesce('RM ' ||
        to_char((v_q.totals->'month'->>'incl')::numeric, 'FM999,999,990.00') || ' per month incl. SST', 'one-time') || ' · ' || v_name
        || coalesce(' · Preferred start date ' || public.register_day(v_on),
                    ' · Starts ' || lower(public.quote_commence_word(v_start)), '')
        || coalesce(' · Matches existing client ' || (v_match->>'name'), '')
        || ' · Send by ' || public.register_day((v_q.reply_due at time zone public.agency_tz())::date)
        || ' (' || trim(to_char(v_q.reply_due at time zone public.agency_tz(), 'FMDay')) || '), ' ||
        lower(to_char(v_q.reply_due at time zone public.agency_tz(), 'FMHH12:MIam')),
      v_q.id::text);
  end if;
  return jsonb_build_object('ok', true, 'ref', v_q.ref, 'key', v_q.access_key);
exception when raise_exception then
  if sqlerrm = 'quote:changed' then
    return jsonb_build_object('error', 'changed', 'changes', jsonb_build_array(jsonb_build_object('kind', 'version')));
  end if;
  if sqlerrm like 'quote:%' then return jsonb_build_object('error', substr(sqlerrm, 7)); end if;
  raise;
end $$;

create or replace function public.app_settings_read()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_team boolean := public.is_team();
begin
  return jsonb_build_object(
    'today', (now() at time zone public.agency_tz())::date,
    'admin', v_team and public.allowed('admin'),
    'settings', coalesce((select jsonb_agg(jsonb_build_object('key', s.key, 'from', s.from_date, 'value', s.value,
                   'by', case when v_team then (select t.name from public.team_members t where t.id = s.set_by) end,
                   'at', case when v_team then s.set_at end)
                 order by s.key, s.from_date) from public.app_settings s
                where v_team or s.key in ('sst_pct', 'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24', 'fx_sgd', 'ad_prepay_pct', 'ad_credit_fee_pct')),
                '[]'::jsonb));
end $$;

create or replace function public.quotation_edit(p_id uuid, p_sel jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_q public.quotations;
  v_c public.clients;
  v_on date := public.doc_day_of(p_sel->>'date');
  v_card jsonb;
  v_ref text;
  v_was_ref text;
  v_p jsonb;
  v_fx numeric;
  v_now timestamptz := now();
  v_days int;
  v_v jsonb;
  v_sel jsonb;
  v_was numeric;
  v_is numeric;
  v_cur text;
  v_n int;
  v_doc text;
  v_x jsonb;
  v_b jsonb;
begin
  if me.id is null or not public.allowed('clients.quotes', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if jsonb_typeof(p_sel) is distinct from 'object' then return jsonb_build_object('error', 'bad-request'); end if;
  if v_on is not null and not public.doc_day_ok(v_on) then return jsonb_build_object('error', 'bad-date'); end if;
  if v_on is not null and v_on <> (v_now at time zone public.agency_tz())::date then
    v_now := (v_on::timestamp + (v_now at time zone public.agency_tz())::time) at time zone public.agency_tz();
  end if;
  v_on := (v_now at time zone public.agency_tz())::date;
  v_card := public.quote_card(v_on, nullif(btrim(coalesce(p_sel->>'card', '')), ''));
  select * into v_q from public.quotations where id = p_id for update;
  if v_q.id is null or not public.client_scope_ok('client', v_q.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if v_q.removed_at is not null then return jsonb_build_object('error', 'removed'); end if;
  if v_q.signed_at is not null or v_q.reviewed_at is not null then return jsonb_build_object('error', 'signed'); end if;
  if v_q.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  if exists (select 1 from public.quotations x where x.replaces = v_q.id and x.removed_at is null) then
    return jsonb_build_object('error', 'revised');
  end if;
  if v_q.sent_out_at is not null or v_q.released_at is not null then return jsonb_build_object('error', 'sent'); end if;
  -- A quotation a letter or service lines came from keeps its figures
  -- (2026-11-07), as its removal is refused then: Edit makes its revision.
  select count(*) into v_n from public.client_services s where s.quotation_id = v_q.id;
  if v_n > 0 then return jsonb_build_object('error', 'lines', 'count', v_n); end if;
  select d.number into v_doc from public.client_documents d
   where d.lines @> jsonb_build_array(jsonb_build_object('quotation_id', v_q.id::text))
   order by d.created_at limit 1;
  if v_doc is not null then return jsonb_build_object('error', 'letter', 'number', v_doc); end if;
  select * into v_c from public.clients where id = v_q.client_id;
  if v_c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_card is null then return jsonb_build_object('error', 'no-card'); end if;
  v_fx := public.quote_fx(v_c.id, v_on);
  if v_fx = 0 then return jsonb_build_object('error', 'no-fx'); end if;
  -- As the team builds it: a colleague is saving, so their edits, names,
  -- descriptions and its one brand are kept on a website request too
  -- (COLLEAGUE'S SAVE ON A WEBSITE REQUEST, 2026-11-27); the public page
  -- itself never adjusts nor sends brands (quotation_make).
  v_sel := p_sel - 'client' - 'date';
  v_p := public.quote_fx_out(public.quote_compose(public.quote_fx_snap(public.quote_tax_snap(v_card->'snapshot', v_c.id, v_on), v_fx),
           v_sel, true), v_fx);
  if v_p ? 'error' then return v_p; end if;
  v_x := public.quote_extras(case when v_q.source = 'console' then v_sel else '{}'::jsonb end);
  if v_x ? 'error' then return v_x; end if;
  if v_q.source = 'console' then
    v_b := public.quote_client_extras(v_c.id, v_p->'lines', v_sel);
    if v_b ? 'error' then return v_b; end if;
    v_x := v_x || v_b;
  end if;
  if jsonb_typeof(v_p->'lines') is distinct from 'array' or jsonb_array_length(v_p->'lines') = 0 then
    return jsonb_build_object('error', 'nothing-priced');
  end if;
  v_was := coalesce((v_q.totals->'month'->>'incl')::numeric, (v_q.totals->'once'->>'incl')::numeric);
  -- Valid for its own days (Build quote's Valid for), website requests
  -- too, else the Business setting (QUOTATION VALID FOR ITS OWN DAYS).
  v_v := public.quote_extras(jsonb_build_object('valid', v_sel->'valid'));
  if v_v ? 'error' then return v_v; end if;
  v_days := coalesce((v_v->>'valid_days')::int, public.app_setting('quote_valid_days', (v_now at time zone public.agency_tz())::date), 30)::int;
  /* A team's quotation dated into another month takes that month's
     reference (it has not been sent); the one it held is kept, never
     issued again. */
  v_ref := v_q.ref; v_was_ref := v_q.ref;
  if v_q.source = 'console' and v_q.ref !~ ('^ADP/QT' || to_char(v_on, 'YYMM') || '-') then
    -- A draft moved to another month takes that month's draft reference and
    -- spends no number (QUOTATIONS CONFIRMED, 2026-11-26).
    if v_q.confirmed_at is null then
      v_ref := public.quote_draft_ref(v_now);
    else
      v_ref := public.quote_ref(v_q.brand, v_now);
      insert into public.quotation_refs_kept (ref) values (v_q.ref) on conflict do nothing;
    end if;
  end if;
  update public.quotations
     set ref = v_ref, version = v_card->>'version', version_id = (v_card->>'id')::uuid, selection = v_sel,
         lines = v_p->'lines', totals = v_p->'totals' || jsonb_build_object('on_request', v_p->'on_request') || v_x,
         -- A team's quotation is dated when it is made ready; a website one
         -- keeps the day it was asked for (its validity runs from its send).
         issued_at = case when v_q.source = 'console' then v_now else issued_at end,
         -- A website quotation already sent runs from the day it was sent.
         valid_until = case when v_q.source <> 'console' and v_q.released_at is not null
                            then (v_q.released_at at time zone public.agency_tz())::date + v_days
                            else (v_now at time zone public.agency_tz())::date + v_days end
   where id = v_q.id
  returning * into v_q;
  v_is := coalesce((v_q.totals->'month'->>'incl')::numeric, (v_q.totals->'once'->>'incl')::numeric);
  v_cur := case when v_fx is null then 'RM ' else 'S$ ' end;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', v_c.name,
          case when v_ref <> v_was_ref then v_was_ref || ' → ' else '' end || v_q.ref || ' edited · ' ||
          coalesce(v_cur || to_char(v_was, 'FM999,999,990.00'), 'not set') || ' → ' ||
          coalesce(v_cur || to_char(v_is, 'FM999,999,990.00'), 'not set') ||
          ' · Rate Card v.' || v_q.version ||
          case coalesce((v_p->>'adjusted')::int, 0) when 0 then '' when 1 then ' · 1 line changed'
               else ' · ' || (v_p->>'adjusted') || ' lines changed' end);
  return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref);
end $$;

create or replace function public.quotation_release(p_id uuid, p_whatsapp boolean)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  q  public.quotations;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_days int;
  v_wa text;
  v_name text;
  v_queued boolean := false;
  v_on boolean;
begin
  if me.id is null or not public.allowed('clients.quotes', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_whatsapp and not public.send_ok('whatsapp') then return jsonb_build_object('error', 'send-off'); end if;
  select * into q from public.quotations x where x.id = p_id for update;
  if q.id is null or q.removed_at is not null or not public.client_scope_ok('client', q.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if q.source <> 'website' then return jsonb_build_object('error', 'bad-quotation'); end if;
  if q.released_at is not null then return jsonb_build_object('ok', true, 'again', true, 'valid_until', q.valid_until); end if;
  if q.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  if exists (select 1 from public.quotations x where x.replaces = q.id and x.removed_at is null) then
    return jsonb_build_object('error', 'revised');
  end if;
  -- A prospect marked Do not contact is not messaged (audit 2026-10-30);
  -- publishing sends them nothing.
  if coalesce(p_whatsapp, true) and q.no_contact_at is not null then return jsonb_build_object('error', 'no-contact'); end if;
  -- The day's WhatsApp messages for website quotations are held to
  -- `quote_wa_day` (counted under one lock); at the limit nothing changes and
  -- Publish still shows the rates.
  if coalesce(p_whatsapp, true) and not public.quote_wa_allowed(q.id) then
    return jsonb_build_object('error', 'wa-limit', 'cap', coalesce(public.app_setting('quote_wa_day', v_today), 30));
  end if;
  -- Valid for its own days (Build quote's Valid for), else the Business
  -- setting, from the day it is shown, as the prospect first sees it.
  v_days := coalesce((public.quote_extras(jsonb_build_object('valid', q.selection->'valid'))->>'valid_days')::int,
                     public.app_setting('quote_valid_days', v_today), 30)::int;
  -- Send quotation is a request's confirmation: it takes its reference
  -- now (QUOTATIONS CONFIRMED, 2026-11-26); one confirmed before keeps its.
  update public.quotations
     set released_at = now(), released_by = me.name, valid_until = v_today + v_days,
         ref = case when confirmed_at is null then public.quote_ref(brand, now()) else ref end,
         confirmed_at = coalesce(confirmed_at, now()), confirmed_by = coalesce(confirmed_by, me.name)
   where id = q.id returning * into q;
  if coalesce(p_whatsapp, true) then
    v_wa := public.quote_website_number(q.contact->>'whatsapp');
    v_name := coalesce(nullif(btrim(q.contact->>'name'), ''), q.brand);
    -- Sent on WhatsApp only where its template is on: wa_enqueue says nothing
    -- when it is off (audit 2026-10-30).
    select exists (select 1 from public.wa_templates x where x.purpose = 'quote_ready' and x.active and x.name <> '') into v_on;
    begin
      if v_on and v_wa ~ '^(60|65)[0-9]{8,10}$' then
        perform public.wa_enqueue('quote_ready', v_wa, v_name,
          jsonb_build_array(public.contact_greeting(q.contact->>'salutation', v_name),
                            coalesce(q.contact->>'brand', q.brand), q.ref),
          'quotation', q.id, q.client_id, q.access_key);
        v_queued := true;
      end if;
    exception when others then v_queued := false;
    end;
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', q.brand,
          q.ref || case when coalesce(p_whatsapp, true)
                        then ' sent to the prospect' || case when v_queued then ' on WhatsApp' else '' end
                        else ' published on the quotation link' end ||
          ' · valid until ' || public.register_day(q.valid_until));
  return jsonb_build_object('ok', true, 'valid_until', q.valid_until, 'whatsapp', v_queued);
end $$;

create or replace function public.creator_bill_auto_on()
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.app_setting('creator_bill_on_completed', (now() at time zone public.agency_tz())::date), 0) = 1
$$;

create or replace function public.creator_bill_auto_set(p_on boolean)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me      public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_was   numeric;
  v_to    numeric := case when coalesce(p_on, false) then 1 else 0 end;
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_was := public.app_setting('creator_bill_on_completed', v_today);
  if v_was is not distinct from v_to then return jsonb_build_object('ok', true); end if;
  insert into public.app_settings (key, from_date, value, set_by, set_at)
  values ('creator_bill_on_completed', v_today, v_to, me.id, now())
  on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Settings',
          'Bill creators on Completed: ' || case when v_was = 1 then 'On' else 'Off' end || ' → ' ||
          case when v_to = 1 then 'On' else 'Off' end || ' · from ' || public.register_day(v_today));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.perf_ops_rate(p_member uuid, p_period date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m_from timestamptz := (date_trunc('month', p_period)::date)::timestamp at time zone public.agency_tz();
  m_to   timestamptz := ((date_trunc('month', p_period) + interval '1 month')::date)::timestamp at time zone public.agency_tz();
  today  date := (now() at time zone public.agency_tz())::date;
  p_due integer; p_ok integer; t_reached integer; t_met integer; s_n integer := 0; s_rate numeric;
begin
  if to_regclass('public.ops_tasks') is null then return null; end if;

  select count(*),
         count(*) filter (where t.live_at is not null
                            and (t.live_at at time zone public.agency_tz())::date
                                <= (t.publish_at at time zone public.agency_tz())::date)
    into p_due, p_ok
    from public.ops_tasks t
   where t.publish_at >= m_from and t.publish_at < m_to
     and t.cancelled_at is null
     and (t.live_at is not null or (t.publish_at at time zone public.agency_tz())::date < today)
     and exists (select 1 from public.ops_workflow_stages s
                  where s.workflow_id = t.workflow_id and s.stage_group = 'live')
     and (select a.team_member_id from public.ops_task_assignees a
           where a.task_id = t.id and a.responsibility = 'owner'
           order by a.ended_at nulls first, a.assigned_at desc limit 1) = p_member;

  with owned as (
    select t.id, t.workflow_id, t.current_final_due_at as due,
           coalesce(t.completed_at, t.delivered_at) as ended,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           (select min(s.position) from public.ops_workflow_stages s
             where s.workflow_id = t.workflow_id and s.stage_group = 'client_review') as review_at,
           (select min(s.position) from public.ops_workflow_stages s
             where s.workflow_id = t.workflow_id and s.stage_group = 'internal_review') as first_review_at
      from public.ops_tasks t
     where t.cancelled_at is null
       and (t.current_final_due_at is not null or t.priority_level in (1, 2, 4))
       and (select a.team_member_id from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc limit 1) = p_member
  ),
  /* When each deadline was met: the first move to its stage or beyond, never
     into On hold, Blocked or Cancelled. The due date's is client review, else
     the finish; a priority's is client review, else the first review. */
  marks as (
    select o.*,
           case when o.review_at is null then o.ended
                else coalesce((select min(e.created_at)
                                 from public.ops_task_events e
                                 join public.ops_workflow_stages w
                                   on w.workflow_id = o.workflow_id and w.key = e.to_value ->> 'stage_key'
                                where e.task_id = o.id and e.event_type = 'stage_changed'
                                  and w.position >= o.review_at
                                  and w.stage_group not in ('kiv', 'blocked', 'cancelled')), o.ended) end as due_met,
           coalesce((select min(e.created_at)
                       from public.ops_task_events e
                       join public.ops_workflow_stages w
                         on w.workflow_id = o.workflow_id and w.key = e.to_value ->> 'stage_key'
                      where e.task_id = o.id and e.event_type = 'stage_changed'
                        and w.position >= coalesce(o.review_at, o.first_review_at)
                        and w.stage_group not in ('kiv', 'blocked', 'cancelled')), o.ended) as prio_met
      from owned o
  ),
  /* A task is counted in the month it met the last of its deadlines. */
  settled as (
    select m.*,
           case when (m.due is null or m.due_met is not null)
                 and (m.prio_by is null or m.prio_met is not null)
                then greatest(case when m.due is not null then m.due_met end,
                              case when m.prio_by is not null then m.prio_met end) end as at
      from marks m
  )
  select count(*),
         count(*) filter (where (s.due is null
                                 or (s.due_met at time zone public.agency_tz())::date
                                    <= (s.due at time zone public.agency_tz())::date)
                            and (s.prio_by is null or s.prio_met <= s.prio_by))
    into t_reached, t_met
    from settled s
   where s.at >= m_from and s.at < m_to;

  /* Client satisfaction (FEEDBACK SATISFACTION RATE): the account manager
     question of each answer submitted in the month (MYT) naming this
     colleague, each as a percentage of its own scale's maximum, then
     averaged; a month with no answer has no rate, never 0. Withheld where
     the reader may not see the manager's score. */
  if public.feedback_sees_manager(p_member) then
    select count(*), round(avg(r.manager_score::numeric * 100 / q.scale_max), 1)
      into s_n, s_rate
      from public.feedback_responses r
      join public.feedback_questions q on q.kind = r.kind and q.about_manager and q.type = 'scale' and q.scale_max > 0
     where r.manager_id = p_member and r.manager_score is not null
       and r.submitted_at >= m_from and r.submitted_at < m_to;
  end if;

  return jsonb_build_object(
    'posting',  jsonb_build_object('due', p_due, 'on_time', p_ok),
    'timeline', jsonb_build_object('reached', t_reached, 'met', t_met))
    || case when s_n > 0 then jsonb_build_object('satisfaction', jsonb_build_object('answers', s_n, 'rate', s_rate)) else '{}'::jsonb end;
end $$;

create or replace function public.quotation_confirm(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  n public.quotations;
  o public.quotations;
  v_by text;
  v_ref text;
begin
  if me.id is null or not public.allowed('clients.quotes', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into n from public.quotations x where x.id = p_id for update;
  if n.id is null or n.removed_at is not null or not public.client_scope_ok('client', n.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if n.confirmed_at is not null then return jsonb_build_object('ok', true, 'same', true, 'ref', n.ref); end if;
  if n.source <> 'console' then return jsonb_build_object('error', 'website'); end if;
  if n.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  -- A draft past its valid-until date is never confirmed: its link would
  -- open on "expired" (review J6). Edit sets a new date first.
  if n.valid_until < (now() at time zone public.agency_tz())::date then return jsonb_build_object('error', 'draft-expired'); end if;
  if n.revises is not null then
    select * into o from public.quotations x where x.id = n.revises for update;
  end if;
  if o.id is not null and o.removed_at is null then
    if o.signed_at is not null or o.reviewed_at is not null then return jsonb_build_object('error', 'signed'); end if;
    select x.ref into v_by from public.quotations x where x.replaces = o.id and x.removed_at is null and x.id <> n.id limit 1;
    if v_by is not null then return jsonb_build_object('error', 'revised', 'ref', v_by); end if;
    -- A website request revised before it was sent holds no ADP/QT number:
    -- its revision takes a fresh one; else the family's next -Rn.
    v_ref := case when o.confirmed_at is null then public.quote_ref(n.brand, n.issued_at) else public.quote_revision_ref(o.id) end;
    update public.quotations set ref = v_ref, confirmed_at = now(), confirmed_by = me.name, replaces = o.id, revises = null
     where id = n.id returning * into n;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'client.quotation', n.brand, n.ref || ' confirmed · revises ' || o.ref);
  else
    -- What it was to revise is gone: it stands as a quotation of its own.
    v_ref := public.quote_ref(n.brand, n.issued_at);
    update public.quotations set ref = v_ref, confirmed_at = now(), confirmed_by = me.name, revises = null
     where id = n.id returning * into n;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'client.quotation', n.brand, n.ref || ' confirmed');
  end if;
  return jsonb_build_object('ok', true, 'ref', n.ref);
end $$;

create or replace function public.link_hit(p_slug text, p_qr text default null)
returns void
language plpgsql volatile security definer set search_path = public as $$
declare
  v_slug text := lower(btrim(coalesce(p_slug, '')));
  v_code text := lower(btrim(coalesce(p_qr, '')));
  v_day  date := (now() at time zone public.agency_tz())::date;
begin
  if not exists (select 1 from public.links l where l.slug = v_slug and l.active) then return; end if;
  if v_code <> '' and not exists (
       select 1 from public.link_qrs q where q.code = v_code and q.slug = v_slug and q.active) then
    return;
  end if;
  insert into public.link_clicks (slug, code, day, n) values (v_slug, v_code, v_day, 1)
  on conflict (slug, code, day) do update set n = public.link_clicks.n + 1;
  /* Kept three years, as the Activity record. */
  delete from public.link_clicks c where c.slug = v_slug and c.day < (v_day - interval '3 years')::date;
end $$;

create or replace function public.quote_decline(p_key text, p_reason text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  w public.quotations;
  q public.quotations;
  c public.clients;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not-found'); end if;
  if char_length(coalesce(v_reason, '')) > 300 then return jsonb_build_object('error', 'too-long'); end if;
  select * into w from public.quotations x where x.access_key = p_key and x.removed_at is null;
  if w.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into q from public.quotations x where x.id = public.quote_shown(w.id) for update;
  if q.id is null or q.removed_at is not null then return jsonb_build_object('error', 'not-found'); end if;
  if q.declined_at is not null then return jsonb_build_object('ok', true, 'again', true); end if;
  if q.signed_at is not null then return jsonb_build_object('error', 'signed'); end if;
  if q.status = 'not_proceeding' then return jsonb_build_object('error', 'closed'); end if;
  if q.source = 'website' and q.released_at is null then return jsonb_build_object('error', 'unsent'); end if;
  if q.valid_until < (now() at time zone public.agency_tz())::date then return jsonb_build_object('error', 'expired'); end if;
  update public.quotations set status = 'not_proceeding', declined_at = now(), decline_reason = v_reason where id = q.id;
  insert into public.signing_steps (doc_kind, doc_id, step, ip, country)
  values ('quotation', q.id, 'declined', nullif(public.request_ip(), ''), nullif(public.request_country(), ''));
  perform public.quote_activity(q, 'quotation.declined', q.ref || coalesce(' · ' || v_reason, ''), q.contact);
  select * into c from public.clients where id = q.client_id;
  if public.quote_sign_member(q.made_by_id) is null and public.quote_sign_member(c.owner_id) is null then
    perform public.quote_tell(q.client_id, 'quote.declined', 'Quotation declined · ' || q.brand,
      q.ref || coalesce(' · ' || v_reason, ''), q.id::text || ':declined');
  else
    perform public.quote_sign_tell(array[public.quote_sign_member(q.made_by_id), public.quote_sign_member(c.owner_id)],
      'quote.declined', 'Quotation declined · ' || q.brand, q.ref || coalesce(' · ' || v_reason, ''),
      q.client_id, q.id::text || ':declined');
  end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.quote_change_request(p_key text, p_sel jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  o jsonb := public.quote_change_open(p_key);
  q public.quotations;
  cl public.clients;
  c jsonb;
  v_fx numeric;
  v_sel jsonb;
  v_p jsonb;
  v_now timestamptz := now();
  v_body text;
begin
  if o ? 'error' then return o; end if;
  select * into q from public.quotations where id = (o->>'id')::uuid for update;
  -- Asked again under the row's lock, as signing is: a quotation signed a
  -- moment before takes no change request (review J14).
  o := public.quote_change_open(p_key);
  if o ? 'error' then return o; end if;
  select * into cl from public.clients where id = q.client_id;
  -- Ten requests or withdrawals a link an hour (MINOR ABUSE PATHS HELD):
  -- each tells the team, and a withdrawal clears the minute's wait.
  if (select count(*) from public.activity_log a
       where a.action in ('quotation.changes', 'quotation.withdrawn') and a.meta->>'ref' = q.ref
         and a.created_at > v_now - interval '1 hour') >= 10 then
    return jsonb_build_object('error', 'busy');
  end if;
  if p_sel is null then
    if q.change_requested_at is null then return jsonb_build_object('ok', true, 'again', true); end if;
    update public.quotations set change_request = null, change_requested_at = null where id = q.id;
    perform public.quote_activity(q, 'quotation.withdrawn', q.ref, q.contact);
    return jsonb_build_object('ok', true);
  end if;
  if q.selection ? 'brands' then return jsonb_build_object('error', 'brands'); end if;
  if q.change_requested_at > v_now - interval '1 minute' then return jsonb_build_object('error', 'recent'); end if;
  c := public.quote_change_snap(q);
  if c is null then return jsonb_build_object('error', 'no-card'); end if;
  v_fx := (c->>'fx')::numeric;
  if v_fx = 0 then return jsonb_build_object('error', 'no-fx'); end if;
  v_sel := public.quote_change_sel(q.selection, p_sel, c->'snap');
  if v_sel ? 'error' then return v_sel; end if;
  -- Unchanged whatever order the platforms were held in.
  if (v_sel - 'platforms') = (q.selection - 'platforms')
     and (select coalesce(jsonb_agg(x order by x), '[]'::jsonb) from jsonb_array_elements_text(coalesce(v_sel->'platforms', '[]'::jsonb)) x)
       = (select coalesce(jsonb_agg(x order by x), '[]'::jsonb) from jsonb_array_elements_text(coalesce(q.selection->'platforms', '[]'::jsonb)) x) then
    return jsonb_build_object('error', 'unchanged');
  end if;
  v_p := public.quote_fx_out(public.quote_compose(c->'snap', v_sel, q.source <> 'website'), v_fx);
  if v_p ? 'error' then return jsonb_build_object('error', v_p->>'error'); end if;
  update public.quotations
     set change_request = jsonb_build_object('selection', v_sel,
           'month', v_p->'totals'->'month'->'incl', 'once', v_p->'totals'->'once'->'incl', 'version', c->>'version'),
         change_requested_at = v_now, reply_due = public.quote_reply_by(v_now)
   where id = q.id
   returning * into q;
  perform public.quote_activity(q, 'quotation.changes', q.ref || coalesce(' · ' || coalesce(q.totals->>'currency', 'RM') || ' ' ||
    to_char((v_p->'totals'->'month'->>'incl')::numeric, 'FM999,999,990.00') || ' per month incl. SST', ''), q.contact);
  v_body := q.ref || coalesce(' · ' || coalesce(q.totals->>'currency', 'RM') || ' ' ||
              to_char((v_p->'totals'->'month'->>'incl')::numeric, 'FM999,999,990.00') || ' per month incl. SST', '')
            || ' · Send by ' || public.register_day((q.reply_due at time zone public.agency_tz())::date)
            || ' (' || trim(to_char(q.reply_due at time zone public.agency_tz(), 'FMDay')) || '), ' ||
            lower(to_char(q.reply_due at time zone public.agency_tz(), 'FMHH12:MIam'));
  -- Who prepared it and the person in charge are told; where neither is
  -- here, the team who work leads.
  if public.quote_sign_member(q.made_by_id) is null and public.quote_sign_member(cl.owner_id) is null then
    perform public.quote_tell(q.client_id, 'quote.changes', 'Changes requested · ' || q.brand, v_body,
      q.id::text || ':' || v_now::text);
  else
    perform public.quote_sign_tell(array[public.quote_sign_member(q.made_by_id), public.quote_sign_member(cl.owner_id)],
      'quote.changes', 'Changes requested · ' || q.brand, v_body, q.client_id, q.id::text || ':' || v_now::text);
  end if;
  return jsonb_build_object('ok', true, 'reply_due', q.reply_due);
end $$;

create or replace function public.quote_website_read(p_key text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  w  public.quotations;
  q  public.quotations;
  c  public.clients;
  m  public.team_members;
  pm public.team_members;
  pc public.client_contacts;
  d  public.client_documents;
  f  public.client_detail_forms;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_stage text;
  v_portal boolean := false;
  v_billed boolean;
  v_own boolean;
  v_unsent boolean;
  v_held boolean;
  v_ds   text;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not-found'); end if;
  -- Any quotation with a link: a website quotation, or a team's once
  -- `quotation_link` made one (QUOTATION SIGNING).
  select * into w from public.quotations x
   where x.access_key = p_key and x.removed_at is null;
  if w.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into q from public.quotations x where x.id = public.quote_shown(w.id);
  -- Details asked of the prospect (QUOTE DETAILS ASKED, 2026-11-27).
  v_ds := public.quote_details_state(q);
  -- A website quotation the team has not sent holds back its price at every
  -- stage, Not proceeding included (audit 2026-10-30).
  v_unsent := q.source = 'website' and q.released_at is null;
  select * into c from public.clients x where x.id = w.client_id;
  -- The representative a quotation names: the client's Sales by alone, never
  -- a stand-in (CLIENT REPRESENTATIVE, 2026-11-27).
  select * into m from public.team_members x where x.id = public.client_rep(c.id, 'sales');
  -- Prepared by: the colleague who made the revision shown; a website
  -- quotation's, the person in charge.
  select * into pm from public.team_members x where x.id = public.quote_sign_member(q.made_by_id);
  if pm.id is null and q.source = 'website' then pm := m; end if;
  -- The letter that stands on the quotation's lines, the latest first.
  select dd.* into d from public.client_documents dd
   where dd.kind = 'offer' and dd.voided_at is null and dd.superseded_by is null
     and exists (select 1 from public.client_document_services ds
                   join public.client_services s on s.id = ds.service_id
                  where ds.document_id = dd.id and s.quotation_id = q.id)
   order by dd.created_at desc limit 1;
  -- The client's details form is offered only on the website quotation
  -- that made the lead: a later website quotation that matched an existing
  -- lead's email and number never opens that lead's form (2026-10-26, audit).
  v_own := w.source = 'website' and c.created_at >= w.issued_at - interval '1 minute'
           and not exists (select 1 from public.quotations o
                            where o.client_id = c.id and o.issued_at < w.issued_at and o.id <> w.id);
  -- A website quotation that found a client the team already serves
  -- (WEBSITE QUOTATION FINDS ITS CLIENT, 2026-11-25) says nothing of that
  -- client while the team has not sent it: no representative, no
  -- preparer, the market read from the number typed.
  v_held := v_unsent and not v_own and coalesce(c.stage, '') not in ('lead', 'contacted', 'proposal');
  if v_held then m := null; pm := null; end if;
  v_billed := coalesce(btrim(c.legal_name), '') <> '' and coalesce(btrim(c.company_no), '') <> ''
              and coalesce(btrim(c.billing_address), '') <> '';

  if d.id is not null then
    if d.verified_at is not null and c.stage = 'active' then
      v_stage := 'welcome';
      select exists (select 1 from public.client_contacts k
                      where k.client_id = c.id and k.archived_at is null and k.portal_access
                        and lower(btrim(k.email)) = lower(btrim(coalesce(w.contact->>'email', '')))) into v_portal;
    elsif d.signed_at is not null then v_stage := 'signed';
    else v_stage := 'letter';
    end if;
  elsif w.status = 'not_proceeding' or q.status = 'not_proceeding' then
    v_stage := 'closed';
  elsif q.source = 'website' and q.released_at is null and v_ds = 'closed' then
    -- Not answered past the close days: closed as Not quoted, worked out.
    v_stage := 'closed';
  elsif q.source = 'website' and q.released_at is null and v_ds in ('asked', 'late') then
    -- The team asked for details: the link opens the fields asked alone.
    v_stage := 'details';
  elsif q.source = 'website' and q.released_at is null then
    -- Being reviewed: nothing priced leaves the database (2026-10-29).
    v_stage := 'review';
  elsif q.signed_at is not null then
    -- Signed on the link or on paper: accepted, then welcome once reviewed
    -- and Active (QUOTATION SIGNING).
    if q.reviewed_at is not null and c.stage = 'active' then
      v_stage := 'welcome';
      select exists (select 1 from public.client_contacts k
                      where k.client_id = c.id and k.archived_at is null and k.portal_access
                        and lower(btrim(k.email)) = lower(btrim(coalesce(q.signed->'contact'->>'email', w.contact->>'email', '')))) into v_portal;
    else v_stage := 'accepted';
    end if;
  elsif q.valid_until < v_today then
    v_stage := 'expired';
  elsif not v_billed and v_own then
    select * into f from public.client_detail_forms x
     where x.client_id = c.id and x.voided_at is null
     order by x.created_at desc limit 1;
    if f.id is not null and f.submitted_at is not null and f.used_at is null then v_stage := 'billing_sent';
    elsif f.id is not null and f.submitted_at is null and f.expires_at > now() then v_stage := 'billing';
    end if;
  elsif v_billed and w.proceed_at is not null and w.source = 'website' then
    v_stage := 'billing_sent';
  end if;
  if v_stage is null then
    v_stage := case when w.proceed_at is not null then 'ready' else 'quote' end;
  end if;
  -- The record's details prefill only its own link: a website quotation
  -- that matched an existing lead never reads that lead's billing or
  -- primary contact, and a closed or expired link prefills nothing
  -- (audit 2026-11-04).
  if q.signed_at is null and (w.source <> 'website' or v_own) then
    select * into pc from public.client_contacts x
     where x.client_id = c.id and x.archived_at is null and x.is_primary
     order by x.created_at limit 1;
  end if;

  return jsonb_build_object(
    'ref', q.ref, 'first_ref', w.ref, 'revised', q.id <> w.id,
    'brand', coalesce(w.contact->>'brand', w.brand), 'version', case when q.source <> 'website' or q.released_at is not null then q.version end,
    'issued_at', q.issued_at,
    'valid_until', case when not v_unsent then q.valid_until end,
    'lines', case when not v_unsent then q.lines end,
    'totals', case when not v_unsent then q.totals end,
    'reply_due', case when v_stage = 'review' then q.reply_due end,
    'details_at', case when v_stage = 'review' then q.details_at end,
    'ask', case when v_stage = 'details' then jsonb_build_object(
      'fields', q.details_ask->'fields', 'note', q.details_ask->>'note', 'due', q.details_due,
      'known', public.quote_details_known(q.contact, array(select jsonb_array_elements_text(q.details_ask->'fields')))) end,
    'selection', w.selection, 'attention', coalesce(w.contact->>'name', pc.name),
    'stage', v_stage,
    'status', case when d.id is not null then 'offer' else q.status end,
    'details_key', case when v_stage = 'billing' then f.access_key end,
    'portal', v_portal,
    'proceed_at', w.proceed_at, 'proceed_due', w.proceed_due,
    'rep', case when m.id is null then null else jsonb_build_object('name', m.name, 'title', nullif(btrim(coalesce(m.designation, '')), ''),
             'whatsapp', case when coalesce(m.card_on, true) and coalesce(m.card_mobile, true) then nullif(public.wa_number(m.mobile), '') end) end,
    'market', case when v_held then case when w.contact->>'whatsapp' like '+65%' then 'SG' else 'MY' end
                   when c.market = 'SG' then 'SG' else 'MY' end,
    'today', v_today,
    -- A Singapore client billed in RM: the S$ rate on its day of issue, so
    -- each total reads its S$ beside it (AD SPEND FIGURES, 2026-11-27).
    'fx_sgd', case when not v_unsent and not v_held and c.market = 'SG' and coalesce(q.totals->>'currency', '') <> 'SGD'
                   then nullif(public.app_setting('fx_sgd', (q.issued_at at time zone public.agency_tz())::date), 0) end,
    'signed', case when q.signed_at is not null then jsonb_build_object('at', q.signed_at, 'via', q.signed->>'via',
                'signer', q.signed->'signer', 'signature', q.signed->'signature', 'company', q.signed->'company',
                'contact', q.signed->'contact', 'record', case when q.signed->>'via' = 'online' then q.signed->'record' end) end,
    'prepared', case when pm.id is not null then jsonb_build_object('name', pm.name, 'title', nullif(btrim(coalesce(pm.designation, '')), ''))
                     when not v_held and nullif(btrim(coalesce(q.made_by, '')), '') is not null then jsonb_build_object('name', q.made_by, 'title', null) end,
    'reviewed', case when q.reviewed_at is not null then jsonb_build_object('name', q.reviewed_by, 'title', q.reviewed_role, 'at', q.reviewed_at) end,
    'prefill', case when q.signed_at is null and not v_unsent and v_stage not in ('closed', 'expired') then jsonb_build_object(
      'company', case when w.source <> 'website' or v_own then
                   jsonb_build_object('legal_name', coalesce(c.legal_name, ''), 'company_no', coalesce(c.company_no, ''),
                                      'billing_address', coalesce(c.billing_address, ''), 'sst_no', coalesce(c.sst_no, ''), 'tin', coalesce(c.tin, ''))
                 else jsonb_build_object('legal_name', '', 'company_no', '', 'billing_address', '', 'sst_no', '', 'tin', '') end,
      'contact', case when pc.id is not null then jsonb_build_object('salutation', coalesce(pc.salutation, ''), 'name', coalesce(pc.name, ''),
                                                                    'phone', coalesce(nullif(btrim(pc.phone), ''), case when btrim(coalesce(pc.whatsapp, '')) !~ '^@' then btrim(pc.whatsapp) end, ''),
                                                                     'email', coalesce(pc.email, ''))
                      else jsonb_build_object('salutation', coalesce(w.contact->>'salutation', ''), 'name', coalesce(w.contact->>'name', ''),
                                              'phone', coalesce(w.contact->>'whatsapp', ''), 'email', coalesce(w.contact->>'email', '')) end) end);
end $$;

create or replace function public.feedback_request(p_client uuid, p_kind text, p_again boolean default false,
  p_channel text default 'email')
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  v_cl   public.clients;
  v_ct   public.client_contacts;
  v_mgr  public.team_members;
  v_key  text;
  v_req  public.feedback_requests;
begin
  if me.id is null or not public.allowed('clients', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_kind is null or p_kind not in ('quick', 'review') then return jsonb_build_object('error', 'bad-kind'); end if;
  if p_channel is null or p_channel not in ('email', 'whatsapp') then return jsonb_build_object('error', 'bad-channel'); end if;
  select * into v_cl from public.clients c where c.id = p_client;
  if v_cl.id is null or not public.client_seen(v_cl.id, 'work') then return jsonb_build_object('error', 'not-found'); end if;
  if v_cl.stage in ('lead', 'contacted', 'proposal') then return jsonb_build_object('error', 'not-active'); end if;
  -- An email needs the primary contact's address; a copy for WhatsApp
  -- needs the contact alone (their name and language).
  select * into v_ct from public.client_contacts k
   where k.client_id = p_client and k.is_primary and k.archived_at is null
     and (p_channel = 'whatsapp' or nullif(btrim(coalesce(k.email, '')), '') is not null)
   limit 1;
  if v_ct.id is null then
    return jsonb_build_object('error', case when p_channel = 'whatsapp' then 'no-primary' else 'no-contact' end);
  end if;
  perform pg_advisory_xact_lock(hashtext('feedback_request:' || p_client::text || ':' || p_kind));
  -- None while one is still going out, and none again within the repeat
  -- hours unless asked again, whichever way either went.
  if exists (select 1 from public.feedback_requests r where r.client_id = p_client and r.kind = p_kind
              and r.mail_status = 'sending' and r.created_at > now() - interval '10 minutes') then
    return jsonb_build_object('error', 'sending');
  end if;
  select * into v_req from public.feedback_requests r
   where r.client_id = p_client and r.kind = p_kind and coalesce(r.mail_status, 'sent') not in ('failed', 'sending')
     and r.closed_reason is distinct from 'withdrawn'
     and r.created_at > now() - make_interval(hours => coalesce(public.app_setting('wa_repeat_hours', (now() at time zone public.agency_tz())::date), 24)::int)
   order by r.created_at desc limit 1;
  if v_req.id is not null and not coalesce(p_again, false) then
    return jsonb_build_object('error', 'recent', 'recent',
      jsonb_build_object('at', v_req.created_at, 'by', v_req.sent_by_name, 'to', v_req.sent_to_name,
        'channel', v_req.channel));
  end if;
  v_req := null;
  select * into v_mgr from public.team_members m
   where m.id = v_cl.owner_id and m.active and m.removed_at is null;
  update public.feedback_requests r set closed_at = now(), closed_reason = 'replaced'
   where r.client_id = p_client and r.kind = p_kind and r.closed_at is null;
  loop
    v_key := public.new_link_key() || public.new_link_key();
    exit when not exists (select 1 from public.feedback_requests r where r.access_key = v_key);
  end loop;
  insert into public.feedback_requests (client_id, kind, access_key, sent_by, sent_by_name, contact_id,
    sent_to_name, sent_to_email, manager_id, manager_name, channel)
  values (p_client, p_kind, v_key, me.id, me.name, v_ct.id, v_ct.name, nullif(lower(btrim(coalesce(v_ct.email, ''))), ''),
    v_mgr.id, coalesce(v_mgr.name, nullif(btrim(coalesce(v_cl.owner, '')), '')), p_channel)
  returning * into v_req;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.edited', v_cl.name,
          (case p_kind when 'quick' then 'Service rating' else 'Performance review' end)
          || ' requested from ' || v_ct.name
          || case when p_channel = 'whatsapp' then ', copied for WhatsApp' else '' end);
  return jsonb_build_object('ok', true, 'id', v_req.id, 'key', v_req.access_key, 'kind', v_req.kind,
    'to_name', v_req.sent_to_name, 'to_email', v_req.sent_to_email, 'lang', coalesce(v_ct.lang, 'en'),
    'manager', v_req.manager_name, 'created_at', v_req.created_at, 'channel', v_req.channel);
end $$;

create or replace function public.ops_task_late(p_task uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select
      (t.current_final_due_at is not null
        and (t.current_final_due_at at time zone public.agency_tz())::date
            < (now() at time zone public.agency_tz())::date
        and (f.at is null or s.position < f.at))
      or
      (p.by is not null and p.by < now()
        and (pf.at is null or s.position < pf.at or s.stage_group in ('kiv', 'blocked')))
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.id = t.stage_id
      cross join lateral (
        select public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as by) p
      cross join lateral (
        select min(w.position) as at from public.ops_workflow_stages w
         where w.workflow_id = t.workflow_id and w.stage_group = 'client_review') f
      cross join lateral (
        select coalesce(min(w.position) filter (where w.stage_group = 'client_review'),
                        min(w.position) filter (where w.stage_group = 'internal_review')) as at
          from public.ops_workflow_stages w where w.workflow_id = t.workflow_id) pf
     where t.id = p_task
       and t.completed_at is null and t.cancelled_at is null and t.archived_at is null
  ), false)
$$;

create or replace function public.ops_tasks_nudge(p_at timestamptz default null)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_at    timestamptz := coalesce(p_at, now());
  v_local timestamp := coalesce(p_at, now()) at time zone public.agency_tz();
  v_today date := (coalesce(p_at, now()) at time zone public.agency_tz())::date;
  v_every integer;
  v_start integer;
  m record;
  v_title text;
  v_body text;
  v_parts text[];
  v_last timestamptz;
  n integer := 0;
begin
  -- Nothing on a public holiday (RETENTION AND JOBS HELD).
  if public.public_holiday_on(v_today) is not null then return 0; end if;
  v_every := coalesce(public.app_setting('task_remind_hours', v_today), 3)::integer;
  v_start := coalesce(public.app_setting('task_start_days', v_today), 2)::integer;
  if v_every <= 0 or extract(isodow from v_today) > 5
     or extract(hour from v_local) < 10 or extract(hour from v_local) >= 18 then
    return 0;
  end if;
  for m in
    with floors as (
      select workflow_id, min(position) as at
        from public.ops_workflow_stages
       where stage_group = 'client_review'
       group by workflow_id
    ),
    pfloors as (
      select workflow_id,
             coalesce(min(position) filter (where stage_group = 'client_review'),
                      min(position) filter (where stage_group = 'internal_review')) as at
        from public.ops_workflow_stages
       group by workflow_id
    ),
    mine as (
      select a.team_member_id as member, k.id, a.assigned_at, k.priority_level, (c.vic_at is not null) as vic,
             public.ops_serial(k.task_no) || ' · ' || public.ops_title(k) as label,
             coalesce(c.name, 'Internal') as client,
             s.stage_group, s.position, f.at as review_at, pf.at as prio_at,
             public.ops_priority_by(coalesce(k.priority_at, k.created_at), k.priority_level) as prio_by,
             (k.current_final_due_at at time zone public.agency_tz())::date as due_day,
             (coalesce(k.current_first_draft_due_at, k.current_final_due_at) at time zone public.agency_tz())::date as first_day
        from public.ops_task_assignees a
        join public.ops_tasks k on k.id = a.task_id
        join public.team_members tm on tm.id = a.team_member_id
        join public.ops_workflow_stages s on s.id = k.stage_id
        left join public.clients c on c.id = k.client_id
        left join floors f on f.workflow_id = k.workflow_id
        left join pfloors pf on pf.workflow_id = k.workflow_id
       where a.responsibility = 'owner' and a.ended_at is null
         and tm.active and not coalesce(tm.system, false)
         and k.completed_at is null and k.cancelled_at is null and k.archived_at is null
         and coalesce(s.stage_group, '') <> 'cancelled'
    ),
    sorted as (
      select x.*,
             (x.prio_by is not null and (x.prio_at is null or x.position < x.prio_at
                                         or x.stage_group in ('kiv', 'blocked'))) as prio_runs,
             (x.review_at is null or x.position < x.review_at) as short_of_review
        from mine x
    ),
    sized as (
      select y.*,
             /* When it became overdue: the earlier of its priority's deadline
                and the end of its due day. */
             least(case when y.prio_runs and y.prio_by < v_at then y.prio_by end,
                   case when y.due_day < v_today and y.short_of_review
                        then (y.due_day + 1)::timestamp at time zone public.agency_tz() end) as late_at,
             case
        when (y.due_day < v_today and y.short_of_review) or (y.prio_runs and y.prio_by < v_at) then 1
        when y.prio_runs and y.priority_level = 1 then 2
        when (y.due_day = v_today and y.short_of_review)
          or (y.prio_runs and (y.prio_by at time zone public.agency_tz())::date = v_today) then 3
        when v_start > 0 and y.stage_group in ('intake', 'ready')
          and ((y.first_day is not null and y.first_day <= v_today + v_start)
            or (y.first_day is null and y.assigned_at <= v_at - make_interval(days => v_start))) then 4
      end as bucket
        from sorted y
    )
    select z.member,
           count(*) as total,
           count(*) filter (where z.bucket = 1) as late,
           count(*) filter (where z.bucket = 2) as urgent,
           count(*) filter (where z.bucket = 3) as today,
           count(*) filter (where z.bucket = 4) as idle,
           count(*) filter (where z.vic) as vic,
           max(z.late_at) filter (where z.vic and z.bucket = 1) as vic_late_at,
           (array_agg(z.id order by not z.vic, z.bucket, coalesce(z.due_day, z.first_day), z.label))[1] as first_id,
           (array_agg(z.bucket order by not z.vic, z.bucket, coalesce(z.due_day, z.first_day), z.label))[1] as first_bucket,
           (array_agg(z.client order by not z.vic, z.bucket, coalesce(z.due_day, z.first_day), z.label))[1] as first_client,
           (array_agg(z.prio_by order by not z.vic, z.bucket, coalesce(z.due_day, z.first_day), z.label))[1] as first_by,
           (array_agg(z.label order by not z.vic, z.bucket, coalesce(z.due_day, z.first_day), z.label))[1:3] as labels
      from sized z
     where z.bucket is not null
     group by z.member
     order by z.member
  loop
    /* Within the window nothing is sent, but a VIC client's task that has
       become overdue since this colleague's last reminder is told at once. */
    select max(o.created_at) into v_last from public.ops_notifications o
     where o.team_member_id = m.member and o.kind = 'tasks.nudge';
    if v_last > v_at - make_interval(mins => v_every * 60 - 10)
       and (m.vic_late_at is null or m.vic_late_at <= v_last) then
      continue;
    end if;
    if m.total = 1 then
      v_title := m.labels[1] || case m.first_bucket when 1 then ' is overdue.' when 2 then ' is Urgent.'
                                                  when 3 then ' is due today.' else ' has not started.' end;
      v_body := m.first_client || case when m.first_bucket = 2 and m.first_by is not null then
        ' · deliver by ' || to_char(m.first_by at time zone public.agency_tz(), 'FMHH12:MIam') || ', ' ||
        public.register_day((m.first_by at time zone public.agency_tz())::date) || '.' else '' end;
    else
      v_parts := array_remove(array[
        case when m.vic > 0 then m.vic || ' for VIC clients' end,
        case when m.late > 0 then m.late || ' overdue' end,
        case when m.urgent > 0 then m.urgent || ' Urgent' end,
        case when m.today > 0 then m.today || ' due today' end,
        case when m.idle > 0 then m.idle || ' not started' end], null);
      v_title := m.total || ' tasks need attention: ' || array_to_string(v_parts, ', ') || '.';
      v_body := array_to_string(m.labels, '; ') ||
                case when m.total > 3 then '; and ' || (m.total - 3) || ' more.' else '.' end;
    end if;
    insert into public.ops_notifications (team_member_id, task_id, kind, title, body, created_at, dedupe_key)
    values (m.member, case when m.total = 1 then m.first_id end, 'tasks.nudge', v_title, v_body, v_at,
            'tasks.nudge.' || m.member || '.' || to_char(v_local, 'YYYY-MM-DD-HH24'))
    on conflict (dedupe_key) do nothing;
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.ops_report_of(
  p_from  timestamptz,
  p_to    timestamptz,
  p_light boolean)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  out jsonb;
begin
  if not public.ops_granted('ops.reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;

  with
  /* Where client review begins in each workflow. The final due date is the
     day the work is owed AT that stage, so everything below that position is
     "has not reached the client yet". Read from `stage_group` and never from
     a stage key: the two seeded workflows name that stage differently. */
  floors as (
    select workflow_id, min(position) as at
      from public.ops_workflow_stages
     where stage_group = 'client_review'
     group by workflow_id
  ),
  /* Where a priority's deadline is met (2026-10-11): client review, else the
     workflow's first review (an everyday task's Review). */
  pfloors as (
    select workflow_id,
           coalesce(min(position) filter (where stage_group = 'client_review'),
                    min(position) filter (where stage_group = 'internal_review')) as at
      from public.ops_workflow_stages
     group by workflow_id
  ),
  live as (
    select t.*, s.label as stage_label, s.position as stage_position,
           s.stage_group, f.at as review_at,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by, pf.at as prio_at
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.id = t.stage_id
      left join floors f on f.workflow_id = t.workflow_id
      left join pfloors pf on pf.workflow_id = t.workflow_id
     where t.completed_at is null and t.cancelled_at is null
       and t.archived_at is null
       /* Client scope: a colleague on Own clients only reads the work of
          the clients they hold, and their own tasks always (2026-10-18). */
       and public.ops_task_in_scope(t.id)
  ),

  /* 1. WHAT IS RUNNING, by the words on the screen. Grouped by the stage's
        own label rather than by its group, because "what is on shooting" is
        the question and Shooting is a label, not a group. */
  running as (
    select jsonb_agg(x order by x ->> 'position', x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key, 'label', stage_label,
               'position', stage_position, 'stage_group', stage_group,
               'count', count(*)) as x
        from live
       where not p_light
       group by stage_key, stage_label, stage_position, stage_group
    ) q
  ),

  /* 2. WHAT IS LATE. Past the commitment and still short of client review,
        or past a priority's deadline and short of its review (On hold and
        Blocked still count): whichever comes first (the user, 2026-10-11).
        The same rule the queue row draws, stated once more here because a
        report a page computes for itself is a second definition. */
  late_now as (
    select l.*,
           (l.current_final_due_at is not null and (l.current_final_due_at at time zone public.agency_tz())::date < (now() at time zone public.agency_tz())::date
            and (l.review_at is null or l.stage_position < l.review_at)) as due_late,
           (l.prio_by is not null and l.prio_by < now()
            and (l.prio_at is null or l.stage_position < l.prio_at or l.stage_group in ('kiv', 'blocked'))) as prio_late
      from live l
  ),
  late as (
    select jsonb_agg(x order by x ->> 'due_at') as j from (
      select jsonb_build_object(
               'task_id', l.id, 'task_no', l.task_no, 'title', l.title,
               'client', c.name, 'stage', l.stage_label,
               'due_at', case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                              then l.prio_by else l.current_final_due_at end,
               'days_over', greatest(case when l.due_late then (now() at time zone public.agency_tz())::date - (l.current_final_due_at at time zone public.agency_tz())::date end,
                                     case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 86400)::int end),
               'over_minutes', case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 60)::int end,
               'owner', (select tm.name
                           from public.ops_task_assignees a
                           join public.team_members tm on tm.id = a.team_member_id
                          where a.task_id = l.id and a.responsibility = 'owner'
                            and a.ended_at is null
                          limit 1)) as x
        from late_now l
        left join public.clients c on c.id = l.client_id
       where (l.due_late or l.prio_late) and not p_light
    ) q
  ),

  /* 3. HOW LONG EACH STAGE TAKES. A task enters a stage at the event that
        names it and leaves at the next event, or at its own ending, or now.
        Only spans that were ENTERED inside the period are counted, so the
        window means what it says and a task that sat in Editing since March
        does not land in every report for ever. */
  spans as (
    select e.task_id,
           e.to_value ->> 'stage_key' as stage_key,
           e.created_at as from_at,
           coalesce(
             lead(e.created_at) over (partition by e.task_id order by e.created_at),
             t.completed_at, t.cancelled_at, now()) as to_at
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
     where e.event_type in ('task_created', 'stage_changed')
       and e.to_value ->> 'stage_key' is not null
       and public.ops_task_in_scope(t.id)
       /* Only a span entered in the period is counted, and its end is the
          task's next event, never an earlier one: what came before the
          period is not read (2026-10-18). */
       and e.created_at >= p_from
  ),
  /* One row per span and no grouping: an earlier draft grouped by the span's
     own timestamps, which silently collapsed two tasks that entered the same
     stage in the same instant into one measurement. The label is looked up
     once per stage below instead of aggregated here. */
  span_mins as (
    select s.stage_key,
           extract(epoch from (s.to_at - s.from_at)) / 60 as mins
      from spans s
     where s.from_at >= p_from and s.from_at < p_to
       and s.to_at > s.from_at
  ),
  stage_time as (
    select jsonb_agg(x order by x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key,
               'label', coalesce((select w.label from public.ops_workflow_stages w
                                   where w.key = sm.stage_key limit 1), stage_key),
               'n', count(*),
               'median_minutes', round(percentile_cont(0.5) within group (order by mins))::int,
               'p90_minutes', round(percentile_cont(0.9) within group (order by mins))::int) as x
        from span_mins sm
       where not p_light
       group by stage_key
    ) q
  ),

  /* 4. WAS IT THERE ON TIME. Of the tasks that reached client review inside
        the period, how many got there on or before the date they were owed;
        the work still late is counted beside them (`late_open`).
        Replanning is counted beside it and never folded into it: an extension
        that moves the date would otherwise erase the miss it was granted for,
        and a rate that cannot be missed is not a measurement. */
  /* A task's FIRST entry into client review ever, counted in the period it
     fell in: its return after a revision is never counted again, in its own
     period or a later one (audit 2026-11-15). */
  reached as (
    select f.* from (
      select distinct on (e.task_id)
             e.task_id, e.created_at as at, t.current_final_due_at as due,
             public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
             (t.original_final_due_at is distinct from t.current_final_due_at) as replanned
        from public.ops_task_events e
        join public.ops_tasks t on t.id = e.task_id
        join public.ops_workflow_stages w
          on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
       where e.event_type = 'stage_changed'
         and w.stage_group = 'client_review'
         and public.ops_task_in_scope(t.id)
         and e.created_at < p_to
       order by e.task_id, e.created_at
    ) f
     where f.at >= p_from
  ),
  /* Work still short of its review and past its deadline is a miss too
     (2026-10-19, the user: "there are late tasks yet showing 100% on time
     delivery"): counted in the period its first missed deadline fell in,
     and in any period that runs to now (its end within ten minutes of now:
     the page names the moment it asks), where it is still late. A task
     counted as reached in the period is not counted again. */
  late_open as (
    select l.id
      from late_now l
     where (l.due_late or l.prio_late)
       and not exists (select 1 from reached r where r.task_id = l.id)
       and (case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                 then l.prio_by else l.current_final_due_at end) < p_to
       and ((case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                  then l.prio_by else l.current_final_due_at end) >= p_from
            or p_to >= now() - interval '10 minutes')
  ),
  on_time as (
    select jsonb_build_object(
             'reached', count(*),
             'met', count(*) filter (where (due is null or (at at time zone public.agency_tz())::date <= (due at time zone public.agency_tz())::date)
                                       and (prio_by is null or at <= prio_by)),
             'missed', count(*) filter (where not ((due is null or (at at time zone public.agency_tz())::date <= (due at time zone public.agency_tz())::date)
                                                 and (prio_by is null or at <= prio_by))),
             'late_open', (select count(*) from late_open),
             'replanned', count(*) filter (where replanned)) as j
      from reached
  ),
  /* 4b. POSTED ON TIME (2026-10-19). Of the content whose post date fell in
         the period and has passed (Malaysia's day), or which went live, how
         much went live by its post date. Client approval counts here, as it
         does for the client; on-time delivery above is the team's own. */
  posted as (
    select jsonb_build_object(
             'due', count(*),
             'met', count(*) filter (where t.live_at is not null
                                       and (t.live_at at time zone public.agency_tz())::date
                                           <= (t.publish_at at time zone public.agency_tz())::date)) as j
      from public.ops_tasks t
     where t.publish_at >= p_from and t.publish_at < p_to
       and t.cancelled_at is null and t.archived_at is null
       and (t.live_at is not null
            or (t.publish_at at time zone public.agency_tz())::date < (now() at time zone public.agency_tz())::date)
       and exists (select 1 from public.ops_workflow_stages s
                    where s.workflow_id = t.workflow_id and s.stage_group = 'live')
       and public.ops_task_in_scope(t.id)
  ),

  /* 5. BY PERSON. The foundation of a KPI and not a KPI: what somebody
        finished in the window, how much of it was on time, and how long their
        work took end to end. No ranking and no score — a number a person can
        check is worth more than a league table nobody trusts. */
  done as (
    select t.id, t.created_at, t.completed_at as ended,
           t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           /* When a priority's deadline was met: the first move into its
              review or beyond (never On hold, Blocked or Cancelled). */
           (select min(e.created_at)
              from public.ops_task_events e
              join public.ops_workflow_stages w
                on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
              join pfloors pf on pf.workflow_id = t.workflow_id
             where e.task_id = t.id and e.event_type = 'stage_changed'
               and w.position >= pf.at and w.stage_group not in ('kiv', 'blocked', 'cancelled')) as met_at,
           /* When it reached client review (2026-10-22, OVW-2): the day the
              due date is owed at, as the on-time ring reads it. */
           (select min(e.created_at)
              from public.ops_task_events e
              join public.ops_workflow_stages w
                on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
             where e.task_id = t.id and e.event_type = 'stage_changed'
               and w.stage_group = 'client_review') as review_at,
           (select a.team_member_id
              from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc
             limit 1) as owner_id
      from public.ops_tasks t
     where t.completed_at is not null
       and t.completed_at >= p_from and t.completed_at < p_to
       and public.ops_task_in_scope(t.id)
  ),
  by_person as (
    select jsonb_agg(x order by x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', d.owner_id,
               'name', coalesce(tm.name, 'Unassigned'),
               'completed', count(*),
               'on_time', count(*) filter (where (d.due is null
                                                 or (coalesce(d.review_at, d.met_at, d.ended) at time zone public.agency_tz())::date
                                                    <= (d.due at time zone public.agency_tz())::date)
                                         and (d.prio_by is null or coalesce(d.met_at, d.ended) <= d.prio_by)),
               'median_cycle_minutes',
                 round(percentile_cont(0.5) within group (
                   order by extract(epoch from (d.ended - d.created_at)) / 60))::int) as x
        from done d
        left join public.team_members tm on tm.id = d.owner_id
       group by d.owner_id, tm.name
    ) q
  ),

  /* 6. WHO IS CARRYING THE OPEN WORK (2026-09-28). One row a Task Owner:
        the open tasks they hold, and how many of those are late by the rule
        in 2 above. The team's whole queue is `ops.all`, so it is answered
        only where that part is granted. */
  open_by_person as (
    select jsonb_agg(x order by (x ->> 'open')::int desc, x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', o.owner_id,
               'name', coalesce(tm.name, 'Unassigned'),
               'open', count(*),
               'late', count(*) filter (where o.is_late)) as x
        from (select l.id,
                     (select a.team_member_id
                        from public.ops_task_assignees a
                       where a.task_id = l.id and a.responsibility = 'owner' and a.ended_at is null
                       limit 1) as owner_id,
                     (l.due_late or l.prio_late) as is_late
                from late_now l) o
        left join public.team_members tm on tm.id = o.owner_id
       where public.ops_granted('ops.all', 'view') and not p_light
       group by o.owner_id, tm.name
    ) q
  )

  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'running',    coalesce((select j from running), '[]'::jsonb),
           'late',       coalesce((select j from late), '[]'::jsonb),
           'stage_time', coalesce((select j from stage_time), '[]'::jsonb),
           'on_time',    coalesce((select j from on_time), '{}'::jsonb),
           'posted',     coalesce((select j from posted), '{}'::jsonb),
           'by_person',  coalesce((select j from by_person), '[]'::jsonb),
           'open_by_person', case when public.ops_granted('ops.all', 'view')
                                  then coalesce((select j from open_by_person), '[]'::jsonb) end)
    into out;

  return out;
end $$;

create or replace function public.page_set(p_pages text[], p_kind text, p_note text default null, p_note_zh text default null,
                                           p_starts timestamptz default null, p_ends timestamptz default null,
                                           p_whatsapp boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_who text;
  v_k text;
  v_on boolean := coalesce(p_kind, 'none') <> 'none';
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_zh text := nullif(btrim(coalesce(p_note_zh, '')), '');
  v_was text;
  v_bits text[] := '{}';
  v_word text;
  v_when text := '';
  f public.app_flags;
begin
  if not public.ops_granted('team.upgrade', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(array_length(p_pages, 1), 0) = 0
     or exists (select 1 from unnest(p_pages) k where not (k = any (public.page_keys()))) then
    return jsonb_build_object('error', 'bad-page');
  end if;
  if coalesce(p_kind, 'none') not in ('none', 'upgrade', 'paused') then return jsonb_build_object('error', 'bad-kind'); end if;
  if v_on and p_ends is not null and p_ends <= greatest(coalesce(p_starts, now()), now()) then
    return jsonb_build_object('error', 'bad-window');
  end if;
  select coalesce(t.name, t.email) into v_who from public.team_members t
   where t.auth_user_id = auth.uid() and t.active limit 1;
  v_word := case p_kind when 'upgrade' then 'Upgrade in progress' when 'paused' then 'Temporarily unavailable' else 'Available' end;
  for v_k in select distinct k from unnest(p_pages) k loop
    select * into f from public.app_flags where key = 'page:' || v_k;
    v_was := case when f.key is not null and f.on_now and (f.ends_at is null or f.ends_at > now())
                  then case coalesce(f.kind, 'upgrade') when 'paused' then 'Temporarily unavailable' else 'Upgrade in progress' end
                  else 'Available' end;
    insert into public.app_flags (key, on_now, note, note_zh, starts_at, ends_at, set_by, set_at, kind, whatsapp)
    values ('page:' || v_k, v_on, case when v_on then left(v_note, 300) end, case when v_on then left(v_zh, 300) end,
            case when v_on and p_starts > now() then p_starts end, case when v_on then p_ends end,
            v_who, now(), case when v_on then p_kind end, v_on and coalesce(p_whatsapp, false))
    on conflict (key) do update
      set on_now = excluded.on_now, note = excluded.note, note_zh = excluded.note_zh, starts_at = excluded.starts_at,
          ends_at = excluded.ends_at, set_by = excluded.set_by, set_at = excluded.set_at, kind = excluded.kind,
          whatsapp = excluded.whatsapp;
    v_bits := v_bits || (public.page_name(v_k) || ': ' || v_was || ' → ' || v_word);
  end loop;
  if v_on and p_starts > now() then
    v_when := ' · from ' || public.register_day((p_starts at time zone public.agency_tz())::date) || ' ' ||
              to_char(p_starts at time zone public.agency_tz(), 'HH24:MI');
  end if;
  if v_on and p_ends is not null then
    v_when := v_when || ' · until ' || public.register_day((p_ends at time zone public.agency_tz())::date) || ' ' ||
              to_char(p_ends at time zone public.agency_tz(), 'HH24:MI');
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'Portal',
          'Page availability: ' || array_to_string(v_bits, ', ') || v_when ||
          case when v_on then coalesce(' · ' || left(v_note, 300), '') else '' end);
  return jsonb_build_object('ok', true, 'pages', public.page_states_all());
end $$;

create or replace function public.team_sessions_idle_end(p_now timestamptz default now())
returns integer
language plpgsql volatile security definer set search_path = public as $$
declare
  v_days integer := coalesce(public.app_setting('session_idle_days', (p_now at time zone public.agency_tz())::date), 30)::integer;
  v_n    integer := 0;
begin
  if v_days > 0 then
    delete from auth.sessions s
     where greatest(s.updated_at, s.refreshed_at at time zone 'UTC', s.created_at) < p_now - make_interval(days => v_days)
       and exists (select 1 from public.team_members t
                    where t.auth_user_id = s.user_id and t.erased_at is null)
       and not exists (select 1 from public.team_members t
                        where t.auth_user_id = s.user_id and coalesce(t.system, false));
    get diagnostics v_n = row_count;
    if v_n > 0 then
      insert into public.activity_log (actor, action, subject, detail)
      values ('system', 'team.changed', 'Signed-in devices',
              v_n || case when v_n = 1 then ' device was' else ' devices were' end || ' signed out after ' || v_days ||
              case when v_days = 1 then ' day' else ' days' end || ' unused.');
    end if;
  end if;
  perform public.job_beat('session-idle', true,
    case when v_days > 0 then v_n || ' signed out' else 'off' end);
  return v_n;
end $$;

create or replace function public.issue_letter(
  p_client    uuid,
  p_services  uuid[],
  p_idem      text,
  p_subtotal  numeric,
  p_tax       numeric,
  p_total     numeric,
  p_deal      jsonb   default '{}'::jsonb,
  p_replaces  uuid    default null,
  p_renewal   boolean default false,
  /* A reference somebody typed. Blank is the ordinary case and the counter
     below makes the number; where one is typed it is checked against every
     document that stands and the counter is not advanced, so filling a gap
     by hand never costs the next letter its place in the sequence. */
  p_serial    text    default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who    text := lower(auth.jwt() ->> 'email');
  cl     public.clients%rowtype;
  ct     public.client_contacts%rowtype;
  me     public.team_members%rowtype;
  v_ym   text;
  v_seq  int;
  v_try  int;
  v_no   text;
  v_id   uuid;
  v_lines jsonb;
  v_n    int;
  v_bad  int;
  v_old  public.client_documents%rowtype;
  v_term int;
  v_each numeric;
  v_etax numeric;
  v_once numeric;
  v_otax numeric;
  v_sub  numeric;
  v_tax  numeric;
  v_tot  numeric;
  v_pct  numeric;
  v_qid  uuid;
  v_q    public.quotations%rowtype;
  v_tp   numeric;
  v_tadj boolean;
  v_qterm int;
  v_msub numeric;
  v_span numeric;
  v_even boolean;
  v_qt   jsonb;
  v_month boolean;
  v_terms jsonb;
  v_ent  public.billing_entities%rowtype;
  v_ect  public.client_contacts%rowtype;
  v_on   date := public.doc_day_of(p_deal ->> 'date');
begin
  if not public.allowed('clients.documents') then
    return jsonb_build_object('error', 'not-allowed');
  end if;
  /* The letter's own date (2026-11-12, the user: a letter may be
     backdated): its reference's month, the SST and the rate in force, and
     the quotation still standing on that day; today where none is chosen. */
  if v_on is not null and not public.doc_day_ok(v_on) then return jsonb_build_object('error', 'bad-date'); end if;
  v_on := coalesce(v_on, (timezone(public.agency_tz(), now()))::date);
  if p_client is null or p_services is null or array_length(p_services, 1) is null then
    return jsonb_build_object('error', 'no-lines');
  end if;

  select * into cl from public.clients where id = p_client;
  if cl.id is null then return jsonb_build_object('error', 'no-client'); end if;

  -- Bill to (2026-10-29): a billing entity of this client other than its
  -- main, named in the deal, is the one the letter bills: its registered
  -- name, numbers, address and finance email stand in for the client's in
  -- the snapshot, and its billing contact is the letter's Attn where one is
  -- set and live. None named is the main entity, the client's own billing.
  if nullif(btrim(coalesce(p_deal ->> 'entity', '')), '') is not null then
    if (p_deal ->> 'entity') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      return jsonb_build_object('error', 'bad-entity');
    end if;
    select e.* into v_ent from public.billing_entities e
      join public.client_entities ce on ce.entity_id = e.id and ce.client_id = p_client
     where e.id = (p_deal ->> 'entity')::uuid;
    if v_ent.id is null then return jsonb_build_object('error', 'bad-entity'); end if;
    if coalesce(btrim(v_ent.legal_name), '') = '' or coalesce(btrim(v_ent.company_no), '') = ''
       or coalesce(btrim(v_ent.billing_address), '') = '' then
      return jsonb_build_object('error', 'entity-incomplete');
    end if;
    cl.legal_name := v_ent.legal_name; cl.company_no := v_ent.company_no;
    cl.company_no_old := v_ent.company_no_old; cl.tin := v_ent.tin; cl.sst_no := v_ent.sst_no;
    cl.finance_email := v_ent.finance_email; cl.billing_address := v_ent.billing_address;
  end if;

  -- The letter's own terms, one point a line, kept with what it was issued
  -- with and printed under TERMS after the term and the validity
  -- (2026-10-23): ten at most, each 1 to 400 characters.
  v_terms := coalesce((select jsonb_agg(btrim(t)) from jsonb_array_elements_text(
               case when jsonb_typeof(p_deal -> 'terms') = 'array' then p_deal -> 'terms' else '[]'::jsonb end) t
             where btrim(t) <> ''), '[]'::jsonb);
  if jsonb_array_length(v_terms) > 10
     or exists (select 1 from jsonb_array_elements_text(v_terms) t where length(t) > 400) then
    return jsonb_build_object('error', 'bad-terms');
  end if;

  -- The Client ID is what the serial is built from, so there is no letter
  -- without one. Staff enter it on the record; nothing invents it. A typed
  -- reference needs no code, because nothing is being built.
  v_no := nullif(btrim(coalesce(p_serial, '')), '');
  if v_no is null and coalesce(btrim(cl.client_code), '') = '' then
    return jsonb_build_object('error', 'no-client-code');
  end if;

  -- The same submission, pressed twice, is one letter. Answered before any
  -- number is reserved, so a double click cannot spend a serial either.
  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.client_documents
      where client_id = p_client and idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
    end if;
  end if;

  -- A typed reference is checked before anything is written: the same shape
  -- the Register accepts, and refused where a document still holds it.
  if v_no is not null then
    if v_no !~ '^[A-Za-z0-9/._-]{3,40}$' then
      return jsonb_build_object('error', 'serial-shape');
    end if;
    if public.serial_taken(v_no) then
      return jsonb_build_object('error', 'serial-taken');
    end if;
  end if;

  -- Every id must be this client's own live line, and in a state this letter
  -- may carry: To quote always, Confirmed only on a deliberate renewal.
  select count(*) into v_bad from unnest(p_services) s(id)
    left join public.client_services cs
      on cs.id = s.id and cs.client_id = p_client and cs.archived_at is null
    where cs.id is null
       or (cs.state = 'confirmed' and not p_renewal)
       or cs.state not in ('quoted', 'confirmed');
  if v_bad > 0 then return jsonb_build_object('error', 'bad-lines'); end if;

  -- The lines are held while this letter is made (2026-11-07): two
  -- presses on the same lines take them in turn, so the second reads the
  -- first one's letter below and is refused, never a second live letter.
  perform 1 from public.client_services where id = any(p_services) order by id for update;

  -- A line already on a live letter is not offered again by accident. The way
  -- through is to void that letter, or to name it as the one being replaced.
  select count(*) into v_bad
    from public.client_document_services m
    join public.client_documents d on d.id = m.document_id
   where m.service_id = any(p_services)
     and d.voided_at is null
     and d.superseded_by is null
     and d.verified_at is null
     and (p_replaces is null or d.id <> p_replaces);
  if v_bad > 0 then return jsonb_build_object('error', 'already-quoted'); end if;

  if p_replaces is not null then
    -- The letter replaced is held while it is read (2026-11-08, audit 5):
    -- two Replace presses at once on one letter, ticking different lines,
    -- each read it live and both issued. The second now waits and reads it
    -- replaced.
    select * into v_old from public.client_documents
      where id = p_replaces and client_id = p_client
      for update;
    if v_old.id is null then return jsonb_build_object('error', 'no-replaces'); end if;
    if v_old.verified_at is not null then return jsonb_build_object('error', 'replaces-verified'); end if;
    -- A letter already replaced, or void, is no longer the live one: a
    -- second Replace would leave two letters on its lines (2026-11-07).
    if v_old.superseded_by is not null then return jsonb_build_object('error', 'superseded'); end if;
    if v_old.voided_at is not null then return jsonb_build_object('error', 'voided'); end if;
  end if;

  select * into ct from public.client_contacts
    where client_id = p_client and archived_at is null
    order by (id = cl.bill_contact_id) desc, is_primary desc, name limit 1;
  -- The brand's billing contact for the entity billed (the one named, else
  -- its primary): its own choice, else the entity's shared one, else its
  -- live main contact (2026-10-31).
  v_ect := public.entity_contact(coalesce(v_ent.id, public.client_main_entity(p_client)), p_client);
  if v_ect.id is not null then ct := v_ect; end if;
  select * into me from public.team_members where auth_user_id = auth.uid() and active limit 1;

  -- A letter is signed by a person. issued_by is this row's name, so a team
  -- row named "Superadmin" printed that word under the issuer's name on a client's
  -- letterhead. Refuse rather than draw a permission as a signatory.
  if not public.issuer_name_ok(me.name) then
    return jsonb_build_object('error', 'issuer-name', 'name', coalesce(me.name, ''));
  end if;

  -- The snapshot is built from the stored rows, never from what the browser
  -- sent: the words on a letter are the words the record held at that moment.
  select jsonb_agg(jsonb_build_object(
           'label', cs.label, 'unit', coalesce(cs.unit, ''), 'note', coalesce(cs.note, ''),
           'detail', coalesce(cs.detail, ''), 'state', cs.state,
           'qty', cs.qty, 'rate', cs.rate,
           'tenure', greatest(1, coalesce(cs.tenure, 1)),
           'start_on', coalesce(cs.start_on, ''),
           -- The line's own answer to whether its term prices it. Written into
           -- the snapshot because the letter is redrawn from it, and a letter
           -- must print the same figure every time it is drawn. A snapshot
           -- taken before this key existed carries none, which money.js reads
           -- as on, so those letters redraw as they were issued.
           'term_adjust', coalesce(cs.term_adjust, false),
           -- And the percentage that tick applies, so a later rate card can
           -- never move a figure this letter printed. Null on a line quoted
           -- before the column existed, which money.js reads as that card.
           'term_pct', cs.term_pct,
           'tax', cl.sst_applies is not false,
           -- The line's own tax code and its rate as issued (2026-10-22);
           -- none is the client's SST, as before.
           'tax_code', cs.tax_code,
           'tax_pct', (select t.rate from public.tax_codes t where t.id = cs.tax_code_id),
           'service_id', cs.id)
           order by cs.created_at)
    into v_lines
    from public.client_services cs
   where cs.id = any(p_services);
  if v_lines is null then return jsonb_build_object('error', 'no-lines'); end if;
  /* A line's tax code is one the team holds and offers (2026-10-22). */
  if exists (select 1 from public.client_services cs
              where cs.id = any(p_services) and cs.tax_code is not null
                and not exists (select 1 from public.tax_codes t where t.id = cs.tax_code_id and t.active)) then
    return jsonb_build_object('error', 'bad-tax');
  end if;

  /* The price is the database's (audit S4, 2026-10-10), worked as the
     letter draws it (js/documents.js priceOf, js/money.js rateFor): each
     line's rate with its term on it, rounded to the cent. Where every line
     of more than a month shares one term, those lines are priced by the
     month and times the term, and a line of one month is a one-off item
     with its own SST (2026-10-15: a one-off item beside them no longer
     turns the letter into one whole total); otherwise every line is its
     whole amount. SST at the rate in force today unless the client is
     exempt. The page's figures are kept only where they agree to the sen,
     so a line changed since the sheet opened, or a figure typed in a
     browser, is refused (`stale`) and the sheet reads the lines again. */
  select case when count(distinct greatest(1, coalesce(cs.tenure, 1)))
                     filter (where greatest(1, coalesce(cs.tenure, 1)) > 1) = 1
              then max(greatest(1, coalesce(cs.tenure, 1))) else 0 end
    into v_term
    from public.client_services cs where cs.id = any(p_services);
  /* A letter whose every line came from one quotation is priced as that
     quotation was (audit F, 2026-10-17), exactly as `quote_price` and
     `quote_adjust` total it (2026-10-17, the review's finding 7): a line
     the quotation bills by the month (`quotation_offer` ticks its term) is
     a monthly line whatever months Build quote gave it, its percentage
     taken once on their subtotal; a line with no term is one-off; SST at
     the quotation's rate. The page's figures are held to the same price
     (js/documents.js priceOf). */
  select case when count(*) filter (where cs.quotation_id is null) = 0
                   and count(distinct cs.quotation_id) = 1 then min(cs.quotation_id::text)::uuid end,
         coalesce(bool_and(greatest(1, coalesce(cs.tenure, 1)) = 1) filter (where not coalesce(cs.term_adjust, false)), true),
         coalesce(max(cs.term_pct) filter (where coalesce(cs.term_adjust, false)), 0)
    into v_qid, v_tadj, v_tp
    from public.client_services cs where cs.id = any(p_services);
  /* Only while the quotation still stands (2026-10-17, the review's
     finding 2): unexpired by Malaysia's day and not removed. A renewal, or a
     letter replacing one after the quotation lapsed, is priced on today's
     rates, as any other letter. */
  if v_qid is not null and v_tadj and not coalesce(p_renewal, false) then
    select * into v_q from public.quotations q
     where q.id = v_qid and q.removed_at is null
       and q.valid_until >= v_on;
  end if;
  if v_q.id is not null then
    /* As quote_adjust totals it: the monthly lines' subtotal of quantity ×
       rate, the percentage once on it; where every one runs the quotation's
       term, a month's excl. SST, its SST rounded once, times the term; where
       Build quote gave a line months of its own, the whole span (each line's
       amount × its months) with the percentage and SST taken once on it.
       One-off lines and their SST apart. */
    v_qterm := greatest(1, coalesce((v_q.totals->>'term')::int, 1));
    v_pct := case when cl.sst_applies is false then 0
                  else coalesce((v_q.totals->>'sst_pct')::numeric, 0) end;
    /* The lines as the quotation reads them (a line with its term ticked is
       monthly, on its own months), totalled by the one calculation every
       quotation shares (2026-10-18). */
    v_qt := public.quote_totals(
      (select coalesce(jsonb_agg(jsonb_build_object(
                'basis', case when coalesce(cs.term_adjust, false) then 'month' else 'once' end,
                'qty', coalesce(cs.qty, 0), 'rate', coalesce(cs.rate, 0),
                'months', greatest(1, coalesce(cs.tenure, 1)),
                /* each line its own percentage, as the quotation priced it
                   (2026-11-24); one with none takes the largest held */
                'pct', case when coalesce(cs.term_adjust, false) then cs.term_pct end,
                'sst', (select t.rate from public.tax_codes t where t.id = cs.tax_code_id))), '[]'::jsonb)
         from public.client_services cs where cs.id = any(p_services)),
      v_qterm, v_tp, v_pct);
    v_month := jsonb_typeof(v_qt->'month') = 'object';
    v_once := coalesce((v_qt->'once'->>'subtotal')::numeric, 0);
    v_otax := coalesce((v_qt->'once'->>'sst')::numeric, 0);
    if not v_month then
      v_sub := round(v_once, 2);
      v_tax := v_otax;
    elsif (v_qt->>'even')::boolean then
      v_each := (v_qt->'month'->>'excl')::numeric;
      v_etax := (v_qt->'month'->>'sst')::numeric;
      /* As the page totals it (js/documents.js quotePrice): a month incl.
         SST rounded, times the term, beside the one-off items incl. SST
         (2026-11-07: 1.5 × 333.33 for 12 months is 6,480.00, never
         6,479.94). */
      v_sub := round(round(v_each * v_qterm, 2) + v_once, 2);
      v_tax := v_etax * v_qterm + v_otax;
      v_tot := round(round(v_each + v_etax, 2) * v_qterm, 2) + round(v_once + v_otax, 2);
    else
      v_sub := (v_qt->>'span_excl')::numeric + round(v_once, 2);
      v_tax := (v_qt->>'span_incl')::numeric + round(v_once, 2) + v_otax - v_sub;
    end if;
    if not (v_month and (v_qt->>'even')::boolean) then v_tot := v_sub + v_tax; end if;
    /* The letter keeps what it was priced on, so a redraw prints the same:
       the quotation, its SST and its term (a snapshot with no `quote_term`
       was priced before this, and redraws as it was). */
    select jsonb_agg(l.e || jsonb_build_object('quotation_id', v_qid, 'quote_sst', v_pct, 'quote_term', v_qterm) order by l.n)
      into v_lines from jsonb_array_elements(v_lines) with ordinality l(e, n);
  else
    v_pct := case when cl.sst_applies is false then 0
                  else coalesce(public.app_setting('sst_pct', v_on), 0) end;
    /* Each line at its own SST rate (2026-10-22): its tax code's, else the
       client's. The SST is worked a rate at a time, rounded once each, so
       a letter on one rate prices as it always did. */
    with x as (
      select greatest(1, coalesce(cs.tenure, 1)) as n,
             coalesce(cs.qty, 0) *
             round(coalesce(cs.rate, 0) *
               case when cs.term_adjust is false then 1
                    when cs.term_pct is not null then 1 + cs.term_pct / 100
                    else case greatest(1, coalesce(cs.tenure, 1))
                           when 3 then 1 / 0.9 when 12 then 0.95 when 24 then 0.9 else 1 end
               end, 2) as v,
             coalesce((select t.rate from public.tax_codes t where t.id = cs.tax_code_id), v_pct) as r
        from public.client_services cs where cs.id = any(p_services)
    ), y as (
      select r,
             coalesce(sum(v) filter (where v_term > 0 and n = v_term), 0) as e,
             coalesce(sum(v * n) filter (where v_term = 0 or n <> v_term), 0) as o
        from x group by r
    )
    select coalesce(sum(e), 0), coalesce(sum(o), 0),
           coalesce(sum(round(e * r) / 100), 0), coalesce(sum(round(o * r) / 100), 0)
      into v_each, v_once, v_etax, v_otax
      from y;
    v_sub := round(v_each * greatest(v_term, 1), 2) + round(v_once, 2);
    v_tax := round(v_etax * greatest(v_term, 1), 2) + v_otax;
    v_tot := round(round(v_each + v_etax, 2) * greatest(v_term, 1), 2) + round(v_once + v_otax, 2);
  end if;
  if abs(coalesce(p_subtotal, -1) - v_sub) > 0.01 or abs(coalesce(p_tax, -1) - v_tax) > 0.01
     or abs(coalesce(p_total, -1) - v_tot) > 0.01 then
    return jsonb_build_object('error', 'stale', 'subtotal', v_sub, 'tax', v_tax, 'total', v_tot);
  end if;

  -- A typed reference spends no sequence number: the counter is the office's
  -- record of how many letters it has issued this month, and a person filling
  -- a gap by hand has not issued one more.
  if v_no is null then
    -- The month is Malaysian, because the office that numbers the letter is.
    v_ym := to_char(v_on, 'YYMM');

    -- The counter still advances on every automatic issue, and the upsert's
    -- row lock is what makes the scan below safe: a second issuer blocks here
    -- until the first has committed its letter, so the two never read the same
    -- gap as free. What the counter gives is a bound to scan within, not the
    -- number itself.
    insert into public.client_document_seq (client_id, ym, next_val)
         values (p_client, v_ym, 2)
    on conflict (client_id, ym)
      do update set next_val = public.client_document_seq.next_val + 1
      returning next_val - 1 into v_seq;

    -- The lowest free slot, not the counter's own value. A letter removed
    -- releases its reference (serial_taken stopped counting removed letters on
    -- 2026-09-20), and without this the automatic path still counted upward
    -- past the gap: a client whose first two letters were issued in testing
    -- and removed started at 03 for ever. The counter is at least the number
    -- of letters issued this month, so a free slot exists at or below it
    -- unless somebody has typed references over the same range by hand; the
    -- cap covers that and refuses rather than looping.
    --
    -- Two digits is the floor, not the ceiling: the hundredth letter of a month
    -- widens to three rather than wrapping. Not lpad(): Postgres pads AND
    -- truncates to the width it is given, so lpad('100', 2, '0') is '10' and the
    -- hundredth letter would collide with the tenth.
    v_try := 1;
    loop
      v_no := 'AQL/' || cl.client_code || '/' || v_ym ||
              case when v_try < 100 then lpad(v_try::text, 2, '0') else v_try::text end;
      exit when not public.serial_taken(v_no);
      v_try := v_try + 1;
      if v_try > greatest(v_seq, 1) + 200 then
        return jsonb_build_object('error', 'no-serial');
      end if;
    end loop;
  end if;

  insert into public.client_documents
    (client_id, kind, number, issued_at, market, subtotal, tax, total,
     bill_to, lines, issued_by, client_code, idem_key)
  values
    (p_client, 'offer', v_no, v_on,
     public.client_bill_market(cl.market, cl.bill_sgd),
     -- the database's own figures, never the page's: the sen allowed
     -- above is for the stale check alone (2026-11-24)
     round(v_sub, 2), round(v_tax, 2), round(v_tot, 2),
     jsonb_build_object(
       'name', coalesce(cl.name, ''), 'legal_name', coalesce(cl.legal_name, ''),
       'address', coalesce(cl.billing_address, ''), 'regno', coalesce(cl.company_no, ''),
       'regno_old', coalesce(cl.company_no_old, ''), 'tin', coalesce(cl.tin, ''),
       'sst_no', coalesce(cl.sst_no, ''), 'sst_applies', cl.sst_applies is not false,
       'contact', coalesce(ct.name, ''), 'contact_role', coalesce(ct.role, ''),
       'contact_salutation', coalesce(ct.salutation, ''),
       -- A Singapore client billed in RM: its market and the rate in force,
       -- so the letter reads its figure in S$ beside it, as issued.
       'market', coalesce(cl.market, 'MY'),
       'fx_sgd', case when cl.market = 'SG' and not cl.bill_sgd then public.app_setting('fx_sgd', v_on) end,
       'phone', coalesce(ct.phone, ''), 'email', coalesce(ct.email, ''),
       'finance_email', coalesce(cl.finance_email, ''),
       'client_code', cl.client_code,
       'entity_id', v_ent.id,
       'owner', coalesce(p_deal ->> 'owner', ''), 'source', coalesce(p_deal ->> 'source', ''),
       'industry', coalesce(p_deal ->> 'industry', ''), 'stage', coalesce(p_deal ->> 'stage', ''),
       'enquiry', coalesce(p_deal ->> 'enquiry', ''),
       'terms', v_terms,
       -- The validity is one of the points typed (2026-10-23): a letter
       -- sent with it in its terms prints none of its own.
       'terms_own', coalesce(p_deal ->> 'terms_own', '') = 'true'),
     v_lines, coalesce(me.name, who), cl.client_code, nullif(btrim(p_idem), ''))
  returning id into v_id;

  insert into public.client_document_services (document_id, service_id)
    select v_id, s.id from unnest(p_services) s(id)
    on conflict do nothing;

  if p_replaces is not null then
    update public.client_documents set superseded_by = v_id where id = p_replaces;
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.superseded', cl.name, v_old.number || ' replaced by ' || v_no);
  end if;

  select count(*) into v_n from public.client_document_services where document_id = v_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'document.issued', cl.name, v_no || ' · ' || v_n || ' line' || case when v_n = 1 then '' else 's' end);

  return jsonb_build_object('ok', true, 'id', v_id, 'number', v_no);
exception
  when unique_violation then
    -- Two presses that raced past the idempotency read: the loser reads the
    -- winner's letter back rather than making a second one.
    if coalesce(btrim(p_idem), '') <> '' then
      select * into v_old from public.client_documents
        where client_id = p_client and idem_key = btrim(p_idem) limit 1;
      if v_old.id is not null then
        return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
      end if;
    end if;
    -- A typed reference two people sent at once: the loser is told the
    -- reference is spent rather than that "two letters were issued at once",
    -- which names a cause they cannot act on.
    if nullif(btrim(coalesce(p_serial, '')), '') is not null then
      return jsonb_build_object('error', 'serial-taken');
    end if;
    return jsonb_build_object('error', 'clash');
end $$;

create or replace function public.issue_document(
  p_type      text,
  p_client    uuid,
  p_member    uuid,
  p_serial    text,
  p_issued_at date,
  p_title     text,
  p_recipient jsonb,
  p_body      jsonb,
  p_signatory jsonb,
  p_languages text[],
  p_idem      text,
  p_salutation text default null,
  p_signed    boolean default null,
  p_supplier  uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who     text := lower(auth.jwt() ->> 'email');
  t       public.doc_types%rowtype;
  cl      public.clients%rowtype;
  mb      public.team_members%rowtype;
  sp      public.suppliers%rowtype;
  me      public.team_members%rowtype;
  v_old   public.documents%rowtype;
  v_serial text;
  v_base  text;
  v_n     int;
  v_id    uuid;
  v_langs text[];
  v_signed boolean;
begin
  select * into t from public.doc_types where id = p_type and active;
  -- A letter's own date, backdated where chosen (2026-11-12): never before
  -- 14 Aug 2023 or after today; its reference follows it.
  if p_issued_at is not null and not public.doc_day_ok(p_issued_at) then return jsonb_build_object('error', 'bad-date'); end if;
  if t.id is null then return jsonb_build_object('error', 'no-type'); end if;
  -- A Quotation Cover opens every quotation's PDF; it is never issued on
  -- its own (QUOTATION COVER NOT ISSUED ALONE, 2026-11-25).
  if t.family = 'quote_cover' then return jsonb_build_object('error', 'not-issuable'); end if;
  if not public.register_may(t.family, 'work') then return jsonb_build_object('error', 'not-allowed'); end if;

  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.documents where idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'serial', v_old.serial);
    end if;
  end if;

  if t.family in ('quote_cover', 'client') then
    if p_client is null then return jsonb_build_object('error', 'no-client'); end if;
    select * into cl from public.clients where id = p_client;
    if cl.id is null then return jsonb_build_object('error', 'no-client'); end if;
  end if;
  if t.family = 'hr' then
    if p_member is null then return jsonb_build_object('error', 'no-member'); end if;
    select * into mb from public.team_members where id = p_member;
    if mb.id is null then return jsonb_build_object('error', 'no-member'); end if;
    if coalesce(btrim(mb.staff_code), '') = '' then return jsonb_build_object('error', 'no-staff-code'); end if;
  end if;
  if t.family = 'supplier' then
    if p_supplier is null then return jsonb_build_object('error', 'no-supplier'); end if;
    select * into sp from public.suppliers where id = p_supplier;
    if sp.id is null then return jsonb_build_object('error', 'no-supplier'); end if;
    /* The agreement carries its schedules (2026-10-18): who the supplier is,
       when it starts, the fee and at least one account. */
    if t.id = 'supplier_sca' and not public.sca_complete(p_body) then
      return jsonb_build_object('error', 'agreement-incomplete');
    end if;
  end if;

  -- Whether the letter leaves space to be signed is the sheet's tick
  -- (2026-10-01), else the type's own setting. A signed letter is signed by
  -- a person, never by a permission; an unsigned one may still name who
  -- issued it, held to the same test.
  v_signed := coalesce(p_signed, t.signed);
  if coalesce(btrim(p_signatory ->> 'name'), '') <> '' and not public.issuer_name_ok(p_signatory ->> 'name') then
    return jsonb_build_object('error', 'issuer-name', 'name', p_signatory ->> 'name');
  end if;
  if v_signed then
    if coalesce(btrim(p_signatory ->> 'name'), '') = '' then return jsonb_build_object('error', 'no-signatory'); end if;
    if not public.issuer_name_ok(p_signatory ->> 'name') then
      return jsonb_build_object('error', 'issuer-name', 'name', p_signatory ->> 'name');
    end if;
  end if;

  v_serial := nullif(btrim(coalesce(p_serial, '')), '');
  if v_serial is null then
    if t.family = 'quote_cover' then return jsonb_build_object('error', 'serial-required'); end if;
    if t.family in ('client', 'supplier') then
      if t.family = 'client' then
        if coalesce(btrim(cl.client_code), '') = '' then return jsonb_build_object('error', 'no-client-code'); end if;
        v_base := 'ACL/' || upper(btrim(cl.client_code));
      elsif t.id = 'supplier_sca' then
        v_base := 'AD/SCA/' || upper(btrim(sp.code));
      else
        v_base := 'ASL/' || upper(btrim(sp.code));
      end if;
      /* A Supplier Service Agreement is numbered by its month
         (AD/SCA/{Supplier ID}/{YYMM}{NN}, 2026-10-18); every other letter by
         its day. */
      v_base := v_base || '/' || to_char(coalesce(p_issued_at, (timezone(public.agency_tz(), now()))::date),
                                         case when t.id = 'supplier_sca' then 'YYMM' else 'YYMMDD' end);
      -- Two issuers on one client (or supplier) and day wait for each other
      -- here, so the second never reads the first one's number as free.
      perform pg_advisory_xact_lock(hashtext('acl:' || v_base));
      v_n := 1;
      loop
        v_serial := v_base || case when v_n < 10 then '0' else '' end || v_n;
        exit when not public.serial_taken(v_serial);
        v_n := v_n + 1;
        if v_n > 999 then return jsonb_build_object('error', 'no-serial'); end if;
      end loop;
    else
      v_base := 'ADHR/' || upper(mb.staff_code) || '/' || coalesce(t.code, 'GL') ||
                to_char(coalesce(p_issued_at, (timezone(public.agency_tz(), now()))::date), 'YYMM');
      -- Two issues for one colleague, kind and month wait for each other
      -- here, as a letter's do, so the second never takes the first's number
      -- (review 2026-11-24).
      perform pg_advisory_xact_lock(hashtext('adhr:' || v_base));
      v_serial := v_base; v_n := 1;
      while public.serial_taken(v_serial) loop
        v_n := v_n + 1; v_serial := v_base || '-' || v_n;
      end loop;
    end if;
  else
    if v_serial !~ '^[A-Za-z0-9/._-]{3,40}$' then return jsonb_build_object('error', 'serial-shape'); end if;
    if public.serial_taken(v_serial) then return jsonb_build_object('error', 'serial-taken'); end if;
  end if;

  v_langs := coalesce(p_languages, '{en}');
  if array_length(v_langs, 1) is null then v_langs := '{en}'; end if;

  select * into me from public.team_members where auth_user_id = auth.uid() and active limit 1;

  insert into public.documents
    (type_id, family, kind, serial, client_id, member_id, supplier_id, issued_at, title, salutation, closing,
     recipient, body, languages, signatory, signed, source, issued_by, idem_key)
  values
    (t.id, t.family, t.name, v_serial,
     case when t.family in ('hr', 'supplier') then null else p_client end,
     case when t.family = 'hr' then p_member else null end,
     case when t.family = 'supplier' then p_supplier else null end,
     coalesce(p_issued_at, (timezone(public.agency_tz(), now()))::date),
     coalesce(nullif(btrim(p_title), ''), t.title),
     coalesce(nullif(btrim(p_salutation), ''), t.salutation), t.closing,
     coalesce(p_recipient, '{}'::jsonb), coalesce(p_body, '{}'::jsonb), v_langs,
     case when coalesce(btrim(p_signatory ->> 'name'), '') <> '' then p_signatory else null end, v_signed, 'portal',
     coalesce(me.name, who), nullif(btrim(p_idem), ''))
  returning id into v_id;

  -- The record is told an HR letter was issued and nothing about whom: the
  -- Activity record is read by more people than HR is.
  if t.family = 'hr' then
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.issued', 'HR', t.name);
  else
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.issued', case when t.family = 'supplier' then sp.name else cl.name end, v_serial || ' · ' || t.name);
  end if;
  return jsonb_build_object('ok', true, 'id', v_id, 'serial', v_serial);
exception
  when unique_violation then
    if coalesce(btrim(p_idem), '') <> '' then
      select * into v_old from public.documents where idem_key = btrim(p_idem) limit 1;
      if v_old.id is not null then
        return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'serial', v_old.serial);
      end if;
    end if;
    return jsonb_build_object('error', 'serial-taken');
end $$;

create or replace function public.document_reissue(
  p_doc       uuid,
  p_issued_at date,
  p_title     text,
  p_recipient jsonb,
  p_body      jsonb,
  p_signatory jsonb,
  p_languages text[],
  p_salutation text,
  p_idem      text
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who    text := lower(auth.jwt() ->> 'email');
  d      public.documents%rowtype;
  v_old  public.documents%rowtype;
  me     public.team_members%rowtype;
  cl     public.clients%rowtype;
  v_id   uuid;
  v_langs text[];
begin
  select * into d from public.documents where id = p_doc;
  if p_issued_at is not null and not public.doc_day_ok(p_issued_at) then return jsonb_build_object('error', 'bad-date'); end if;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if d.source <> 'portal' then return jsonb_build_object('error', 'not-portal'); end if;
  if d.family = 'quote_cover' then return jsonb_build_object('error', 'not-issuable'); end if;
  if not public.register_may(d.family, 'work') then return jsonb_build_object('error', 'not-allowed'); end if;
  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.documents where idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'serial', v_old.serial);
    end if;
  end if;
  if exists (select 1 from public.documents
              where upper(serial) = upper(d.serial) and voided_at is null and id <> d.id) then
    return jsonb_build_object('error', 'not-current');
  end if;
  if d.signed then
    if coalesce(btrim(p_signatory ->> 'name'), '') = '' then return jsonb_build_object('error', 'no-signatory'); end if;
    if not public.issuer_name_ok(p_signatory ->> 'name') then
      return jsonb_build_object('error', 'issuer-name', 'name', p_signatory ->> 'name');
    end if;
  end if;
  v_langs := coalesce(p_languages, d.languages, '{en}');
  if array_length(v_langs, 1) is null then v_langs := '{en}'; end if;
  select * into me from public.team_members where auth_user_id = auth.uid() and active limit 1;

  if d.voided_at is null then
    update public.documents set voided_at = now(), voided_by = who, void_reason = 'Reissued' where id = d.id;
  end if;
  insert into public.documents
    (type_id, family, kind, serial, client_id, member_id, supplier_id, issued_at, title, salutation, closing,
     recipient, body, languages, signatory, signed, source, issued_by, idem_key, replaces)
  values
    (d.type_id, d.family, d.kind, d.serial, d.client_id, d.member_id, d.supplier_id,
     coalesce(p_issued_at, d.issued_at, (timezone(public.agency_tz(), now()))::date),
     coalesce(nullif(btrim(p_title), ''), d.title),
     coalesce(nullif(btrim(p_salutation), ''), d.salutation), d.closing,
     coalesce(p_recipient, d.recipient), coalesce(p_body, d.body), v_langs,
     case when d.signed then p_signatory else null end, d.signed, 'portal',
     coalesce(me.name, who), nullif(btrim(p_idem), ''), d.id)
  returning id into v_id;

  if d.client_id is not null then select * into cl from public.clients where id = d.client_id; end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'document.reissued',
          case when d.family = 'hr' then 'HR' else coalesce(cl.name, (select s.name from public.suppliers s where s.id = d.supplier_id), d.recipient ->> 'name', '') end,
          case when d.family = 'hr' then d.kind else d.serial || ' · ' || d.kind end);
  return jsonb_build_object('ok', true, 'id', v_id, 'serial', d.serial);
exception
  when unique_violation then
    return jsonb_build_object('error', 'serial-taken');
end $$;

create or replace function public.register_add(
  p_serial    text,
  p_family    text,
  p_kind      text,
  p_issued_at date,
  p_recipient text,
  p_client    uuid,
  p_note      text,
  p_file_url  text,
  p_member    uuid default null,
  p_supplier  uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who   text := lower(auth.jwt() ->> 'email');
  me    public.team_members%rowtype;
  v_serial text := nullif(btrim(coalesce(p_serial, '')), '');
  v_fam text := coalesce(nullif(btrim(p_family), ''), 'other');
  v_id  uuid;
  cl    public.clients%rowtype;
  tm    public.team_members%rowtype;
  sp    public.suppliers%rowtype;
begin
  if v_fam not in ('quote_cover', 'client', 'hr', 'other', 'supplier') then return jsonb_build_object('error', 'bad-family'); end if;
  if not public.register_may(v_fam, 'work') then return jsonb_build_object('error', 'not-allowed'); end if;
  -- A Quotation Cover is the first page of every quotation, never a
  -- document added on its own (QUOTATION COVER NOT ADDED, 2026-11-26).
  if v_fam = 'quote_cover' then return jsonb_build_object('error', 'not-issuable'); end if;
  if v_serial is null then return jsonb_build_object('error', 'serial-required'); end if;
  if v_serial !~ '^[A-Za-z0-9/._-]{3,40}$' then return jsonb_build_object('error', 'serial-shape'); end if;
  if public.serial_taken(v_serial) then return jsonb_build_object('error', 'serial-taken'); end if;
  if coalesce(btrim(p_kind), '') = '' then return jsonb_build_object('error', 'kind-required'); end if;
  if v_fam = 'hr' then
    if p_member is not null then select * into tm from public.team_members where id = p_member; end if;
  elsif v_fam = 'supplier' then
    if p_supplier is not null then select * into sp from public.suppliers where id = p_supplier; end if;
    if sp.id is null then return jsonb_build_object('error', 'no-supplier'); end if;
  elsif p_client is not null then
    select * into cl from public.clients where id = p_client;
  end if;
  select * into me from public.team_members where auth_user_id = auth.uid() and active limit 1;

  insert into public.documents
    (family, kind, serial, client_id, member_id, supplier_id, issued_at, recipient, signed, source, file_url, note, issued_by)
  values
    (v_fam, btrim(p_kind), v_serial, cl.id, tm.id, sp.id, coalesce(p_issued_at, (now() at time zone public.agency_tz())::date),
     jsonb_build_object('name', coalesce(btrim(p_recipient), '')), false, 'manual',
     nullif(btrim(p_file_url), ''), nullif(btrim(p_note), ''), coalesce(me.name, who))
  returning id into v_id;

  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'register.added',
          case when v_fam = 'hr' then 'HR' else coalesce(cl.name, sp.name, sp.code, btrim(p_recipient), '') end,
          case when v_fam = 'hr' then btrim(p_kind) else v_serial || ' · ' || btrim(p_kind) end);
  return jsonb_build_object('ok', true, 'id', v_id, 'serial', v_serial);
exception
  when unique_violation then return jsonb_build_object('error', 'serial-taken');
end $$;

create or replace function public.get_portal(p_client uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who text := lower(auth.jwt() ->> 'email');
  cid uuid;
  cl  public.clients%rowtype;
  me  public.client_contacts%rowtype;
begin
  if who is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  select p into cid from public.portal_clients() p
    order by (p = p_client) desc nulls last limit 1;
  if cid is null then return jsonb_build_object('error', 'no-access'); end if;
  select * into cl from public.clients where id = cid;
  select * into me from public.client_contacts
    where client_id = cid and portal_access and archived_at is null and auth_user_id = auth.uid()
    order by is_primary desc limit 1;

  return jsonb_build_object(
    'clients', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name) order by c.name)
      from public.clients c where c.id in (select public.portal_clients())), '[]'::jsonb),
    'client', jsonb_build_object(
      'id', cl.id, 'name', cl.name, 'legal_name', cl.legal_name, 'company_no', cl.company_no,
      'billing_address', cl.billing_address, 'market', coalesce(cl.market, 'MY'),
      'bill_market', public.client_bill_market(cl.market, cl.bill_sgd),
      'sst_applies', coalesce(cl.sst_applies, true), 'stage', cl.stage, 'owner', (select x.name from public.team_members x where x.id = public.client_rep(cl.id, 'service')),
      'industry', cl.industry, 'website', cl.website, 'logo_url', cl.logo_url),
    'me', jsonb_build_object('id', me.id, 'name', me.name, 'email', me.email,
      'lang', case when me.lang = 'zh' then 'zh' else 'en' end),
    'contacts', coalesce((
      select jsonb_agg(jsonb_build_object('id', k.id, 'name', k.name, 'role', k.role, 'phone', k.phone,
        'email', k.email, 'is_primary', k.is_primary, 'portal_access', k.portal_access)
        order by k.is_primary desc, k.name)
      from public.client_contacts k where k.client_id = cid and k.archived_at is null), '[]'::jsonb),
    'services', coalesce((
      -- `term_adjust` travels with the line, because the client's page works
      -- the figure out the same way the console and the letter do and must
      -- never print a different one.
      select jsonb_agg(jsonb_build_object('id', s.id, 'label', s.label, 'unit', s.unit, 'qty', s.qty,
        'rate', s.rate, 'tenure', s.tenure, 'start_on', s.start_on, 'state', s.state, 'note', s.note,
        'term_adjust', coalesce(s.term_adjust, false), 'term_pct', s.term_pct)
        order by s.created_at)
      from public.client_services s
      where s.client_id = cid and s.archived_at is null and s.state in ('quoted', 'confirmed')), '[]'::jsonb),
    'documents', coalesce((
      select jsonb_agg(jsonb_build_object('id', d.id, 'kind', d.kind, 'number', d.number,
        'issued_at', d.issued_at, 'market', d.market, 'subtotal', d.subtotal, 'tax', d.tax,
        'total', d.total, 'bill_to', d.bill_to, 'lines', d.lines, 'issued_by', d.issued_by)
        order by d.created_at desc)
      from public.client_documents d where d.client_id = cid and d.voided_at is null), '[]'::jsonb),
    'requests', coalesce((
      select jsonb_agg(jsonb_build_object('id', r.id, 'kind', r.kind, 'service_label', r.service_label,
        'note', r.note, 'state', r.state, 'fee', r.fee, 'reply', r.reply,
        'created_at', r.created_at, 'withdrawn_at', r.withdrawn_at, 'request_ref', r.request_ref)
        order by r.created_at desc)
      from public.client_requests r where r.client_id = cid), '[]'::jsonb),
    'review', case
      when cl.review_hidden is not true
       and exists (select 1 from public.batches b where b.client_id = cid and b.published)
      then jsonb_build_object('token', cl.access_token) end,
    'campaigns', coalesce((
      -- Where each campaign stands (2026-11-25): its booked creators'
      -- steps, never who they are, and the next shoot ahead.
      select jsonb_agg(jsonb_build_object('id', m.id, 'title', m.title, 'title_zh', m.title_zh,
        'state', m.state, 'deadline', m.deadline, 'token', m.access_token,
        'push_format', m.push_format,
        'booked', coalesce((select jsonb_agg(o.state order by o.position, o.added_at)
          from public.campaign_options o where o.campaign_id = m.id
           and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'reviewing',
                           'changes', 'scheduled', 'posted', 'completed')), '[]'::jsonb),
        'next_shoot', (select min(o.visit_date) from public.campaign_options o
          where o.campaign_id = m.id and o.state in ('confirmed', 'pending_visit')
            and o.visit_date >= (now() at time zone public.agency_tz())::date))
        order by m.created_at desc)
      from public.campaigns m where m.client_id = cid and m.state <> 'draft'), '[]'::jsonb),
    'access', coalesce((
      select jsonb_agg(jsonb_build_object('name', k.name, 'email', k.email) order by k.is_primary desc, k.name)
      from public.client_contacts k
      where k.client_id = cid and k.archived_at is null and k.portal_access), '[]'::jsonb)
  );
end $$;

create or replace function public.template_render(p_key text, p_lang text, p_record uuid default null,
  p_values jsonb default null, p_at date default null, p_strict boolean default false)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_at date := coalesce(p_at, (now() at time zone public.agency_tz())::date);
  v_t public.templates;
  v_fb boolean := false;
  v_vals jsonb;
  v_k text;
  v_n text;
  v_s jsonb;
  v_b jsonb;
  v_miss jsonb;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p_lang is null or p_lang not in ('en', 'zh') then return jsonb_build_object('error', 'bad-lang'); end if;
  if p_values is not null and jsonb_typeof(p_values) <> 'object' then return jsonb_build_object('error', 'bad-values'); end if;
  v_t := public.template_in_force(p_key, p_lang, v_at);
  if v_t.id is null and p_lang <> 'en' then
    v_t := public.template_in_force(p_key, 'en', v_at);
    v_fb := v_t.id is not null;
  end if;
  if v_t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  v_vals := public.template_values(v_t.kind, p_record);
  if v_vals ? 'error' then return v_vals; end if;
  for v_k in select jsonb_object_keys(coalesce(p_values, '{}'::jsonb)) loop
    v_n := public.template_norm(v_k);
    if not (v_n = any (coalesce(public.template_fields(v_t.kind), '{}'::text[]))) then
      return jsonb_build_object('error', 'unknown-field', 'field', '{' || v_k || '}',
        'fields', to_jsonb(public.template_fields(v_t.kind)));
    end if;
    if not (v_vals ? v_n) and jsonb_typeof(p_values -> v_k) in ('string', 'number') then
      v_vals := v_vals || jsonb_build_object(v_n, p_values ->> v_k);
    end if;
  end loop;
  v_s := public.template_fill(v_t.subject, v_vals);
  v_b := public.template_fill(v_t.body, v_vals);
  select coalesce(jsonb_agg(y.n order by y.f), '[]'::jsonb) into v_miss
    from (select x.n, min(x.o) as f
            from jsonb_array_elements_text((v_s -> 'missing') || (v_b -> 'missing')) with ordinality as x (n, o)
           group by x.n) y;
  if p_strict and jsonb_array_length(v_miss) > 0 then
    return jsonb_build_object('error', 'missing-field', 'fields', v_miss);
  end if;
  return jsonb_build_object('ok', true, 'id', v_t.id, 'key', v_t.key, 'lang', v_t.language, 'fallback', v_fb,
    'version', v_t.version, 'effective_from', v_t.effective_from, 'sample', v_t.sample,
    'subject', v_s ->> 'text', 'subject_html', v_s ->> 'html', 'text', v_b ->> 'text', 'html', v_b ->> 'html',
    'missing', v_miss);
end $$;

create or replace function public.templates_list(p_key text default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object('ok', true, 'fields', public.template_fields_all(), 'rows', coalesce((
    select jsonb_agg(jsonb_build_object('id', x.id, 'key', x.key, 'kind', x.kind, 'lang', x.language,
      'version', x.version, 'status', x.status, 'effective_from', x.effective_from, 'sample', x.sample,
      'in_force', x.id = (public.template_in_force(x.key, x.language, v_today)).id,
      'subject', x.subject, 'body', x.body, 'placeholders', to_jsonb(x.placeholders),
      'created_by_id', x.created_by_id, 'created_by', cm.name, 'created_at', x.created_at, 'updated_at', x.updated_at,
      'published_by_id', x.published_by_id, 'published_by', pm.name, 'published_at', x.published_at)
      order by x.key, array_position(array['en', 'zh'], x.language), x.version desc)
      from public.templates x
      left join public.team_members cm on cm.id = x.created_by_id
      left join public.team_members pm on pm.id = x.published_by_id
     where p_key is null or x.key = p_key), '[]'::jsonb));
end $$;

create or replace function public.template_publish(p_id uuid, p_from date)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_today date := (now() at time zone public.agency_tz())::date;
  v_row public.templates;
  v_cur date;
begin
  if me.id is null or not public.ops_granted('team.settings', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into v_row from public.templates x where x.id = p_id;
  if v_row.id is null then return jsonb_build_object('error', 'not-found'); end if;
  perform pg_advisory_xact_lock(hashtext('templates:' || v_row.key));
  select * into v_row from public.templates x where x.id = p_id for update;
  if v_row.status = 'live' then return jsonb_build_object('error', 'live'); end if;
  if p_from is null then return jsonb_build_object('error', 'bad-date'); end if;
  if p_from < v_today then return jsonb_build_object('error', 'past'); end if;
  select max(x.effective_from) into v_cur from public.templates x
   where x.key = v_row.key and x.language = v_row.language and x.status = 'live';
  if v_cur is not null and p_from < v_cur then return jsonb_build_object('error', 'before-current', 'from', v_cur); end if;
  update public.templates x set status = 'live', effective_from = p_from, published_by_id = me.id, published_at = now()
   where x.id = v_row.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Templates',
    v_row.key || ' (' || case v_row.language when 'zh' then '中文' else 'English' end || ') · Version ' || v_row.version
      || ' live from ' || public.register_day(p_from));
  return jsonb_build_object('ok', true, 'id', v_row.id, 'version', v_row.version, 'effective_from', p_from);
end $$;

create or replace function public.brn_check(p_no text, p_market text default 'MY', p_kind text default null)
returns text
language plpgsql stable set search_path = public as $$
declare
  v      text := upper(regexp_replace(coalesce(p_no, ''), '[\s-]+', '', 'g'));
  v_uen  boolean;
  v_code text;
begin
  v_uen := v ~ '^([0-9]{8,9}[A-Z]|[TSR][0-9]{2}[A-Z]{2}[0-9]{4}[A-Z])$';
  if (p_market is null or p_market = 'SG') and v_uen then return null; end if;
  if v !~ '^[0-9]{12}$' then return 'bad-brn'; end if;
  if left(v, 4)::int < 1900 or left(v, 4)::int > extract(year from (now() at time zone public.agency_tz()))::int then
    return 'bad-brn';
  end if;
  v_code := substr(v, 5, 2);
  if v_code not in ('01', '02', '03', '04') then return 'bad-brn'; end if;
  if p_kind = 'soleprop' and v_code <> '03' then return 'brn-kind'; end if;
  if p_kind = 'company' and v_code = '03' then return 'brn-kind'; end if;
  return null;
end $$;

create or replace function public.quote_intake_check(p jsonb, p_fields text[])
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_kind text := nullif(btrim(coalesce(p->>'kind', '')), '');
  v_brn  text := regexp_replace(coalesce(p->>'brn', ''), '[\s-]+', '', 'g');
  v_code text;
  v_legal text := upper(btrim(regexp_replace(coalesce(p->>'legal', ''), '\s+', ' ', 'g')));
  v_site text := btrim(coalesce(p->>'website', ''));
  v_none boolean := coalesce(p->>'no_site', '') = 'true';
  v_plat text := nullif(btrim(coalesce(p->>'platform', '')), '');
  v_hdl  text := regexp_replace(btrim(coalesce(p->>'handle', '')), '^@+', '');
  v_ind  text := nullif(btrim(coalesce(p->>'industry', '')), '');
  v_start text := nullif(btrim(coalesce(p->>'commence', '')), '');
  v_on_t text := nullif(btrim(coalesce(p->>'commence_on', '')), '');
  v_on   date;
  v_out  jsonb := '{}'::jsonb;
begin
  if p_fields is null or jsonb_typeof(coalesce(p, 'null'::jsonb)) <> 'object' then return jsonb_build_object('error', 'bad-request'); end if;
  if 'registration' = any(p_fields) then
    if v_kind is null or v_kind not in ('company', 'soleprop') then return jsonb_build_object('error', 'bad-kind'); end if;
    v_code := public.brn_check(v_brn, 'MY', v_kind);
    if v_code = 'bad-brn' then return jsonb_build_object('error', 'bad-brn'); end if;
    if v_code = 'brn-kind' then
      return jsonb_build_object('error', 'brn-kind', 'kind', case when v_kind = 'company' then 'soleprop' else 'company' end);
    end if;
    if length(v_legal) < 2 or length(v_legal) > 150 or v_legal ~* public.quote_link_like() then
      return jsonb_build_object('error', 'bad-legal');
    end if;
    v_out := v_out || jsonb_build_object('kind', v_kind, 'brn', v_brn, 'legal', v_legal);
  end if;
  if 'industry' = any(p_fields) then
    if v_ind is null then return jsonb_build_object('error', 'need-industry'); end if;
    if not exists (select 1 from public.industries i where i.name = v_ind) then return jsonb_build_object('error', 'bad-industry'); end if;
    v_out := v_out || jsonb_build_object('industry', v_ind);
  end if;
  if 'online' = any(p_fields) then
    if v_site <> '' then
      if v_site !~* '^https?://' then v_site := 'https://' || v_site; end if;
      if length(v_site) > 200 or v_site !~* '^https?://[^\s"''<>`\\/]+\.[^\s"''<>`\\]{2,}$' then
        return jsonb_build_object('error', 'bad-site');
      end if;
      v_none := false;
    elsif not v_none then
      return jsonb_build_object('error', 'need-site');
    end if;
    if v_hdl <> '' then
      if v_plat is null or v_plat not in ('instagram', 'facebook', 'tiktok', 'xhs') then return jsonb_build_object('error', 'bad-platform'); end if;
      if v_hdl !~ '^[A-Za-z0-9._-]{1,60}$' then return jsonb_build_object('error', 'bad-handle'); end if;
    elsif v_none then
      return jsonb_build_object('error', 'need-handle');
    end if;
    v_out := v_out || jsonb_build_object('website', nullif(v_site, ''), 'no_site', v_none,
      'platform', case when v_hdl <> '' then v_plat end, 'handle', case when v_hdl <> '' then '@' || v_hdl end);
  end if;
  if 'commence' = any(p_fields) then
    if v_start is null or v_start not in ('1_3', '3_6', '6_plus') then return jsonb_build_object('error', 'bad-commence'); end if;
    if v_on_t is not null then
      if v_on_t !~ '^\d{4}-\d{2}-\d{2}$' then return jsonb_build_object('error', 'bad-start-date'); end if;
      begin
        v_on := v_on_t::date;
      exception when others then
        return jsonb_build_object('error', 'bad-start-date');
      end;
      if v_on < (now() at time zone public.agency_tz())::date or v_on > date '2099-12-31' then
        return jsonb_build_object('error', 'bad-start-date');
      end if;
    end if;
    v_out := v_out || jsonb_build_object('commence', v_start, 'commence_on', v_on);
  end if;
  return jsonb_strip_nulls(v_out);
end $$;

create or replace function public.privacy_retention(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_wa integer := 0; v_act integer := 0; v_hc integer := 0; v_hl integer := 0; v_lt integer := 0; v_vt integer := 0; v_vd integer := 0; v_vc integer := 0; v_hm integer := 0; v_qc integer := 0;
  v_fh integer := 0; v_qh integer := 0; v_vn integer := 0;
  v_today date := (p_now at time zone public.agency_tz())::date;
  v_keep integer := coalesce(public.app_setting('health_keep_months', (p_now at time zone public.agency_tz())::date), 24)::integer;
  v_left integer := coalesce(public.app_setting('health_leaver_months', (p_now at time zone public.agency_tz())::date), 6)::integer;
  v_act_routine integer := greatest(coalesce(public.app_setting('activity_routine_months', (p_now at time zone public.agency_tz())::date), 3)::integer, 1);
  v_act_keep integer := greatest(coalesce(public.app_setting('activity_keep_months', (p_now at time zone public.agency_tz())::date), 36)::integer, 12);
  v_act_r integer := 0;
  v_gone uuid[];
begin
  update public.wa_outbox o
     set to_number = '', to_name = null, params = '[]'::jsonb, button = null
   where o.created_at < p_now - interval '12 months'
     and o.state not in ('queued', 'sending')
     and (o.to_number <> '' or o.to_name is not null or o.params <> '[]'::jsonb or o.button is not null);
  get diagnostics v_wa = row_count;
  /* The Activity record by kind (ACTIVITY KEPT BY KIND, 2026-11-28): a
     routine entry (`activity_routine`) after the routine months, every
     entry after the key months, each a setting. */
  delete from public.activity_log a
   where public.activity_routine(a.action) and a.created_at < p_now - make_interval(months => v_act_routine);
  get diagnostics v_act_r = row_count;
  delete from public.activity_log a where a.created_at < p_now - make_interval(months => v_act_keep);
  get diagnostics v_act = row_count;
  v_act := v_act + v_act_r;
  delete from public.health_checkins k where k.half < v_today - make_interval(months => v_keep);
  get diagnostics v_hc = row_count;
  delete from public.health_moods k where k.period_start < v_today - make_interval(months => v_keep);
  get diagnostics v_hm = row_count;
  v_hc := v_hc + v_hm;
  select coalesce(array_agg(m.id), '{}') into v_gone from public.team_members m
   where not m.active and coalesce(m.removed_at, m.expired_at, m.inactive_at) < p_now - make_interval(months => v_left);
  if array_length(v_gone, 1) > 0 then
    delete from public.health_checkins k where k.team_member_id = any(v_gone);
    get diagnostics v_hl = row_count;
    delete from public.health_moods k where k.team_member_id = any(v_gone);
    get diagnostics v_hm = row_count;
    v_hl := v_hl + v_hm;
    delete from public.health_talks t where t.team_member_id = any(v_gone) or t.with_id = any(v_gone);
    delete from public.health_log l where l.team_member_id = any(v_gone);
    delete from public.health_consents c where c.team_member_id = any(v_gone);
  end if;
  -- A caller's address against a link's passcode, once it has had nothing
  -- to say for 30 days and holds no lock (audit 2026-10-18, item 14).
  delete from public.link_tries t
   where greatest(t.last_at, coalesce(t.ok_at, t.last_at)) < p_now - interval '30 days'
     and coalesce(t.locked_until, t.last_at) < p_now;
  get diagnostics v_lt = row_count;
  -- A caller's address against /verify/, once its hour began 30 days ago.
  delete from public.verify_tries v where v.since < p_now - interval '30 days';
  get diagnostics v_vt = row_count;
  -- And against /verify/'s details (VERIFY DETAILS, 2026-11-20).
  delete from public.verify_detail_tries v where v.since < p_now - interval '30 days';
  get diagnostics v_vd = row_count;
  -- And a check's address hash, 30 days after its day; the document's
  -- total stays (VERIFY CHECKS COUNTED, 2026-11-21).
  delete from public.verify_checks v where v.day < v_today - 30;
  get diagnostics v_vc = row_count;
  -- A caller's hourly count on /feedback/ and /quote/, a day after its
  -- hour (ADDRESSES LET GO, 2026-11-25): the count is read for the hour
  -- alone, so nothing older is needed.
  delete from public.feedback_hits h where h.hour < (p_now at time zone public.agency_tz()) - interval '1 day';
  get diagnostics v_fh = row_count;
  delete from public.quote_hits h where h.hour < (p_now at time zone public.agency_tz()) - interval '1 day';
  get diagnostics v_qh = row_count;
  -- And against /verify/'s name check, once its count began 30 days ago
  -- and it holds no lock.
  delete from public.verify_name_caller_tries v
   where v.since < p_now - interval '30 days'
     and coalesce(v.locked_until, v.since) < p_now;
  get diagnostics v_vn = row_count;
  -- And where a colleague copied a quotation's link, 30 days after the copy
  -- (QUOTATION COPIER'S OPENING, 2026-11-25).
  update public.quotation_link_copies c set ip = null where c.ip is not null and c.at < p_now - interval '30 days';
  get diagnostics v_qc = row_count;
  return jsonb_build_object('whatsapp_cleared', v_wa, 'activity_removed', v_act, 'activity_routine_removed', v_act_r,
    'health_checkins_removed', v_hc + v_hl, 'health_leavers', coalesce(array_length(v_gone, 1), 0),
    'link_tries_removed', v_lt, 'verify_tries_removed', v_vt, 'verify_detail_tries_removed', v_vd,
    'verify_checks_removed', v_vc, 'quotation_copiers_cleared', v_qc, 'feedback_hits_removed', v_fh, 'quote_hits_removed', v_qh,
    'verify_name_tries_removed', v_vn);
end $$;

create or replace function public.jobs_prune(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_runs integer := 0; v_notes integer := 0;
  v_days integer := greatest(coalesce(public.app_setting('jobs_keep_days', (p_now at time zone public.agency_tz())::date), 7)::integer, 1);
begin
  if to_regclass('cron.job_run_details') is not null then
    delete from cron.job_run_details d where d.end_time < p_now - make_interval(days => v_days);
    get diagnostics v_runs = row_count;
  end if;
  /* A colleague's notice (notice_id) stays: Notices read its copies. */
  delete from public.ops_notifications n
   where n.notice_id is null
     and ((n.read_at is not null and n.created_at < p_now - interval '90 days')
       or (n.read_at is null and n.created_at < p_now - interval '180 days'));
  get diagnostics v_notes = row_count;
  return jsonb_build_object('job_runs', v_runs, 'notices', v_notes);
end $$;

create or replace function public.hiring_outcome_mail_queue(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v_role text := public.hiring_role(p_id); c public.hiring_candidates;
  v_secs integer := greatest(coalesce(public.app_setting('send_undo_seconds', (now() at time zone public.agency_tz())::date), 60)::integer, 10);
begin
  if v_role is null or v_role not in ('admin', 'owner') then return jsonb_build_object('error', 'denied'); end if;
  select * into c from public.hiring_candidates where id = p_id for update;
  if c.id is null or c.removed_at is not null then return jsonb_build_object('error', 'not-found'); end if;
  if c.outcome is null or c.outcome not in ('pool', 'not') then return jsonb_build_object('error', 'no-email'); end if;
  if c.outcome_mail in ('sent', 'sending') then return jsonb_build_object('ok', true, 'same', true); end if;
  update public.hiring_candidates set outcome_mail = 'queued', outcome_mail_at = null,
    outcome_mail_due = now() + make_interval(secs => v_secs), updated_at = now() where id = c.id;
  return jsonb_build_object('ok', true, 'due', now() + make_interval(secs => v_secs), 'seconds', v_secs);
end $$;

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text; v_pre text;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct', 'priority_urgent_hours', 'priority_high_hours', 'priority_medium_hours',
    'task_remind_hours', 'task_start_days', 'quote_valid_days', 'details_form_days', 'wa_repeat_hours',
    'bench_cpr_low', 'bench_cpr_mid', 'bench_cpr_high', 'bench_cpr_top', 'bench_msg_min', 'bench_msg_target', 'bench_msg_max',
    'bench_form_min', 'bench_form_target', 'bench_form_max', 'bench_cpm_min', 'bench_cpm_max', 'bench_cpl_rise',
    'bench_reels_share', 'bench_ad_spend_pct', 'bench_adset_daily', 'vic_lead_followup_hours', 'vic_proposal_followup_days', 'fx_sgd',
    'health_keep_months', 'health_leaver_months', 'abroad_days', 'abroad_remind_hours', 'analytics_from',
    'analytics_change_pct', 'analytics_churn_pct', 'quote_reply_days', 'quote_details_days', 'quote_details_close_days', 'quote_wa_day', 'client_email_on', 'ai_price_image', 'report_post_links', 'creator_bill_on_completed',
    'creator_pay_days_myr', 'creator_pay_days_other', 'task_past_days', 'hiring_invite_days', 'hiring_link_days', 'hiring_pool_months', 'hiring_keep_months', 'feedback_quiet_months', 'plan_db_mb', 'plan_db_alert_pct',
    'timely_pct', 'timely_late_days', 'stage_back_days', 'hiring_reply_days', 'session_idle_days', 'hiring_decision_days', 'verify_code_from',
    'work_start', 'work_end', 'work_lunch_min', 'work_weekend',
    'health_cap_default', 'health_near_pct', 'health_task_hours', 'health_remind_days', 'health_alert',
    'outstation_office_lat', 'outstation_office_lng', 'outstation_accuracy_m', 'outstation_keep_months',
    'outstation_office_radius_m', 'outstation_remind_hours',
    'reveal_seconds', 'ad_prepay_pct', 'ad_credit_fee_pct',
    'activity_routine_months', 'activity_keep_months', 'jobs_keep_days', 'activity_window_days', 'send_undo_seconds'];
  v_moved text[] := '{}';
  v_drop boolean; v_fw text; v_fv text;
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, case when v_k = 'fx_sgd' then 4 when v_k in ('outstation_office_lat', 'outstation_office_lng') then 6 else 2 end) <> v_v
       or (v_k = 'fx_sgd' and (v_v < 0.5 or v_v > 10))
       or (v_k in ('lead_followup_hours', 'vic_lead_followup_hours') and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k in ('proposal_followup_days', 'vic_proposal_followup_days') and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k in ('meta_checks', 'client_email_on', 'report_post_links', 'health_alert', 'creator_bill_on_completed') and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5))
       or (v_k like 'priority_%_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'task_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'task_start_days' and (v_v < 0 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k = 'task_past_days' and (v_v < 0 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'hiring_invite_days' and (v_v < 1 or v_v > 14 or v_v <> trunc(v_v)))
       or (v_k = 'hiring_link_days' and (v_v < 7 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'hiring_pool_months' and (v_v < 1 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'ad_prepay_pct' and (v_v < 1 or v_v > 100 or v_v <> trunc(v_v)))
       or (v_k = 'ad_credit_fee_pct' and (v_v < 0 or v_v > 100))
       or (v_k = 'feedback_quiet_months' and (v_v < 1 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'hiring_keep_months' and (v_v < 1 or v_v > 36 or v_v <> trunc(v_v)))
       or (v_k = 'plan_db_mb' and (v_v < 100 or v_v > 1000000 or v_v <> trunc(v_v)))
       or (v_k = 'plan_db_alert_pct' and (v_v < 10 or v_v > 100 or v_v <> trunc(v_v)))
       or (v_k = 'timely_pct' and (v_v < 1 or v_v > 100 or v_v <> trunc(v_v)))
       or (v_k = 'timely_late_days' and (v_v < 0 or v_v > 30 or round(v_v, 1) <> v_v))
       or (v_k = 'stage_back_days' and (v_v < 0 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k = 'hiring_reply_days' and (v_v < 1 or v_v > 14 or v_v <> trunc(v_v)))
       or (v_k = 'session_idle_days' and (v_v < 0 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'reveal_seconds' and (v_v < 10 or v_v > 600 or v_v <> trunc(v_v)))
       or (v_k = 'hiring_decision_days' and (v_v < 1 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k in ('quote_valid_days', 'details_form_days') and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'quote_reply_days' and (v_v < 1 or v_v > 10 or v_v <> trunc(v_v)))
       or (v_k = 'quote_details_days' and (v_v < 1 or v_v > 10 or v_v <> trunc(v_v)))
       or (v_k = 'quote_details_close_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k in ('creator_pay_days_myr', 'creator_pay_days_other') and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'wa_repeat_hours' and (v_v < 0 or v_v > 168 or v_v <> trunc(v_v)))
       or (v_k = 'quote_wa_day' and (v_v < 0 or v_v > 500 or v_v <> trunc(v_v)))
       or (v_k = 'health_keep_months' and (v_v < 6 or v_v > 120 or v_v <> trunc(v_v)))
       or (v_k = 'health_leaver_months' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'activity_routine_months' and (v_v < 1 or v_v > 36 or v_v <> trunc(v_v)))
       or (v_k = 'activity_keep_months' and (v_v < 12 or v_v > 120 or v_v <> trunc(v_v)))
       or (v_k = 'jobs_keep_days' and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'activity_window_days' and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'send_undo_seconds' and (v_v < 10 or v_v > 300 or v_v <> trunc(v_v)))
       or (v_k = 'health_cap_default' and (v_v < 1 or v_v > 80 or v_v <> trunc(v_v)))
       or (v_k = 'health_near_pct' and (v_v < 50 or v_v > 100 or v_v <> trunc(v_v)))
       or (v_k = 'health_task_hours' and (v_v < 0.5 or v_v > 40 or v_v * 2 <> trunc(v_v * 2)))
       or (v_k = 'health_remind_days' and (v_v < 0 or v_v > 14 or v_v <> trunc(v_v)))
       or (v_k = 'outstation_office_lat' and (v_v < -90 or v_v > 90))
       or (v_k = 'outstation_office_lng' and (v_v < -180 or v_v > 180))
       or (v_k = 'outstation_accuracy_m' and (v_v < 5 or v_v > 500 or v_v <> trunc(v_v)))
       or (v_k = 'outstation_keep_months' and (v_v < 6 or v_v > 120 or v_v <> trunc(v_v)))
       or (v_k = 'outstation_office_radius_m' and (v_v < 20 or v_v > 1000 or v_v <> trunc(v_v)))
       or (v_k = 'outstation_remind_hours' and (v_v < 1 or v_v > 12 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_days' and (v_v < 1 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'analytics_from' and (v_v < 202308 or v_v > 209912 or v_v <> trunc(v_v) or mod(v_v, 100) not between 1 and 12))
       or (v_k = 'verify_code_from' and (v_v < 20230814 or v_v > 20991231 or v_v <> trunc(v_v) or mod(v_v, 100) not between 1 and 31 or mod(trunc(v_v / 100), 100) not between 1 and 12))
       or (v_k in ('work_start', 'work_end') and (v_v < 0 or v_v > 2345 or v_v <> trunc(v_v) or mod(v_v, 100) not in (0, 15, 30, 45)))
       or (v_k = 'work_lunch_min' and (v_v < 0 or v_v > 180 or v_v <> trunc(v_v) or mod(v_v, 15) <> 0))
       or (v_k = 'work_weekend' and v_v not in (0, 1, 2))
       or (v_k = 'analytics_change_pct' and (v_v < 1 or v_v > 50 or v_v <> trunc(v_v)))
       or (v_k = 'analytics_churn_pct' and (v_v < 1 or v_v > 100 or v_v <> trunc(v_v)))
       or (v_k in ('bench_reels_share') and (v_v < 0 or v_v > 100))
       or (v_k = 'bench_ad_spend_pct' and (v_v < 1 or v_v > 100))
       or (v_k = 'bench_cpl_rise' and (v_v < -100 or v_v > 100))
       or (v_k like 'bench_%' and v_k not in ('bench_reels_share', 'bench_ad_spend_pct', 'bench_cpl_rise') and (v_v < 0 or v_v > 10000)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  /* A working day ends after it starts, as the two stand on the From day. */
  if (p_values ? 'work_start' or p_values ? 'work_end')
     and coalesce((p_values ->> 'work_end')::numeric, public.app_setting('work_end', p_from))
      <= coalesce((p_values ->> 'work_start')::numeric, public.app_setting('work_start', p_from)) then
    return jsonb_build_object('error', 'bad-hours');
  end if;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      /* A planned change saved back to the value in force the day before is
         withdrawn: its row goes, rather than a second row restating it. */
      v_drop := p_from > v_today
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date = p_from)
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date < p_from)
        and public.app_setting(v_k, p_from - 1) = v_v;
      if v_drop then
        delete from public.app_settings s where s.key = v_k and s.from_date = p_from;
      else
        insert into public.app_settings (key, from_date, value, set_by, set_at)
        values (v_k, p_from, v_v, v_me.id, now())
        on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      end if;
      v_name := case v_k when 'lead_followup_hours' then 'Lead follow-up limit' when 'proposal_followup_days' then 'Proposal follow-up limit'
        when 'vic_lead_followup_hours' then 'VIC lead follow-up limit' when 'vic_proposal_followup_days' then 'VIC proposal follow-up limit'
        when 'sst_pct' then 'SST' when 'term_1_3' then 'Under 3 months' when 'term_4_5' then '3-month commitment'
        when 'term_6_11' then '6-month commitment' when 'term_12_23' then '12-month commitment' when 'term_18_23' then '18-month commitment' when 'term_24' then '24-month commitment'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input price per million tokens'
        when 'ai_price_out' then 'AI output price per million tokens' when 'ai_price_search' then 'AI web search price per thousand searches' when 'ai_price_image' then 'AI price per scene picture' when 'meta_checks' then 'Meta checks' when 'client_email_on' then 'Send by email' when 'report_post_links' then 'Posts linked to tasks' when 'creator_bill_on_completed' then 'Bill creators on Completed'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        when 'priority_urgent_hours' then 'Urgent deadline' when 'priority_high_hours' then 'High deadline'
        when 'priority_medium_hours' then 'Medium deadline' when 'task_remind_hours' then 'Task reminders'
        when 'task_start_days' then 'Not started reminder' when 'task_past_days' then 'Past dates on new tasks' when 'hiring_invite_days' then 'Interview times within' when 'hiring_link_days' then 'Candidate link open' when 'hiring_pool_months' then 'Talent pool kept' when 'hiring_keep_months' then 'Closed candidates kept' when 'feedback_quiet_months' then 'Feedback last requested within' when 'quote_valid_days' then 'Quotation validity' when 'details_form_days' then 'Details form open'
        when 'quote_reply_days' then 'Contact within'
        when 'quote_details_days' then 'Details reply within' when 'quote_details_close_days' then 'Close after Reply by'
        when 'plan_db_mb' then 'Database plan' when 'plan_db_alert_pct' then 'Database alert'
        when 'timely_pct' then 'On time or early target' when 'timely_late_days' then 'Average lateness target'
        when 'stage_back_days' then 'Past dates on stage moves'
        when 'hiring_reply_days' then 'Interview reply time'
        when 'session_idle_days' then 'Signed-in devices'
        when 'reveal_seconds' then 'Hidden personal details'
        when 'hiring_decision_days' then 'Decision time'
        when 'creator_pay_days_myr' then 'Creator payment in MYR' when 'creator_pay_days_other' then 'Creator payment in other currencies'
        when 'wa_repeat_hours' then 'WhatsApp sent again'
        when 'quote_wa_day' then 'Quotation portal on WhatsApp'
        when 'bench_cpr_low' then 'Property cost per result, tier 1 from' when 'bench_cpr_mid' then 'Property cost per result, tier 2 from'
        when 'bench_cpr_high' then 'Property cost per result, tier 3 from' when 'bench_cpr_top' then 'Property cost per result, tier 3 up to'
        when 'bench_msg_min' then 'Messaging cost per result, low' when 'bench_msg_target' then 'Messaging cost per result, target'
        when 'bench_msg_max' then 'Messaging cost per result, high' when 'bench_form_min' then 'Lead form cost per result, low'
        when 'bench_form_target' then 'Lead form cost per result, target' when 'bench_form_max' then 'Lead form cost per result, high'
        when 'bench_cpm_min' then 'Cost per 1,000 impressions, low' when 'bench_cpm_max' then 'Cost per 1,000 impressions, high'
        when 'bench_cpl_rise' then 'Yearly rise in cost per lead' when 'bench_reels_share' then 'Reels share of impressions'
        when 'bench_ad_spend_pct' then 'Ad spend share of the budget' when 'bench_adset_daily' then 'Minimum daily budget per ad set'
        when 'fx_sgd' then 'Singapore dollar rate'
        when 'activity_routine_months' then 'Routine activity kept' when 'activity_keep_months' then 'Important activity kept'
        when 'jobs_keep_days' then 'Automatic run history kept' when 'activity_window_days' then 'Activity lists show'
        when 'send_undo_seconds' then 'Undo before sending'
        when 'health_keep_months' then 'Health check-ins kept' when 'health_leaver_months' then 'Leavers'' health data kept'
        when 'health_cap_default' then 'Health default weekly capacity' when 'health_near_pct' then 'Health near capacity'
        when 'health_task_hours' then 'Health default hours per task' when 'health_remind_days' then 'Health check-in reminder'
        when 'health_alert' then 'Health heavy workload notice'
        when 'outstation_office_lat' then 'Office latitude' when 'outstation_office_lng' then 'Office longitude'
        when 'outstation_accuracy_m' then 'Location accuracy limit' when 'outstation_keep_months' then 'Outstation trips kept'
        when 'outstation_office_radius_m' then 'Office radius' when 'outstation_remind_hours' then 'Reminder for open trips'
        when 'abroad_days' then 'Overseas approval' when 'abroad_remind_hours' then 'Overseas reminder'
        when 'analytics_from' then 'Analytics counts from'
        when 'verify_code_from' then 'Document IDs printed from'
        when 'ad_prepay_pct' then 'Next month''s budget requested at' when 'ad_credit_fee_pct' then 'Agency Credit Term Fee'
        when 'work_start' then 'Working hours start' when 'work_end' then 'Working hours end'
        when 'work_lunch_min' then 'Lunch' when 'work_weekend' then 'Saturday and Sunday'
        when 'analytics_change_pct' then 'Analytics change threshold' when 'analytics_churn_pct' then 'Analytics quarterly churn alert'
        else 'Report due' end;
      v_pre := case when v_k = 'fx_sgd' then 'RM ' when v_k like 'ai_price_%' then 'US$' when v_k like 'bench_%' and v_k not in ('bench_cpl_rise', 'bench_reels_share', 'bench_ad_spend_pct') then 'RM ' else '' end;
      v_unit := case when v_k = 'fx_sgd' then ' per S$1' when v_k in ('lead_followup_hours', 'vic_lead_followup_hours', 'task_remind_hours', 'wa_repeat_hours', 'abroad_remind_hours', 'health_cap_default', 'health_task_hours') or v_k like 'priority_%_hours' then ' hours'
        when v_k in ('proposal_followup_days', 'vic_proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days', 'task_start_days', 'task_past_days', 'quote_valid_days', 'details_form_days', 'quote_details_close_days', 'abroad_days', 'hiring_invite_days', 'hiring_link_days', 'timely_late_days', 'stage_back_days', 'hiring_reply_days', 'session_idle_days', 'health_remind_days', 'jobs_keep_days', 'activity_window_days') then ' days'
        when v_k in ('quote_reply_days', 'quote_details_days', 'creator_pay_days_myr', 'creator_pay_days_other', 'hiring_decision_days') then ' working days'
        when v_k = 'quote_wa_day' then ' per day'
        when v_k = 'plan_db_mb' then ' MB'
        when v_k = 'work_lunch_min' then ' minutes'
        when v_k in ('reveal_seconds', 'send_undo_seconds') then ' seconds'
        when v_k in ('outstation_accuracy_m', 'outstation_office_radius_m') then ' m'
        when v_k = 'outstation_remind_hours' then ' hours'
        when v_k in ('outstation_office_lat', 'outstation_office_lng') then ''
        when v_k in ('health_keep_months', 'hiring_pool_months', 'hiring_keep_months', 'feedback_quiet_months', 'health_leaver_months', 'outstation_keep_months', 'activity_routine_months', 'activity_keep_months') then ' months'
        when v_pre <> '' then '' else '%' end;
      v_fw := case when v_k in ('meta_checks', 'client_email_on', 'report_post_links', 'health_alert', 'creator_bill_on_completed') then case when v_was = 1 then 'On' else 'Off' end
              when v_k like 'work\_%' and v_k <> 'work_lunch_min' then coalesce(public.work_hours_word(v_k, v_was), 'not set')
              when v_k = 'analytics_from' then coalesce(substr(public.register_day(to_date(v_was::bigint::text, 'YYYYMM')), 3), 'not set')
              when v_k = 'verify_code_from' then coalesce(public.register_day(to_date(v_was::bigint::text, 'YYYYMMDD')), 'not set') else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' when v_k in ('outstation_office_lat', 'outstation_office_lng') then 'FM990.999999' else 'FM999999990.99' end), '.') || v_unit, 'not set') end;
      v_fv := case when v_k in ('meta_checks', 'client_email_on', 'report_post_links', 'health_alert', 'creator_bill_on_completed') then case when v_v = 1 then 'On' else 'Off' end
              when v_k like 'work\_%' and v_k <> 'work_lunch_min' then public.work_hours_word(v_k, v_v)
              when v_k = 'analytics_from' then substr(public.register_day(to_date(v_v::bigint::text, 'YYYYMM')), 3)
              when v_k = 'verify_code_from' then public.register_day(to_date(v_v::bigint::text, 'YYYYMMDD')) else v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' when v_k in ('outstation_office_lat', 'outstation_office_lng') then 'FM990.999999' else 'FM999999990.99' end), '.') || v_unit end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              case when v_drop then v_name || ': planned change withdrawn · ' || v_fw || ' from ' || public.register_day(p_from) ||
                ', stays ' || v_fv else
              case when v_k in ('analytics_from', 'verify_code_from') or (v_k like 'work\_%' and v_k <> 'work_lunch_min') then v_name || ': ' || v_fw || ' → ' || v_fv || ' · from ' || public.register_day(p_from) else
              v_name || ': ' || case when v_k in ('meta_checks', 'client_email_on', 'report_post_links', 'health_alert', 'creator_bill_on_completed') then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k in ('meta_checks', 'client_email_on', 'report_post_links', 'health_alert', 'creator_bill_on_completed') then '' else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' when v_k in ('outstation_office_lat', 'outstation_office_lng') then 'FM990.999999' else 'FM999999990.99' end), '.') || v_unit, 'not set') || ' → ' || v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' when v_k in ('outstation_office_lat', 'outstation_office_lng') then 'FM990.999999' else 'FM999999990.99' end), '.') || v_unit ||
              ' · from ' || public.register_day(p_from) end end end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;

create or replace function public.ops_outstation_remind()
returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0;
begin
  for r in
    select e.id, e.meeting_at, coalesce((select t.id from public.team_members t where t.id = e.meeting_owner_id and t.active),
                                       (select t.id from public.team_members t where t.id = e.manager_id and t.active)) as who, c.name as client_name
      from public.ops_engagements e
      left join public.clients c on c.id = e.client_id
     where e.meeting_channel = 'onsite' and not e.meeting_na and e.meeting_at is not null
       and e.outstation_told_at is null
       and e.meeting_at + make_interval(mins => coalesce(e.meeting_minutes, 30)) <= now()
       and coalesce(e.status, '') <> 'cancelled'
     for update of e skip locked
  loop
    if r.who is not null and exists (select 1 from public.team_members t where t.id = r.who and t.active) then
      insert into public.ops_notifications (team_member_id, kind, title, body, link, dedupe_key)
      values (r.who, 'outstation', 'Submit the outstation record',
              coalesce(r.client_name, 'Client') || ' · on-site meeting on ' ||
                public.register_day((r.meeting_at at time zone public.agency_tz())::date),
              'https://' || public.agency('link_domain') || '/outstation',
              'outstation.' || r.id::text || '.' || extract(epoch from r.meeting_at)::bigint::text)
      on conflict (dedupe_key) do nothing;
      n := n + 1;
    end if;
    update public.ops_engagements set outstation_told_at = now() where id = r.id;
  end loop;
  return n;
end $$;

create or replace function public.creator_mail_queue(p_purpose text, p_req uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  t   public.creator_email_templates;
  r   public.creator_pay_requests;
  c   public.creators;
  v_to text;
  v_sub text;
  v_body text;
  v_vals jsonb;
  w   public.creator_pay_requests;
  v_day date;
begin
  select * into t from public.creator_email_templates x where x.purpose = p_purpose;
  if t.purpose is null or not t.on_send then return; end if;
  select * into r from public.creator_pay_requests x where x.id = p_req;
  select * into c from public.creators x where x.id = r.creator_id;
  -- Details changed goes to the email on file, the set it replaced.
  select * into w from public.creator_pay_requests x where x.id = r.prior_id;
  v_to := lower(btrim(coalesce(case when p_purpose = 'review' then t.to_email
                                    when p_purpose = 'changed' then w.email else r.email end, '')));
  v_day := (r.created_at at time zone public.agency_tz())::date;
  if v_to !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return; end if;
  v_sub := t.subject;
  v_body := t.body;
  v_vals := jsonb_build_object(
    'creator name', c.name, 'creator id', coalesce(c.creator_code, ''), 'reference', r.ref, 'payee', r.payee,
    'method', public.creator_pay_method(r.method, r.bank), 'account ending', right(r.account, 4),
    'review link', 'https://' || public.agency('portal_domain') || '/admin/?s=campaigns&tab=roster&pay=' || c.id,
    'date', public.register_day(v_day),
    'chinese date', to_char(v_day, 'YYYY') || '年' || to_char(v_day, 'FMMM') || '月' || to_char(v_day, 'FMDD') || '日',
    'changes', array_to_string(coalesce(r.changes, '{}'), E'\n'));
  v_sub := public.creator_mail_fill(v_sub, v_vals);
  -- A field filled empty (no changes) leaves no blank lines behind it.
  v_body := regexp_replace(public.creator_mail_fill(v_body, v_vals), E'\n{3,}', E'\n\n', 'g');
  -- Off, the email is kept as Not sent and never sent later (2026-11-10).
  insert into public.creator_emails (purpose, creator_id, request_id, to_email, subject, body, status, error)
  values (p_purpose, c.id, r.id, v_to, left(v_sub, 200), v_body,
          case when public.auto_send_on('email') then 'queued' else 'failed' end,
          case when public.auto_send_on('email') then null else 'off: Automatic emails are off.' end);
  perform public.creator_mail_kick();
end $$;

create or replace function public.agent_schedule_do(s public.agent_schedules, m public.team_members)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  p jsonb := s.payload;
  v jsonb;
  b public.batches;
  c public.clients;
  v_on boolean;
  v_today date := (now() at time zone public.agency_tz())::date;
  v_day   date;
  v_n integer;
  v_what text;
  v_rec jsonb;
begin
  if s.kind = 'reminder' then
    insert into public.ops_notifications (team_member_id, task_id, report_id, client_id, kind, title, body, dedupe_key)
    values (m.id,
            (select t.id from public.ops_tasks t where t.id = nullif(p ->> 'task_id', '')::uuid),
            (select r.id from public.sm_reports r where r.id = nullif(p ->> 'report_id', '')::uuid),
            (select x.id from public.clients x where x.id = nullif(p ->> 'client_id', '')::uuid),
            'assistant.reminder', left(s.title, 200), left(p ->> 'message', 500), 'agent.' || s.id)
    on conflict (dedupe_key) do nothing;
    return jsonb_build_object('ok', true, 'said', 'Reminder sent to you.');
  end if;
  if s.kind = 'mark_sent' then
    -- The record names the day written, never the day it ran (review 2026-11-24).
    v_day := coalesce(nullif(p ->> 'sent_on', '')::date, v_today);
    v := public.sm_report_sent((p ->> 'report_id')::uuid, v_day);
    if v ? 'error' then return v; end if;
    insert into public.activity_log (actor, action, subject, detail)
    values (m.name, 'assistant.report', s.title, 'Marked as sent ' || public.register_day(v_day) || ' · scheduled through the Assistant');
    return jsonb_build_object('ok', true, 'said', 'Marked as sent.');
  end if;
  if s.kind = 'add_task' then
    v := public.ops_create_task(p, 'agent-schedule-' || s.id::text);
    if v ? 'error' then return v; end if;
    insert into public.activity_log (actor, action, subject, detail)
    values (m.name, 'assistant.task', coalesce((select x.name from public.clients x where x.id = nullif(p ->> 'client_id', '')::uuid), 'Internal'),
            'Task added: ' || coalesce(p ->> 'title', '') || ' · scheduled through the Assistant');
    return jsonb_build_object('ok', true, 'said', 'Task added.', 'task_id', v ->> 'id');
  end if;
  if s.kind in ('publish_set', 'unpublish_set') then
    if not public.allowed('review.sets', 'work') then return jsonb_build_object('error', 'denied'); end if;
    select * into b from public.batches x where x.id = (p ->> 'set_id')::uuid for update;
    if b.id is null or not public.client_seen(b.client_id, 'work') then return jsonb_build_object('error', 'not-found'); end if;
    v_on := s.kind = 'publish_set';
    if v_on and not exists (select 1 from public.posts po where po.batch_id = b.id) then
      return jsonb_build_object('error', 'empty');
    end if;
    if b.published = v_on then return jsonb_build_object('ok', true, 'said', case when v_on then 'Already published.' else 'Already unpublished.' end); end if;
    update public.batches x set published = v_on where x.id = b.id;
    select * into c from public.clients x where x.id = b.client_id;
    insert into public.activity_log (actor, action, subject, detail)
    values (m.name, case when v_on then 'set.published' else 'set.withdrawn' end, c.name || ' — ' || b.title, null),
           (m.name, 'assistant.set', c.name || ' — ' || b.title,
            case when v_on then 'Published' else 'Unpublished' end || ' · scheduled through the Assistant');
    return jsonb_build_object('ok', true, 'said', case when v_on then 'Published.' else 'Unpublished.' end);
  end if;
  if s.kind = 'whatsapp' then
    v := public.wa_compose_prepare('contact', (p ->> 'to_id')::uuid, p ->> 'purpose', nullif(p ->> 'ref', '')::uuid);
    if v ? 'error' then return v; end if;
    if not exists (select 1 from public.wa_templates t where t.purpose = p ->> 'purpose' and t.active and t.name <> '') then
      return jsonb_build_object('error', 'wa-off');
    end if;
    v_rec := public.wa_sent_recently('contact', (p ->> 'to_id')::uuid, p ->> 'purpose', nullif(p ->> 'ref', '')::uuid, null);
    if coalesce((v_rec ->> 'recent')::boolean, false) then
      return jsonb_build_object('skip', true, 'said', 'Not sent: it was sent on WhatsApp recently.');
    end if;
    /* What waits, as the composer words it: the set's undecided posts, or
       the creator's draft. */
    if p ->> 'purpose' = 'approval' then
      select * into b from public.batches x where x.id = nullif(p ->> 'ref', '')::uuid;
      if b.id is not null then
        select count(*)::int into v_n from public.posts po
         where po.batch_id = b.id
           and not exists (select 1 from public.reviews r where r.post_id = po.id and r.undone_at is null
                              and coalesce(r.round, 1) = coalesce(po.round, 1)
                              and (po.review_reset_at is null or r.created_at > po.review_reset_at));
        v_what := v_n || case when v_n = 1 then ' post' else ' posts' end || ' in ' || b.title;
      else
        v_what := coalesce(nullif(p ->> 'what', ''), 'A draft');
      end if;
    end if;
    perform public.wa_enqueue(p ->> 'purpose', v ->> 'number', v ->> 'name',
      jsonb_build_array(v ->> 'greeting', v ->> 'client',
        case p ->> 'purpose' when 'approval' then v_what when 'representative' then v ->> 'rep' else '' end,
        case when p ->> 'purpose' = 'approval' then 'https://' || public.agency('portal_domain') || '/' || coalesce(v ->> 'link', '') else '' end),
      v ->> 'ref_kind', nullif(p ->> 'ref', '')::uuid, (v ->> 'client_id')::uuid,
      case p ->> 'purpose' when 'approval' then v ->> 'link' when 'representative' then v ->> 'code' end);
    /* Sent for a colleague, never Automatic. */
    update public.wa_outbox o set created_by = m.name, to_kind = 'contact', to_id = (p ->> 'to_id')::uuid
     where o.id = (select x.id from public.wa_outbox x where x.created_by = 'system' and x.created_at = now()
                      and x.purpose = p ->> 'purpose' and x.to_number = v ->> 'number' order by x.id limit 1);
    insert into public.activity_log (actor, action, subject, detail)
    values (m.name, 'assistant.whatsapp', coalesce(v ->> 'subject', s.title),
            'Sent on WhatsApp to ' || coalesce(v ->> 'name', '') || ' · scheduled through the Assistant');
    return jsonb_build_object('ok', true, 'said', 'Sent on WhatsApp.');
  end if;
  return jsonb_build_object('error', 'bad-kind');
end $$;

create or replace function public.outstation_remind()
returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0;
  v_hours numeric := coalesce(public.app_setting('outstation_remind_hours', (now() at time zone public.agency_tz())::date), 3);
begin
  for r in
    select t.id, t.ref, t.driver_id,
           (select public.outstation_last_activity(s.id) from public.outstation_stops s where s.trip_id = t.id order by s.seq desc limit 1) as last_at
      from public.outstation_trips t
     where t.state = 'open' and t.reminded_at is null
     for update of t skip locked
  loop
    continue when r.last_at is null or r.last_at + make_interval(mins => round(v_hours * 60)::int) > now();
    insert into public.ops_notifications (team_member_id, kind, title, body, link, dedupe_key)
    values (r.driver_id, 'outstation', 'Your trip is still open. Check out?', coalesce(r.ref, 'Outstation trip'),
            'https://' || public.agency('portal_domain') || '/admin/?s=work&view=outstation', 'outstation.open.' || r.id::text)
    on conflict (dedupe_key) do nothing;
    update public.outstation_trips set reminded_at = now() where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.quotation_details_ask(p_id uuid, p_fields text[], p_note text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  q      public.quotations;
  v_f    text[];
  v_note text := nullif(btrim(regexp_replace(coalesce(p_note, ''), '[ \t]+', ' ', 'g')), '');
  v_due  timestamptz;
  v_zh   boolean;
  v_t    public.quote_email_templates;
  v_link text;
  v_body text;
  v_k    text;
  v_v    text;
begin
  if me.id is null or not public.allowed('clients.quotes', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into q from public.quotations x where x.id = p_id for update;
  if q.id is null or not public.client_scope_ok('client', q.client_id, 'work') then return jsonb_build_object('error', 'not-found'); end if;
  if q.source <> 'website' or q.removed_at is not null then return jsonb_build_object('error', 'not-found'); end if;
  if q.released_at is not null then return jsonb_build_object('error', 'sent'); end if;
  if q.status = 'not_proceeding' then return jsonb_build_object('error', 'closed'); end if;
  select coalesce(array_agg(distinct x), '{}') into v_f from unnest(coalesce(p_fields, '{}')) x;
  if exists (select 1 from unnest(v_f) x where x not in ('registration', 'industry', 'online', 'commence')) then
    return jsonb_build_object('error', 'bad-fields');
  end if;
  v_f := array(select x from unnest(array['registration', 'industry', 'online', 'commence']) x where x = any(v_f));
  if v_note is not null and (length(v_note) > 500 or v_note ~* public.quote_link_like()) then return jsonb_build_object('error', 'bad-note'); end if;
  if cardinality(v_f) = 0 and v_note is null then return jsonb_build_object('error', 'bad-fields'); end if;
  v_due := public.ops_add_business_days(now(),
    coalesce(public.app_setting('quote_details_days', (now() at time zone public.agency_tz())::date), 3)::int);
  update public.quotations x
     set details_ask = jsonb_build_object('fields', to_jsonb(v_f), 'note', v_note),
         details_asked_at = now(), details_asked_by = me.name, details_due = v_due, details_at = null, details = null
   where x.id = q.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', q.brand, q.ref || ' · Details asked: ' ||
          replace(substr(public.quote_details_lines(v_f, v_note, false), 3), E'\n• ', ', ') ||
          ' · Reply by ' || public.register_day((v_due at time zone public.agency_tz())::date));
  -- The same words as the email, for WhatsApp by hand.
  v_zh := coalesce(q.contact->>'lang', 'en') = 'zh';
  select * into v_t from public.quote_email_templates x where x.kind = 'details' and x.lang = case when v_zh then 'zh' else 'en' end;
  v_link := 'https://' || public.agency('portal_domain') || '/quote/?q=' || q.access_key;
  v_body := coalesce(v_t.body, '');
  foreach v_k in array array['contact name', 'brand', 'reference', 'details', 'reply by', 'link'] loop
    v_v := case v_k when 'contact name' then public.contact_named(q.contact->>'salutation', q.contact->>'name')
      when 'brand' then coalesce(q.contact->>'brand', q.brand) when 'reference' then q.ref
      when 'details' then public.quote_details_lines(v_f, v_note, v_zh)
      when 'reply by' then public.quote_day_word((v_due at time zone public.agency_tz())::date, v_zh)
      else v_link end;
    v_body := regexp_replace(v_body, '\{\s*' || v_k || '\s*\}', replace(coalesce(v_v, ''), '\', '\\'), 'gi');
  end loop;
  return jsonb_build_object('ok', true, 'due', v_due, 'key', q.access_key, 'text', v_body || E'\n\n' || v_link);
end $$;

create or replace function public.mail_queue_put(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_src  text := p->>'source';
  v_log  uuid := nullif(p->>'log_id', '')::uuid;
  v_by   uuid;
  v_secs int := greatest(0, least(600, coalesce(public.app_setting('send_undo_seconds', (now() at time zone public.agency_tz())::date)::int, 60)));
  q      public.mail_queue;
begin
  if v_src is null or v_log is null or jsonb_typeof(p->'msg') <> 'object' or coalesce(p->>'idem', '') = '' then
    return jsonb_build_object('error', 'bad-request');
  end if;
  v_by := case v_src
    when 'supplier' then (select e.sent_by from public.supplier_emails e where e.id = v_log)
    when 'client' then (select e.sent_by from public.client_emails e where e.id = v_log)
    when 'manual' then (select e.sent_by from public.team_emails e where e.id = v_log)
    when 'invoice' then (select e.sent_by from public.invoice_emails e where e.id = v_log)
    when 'feedback' then (select e.sent_by from public.feedback_requests e where e.id = v_log)
    else (select t.id from public.team_members t where t.auth_user_id = nullif(p->>'by', '')::uuid limit 1) end;
  insert into public.mail_queue (source, log_id, close, msg, idem, to_name, what, send_at, queued_by)
  values (v_src, v_log, coalesce(p->'close', '{}'::jsonb), p->'msg', p->>'idem', left(nullif(p->>'to_name', ''), 200),
          left(nullif(p->>'what', ''), 200), now() + make_interval(secs => v_secs), v_by)
  on conflict (source, log_id) do nothing
  returning * into q;
  if q.id is null then return jsonb_build_object('error', 'already'); end if;
  perform public.mail_queue_mark(q, 'queued');
  perform public.mail_queue_note(q, 'queued', (select t.name from public.team_members t where t.id = v_by));
  return jsonb_build_object('ok', true, 'queue', q.id, 'source', v_src, 'id', v_log, 'seconds', v_secs, 'send_at', q.send_at);
end $$;

create or replace function public.supplier_email_prepare(p_supplier uuid, p_purpose text, p_document uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  s     public.suppliers;
  d     public.documents;
  t     public.supplier_email_templates;
  v     jsonb;
  hours numeric;
  r     public.supplier_emails;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.send_ok('email') then return jsonb_build_object('error', 'send-off'); end if;
  select * into s from public.suppliers x where x.id = p_supplier;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into t from public.supplier_email_templates x where x.purpose = p_purpose;
  if t.purpose is null then return jsonb_build_object('error', 'bad-purpose'); end if;
  if coalesce(s.email, '') = '' then return jsonb_build_object('error', 'no-email'); end if;
  if p_purpose = 'approved' and s.status <> 'active' then return jsonb_build_object('error', 'not-active'); end if;
  if p_purpose = 'document' then
    select * into d from public.documents x where x.id = p_document and x.supplier_id = s.id;
    if d.id is null or d.voided_at is not null then return jsonb_build_object('error', 'bad-document'); end if;
  end if;
  v := jsonb_build_object(
    'supplier name', coalesce(s.name, s.code), 'supplier id', s.code,
    'contact name', coalesce(s.contact_name, ''), 'designation', coalesce(s.designation, ''),
    'payment term', coalesce(s.payment_term, ''),
    'currency', case s.currency when 'SGD' then 'SGD' else 'MYR' end,
    'document title', coalesce(d.kind, ''), 'document reference', coalesce(d.serial, ''),
    'document date', case when d.issued_at is null then ''
      else to_char(d.issued_at at time zone public.agency_tz(), 'FMDD FMMonth YYYY') end,
    'sender name', coalesce(me.name, ''));
  hours := coalesce(public.app_setting('wa_repeat_hours', (now() at time zone public.agency_tz())::date), 24);
  if hours > 0 then
    select * into r from public.supplier_emails x
     where x.supplier_id = s.id and x.purpose = p_purpose and x.document_id is not distinct from d.id
       and x.status not in ('failed', 'cancelled') and x.created_at > now() - make_interval(secs => hours * 3600)
     order by x.created_at desc limit 1;
  end if;
  return jsonb_build_object('ok', true,
    'to', jsonb_build_object('name', coalesce(s.contact_name, coalesce(s.name, s.code)), 'email', s.email),
    'cc', nullif(coalesce(s.finance_email, ''), s.email),
    'values', v,
    'subject', public.supplier_email_fill(t.subject, v),
    'body', public.supplier_email_fill(t.body, v),
    'document', case when d.id is null then null else jsonb_build_object('id', d.id, 'serial', d.serial, 'kind', d.kind) end,
    'recent', case when r.id is null then null else jsonb_build_object('at', r.created_at, 'to', r.to_email,
      'by', (select m.name from public.team_members m where m.id = r.sent_by)) end);
end $$;

create or replace function public.client_email_prepare(p_kind text, p_ref uuid, p_contact uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  c      public.clients;
  q      public.quotations;
  o      public.client_documents;
  d      public.documents;
  k      public.client_contacts;
  t      public.client_email_templates;
  v_cid  uuid;
  v_ref  text;
  v_tit  text;
  v_day  date;
  v_val  date;
  v      jsonb;
  ppl    jsonb;
  hours  numeric;
  r      public.client_emails;
  v_cc   text;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if not public.send_ok('email') then return jsonb_build_object('error', 'send-off'); end if;
  if p_kind not in ('quotation', 'offer', 'letter') then return jsonb_build_object('error', 'bad-request'); end if;
  if not public.client_email_may(p_kind, 'work') or not public.allowed('clients.contacts', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  if coalesce(public.app_setting('client_email_on', (now() at time zone public.agency_tz())::date), 0) <> 1 then
    return jsonb_build_object('error', 'email-off');
  end if;
  if p_kind = 'quotation' then
    select * into q from public.quotations x where x.id = p_ref;
    if q.id is null or q.removed_at is not null then return jsonb_build_object('error', 'not-found'); end if;
    if q.status = 'not_proceeding' then return jsonb_build_object('error', 'void'); end if;
    if q.source = 'website' and q.released_at is null then return jsonb_build_object('error', 'unreleased'); end if;
    if q.confirmed_at is null then return jsonb_build_object('error', 'not-confirmed'); end if;
    if q.no_contact_at is not null then return jsonb_build_object('error', 'no-contact'); end if;
    v_cid := q.client_id; v_ref := q.ref; v_tit := 'Quotation';
    v_day := (q.issued_at at time zone public.agency_tz())::date; v_val := q.valid_until;
  elsif p_kind = 'offer' then
    select * into o from public.client_documents x where x.id = p_ref;
    if o.id is null or o.kind not in ('offer', 'intent', 'cover') then return jsonb_build_object('error', 'not-found'); end if;
    if o.voided_at is not null or o.superseded_by is not null then return jsonb_build_object('error', 'void'); end if;
    v_cid := o.client_id; v_ref := o.number; v_tit := 'Letter of Offer'; v_day := o.issued_at;
  else
    select * into d from public.documents x where x.id = p_ref and x.family = 'client';
    if d.id is null or d.client_id is null then return jsonb_build_object('error', 'not-found'); end if;
    if d.voided_at is not null then return jsonb_build_object('error', 'void'); end if;
    if d.source <> 'portal' then return jsonb_build_object('error', 'no-file'); end if;
    v_cid := d.client_id; v_ref := d.serial; v_tit := coalesce(nullif(d.kind, ''), 'Letter'); v_day := d.issued_at;
  end if;
  select * into c from public.clients x where x.id = v_cid;
  if c.id is null or not public.client_seen(c.id, 'view') then return jsonb_build_object('error', 'not-found'); end if;
  select * into t from public.client_email_templates x where x.kind = p_kind;
  if t.kind is null then return jsonb_build_object('error', 'needs-update'); end if;

  /* The client's contacts holding an email, the billing contact first, then
     the primary, then by name. */
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', public.contact_named(x.salutation, x.name),
           'email', btrim(x.email), 'role', x.role, 'billing', coalesce(x.id = c.bill_contact_id, false), 'primary', x.is_primary)
           order by (x.id = c.bill_contact_id) desc nulls last, x.is_primary desc, x.name), '[]'::jsonb)
    into ppl
    from public.client_contacts x
   where x.client_id = c.id and x.archived_at is null and coalesce(btrim(x.email), '') ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$';
  if jsonb_array_length(ppl) = 0 then return jsonb_build_object('error', 'no-email'); end if;
  if p_contact is not null then
    select * into k from public.client_contacts x
     where x.id = p_contact and x.client_id = c.id and x.archived_at is null
       and coalesce(btrim(x.email), '') ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$';
    if k.id is null then return jsonb_build_object('error', 'bad-contact'); end if;
  else
    select * into k from public.client_contacts x where x.id = (ppl->0->>'id')::uuid;
  end if;
  -- The finance email and registered name are Billing's (audit 2026-11-04).
  v_cc := case when public.allowed('clients.billing', 'view') then nullif(btrim(coalesce(c.finance_email, '')), '') end;
  if v_cc is not null and (lower(v_cc) = lower(btrim(k.email)) or v_cc !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$') then v_cc := null; end if;

  v := jsonb_build_object(
    'contact name', public.contact_named(k.salutation, k.name),
    'client name', c.name,
    'company name', coalesce(case when public.allowed('clients.billing', 'view') then nullif(c.legal_name, '') end, c.name),
    'document title', v_tit, 'document reference', v_ref,
    'document date', case when v_day is null then '' else to_char(v_day, 'FMDD FMMonth YYYY') end,
    'valid until', case when v_val is null then '' else to_char(v_val, 'FMDD FMMonth YYYY') end,
    'sender name', coalesce(me.name, ''));
  hours := coalesce(public.app_setting('wa_repeat_hours', (now() at time zone public.agency_tz())::date), 24);
  if hours > 0 then
    select * into r from public.client_emails x
     where x.kind = p_kind and x.ref_id = p_ref and x.status not in ('failed', 'cancelled')
       and x.created_at > now() - make_interval(secs => hours * 3600)
     order by x.created_at desc limit 1;
  end if;
  return jsonb_build_object('ok', true,
    'client_id', c.id, 'client', c.name,
    'contacts', ppl,
    'to', jsonb_build_object('id', k.id, 'name', public.contact_named(k.salutation, k.name), 'email', btrim(k.email)),
    'cc', v_cc,
    'reply_to', nullif(btrim(coalesce(me.email, '')), ''),
    'values', v,
    'subject', public.supplier_email_fill(t.subject, v),
    'body', public.supplier_email_fill(t.body, v),
    'document', jsonb_build_object('id', p_ref, 'kind', p_kind, 'serial', v_ref, 'title', v_tit),
    'recent', case when r.id is null then null else jsonb_build_object('at', r.created_at, 'to', r.to_email,
      'by', (select m.name from public.team_members m where m.id = r.sent_by)) end);
end $$;

create or replace function public.invoice_mail_begin(p_purpose text, p_actor uuid, p_client uuid, p_contact bigint, p_name text,
  p_email text, p_invoices jsonb, p_cc boolean, p_subject text, p_body text, p_again boolean, p_to text, p_ccs text[])
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members;
  t      public.invoice_email_template;
  v_tpl  public.invoice_send_template;
  rcp    jsonb;
  opts   jsonb;
  pick   jsonb;
  inv    jsonb;
  hours  numeric;
  r      public.invoice_emails;
  v_n    int;
  v_k    int;
  v_m    int;
  v_d    int;
  v_to   text;
  v_cc   text;
  v_who  text;
  v_nm   boolean;
  v_co   text;
  v_tot  text;
  v_nos  text;
  v_list text[];
  v_vals jsonb;
  v_s    text;
  v_b    text;
  v_id   uuid;
begin
  select * into me from public.team_members x where x.id = p_actor and x.active;
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if not public.send_ok_of(me.id, 'email') then return jsonb_build_object('error', 'send-off'); end if;
  if p_purpose is null or p_purpose not in ('reminder', 'invoice') then return jsonb_build_object('error', 'bad-request'); end if;
  if p_contact is null or p_contact <= 0 then return jsonb_build_object('error', 'bad-request'); end if;
  if jsonb_typeof(p_invoices) <> 'array' or jsonb_array_length(p_invoices) < 1 or jsonb_array_length(p_invoices) > 50 then
    return jsonb_build_object('error', 'bad-invoices');
  end if;
  for inv in select value from jsonb_array_elements(p_invoices) loop
    if btrim(coalesce(inv->>'number', '')) = '' or coalesce(inv->>'number', '') !~ '^[^[:cntrl:]]{1,60}$' or coalesce(inv->>'currency', '') !~ '^[A-Z]{3}$'
       or (inv->>'amount') is null or (inv->>'amount')::numeric <= 0
       or (coalesce(inv->>'link', '') <> '' and inv->>'link' !~ '^https://[a-z0-9-]+\.bukku\.my/[A-Za-z0-9/_-]+$') then
      return jsonb_build_object('error', 'bad-invoices');
    end if;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('invoice-mail:' || p_contact::text, 0));
  select * into r from public.invoice_emails x
   where x.bukku_contact = p_contact and x.status = 'sending' and x.created_at > now() - interval '10 minutes'
   order by x.created_at desc limit 1;
  if r.id is not null then return jsonb_build_object('error', 'sending'); end if;
  hours := coalesce(public.app_setting('wa_repeat_hours', (now() at time zone public.agency_tz())::date), 24);
  if hours > 0 and not coalesce(p_again, false) then
    select * into r from public.invoice_emails x
     where x.bukku_contact = p_contact and x.purpose = p_purpose and x.status not in ('failed', 'cancelled') and x.created_at > now() - make_interval(secs => hours * 3600)
     order by x.created_at desc limit 1;
    if r.id is not null then
      return jsonb_build_object('error', 'recent', 'recent', jsonb_build_object('at', r.created_at, 'to', r.to_email,
        'by', (select m.name from public.team_members m where m.id = r.sent_by)));
    end if;
  end if;
  rcp := case when p_client is null then null else public.invoice_recipient_for(p_client, p_contact) end;
  /* The addresses chosen on the sheet: the client's own, nothing typed. */
  if p_to is not null or p_ccs is not null then opts := public.invoice_recipient_options(p_client, p_contact); end if;
  if p_to is not null then
    select x into pick from jsonb_array_elements(opts) x where lower(x->>'email') = lower(btrim(p_to)) limit 1;
    if pick is null then return jsonb_build_object('error', 'bad-recipient'); end if;
    v_to := pick->>'email';
    v_who := coalesce(pick->>'name', 'Sir or Madam');
    v_nm := pick->>'name' is not null;
  else
    v_to := coalesce(rcp->>'email', nullif(btrim(coalesce(p_email, '')), ''));
    v_who := coalesce(rcp->>'name', 'Sir or Madam');
    v_nm := rcp->>'name' is not null;
  end if;
  if v_to is null or v_to !~ '^[^@\s,;<>]+@[^@\s,;<>]+\.[^@\s,;<>]+$' then return jsonb_build_object('error', 'no-email'); end if;
  if p_ccs is not null then
    select count(*), count(o.e), count(distinct lower(o.e)), count(*) filter (where lower(o.e) = lower(v_to)),
           string_agg(o.e, ', ' order by o.i)
      into v_k, v_m, v_d, v_n, v_cc
      from (select a.i, (select x->>'email' from jsonb_array_elements(opts) x where lower(x->>'email') = lower(btrim(a.v)) limit 1) as e
              from unnest(p_ccs) with ordinality as a (v, i)
             where nullif(btrim(coalesce(a.v, '')), '') is not null) o;
    if v_k > 5 or v_m <> v_k or v_d <> v_m or v_n > 0 then return jsonb_build_object('error', 'bad-copy'); end if;
  else
    v_cc := case when coalesce(p_cc, false) and lower(coalesce(rcp->>'cc', '')) <> lower(v_to) then rcp->>'cc' end;
  end if;
  v_co := coalesce(rcp->>'company', nullif(btrim(coalesce(p_name, '')), ''), 'Client');
  v_n := jsonb_array_length(p_invoices);
  select string_agg(public.invoice_money(s.amt, s.cur), ' and ' order by s.cur) into v_tot
    from (select x->>'currency' as cur, sum((x->>'amount')::numeric) as amt
            from jsonb_array_elements(p_invoices) x group by x->>'currency') s;
  select array_agg(x->>'number' order by o) into v_list from jsonb_array_elements(p_invoices) with ordinality as a (x, o);
  v_nos := case when v_n = 1 then v_list[1]
                else array_to_string(v_list[1:v_n - 1], ', ') || ' and ' || v_list[v_n] end;
  v_vals := jsonb_build_object('contact name', v_who, 'client', v_co, 'invoice no', v_nos, 'count', v_n::text,
    'total', v_tot, 'sign off', case when v_nm then 'Yours sincerely' else 'Yours faithfully' end);
  if p_purpose = 'invoice' then
    select * into v_tpl from public.invoice_send_template x where x.id = 1;
    t.subject_one := v_tpl.subject_one; t.subject_many := v_tpl.subject_many; t.body := v_tpl.body;
    t.legal := v_tpl.legal; t.disclaimer := v_tpl.disclaimer;
  else
    select * into t from public.invoice_email_template x where x.id = 1;
  end if;
  v_s := btrim(regexp_replace(public.supplier_email_fill(coalesce(nullif(btrim(coalesce(p_subject, '')), ''),
           case when v_n = 1 then t.subject_one else t.subject_many end), v_vals), '\s+', ' ', 'g'));
  v_b := btrim(replace(public.supplier_email_fill(coalesce(nullif(btrim(coalesce(p_body, '')), ''), t.body), v_vals), E'\r', ''));
  if length(v_s) < 2 or length(v_s) > 200 then return jsonb_build_object('error', 'bad-subject'); end if;
  if length(v_b) < 2 or length(v_b) > 5000 then return jsonb_build_object('error', 'bad-body'); end if;
  if v_b !~* '\{\s*invoices\s*\}' then return jsonb_build_object('error', 'no-invoices'); end if;
  insert into public.invoice_emails (client_id, bukku_contact, client_name, invoices, to_email, cc_email, subject, body, sent_by, purpose)
  values (p_client, p_contact, v_co, p_invoices, v_to, nullif(v_cc, ''), v_s, v_b, me.id, p_purpose)
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'to', v_to, 'cc', nullif(v_cc, ''),
    'cc_list', coalesce(to_jsonb(string_to_array(nullif(v_cc, ''), ', ')), '[]'::jsonb), 'subject', v_s, 'body', v_b,
    'legal', t.legal, 'disclaimer', t.disclaimer);
end $$;

create or replace function public.mail_log(p_month date default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  v_from date := date_trunc('month', coalesce(p_month, (now() at time zone public.agency_tz())::date))::date;
  v_a    timestamptz;
  v_b    timestamptz;
  v_sup  boolean;
  v_bill boolean;
  v_quo  boolean;
  v_all  boolean;
  v_cr   boolean;
  v_team boolean;
  v_con  boolean;
begin
  if me.id is null or not public.allowed('whatsapp', 'view') then return jsonb_build_object('error', 'denied'); end if;
  v_a := v_from::timestamp at time zone public.agency_tz();
  v_b := (v_from + interval '1 month')::timestamp at time zone public.agency_tz();
  v_sup := public.allowed('suppliers', 'view');
  v_bill := public.allowed('clients.billing', 'view');
  v_quo := public.allowed('clients.quotes', 'view');
  v_all := public.client_scope_free('view');
  v_cr := public.allowed('campaigns.creators', 'view');
  v_team := public.allowed('team', 'view');
  v_con := public.allowed('clients.contacts', 'view');
  return jsonb_build_object(
    'month', v_from,
    'senders', (select jsonb_object_agg(m.key, m.name || ' <' || m.address || '>') from public.mail_senders m),
    'items', coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (
        select * from (
          select 'supplier'::text as source, e.id, e.purpose as kind, e.to_email, e.cc_email, e.subject, e.body,
                 t.name as sent_by, e.created_at, e.status, e.error, e.sent_at, e.delivered_at, e.opened_at, e.bounced_at,
                 null::uuid as client_id, null::text as client, e.supplier_id, s.name as supplier, s.code as supplier_code,
                 d.serial as reference, null::text as to_name, null::uuid as ref_id, null::uuid as again_of, e.sent_by as sent_by_id
            from public.supplier_emails e
            left join public.suppliers s on s.id = e.supplier_id
            left join public.documents d on d.id = e.document_id
            left join public.team_members t on t.id = e.sent_by
           where v_sup and e.created_at >= v_a and e.created_at < v_b
          union all
          select 'client', e.id, e.kind, e.to_email, e.cc_email, e.subject, e.body,
                 t.name, e.created_at, e.status, e.error, e.sent_at, e.delivered_at, e.opened_at, e.bounced_at,
                 e.client_id, c.name, null, null, null,
                 e.reference, k.name, null, null, e.sent_by
            from public.client_emails e
            left join public.clients c on c.id = e.client_id
            left join public.client_contacts k on k.id = e.contact_id
            left join public.team_members t on t.id = e.sent_by
           where e.created_at >= v_a and e.created_at < v_b
             and public.client_email_may(e.kind, 'view')
             and (case when e.client_id is null then v_all else public.client_seen(e.client_id, 'view') end)
          union all
          select 'invoice', e.id, e.purpose, e.to_email, e.cc_email, e.subject, e.body,
                 t.name, e.created_at, e.status, e.error, e.sent_at, e.delivered_at, e.opened_at, e.bounced_at,
                 e.client_id, coalesce(c.name, e.client_name), null, null, null,
                 (select string_agg(i->>'number', ', ' order by o) from jsonb_array_elements(e.invoices) with ordinality as a (i, o)),
                 null, null, null, e.sent_by
            from public.invoice_emails e
            left join public.clients c on c.id = e.client_id
            left join public.team_members t on t.id = e.sent_by
           where v_bill and e.created_at >= v_a and e.created_at < v_b
             and (case when e.client_id is null then v_all else public.client_seen(e.client_id, 'view') end)
          union all
          select 'manual', e.id, 'message', e.to_email, e.cc_email, e.subject, e.body,
                 t.name, e.created_at, e.status, e.error, e.sent_at, e.delivered_at, e.opened_at, e.bounced_at,
                 e.client_id, c.name, e.supplier_id, s.name, s.code,
                 e.attachment, e.to_name, null, null, e.sent_by
            from public.team_emails e
            left join public.clients c on c.id = e.client_id
            left join public.suppliers s on s.id = e.supplier_id
            left join public.team_members t on t.id = e.sent_by
           where e.created_at >= v_a and e.created_at < v_b
             and (case when e.client_id is not null then public.allowed('clients.contacts', 'view') and public.client_seen(e.client_id, 'view')
                       when e.supplier_id is not null then v_sup else true end)
             and (not e.finance or v_bill)
          union all
          select 'creator', e.id, 'creator_' || e.purpose, e.to_email, null, e.subject, e.body,
                 t.name, e.created_at, e.status, e.error, e.sent_at, e.delivered_at, e.opened_at, e.bounced_at,
                 null, null, null, null, null,
                 r.ref, k.name, null, e.again_of, e.sent_by
            from public.creator_emails e
            left join public.creators k on k.id = e.creator_id
            left join public.creator_pay_requests r on r.id = e.request_id
            left join public.team_members t on t.id = e.sent_by
           where v_cr and e.created_at >= v_a and e.created_at < v_b
          union all
          select 'system', e.id, e.kind, e.to_email, null, e.subject, e.body,
                 t.name, e.created_at, e.status, e.error, e.sent_at, e.delivered_at, e.opened_at, e.bounced_at,
                 e.client_id, c.name, null, null, null,
                 e.reference, e.to_name, e.ref_id, e.again_of, e.sent_by
            from public.system_emails e
            left join public.clients c on c.id = e.client_id
            left join public.team_members t on t.id = e.sent_by
           where e.created_at >= v_a and e.created_at < v_b
             and (case when e.kind like 'hiring%' then public.hiring_role(e.candidate_id) is not null
                       when e.kind = 'invite_team' then v_team
                       when e.kind = 'invite_client' then v_con and e.client_id is not null and public.client_seen(e.client_id, 'view')
                       else false end)
          union all
          select 'signing', g.id, 'signing', g.email, null, 'Your ' || public.agency('trading_name') || ' signing code for quotation ' || q.ref, null,
                 null, g.created_at,
                 case when g.used_at is not null then 'used' when g.expires_at < now() then 'expired' else 'requested' end,
                 null, g.created_at, null, null, null,
                 q.client_id, c.name, null, null, null,
                 q.ref, nullif(btrim(coalesce(g.payload->'contact'->>'salutation', '') || ' ' || coalesce(g.payload->'contact'->>'name', '')), ''),
                 null, null, null::uuid
            from public.quote_sign_codes g
            join public.quotations q on q.id = g.quotation_id
            left join public.clients c on c.id = q.client_id
           where v_quo and g.created_at >= v_a and g.created_at < v_b
             and (case when q.client_id is null then v_all else public.client_seen(q.client_id, 'view') end)
        ) u
        order by u.created_at desc
        limit 2000) x), '[]'::jsonb));
end $$;

create or replace function public.feedback_mail_begin(p_client uuid, p_kind text, p_again boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  r     jsonb;
  v_cl  public.clients;
  v_ct  public.client_contacts;
  v_t   public.feedback_email_templates;
  v_zh  boolean;
  v_s   text;
  v_b   text;
  v_btn text;
  v_k   text;
  v_v   text;
begin
  if me.id is null or not public.allowed('clients', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.send_ok('email') then return jsonb_build_object('error', 'send-off'); end if;
  if coalesce(public.app_setting('client_email_on', (now() at time zone public.agency_tz())::date), 0) <> 1 then
    return jsonb_build_object('error', 'email-off');
  end if;
  if p_kind in ('quick', 'review')
     and (select count(*) from public.feedback_email_templates x where x.kind = p_kind) < 2 then
    return jsonb_build_object('error', 'not-found');
  end if;
  r := public.feedback_request(p_client, p_kind, p_again);
  if r ? 'error' then return r; end if;
  select * into v_cl from public.clients c where c.id = p_client;
  select * into v_ct from public.client_contacts k
   where k.id = (select q.contact_id from public.feedback_requests q where q.id = (r->>'id')::uuid);
  -- Every email in English, whatever the contact's language (the user, 2026-11-28).
  v_zh := false;
  select * into v_t from public.feedback_email_templates x
   where x.kind = p_kind and x.lang = case when v_zh then 'zh' else 'en' end;
  v_s := v_t.subject;
  v_b := v_t.body;
  v_btn := v_t.button;
  foreach v_k in array array['contact name', 'client name', 'link'] loop
    v_v := case v_k when 'contact name' then public.contact_named(v_ct.salutation, v_ct.name)
      when 'client name' then v_cl.name
      else 'https://' || public.agency('portal_domain') || '/feedback/?k=' || (r->>'key') end;
    v_s := regexp_replace(v_s, '\{\s*' || v_k || '\s*\}', replace(coalesce(v_v, ''), '\', '\\'), 'gi');
    v_b := regexp_replace(v_b, '\{\s*' || v_k || '\s*\}', replace(coalesce(v_v, ''), '\', '\\'), 'gi');
    v_btn := regexp_replace(v_btn, '\{\s*' || v_k || '\s*\}', replace(coalesce(v_v, ''), '\', '\\'), 'gi');
  end loop;
  update public.feedback_requests q set mail_status = 'sending' where q.id = (r->>'id')::uuid;
  return r || jsonb_build_object('subject', left(v_s, 200), 'body', v_b, 'button', v_btn, 'lang', case when v_zh then 'zh' else 'en' end);
end $$;

create or replace function public.quote_details_mail_begin(p_id uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  q     public.quotations;
  v_ds  text;
  v_zh  boolean;
  v_t   public.quote_email_templates;
  v_s   text;
  v_b   text;
  v_btn text;
  v_k   text;
  v_v   text;
  v_to  text;
  v_ct  uuid;
  v_id  uuid;
  v_f   text[];
begin
  if me.id is null or not public.allowed('clients.quotes', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.send_ok('email') then return jsonb_build_object('error', 'send-off'); end if;
  if coalesce(public.app_setting('client_email_on', (now() at time zone public.agency_tz())::date), 0) <> 1 then
    return jsonb_build_object('error', 'email-off');
  end if;
  select * into q from public.quotations x where x.id = p_id;
  if q.id is null or q.source <> 'website' or q.removed_at is not null
     or not public.client_scope_ok('client', q.client_id, 'work') then return jsonb_build_object('error', 'not-found'); end if;
  if q.released_at is not null then return jsonb_build_object('error', 'sent'); end if;
  v_ds := public.quote_details_state(q);
  if v_ds not in ('asked', 'late') or q.status = 'not_proceeding' then return jsonb_build_object('error', 'closed'); end if;
  if q.no_contact_at is not null then return jsonb_build_object('error', 'no-contact'); end if;
  v_to := lower(btrim(coalesce(q.contact->>'email', '')));
  if not (v_to ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$') then return jsonb_build_object('error', 'no-email'); end if;
  -- Every email in English, whatever the prospect's language (the user, 2026-11-28).
  v_zh := false;
  select * into v_t from public.quote_email_templates x where x.kind = 'details' and x.lang = case when v_zh then 'zh' else 'en' end;
  if v_t.kind is null then return jsonb_build_object('error', 'not-found'); end if;
  v_f := array(select jsonb_array_elements_text(q.details_ask->'fields'));
  v_s := v_t.subject; v_b := v_t.body; v_btn := v_t.button;
  foreach v_k in array array['contact name', 'brand', 'reference', 'details', 'reply by', 'link'] loop
    v_v := case v_k when 'contact name' then public.contact_named(q.contact->>'salutation', q.contact->>'name')
      when 'brand' then coalesce(q.contact->>'brand', q.brand) when 'reference' then q.ref
      when 'details' then public.quote_details_lines(v_f, q.details_ask->>'note', v_zh)
      when 'reply by' then public.quote_day_word((q.details_due at time zone public.agency_tz())::date, v_zh)
      else 'https://' || public.agency('portal_domain') || '/quote/?q=' || q.access_key end;
    v_s := regexp_replace(v_s, '\{\s*' || v_k || '\s*\}', replace(coalesce(v_v, ''), '\', '\\'), 'gi');
    v_b := regexp_replace(v_b, '\{\s*' || v_k || '\s*\}', replace(coalesce(v_v, ''), '\', '\\'), 'gi');
    v_btn := regexp_replace(v_btn, '\{\s*' || v_k || '\s*\}', replace(coalesce(v_v, ''), '\', '\\'), 'gi');
  end loop;
  select k.id into v_ct from public.client_contacts k
   where k.client_id = q.client_id and k.archived_at is null and lower(btrim(coalesce(k.email, ''))) = v_to
   order by k.is_primary desc, k.created_at limit 1;
  insert into public.client_emails (client_id, kind, ref_id, reference, contact_id, to_email, reply_to, subject, body, sent_by)
  values (q.client_id, 'details', q.id, q.ref, v_ct, v_to, public.mail_sender('clients')->>'reply_to', left(v_s, 200), v_b, me.id)
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'to_email', v_to,
    'to_name', public.contact_named(q.contact->>'salutation', q.contact->>'name'),
    'subject', left(v_s, 200), 'body', v_b, 'button', v_btn, 'key', q.access_key);
end $$;

create or replace function public.public_request_ref(p_at timestamptz)
returns text language plpgsql volatile set search_path = public, extensions as $$
declare
  alphabet constant text := 'BCDFGHJKLMNPQRSTVWXZ';
  deny constant text[] := array['FCK', 'FKN', 'SHT', 'KKK', 'XXX', 'WTF', 'STD', 'NGR', 'PKM', 'BBW', 'DCK', 'CNT', 'PSS', 'TTS'];
  f public.id_formats;
  v_n int; v_total bigint; v_at bigint; v_step bigint; v_x bigint; v_seen bigint := 0;
  v_out text; v_ref text; v_head text; v_bytes bytea; v_i int;
begin
  -- One draw at a time until the caller's transaction ends, so two
  -- submissions in the same moment never take one number.
  perform pg_advisory_xact_lock(hashtext('public_request_ref'));
  select * into f from public.id_formats where kind = 'request';
  v_n := greatest(3, least(6, coalesce(f.width, 3)));
  v_total := power(length(alphabet), v_n)::bigint;
  v_head := 'ADP/' || coalesce(nullif(f.prefix, ''), 'REQ') || to_char(p_at at time zone public.agency_tz(), 'YYMM') || '-';
  -- The order: a random first code, a random step prime to the count.
  v_bytes := gen_random_bytes(8);
  v_at := 0; v_step := 0;
  for v_i in 0..3 loop
    v_at := v_at * 256 + get_byte(v_bytes, v_i);
    v_step := v_step * 256 + get_byte(v_bytes, v_i + 4);
  end loop;
  v_at := v_at % v_total;
  v_step := 1 + v_step % (v_total - 1);
  while gcd(v_step, v_total) <> 1 loop v_step := 1 + v_step % (v_total - 1); end loop;
  loop
    if v_seen >= v_total then raise exception 'public_request_ref: no free number'; end if;
    v_seen := v_seen + 1;
    v_out := ''; v_x := v_at;
    for v_i in 1..v_n loop
      v_out := v_out || substr(alphabet, 1 + (v_x % length(alphabet))::int, 1);
      v_x := v_x / length(alphabet);
    end loop;
    v_at := (v_at + v_step) % v_total;
    continue when v_out = any (deny);
    v_ref := v_head || v_out;
    exit when not exists (select 1 from public.quotations q where q.ref = v_ref or q.request_ref = v_ref)
          and not exists (select 1 from public.quotation_refs_kept k where k.ref = v_ref)
          and not exists (select 1 from public.client_detail_forms d where d.request_ref = v_ref)
          and not exists (select 1 from public.supplier_forms s where s.request_ref = v_ref)
          and not exists (select 1 from public.hiring_candidates h where h.request_ref = v_ref)
          and not exists (select 1 from public.client_requests r where r.request_ref = v_ref)
          and not exists (select 1 from public.feedback_responses b where b.request_ref = v_ref);
  end loop;
  return v_ref;
end $$;

